#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
enum TokenRole {
    Contributor,
    Reviewer,
    Admin,
    ExportWorker,
    RetentionWorker,
    VectorWorker,
    BenchmarkWorker,
    UtilityWorker,
    ProcessEvalWorker,
    RevocationWorker,
    CompetitionReadWorker,
    RegisterStatsWorker,
}

impl TokenRole {
    fn parse(raw: &str) -> anyhow::Result<Self> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "contributor" => Ok(Self::Contributor),
            "reviewer" => Ok(Self::Reviewer),
            "admin" => Ok(Self::Admin),
            "export_worker" | "export-worker" => Ok(Self::ExportWorker),
            "retention_worker" | "retention-worker" => Ok(Self::RetentionWorker),
            "vector_worker" | "vector-worker" => Ok(Self::VectorWorker),
            "benchmark_worker" | "benchmark-worker" => Ok(Self::BenchmarkWorker),
            "utility_worker" | "utility-worker" => Ok(Self::UtilityWorker),
            "process_eval_worker"
            | "process-eval-worker"
            | "process_evaluation_worker"
            | "process-evaluation-worker" => Ok(Self::ProcessEvalWorker),
            "revocation_worker" | "revocation-worker" => Ok(Self::RevocationWorker),
            "competition_read_worker" | "competition-read-worker" => {
                Ok(Self::CompetitionReadWorker)
            }
            "register_stats_worker" | "register-stats-worker" => Ok(Self::RegisterStatsWorker),
            other => anyhow::bail!("unknown Trace Commons token role: {other}"),
        }
    }

    fn can_review(self) -> bool {
        matches!(self, Self::Reviewer | Self::Admin)
    }

    fn can_export(self) -> bool {
        matches!(self, Self::Reviewer | Self::Admin | Self::ExportWorker)
    }

    fn can_benchmark(self) -> bool {
        matches!(self, Self::Reviewer | Self::Admin | Self::BenchmarkWorker)
    }

    fn can_admin(self) -> bool {
        matches!(self, Self::Admin)
    }

    fn storage_name(self) -> &'static str {
        match self {
            Self::Contributor => "contributor",
            Self::Reviewer => "reviewer",
            Self::Admin => "admin",
            Self::ExportWorker => "export_worker",
            Self::RetentionWorker => "retention_worker",
            Self::VectorWorker => "vector_worker",
            Self::BenchmarkWorker => "benchmark_worker",
            Self::UtilityWorker => "utility_worker",
            Self::ProcessEvalWorker => "process_eval_worker",
            Self::RevocationWorker => "revocation_worker",
            Self::CompetitionReadWorker => "competition_read_worker",
            Self::RegisterStatsWorker => "register_stats_worker",
        }
    }
}

