fn is_enabled_object_primary_trace_object_store(artifact_store_name: Option<&str>) -> bool {
    matches!(
        artifact_store_name,
        Some(
            TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE
                | TRACE_COMMONS_SERVICE_REMOTE_OBJECT_STORE
        )
    )
}

fn validate_required_object_store_versioning_config(
    required: bool,
    artifact_store: Option<&ConfiguredTraceArtifactStore>,
) -> anyhow::Result<()> {
    if !required {
        return Ok(());
    }
    let Some(store) = artifact_store else {
        anyhow::bail!(
            "{TRACE_COMMONS_OBJECT_STORE_REQUIRE_VERSIONING} requires TRACE_COMMONS_OBJECT_STORE with a versioned, restore-capable provider"
        );
    };
    anyhow::ensure!(
        store.object_versioning_supported() && store.restore_after_delete_supported(),
        "{TRACE_COMMONS_OBJECT_STORE_REQUIRE_VERSIONING} requires a versioned, restore-capable Trace Commons object store; object_store={}, object_versioning={}, restore_after_delete={}",
        store.object_store_name(),
        store.object_versioning_supported(),
        store.restore_after_delete_supported()
    );
    Ok(())
}

fn enforce_db_mirror_write_result(
    state: &AppState,
    operation: &str,
    result: anyhow::Result<()>,
) -> anyhow::Result<()> {
    match result {
        Ok(()) => {
            if state.require_db_mirror_writes && state.db_mirror.is_none() {
                anyhow::bail!(
                    "TRACE_COMMONS_REQUIRE_DB_MIRROR_WRITES requires TRACE_COMMONS_DB_DUAL_WRITE for {operation}"
                );
            }
            Ok(())
        }
        Err(error) if state.require_db_mirror_writes => Err(error.context(format!(
            "required Trace Commons DB mirror write failed: {operation}"
        ))),
        Err(_) => Ok(()),
    }
}

fn validate_rollout_gate_dependency(
    gates: &TraceTenantRolloutGates,
    feature: TraceTenantRolloutFeature,
    feature_global: bool,
    dependency: TraceTenantRolloutFeature,
    dependency_global: bool,
    message: &str,
) -> anyhow::Result<()> {
    let feature_tenant_ids = gates.tenant_ids(feature);
    if !feature_global && feature_tenant_ids.is_empty() {
        return Ok(());
    }
    if dependency_global {
        return Ok(());
    }
    let dependency_tenant_ids = gates.tenant_ids(dependency);
    if feature_global
        || dependency_tenant_ids.is_empty()
        || !feature_tenant_ids.is_subset(&dependency_tenant_ids)
    {
        anyhow::bail!("{message}");
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, Default)]
struct DbReadCutoverGuardConfig {
    require_db_reconciliation_clean: bool,
    require_db_mirror_writes: bool,
    db_contributor_reads: bool,
    db_reviewer_reads: bool,
    db_replay_export_reads: bool,
    db_audit_reads: bool,
    db_tenant_policy_reads: bool,
}

fn validate_db_read_cutover_guard_config(
    gates: &TraceTenantRolloutGates,
    config: DbReadCutoverGuardConfig,
) -> anyhow::Result<()> {
    if !config.require_db_reconciliation_clean || config.require_db_mirror_writes {
        return Ok(());
    }
    let db_read_promotion_configured = [
        (
            TraceTenantRolloutFeature::DbContributorReads,
            config.db_contributor_reads,
        ),
        (
            TraceTenantRolloutFeature::DbReviewerReads,
            config.db_reviewer_reads,
        ),
        (
            TraceTenantRolloutFeature::DbReplayExportReads,
            config.db_replay_export_reads,
        ),
        (
            TraceTenantRolloutFeature::DbAuditReads,
            config.db_audit_reads,
        ),
        (
            TraceTenantRolloutFeature::DbTenantPolicyReads,
            config.db_tenant_policy_reads,
        ),
    ]
    .into_iter()
    .any(|(feature, global_enabled)| gates.configured(feature, global_enabled));
    if db_read_promotion_configured {
        anyhow::bail!(
            "{TRACE_COMMONS_REQUIRE_DB_RECONCILIATION_CLEAN} with DB reader promotion requires TRACE_COMMONS_REQUIRE_DB_MIRROR_WRITES"
        );
    }
    Ok(())
}

async fn trace_artifact_store_from_env(
    default_root: &Path,
) -> anyhow::Result<Option<ConfiguredTraceArtifactStore>> {
    let object_store_mode = std::env::var("TRACE_COMMONS_OBJECT_STORE").ok();
    let key = std::env::var("TRACE_COMMONS_ARTIFACT_KEY_HEX").ok();
    let encrypted_store_kind = TraceEncryptedObjectStoreKind::from_config(
        object_store_mode.as_deref(),
        key.is_some() || env_truthy("TRACE_COMMONS_ENCRYPTED_ARTIFACTS"),
    )?;
    let Some(encrypted_store_kind) = encrypted_store_kind else {
        return Ok(None);
    };
    if encrypted_store_kind == TraceEncryptedObjectStoreKind::ServiceRemote {
        let config = TraceRemoteObjectStoreConfig::from_env()?;
        match config.provider {
            TraceRemoteObjectStoreProvider::FileSystem => {
                let key = key.context(
                    "TRACE_COMMONS_OBJECT_STORE=remote_service with provider=file_system requires TRACE_COMMONS_ARTIFACT_KEY_HEX",
                )?;
                return Ok(Some(ConfiguredTraceArtifactStore::remote_service(
                    config,
                    SecretString::from(key),
                )?));
            }
            #[cfg(feature = "gcs-client")]
            TraceRemoteObjectStoreProvider::Gcs => {
                let key = key.context(
                    "TRACE_COMMONS_OBJECT_STORE=remote_service with provider=gcs requires TRACE_COMMONS_ARTIFACT_KEY_HEX",
                )?;
                return Ok(Some(
                    ConfiguredTraceArtifactStore::remote_gcs(config, SecretString::from(key))
                        .await?,
                ));
            }
            _ => {}
        }
        return Ok(Some(ConfiguredTraceArtifactStore::remote_disabled(config)));
    }
    let key = key.context(
        "encrypted Trace Commons object storage requires TRACE_COMMONS_ARTIFACT_KEY_HEX",
    )?;
    let root = encrypted_store_kind.root_from_env(default_root);
    let object_store_name = encrypted_store_kind.object_store_name();
    let crypto = SecretsCrypto::new(SecretString::from(key))
        .context("failed to initialize Trace Commons artifact encryption")?;
    Ok(Some(ConfiguredTraceArtifactStore::new(
        object_store_name,
        Arc::new(LocalEncryptedTraceArtifactStore::new(root, crypto)),
    )))
}

