/// Build the `Arc<dyn TraceGateService>` carried on `AppState`.
///
/// Selected at startup via `TRACE_COMMONS_GATE_SERVICE`:
///
/// - unset / `""` / `"in_memory"` (default for dev): `InMemoryGateService`
///   stamped with `gate_policy_version = "in_memory_default"` so decision rows
///   are clearly tagged.
/// - `"enclave_mock"`: `EnclaveGateService` wired with the mock perplexity /
///   embedder / vector-index pipeline plus a `LocalMasterKeyWrapper` keyed by
///   `TRACE_COMMONS_GATE_SERVICE_MASTER_KEY`. Used to exercise the
///   ciphertext + wrapped-DEK plumbing end-to-end.
/// - `"enclave_local_gpu"` (only available when the `local-gpu-models` cargo
///   feature is compiled in): `EnclaveGateService` wired with the
///   mistralrs-backed `LocalPerplexityScorer` + `FastEmbedTextEmbedder` +
///   `MockVectorIndex`. Reads `TRACE_COMMONS_PERPLEXITY_MODEL_PATH`
///   (required), `TRACE_COMMONS_PERPLEXITY_MODEL_ID`,
///   `TRACE_COMMONS_PERPLEXITY_DEVICE`, `TRACE_COMMONS_PERPLEXITY_MAX_TOKENS`,
///   `TRACE_COMMONS_PERPLEXITY_TAIL_LOGPROB_CUTOFF`,
///   `TRACE_COMMONS_EMBEDDER_MODEL_ID`, `TRACE_COMMONS_EMBEDDER_CACHE_DIR`,
///   `TRACE_COMMONS_EMBEDDER_MAX_TOKENS`,
///   `TRACE_COMMONS_EMBEDDER_MATRYOSHKA_DIM`, and the same
///   `TRACE_COMMONS_GATE_SERVICE_MASTER_KEY` as `enclave_mock`. The candle
///   forward pass and fastembed inference are hardware-untested in this
///   repo's CI; A4 will swap the mock vector index for the production
///   implementation.
/// - `"dstack"`: fail-closed `DstackGateService` stub. Operator-supplied
///   `TRACE_COMMONS_GATE_SERVICE_ENCLAVE_ENDPOINT` and
///   `TRACE_COMMONS_GATE_SERVICE_ATTESTATION_VERIFIER_LABEL` are accepted but
///   only surfaced as labels — every `evaluate_trace` call still bails until
///   the dstack client lands.
///
/// Any other value fails startup with a hash-only "GateServiceUnknown" label.
async fn build_trace_gate_service_from_env() -> anyhow::Result<Arc<dyn TraceGateService>> {
    let raw = std::env::var(TRACE_COMMONS_GATE_SERVICE).unwrap_or_default();
    let kind = raw.trim();
    match kind {
        "" | "in_memory" => Ok(Arc::new(InMemoryGateService::new(
            "in_memory_default",
            "sha256:in_memory_default",
        ))),
        "enclave_mock" => {
            let master_key = std::env::var(TRACE_COMMONS_GATE_SERVICE_MASTER_KEY)
                .with_context(|| {
                    format!(
                        "{TRACE_COMMONS_GATE_SERVICE_MASTER_KEY} must be set when {TRACE_COMMONS_GATE_SERVICE}=\"enclave_mock\""
                    )
                })?;
            let crypto = SecretsCrypto::new(SecretString::from(master_key))
                .context("failed to initialize gate-service KEK wrapper")?;
            let wrapper: Arc<dyn KmsKeyWrapper> = Arc::new(LocalMasterKeyWrapper::new(
                crypto,
                "trace-commons-gate-enclave-mock-v1",
            ));
            Ok(Arc::new(EnclaveGateService::mock_with_decryptor(wrapper)))
        }
        #[cfg(feature = "local-gpu-models")]
        "enclave_local_gpu" => build_enclave_local_gpu_gate_service_from_env().await,
        #[cfg(not(feature = "local-gpu-models"))]
        "enclave_local_gpu" => {
            anyhow::bail!(
                "{TRACE_COMMONS_GATE_SERVICE}=\"enclave_local_gpu\" requires the trace-commons-server `local-gpu-models` cargo feature; rebuild with --features local-gpu-models"
            );
        }
        #[cfg(feature = "near-ai-scorer")]
        "enclave_near_ai" => build_enclave_near_ai_gate_service_from_env().await,
        #[cfg(not(feature = "near-ai-scorer"))]
        "enclave_near_ai" => {
            anyhow::bail!(
                "{TRACE_COMMONS_GATE_SERVICE}=\"enclave_near_ai\" requires the trace-commons-server `near-ai-scorer` cargo feature; rebuild with --features near-ai-scorer"
            );
        }
        "dstack" => {
            let endpoint =
                std::env::var(TRACE_COMMONS_GATE_SERVICE_ENCLAVE_ENDPOINT).unwrap_or_default();
            let verifier_label =
                std::env::var(TRACE_COMMONS_GATE_SERVICE_ATTESTATION_VERIFIER_LABEL)
                    .unwrap_or_default();
            Ok(Arc::new(DstackGateService::new(endpoint, verifier_label)))
        }
        other => {
            // Hash-only label avoids leaking misconfigured operator-set values.
            let mut h = Sha256::new();
            h.update(other.as_bytes());
            anyhow::bail!("GateServiceUnknown: sha256:{:x}", h.finalize())
        }
    }
}

/// Build the `enclave_local_gpu` gate service: mistralrs-backed perplexity
/// scorer + fastembed-rs embedder + mock vector index. Returns a fail-closed
/// error if the perplexity model path is unset, mistralrs rejects the
/// staged checkpoint, or fastembed cannot load its ONNX model from the
/// configured cache directory.
///
/// The mistralrs forward path and fastembed inference are hardware-untested
/// in this repo's CI; first production deployment must verify a non-zero
/// perplexity on a known input and a unit-normalized embedding before the
/// gate is allowed to drive credit emission.
#[cfg(feature = "local-gpu-models")]
async fn build_enclave_local_gpu_gate_service_from_env() -> anyhow::Result<Arc<dyn TraceGateService>>
{
    use trace_commons_gate_enclave::embedder_fastembed::FastEmbedTextEmbedder;
    use trace_commons_gate_enclave::perplexity_local::{CandleDeviceKind, LocalPerplexityScorer};
    use trace_commons_gate_enclave::vector_index_usearch::{
        UsearchVectorIndex, UsearchVectorIndexConfig,
    };
    use trace_commons_gate_enclave::{EnclaveGateOrchestrator, EnclaveGateOrchestratorConfig};

    let master_key = std::env::var(TRACE_COMMONS_GATE_SERVICE_MASTER_KEY).with_context(|| {
        format!(
            "{TRACE_COMMONS_GATE_SERVICE_MASTER_KEY} must be set when {TRACE_COMMONS_GATE_SERVICE}=\"enclave_local_gpu\""
        )
    })?;
    let crypto = SecretsCrypto::new(SecretString::from(master_key))
        .context("failed to initialize gate-service KEK wrapper")?;
    let wrapper: Arc<dyn KmsKeyWrapper> = Arc::new(LocalMasterKeyWrapper::new(
        crypto,
        "trace-commons-gate-enclave-local-gpu-v1",
    ));

    let model_path = std::env::var(TRACE_COMMONS_PERPLEXITY_MODEL_PATH).with_context(|| {
        format!(
            "{TRACE_COMMONS_PERPLEXITY_MODEL_PATH} must be set when {TRACE_COMMONS_GATE_SERVICE}=\"enclave_local_gpu\""
        )
    })?;
    let model_id = std::env::var(TRACE_COMMONS_PERPLEXITY_MODEL_ID)
        .unwrap_or_else(|_| TRACE_COMMONS_PERPLEXITY_DEFAULT_MODEL_ID.to_string());
    let device_raw =
        std::env::var(TRACE_COMMONS_PERPLEXITY_DEVICE).unwrap_or_else(|_| "cuda".to_string());
    let device = CandleDeviceKind::from_env_str(&device_raw).with_context(|| {
        format!("{TRACE_COMMONS_PERPLEXITY_DEVICE} must be one of: cuda, cuda:N, metal, cpu")
    })?;
    let max_tokens = match std::env::var(TRACE_COMMONS_PERPLEXITY_MAX_TOKENS) {
        Ok(raw) => raw.trim().parse::<usize>().with_context(|| {
            format!("{TRACE_COMMONS_PERPLEXITY_MAX_TOKENS} must be a positive integer")
        })?,
        Err(_) => TRACE_COMMONS_PERPLEXITY_DEFAULT_MAX_TOKENS,
    };
    anyhow::ensure!(
        max_tokens > 0,
        "{TRACE_COMMONS_PERPLEXITY_MAX_TOKENS} must be greater than zero"
    );
    let tail_cutoff = match std::env::var(TRACE_COMMONS_PERPLEXITY_TAIL_LOGPROB_CUTOFF) {
        Ok(raw) => raw.trim().parse::<f32>().with_context(|| {
            format!(
                "{TRACE_COMMONS_PERPLEXITY_TAIL_LOGPROB_CUTOFF} must be a floating-point number"
            )
        })?,
        Err(_) => TRACE_COMMONS_PERPLEXITY_DEFAULT_TAIL_LOGPROB_CUTOFF,
    };
    anyhow::ensure!(
        tail_cutoff.is_finite(),
        "{TRACE_COMMONS_PERPLEXITY_TAIL_LOGPROB_CUTOFF} must be finite"
    );

    // A2.3: TRACE_COMMONS_PERPLEXITY_MODEL_ARCH is deprecated. mistralrs
    // auto-detects the architecture from `config.json`. We continue to
    // honor the env var's *presence* by emitting a deprecation warning so
    // operators flip their configs, but the value is otherwise ignored.
    if std::env::var(TRACE_COMMONS_PERPLEXITY_MODEL_ARCH).is_ok() {
        tracing::warn!(
            deprecated_env = TRACE_COMMONS_PERPLEXITY_MODEL_ARCH,
            "TRACE_COMMONS_PERPLEXITY_MODEL_ARCH is deprecated; mistralrs auto-detects \
             architecture from config.json"
        );
    }

    let scorer =
        LocalPerplexityScorer::try_new(model_id, &model_path, device, tail_cutoff, max_tokens)
            .context("LocalPerplexityScorerInitFailed")?;

    // fastembed-rs embedder (Phase A3). Loads the configured sentence
    // embedder once at startup; same H100 hosts both this and the candle
    // perplexity scorer.
    let embedder_model_id = std::env::var(TRACE_COMMONS_EMBEDDER_MODEL_ID)
        .unwrap_or_else(|_| TRACE_COMMONS_EMBEDDER_DEFAULT_MODEL_ID.to_string());
    let embedder_cache_dir = std::env::var(TRACE_COMMONS_EMBEDDER_CACHE_DIR)
        .unwrap_or_else(|_| TRACE_COMMONS_EMBEDDER_DEFAULT_CACHE_DIR.to_string());
    let embedder_max_tokens = match std::env::var(TRACE_COMMONS_EMBEDDER_MAX_TOKENS) {
        Ok(raw) => raw.trim().parse::<usize>().with_context(|| {
            format!("{TRACE_COMMONS_EMBEDDER_MAX_TOKENS} must be a positive integer")
        })?,
        Err(_) => TRACE_COMMONS_EMBEDDER_DEFAULT_MAX_TOKENS,
    };
    anyhow::ensure!(
        embedder_max_tokens > 0,
        "{TRACE_COMMONS_EMBEDDER_MAX_TOKENS} must be greater than zero"
    );
    let embedder_matryoshka_dim = match std::env::var(TRACE_COMMONS_EMBEDDER_MATRYOSHKA_DIM) {
        Ok(raw) => {
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                None
            } else {
                Some(trimmed.parse::<usize>().with_context(|| {
                    format!("{TRACE_COMMONS_EMBEDDER_MATRYOSHKA_DIM} must be a positive integer")
                })?)
            }
        }
        Err(_) => None,
    };
    if let Some(d) = embedder_matryoshka_dim {
        anyhow::ensure!(
            d > 0,
            "{TRACE_COMMONS_EMBEDDER_MATRYOSHKA_DIM} must be greater than zero"
        );
    }
    let embedder = FastEmbedTextEmbedder::try_new(
        embedder_model_id,
        &embedder_cache_dir,
        embedder_matryoshka_dim,
        embedder_max_tokens,
    )
    .await
    .context("FastEmbedTextEmbedderInitFailed")?;

    // usearch-backed vector index (Phase A4). Disk-backed, per-tenant.
    let vector_index_root = std::env::var(TRACE_COMMONS_VECTOR_INDEX_ROOT)
        .unwrap_or_else(|_| TRACE_COMMONS_VECTOR_INDEX_DEFAULT_ROOT.to_string());
    let vector_index_dim = parse_usize_env(
        TRACE_COMMONS_VECTOR_INDEX_DIM,
        TRACE_COMMONS_VECTOR_INDEX_DEFAULT_DIM,
    )?;
    let vector_index_max_open = parse_usize_env(
        TRACE_COMMONS_VECTOR_INDEX_MAX_OPEN,
        TRACE_COMMONS_VECTOR_INDEX_DEFAULT_MAX_OPEN,
    )?;
    let vector_index_flush_every = parse_usize_env(
        TRACE_COMMONS_VECTOR_INDEX_FLUSH_EVERY,
        TRACE_COMMONS_VECTOR_INDEX_DEFAULT_FLUSH_EVERY,
    )?;
    let vector_index_hnsw_m = parse_usize_env(
        TRACE_COMMONS_VECTOR_INDEX_HNSW_M,
        TRACE_COMMONS_VECTOR_INDEX_DEFAULT_HNSW_M,
    )?;
    let vector_index_ef_construction = parse_usize_env(
        TRACE_COMMONS_VECTOR_INDEX_EF_CONSTRUCTION,
        TRACE_COMMONS_VECTOR_INDEX_DEFAULT_EF_CONSTRUCTION,
    )?;
    let vector_index_ef_search = parse_usize_env(
        TRACE_COMMONS_VECTOR_INDEX_EF_SEARCH,
        TRACE_COMMONS_VECTOR_INDEX_DEFAULT_EF_SEARCH,
    )?;
    let vector_index_flush_interval = vector_index_flush_interval_from_env()?;
    let vector_index = UsearchVectorIndex::try_new(
        &vector_index_root,
        UsearchVectorIndexConfig {
            dim: vector_index_dim,
            hnsw_m: vector_index_hnsw_m,
            ef_construction: vector_index_ef_construction,
            ef_search: vector_index_ef_search,
            max_open: vector_index_max_open,
            flush_every: vector_index_flush_every,
            flush_interval: vector_index_flush_interval,
        },
    )
    .with_context(|| {
        format!(
            "failed to initialize UsearchVectorIndex (root={vector_index_root}, dim={vector_index_dim})"
        )
    })?;

    // Embedder/vector-index dim agreement is load-bearing: if usearch is
    // configured for dim D but the embedder produces dim D', every insert
    // would fail with a dim-mismatch at first eval. Refuse at startup.
    anyhow::ensure!(
        embedder.output_dim() == vector_index_dim,
        "embedder output_dim ({}) must equal {} ({})",
        embedder.output_dim(),
        TRACE_COMMONS_VECTOR_INDEX_DIM,
        vector_index_dim,
    );

    // Real env-driven orchestrator config. The previous `mock_default()` had
    // zero floors AND a fixed gate_policy_version ("enclave_mock_v1") — under
    // those settings every trace passes the gate trivially and every credit
    // event is stamped with a placeholder version hash. Both are blocked at
    // startup here.
    let perplexity_floor_micros =
        parse_required_u64_env(TRACE_COMMONS_GATE_PERPLEXITY_FLOOR_MICROS)?;
    let tail_fraction_floor_micros =
        parse_required_u64_env(TRACE_COMMONS_GATE_TAIL_FRACTION_FLOOR_MICROS)?;
    let novelty_floor_micros = parse_required_u64_env(TRACE_COMMONS_GATE_NOVELTY_FLOOR_MICROS)?;
    anyhow::ensure!(
        perplexity_floor_micros > 0 || tail_fraction_floor_micros > 0 || novelty_floor_micros > 0,
        "{}/{}/{} cannot all be zero — at least one gate floor must be positive",
        TRACE_COMMONS_GATE_PERPLEXITY_FLOOR_MICROS,
        TRACE_COMMONS_GATE_TAIL_FRACTION_FLOOR_MICROS,
        TRACE_COMMONS_GATE_NOVELTY_FLOOR_MICROS,
    );
    let gate_policy_version =
        std::env::var(TRACE_COMMONS_GATE_POLICY_VERSION).with_context(|| {
            format!(
                "{} must be set when {}=\"enclave_local_gpu\"",
                TRACE_COMMONS_GATE_POLICY_VERSION, TRACE_COMMONS_GATE_SERVICE,
            )
        })?;
    anyhow::ensure!(
        !gate_policy_version.trim().is_empty(),
        "{} must be non-empty",
        TRACE_COMMONS_GATE_POLICY_VERSION,
    );
    let top_k = parse_usize_env(TRACE_COMMONS_GATE_TOP_K, TRACE_COMMONS_GATE_DEFAULT_TOP_K)?;
    let chunking = parse_gate_chunking_config_from_env()?;

    let gate_version_hash = compute_gate_version_hash(
        &gate_policy_version,
        perplexity_floor_micros,
        tail_fraction_floor_micros,
        novelty_floor_micros,
        top_k,
        &std::env::var(TRACE_COMMONS_PERPLEXITY_MODEL_ID)
            .unwrap_or_else(|_| TRACE_COMMONS_PERPLEXITY_DEFAULT_MODEL_ID.to_string()),
        max_tokens,
        tail_cutoff,
        &std::env::var(TRACE_COMMONS_EMBEDDER_MODEL_ID)
            .unwrap_or_else(|_| TRACE_COMMONS_EMBEDDER_DEFAULT_MODEL_ID.to_string()),
        embedder_max_tokens,
        embedder_matryoshka_dim,
        vector_index_dim,
        chunking.chunk_target_tokens,
        chunking.chunk_max_tokens,
        chunking.chunk_cap,
        chunking.chunk_min_tokens,
        chunking.embed_insert_novelty_micros,
    );

    let cfg = EnclaveGateOrchestratorConfig {
        gate_policy_version,
        gate_version_hash,
        perplexity_floor_micros,
        tail_fraction_floor_micros,
        novelty_floor_micros,
        top_k,
        chunk_target_tokens: chunking.chunk_target_tokens,
        chunk_max_tokens: chunking.chunk_max_tokens,
        chunk_cap: chunking.chunk_cap,
        chunk_min_tokens: chunking.chunk_min_tokens,
        embed_insert_novelty_micros: chunking.embed_insert_novelty_micros,
        qualifying_chunk_floor_micros: chunking
            .qualifying_chunk_floor_micros
            .unwrap_or(perplexity_floor_micros),
    };
    let orchestrator = EnclaveGateOrchestrator::new(scorer, embedder, vector_index, cfg);
    Ok(Arc::new(EnclaveGateService::new(
        orchestrator,
        wrapper,
        "enclave_local_gpu",
    )))
}

/// Build the `enclave_near_ai` gate service: NEAR AI Cloud-backed perplexity
/// scorer (HTTP, TEE-hosted vLLM) + fastembed-rs embedder + usearch vector
/// index. The embedder and vector index run locally on CPU — the GPU work is
/// the perplexity scoring, which the NEAR AI host owns. This is the pilot
/// deployment path that removes the local CUDA / mistralrs dependency from
/// the production server.
///
/// Required env vars:
/// - `TRACE_COMMONS_NEAR_AI_BASE_URL` — direct-completions endpoint, e.g.
///   `https://qwen3-6-35b.completions.near.ai/v1`. No trailing slash.
/// - `TRACE_COMMONS_NEAR_AI_MODEL` — model id passed to the API, e.g.
///   `Qwen/Qwen3.6-35B-A3B-FP8`.
/// - `TRACE_COMMONS_NEAR_AI_API_KEY` — bearer token (never logged, never
///   accepted on the CLI).
/// - The same gate-floor / policy-version / embedder / vector-index env
///   vars as `enclave_local_gpu`.
#[cfg(feature = "near-ai-scorer")]
async fn build_enclave_near_ai_gate_service_from_env() -> anyhow::Result<Arc<dyn TraceGateService>>
{
    use std::time::Duration as StdDuration;
    use trace_commons_gate_enclave::embedder_fastembed::FastEmbedTextEmbedder;
    use trace_commons_gate_enclave::vector_index_usearch::{
        UsearchVectorIndex, UsearchVectorIndexConfig,
    };
    use trace_commons_gate_enclave::{
        EnclaveGateOrchestrator, EnclaveGateOrchestratorConfig, NearAiPerplexityScorer,
        NearAiScorerConfig,
    };

    let master_key = std::env::var(TRACE_COMMONS_GATE_SERVICE_MASTER_KEY).with_context(|| {
        format!(
            "{TRACE_COMMONS_GATE_SERVICE_MASTER_KEY} must be set when {TRACE_COMMONS_GATE_SERVICE}=\"enclave_near_ai\""
        )
    })?;
    // Decrypt each submission's DEK with the SAME KEK the artifact store used to
    // wrap it, selected by TRACE_COMMONS_KEK_PROVIDER. Hardcoding
    // LocalMasterKeyWrapper here broke every KMS-backed deployment: the stored
    // wrapped_dek carries the KMS wrapper_kind, so a local unwrapper fails with
    // "KekUnwrapFailed: wrapper kind mismatch" on every evaluation. For
    // local_master_key deployments this still resolves to a local wrapper (kind
    // "local_master_key"), keyed by the gate-service master key as before.
    let wrapper: Arc<dyn KmsKeyWrapper + Send + Sync> =
        Arc::from(build_selected_kek_wrapper_async(SecretString::from(master_key)).await?);
    let wrapper: Arc<dyn KmsKeyWrapper> = wrapper;

    let base_url = std::env::var(TRACE_COMMONS_NEAR_AI_BASE_URL).with_context(|| {
        format!(
            "{TRACE_COMMONS_NEAR_AI_BASE_URL} must be set when {TRACE_COMMONS_GATE_SERVICE}=\"enclave_near_ai\""
        )
    })?;
    let model = std::env::var(TRACE_COMMONS_NEAR_AI_MODEL).with_context(|| {
        format!(
            "{TRACE_COMMONS_NEAR_AI_MODEL} must be set when {TRACE_COMMONS_GATE_SERVICE}=\"enclave_near_ai\""
        )
    })?;
    let api_key = std::env::var(TRACE_COMMONS_NEAR_AI_API_KEY).with_context(|| {
        format!(
            "{TRACE_COMMONS_NEAR_AI_API_KEY} must be set when {TRACE_COMMONS_GATE_SERVICE}=\"enclave_near_ai\""
        )
    })?;
    let timeout_seconds = match std::env::var(TRACE_COMMONS_NEAR_AI_TIMEOUT_SECONDS) {
        Ok(raw) => {
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                TRACE_COMMONS_NEAR_AI_DEFAULT_TIMEOUT_SECONDS
            } else {
                trimmed.parse::<u64>().with_context(|| {
                    format!("{TRACE_COMMONS_NEAR_AI_TIMEOUT_SECONDS} must be a positive integer")
                })?
            }
        }
        Err(_) => TRACE_COMMONS_NEAR_AI_DEFAULT_TIMEOUT_SECONDS,
    };
    anyhow::ensure!(
        timeout_seconds > 0,
        "{TRACE_COMMONS_NEAR_AI_TIMEOUT_SECONDS} must be greater than zero"
    );
    let tail_cutoff = match std::env::var(TRACE_COMMONS_PERPLEXITY_TAIL_LOGPROB_CUTOFF) {
        Ok(raw) => raw.trim().parse::<f32>().with_context(|| {
            format!(
                "{TRACE_COMMONS_PERPLEXITY_TAIL_LOGPROB_CUTOFF} must be a floating-point number"
            )
        })?,
        Err(_) => TRACE_COMMONS_PERPLEXITY_DEFAULT_TAIL_LOGPROB_CUTOFF,
    };
    anyhow::ensure!(
        tail_cutoff.is_finite(),
        "{TRACE_COMMONS_PERPLEXITY_TAIL_LOGPROB_CUTOFF} must be finite"
    );

    let scorer_cfg = NearAiScorerConfig {
        base_url,
        model: model.clone(),
        api_key,
        tail_logprob_cutoff: tail_cutoff,
        logprobs_top_k: TRACE_COMMONS_NEAR_AI_DEFAULT_LOGPROBS_TOP_K,
        timeout: StdDuration::from_secs(timeout_seconds),
    };
    // reqwest's blocking client owns an internal Tokio runtime and must not be
    // constructed from this async startup task. Build it on the blocking pool,
    // which is also where synchronous gate evaluation runs below.
    let scorer = tokio::task::spawn_blocking(move || NearAiPerplexityScorer::try_new(scorer_cfg))
        .await
        .context("NearAiPerplexityScorerInitJoinFailed")?
        .context("NearAiPerplexityScorerInitFailed")?;

    // fastembed-rs embedder — same configuration surface as the local-GPU
    // path. Runs locally on CPU; no GPU required.
    let embedder_model_id = std::env::var(TRACE_COMMONS_EMBEDDER_MODEL_ID)
        .unwrap_or_else(|_| TRACE_COMMONS_EMBEDDER_DEFAULT_MODEL_ID.to_string());
    let embedder_cache_dir = std::env::var(TRACE_COMMONS_EMBEDDER_CACHE_DIR)
        .unwrap_or_else(|_| TRACE_COMMONS_EMBEDDER_DEFAULT_CACHE_DIR.to_string());
    let embedder_max_tokens = match std::env::var(TRACE_COMMONS_EMBEDDER_MAX_TOKENS) {
        Ok(raw) => raw.trim().parse::<usize>().with_context(|| {
            format!("{TRACE_COMMONS_EMBEDDER_MAX_TOKENS} must be a positive integer")
        })?,
        Err(_) => TRACE_COMMONS_EMBEDDER_DEFAULT_MAX_TOKENS,
    };
    anyhow::ensure!(
        embedder_max_tokens > 0,
        "{TRACE_COMMONS_EMBEDDER_MAX_TOKENS} must be greater than zero"
    );
    let embedder_matryoshka_dim = match std::env::var(TRACE_COMMONS_EMBEDDER_MATRYOSHKA_DIM) {
        Ok(raw) => {
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                None
            } else {
                Some(trimmed.parse::<usize>().with_context(|| {
                    format!("{TRACE_COMMONS_EMBEDDER_MATRYOSHKA_DIM} must be a positive integer")
                })?)
            }
        }
        Err(_) => None,
    };
    if let Some(d) = embedder_matryoshka_dim {
        anyhow::ensure!(
            d > 0,
            "{TRACE_COMMONS_EMBEDDER_MATRYOSHKA_DIM} must be greater than zero"
        );
    }
    let embedder = FastEmbedTextEmbedder::try_new(
        embedder_model_id.clone(),
        &embedder_cache_dir,
        embedder_matryoshka_dim,
        embedder_max_tokens,
    )
    .await
    .context("FastEmbedTextEmbedderInitFailed")?;

    let vector_index_root = std::env::var(TRACE_COMMONS_VECTOR_INDEX_ROOT)
        .unwrap_or_else(|_| TRACE_COMMONS_VECTOR_INDEX_DEFAULT_ROOT.to_string());
    let vector_index_dim = parse_usize_env(
        TRACE_COMMONS_VECTOR_INDEX_DIM,
        TRACE_COMMONS_VECTOR_INDEX_DEFAULT_DIM,
    )?;
    let vector_index_max_open = parse_usize_env(
        TRACE_COMMONS_VECTOR_INDEX_MAX_OPEN,
        TRACE_COMMONS_VECTOR_INDEX_DEFAULT_MAX_OPEN,
    )?;
    let vector_index_flush_every = parse_usize_env(
        TRACE_COMMONS_VECTOR_INDEX_FLUSH_EVERY,
        TRACE_COMMONS_VECTOR_INDEX_DEFAULT_FLUSH_EVERY,
    )?;
    let vector_index_hnsw_m = parse_usize_env(
        TRACE_COMMONS_VECTOR_INDEX_HNSW_M,
        TRACE_COMMONS_VECTOR_INDEX_DEFAULT_HNSW_M,
    )?;
    let vector_index_ef_construction = parse_usize_env(
        TRACE_COMMONS_VECTOR_INDEX_EF_CONSTRUCTION,
        TRACE_COMMONS_VECTOR_INDEX_DEFAULT_EF_CONSTRUCTION,
    )?;
    let vector_index_ef_search = parse_usize_env(
        TRACE_COMMONS_VECTOR_INDEX_EF_SEARCH,
        TRACE_COMMONS_VECTOR_INDEX_DEFAULT_EF_SEARCH,
    )?;
    let vector_index_flush_interval = vector_index_flush_interval_from_env()?;
    let vector_index = UsearchVectorIndex::try_new(
        &vector_index_root,
        UsearchVectorIndexConfig {
            dim: vector_index_dim,
            hnsw_m: vector_index_hnsw_m,
            ef_construction: vector_index_ef_construction,
            ef_search: vector_index_ef_search,
            max_open: vector_index_max_open,
            flush_every: vector_index_flush_every,
            flush_interval: vector_index_flush_interval,
        },
    )
    .with_context(|| {
        format!(
            "failed to initialize UsearchVectorIndex (root={vector_index_root}, dim={vector_index_dim})"
        )
    })?;

    anyhow::ensure!(
        embedder.output_dim() == vector_index_dim,
        "embedder output_dim ({}) must equal {} ({})",
        embedder.output_dim(),
        TRACE_COMMONS_VECTOR_INDEX_DIM,
        vector_index_dim,
    );

    let perplexity_floor_micros =
        parse_required_u64_env(TRACE_COMMONS_GATE_PERPLEXITY_FLOOR_MICROS)?;
    let tail_fraction_floor_micros =
        parse_required_u64_env(TRACE_COMMONS_GATE_TAIL_FRACTION_FLOOR_MICROS)?;
    let novelty_floor_micros = parse_required_u64_env(TRACE_COMMONS_GATE_NOVELTY_FLOOR_MICROS)?;
    anyhow::ensure!(
        perplexity_floor_micros > 0 || tail_fraction_floor_micros > 0 || novelty_floor_micros > 0,
        "{}/{}/{} cannot all be zero — at least one gate floor must be positive",
        TRACE_COMMONS_GATE_PERPLEXITY_FLOOR_MICROS,
        TRACE_COMMONS_GATE_TAIL_FRACTION_FLOOR_MICROS,
        TRACE_COMMONS_GATE_NOVELTY_FLOOR_MICROS,
    );
    let gate_policy_version =
        std::env::var(TRACE_COMMONS_GATE_POLICY_VERSION).with_context(|| {
            format!(
                "{} must be set when {}=\"enclave_near_ai\"",
                TRACE_COMMONS_GATE_POLICY_VERSION, TRACE_COMMONS_GATE_SERVICE,
            )
        })?;
    anyhow::ensure!(
        !gate_policy_version.trim().is_empty(),
        "{} must be non-empty",
        TRACE_COMMONS_GATE_POLICY_VERSION,
    );
    let top_k = parse_usize_env(TRACE_COMMONS_GATE_TOP_K, TRACE_COMMONS_GATE_DEFAULT_TOP_K)?;
    let chunking = parse_gate_chunking_config_from_env()?;

    // Gate version hash mixes in the perplexity *model id* (which here is
    // the NEAR AI hosted model name) so rotating the hosted model produces a
    // distinct audit trail. `max_tokens` is left at 0 for the NEAR AI arm —
    // the hosted endpoint enforces its own input cap and we don't drive it
    // from a client-side env.
    let gate_version_hash = compute_gate_version_hash(
        &gate_policy_version,
        perplexity_floor_micros,
        tail_fraction_floor_micros,
        novelty_floor_micros,
        top_k,
        &model,
        0,
        tail_cutoff,
        &embedder_model_id,
        embedder_max_tokens,
        embedder_matryoshka_dim,
        vector_index_dim,
        chunking.chunk_target_tokens,
        chunking.chunk_max_tokens,
        chunking.chunk_cap,
        chunking.chunk_min_tokens,
        chunking.embed_insert_novelty_micros,
    );

    let cfg = EnclaveGateOrchestratorConfig {
        gate_policy_version,
        gate_version_hash,
        perplexity_floor_micros,
        tail_fraction_floor_micros,
        novelty_floor_micros,
        top_k,
        chunk_target_tokens: chunking.chunk_target_tokens,
        chunk_max_tokens: chunking.chunk_max_tokens,
        chunk_cap: chunking.chunk_cap,
        chunk_min_tokens: chunking.chunk_min_tokens,
        embed_insert_novelty_micros: chunking.embed_insert_novelty_micros,
        qualifying_chunk_floor_micros: chunking
            .qualifying_chunk_floor_micros
            .unwrap_or(perplexity_floor_micros),
    };
    let orchestrator = EnclaveGateOrchestrator::new(scorer, embedder, vector_index, cfg);
    Ok(Arc::new(EnclaveGateService::new(
        orchestrator,
        wrapper,
        "enclave_near_ai",
    )))
}

/// Build the cross-trace dedup vector index (shadow-only). A SEPARATE
/// `UsearchVectorIndex` instance from the novelty index built above — the
/// two must never share a root, or a dedup lookup would return novelty's
/// neighbors (and vice versa), silently changing novelty scoring.
///
/// Uses the same dim/hnsw/ef/max_open/flush_every knobs as the novelty index
/// (`TRACE_COMMONS_VECTOR_INDEX_*`) so the two indexes stay dimensionally
/// compatible with the shared embedder, but reads its OWN root from
/// `TRACE_COMMONS_DEDUP_VECTOR_INDEX_ROOT`, defaulting to a sibling
/// directory of the novelty root (`<novelty_root>/../dedup-index`).
///
/// Fail-open by design: dedup is shadow-only (no settlement, no gating), so
/// a construction failure here must not take down the server. On error this
/// logs a hash-only warning and returns `None`; `dedup_index_query`/
/// `dedup_index_insert` already no-op on `None`, so the simhash-only dedup
/// signal keeps working.
#[cfg(any(feature = "local-gpu-models", feature = "near-ai-scorer"))]
fn build_dedup_vector_index_from_env() -> Option<Arc<dyn trace_commons_gate_enclave::VectorIndex>> {
    use trace_commons_gate_enclave::vector_index_usearch::{
        UsearchVectorIndex, UsearchVectorIndexConfig,
    };

    let novelty_root = std::env::var(TRACE_COMMONS_VECTOR_INDEX_ROOT)
        .unwrap_or_else(|_| TRACE_COMMONS_VECTOR_INDEX_DEFAULT_ROOT.to_string());
    let dedup_root = std::env::var(TRACE_COMMONS_DEDUP_VECTOR_INDEX_ROOT)
        .unwrap_or_else(|_| format!("{novelty_root}/../dedup-index"));

    let result = (|| -> anyhow::Result<UsearchVectorIndex> {
        let dim = parse_usize_env(
            TRACE_COMMONS_VECTOR_INDEX_DIM,
            TRACE_COMMONS_VECTOR_INDEX_DEFAULT_DIM,
        )?;
        let max_open = parse_usize_env(
            TRACE_COMMONS_VECTOR_INDEX_MAX_OPEN,
            TRACE_COMMONS_VECTOR_INDEX_DEFAULT_MAX_OPEN,
        )?;
        let flush_every = parse_usize_env(
            TRACE_COMMONS_VECTOR_INDEX_FLUSH_EVERY,
            TRACE_COMMONS_VECTOR_INDEX_DEFAULT_FLUSH_EVERY,
        )?;
        let hnsw_m = parse_usize_env(
            TRACE_COMMONS_VECTOR_INDEX_HNSW_M,
            TRACE_COMMONS_VECTOR_INDEX_DEFAULT_HNSW_M,
        )?;
        let ef_construction = parse_usize_env(
            TRACE_COMMONS_VECTOR_INDEX_EF_CONSTRUCTION,
            TRACE_COMMONS_VECTOR_INDEX_DEFAULT_EF_CONSTRUCTION,
        )?;
        let ef_search = parse_usize_env(
            TRACE_COMMONS_VECTOR_INDEX_EF_SEARCH,
            TRACE_COMMONS_VECTOR_INDEX_DEFAULT_EF_SEARCH,
        )?;
        UsearchVectorIndex::try_new(
            &dedup_root,
            UsearchVectorIndexConfig {
                dim,
                hnsw_m,
                ef_construction,
                ef_search,
                max_open,
                flush_every,
                flush_interval: vector_index_flush_interval_from_env()?,
            },
        )
        .with_context(|| format!("failed to initialize dedup UsearchVectorIndex (dim={dim})"))
    })();

    match result {
        Ok(index) => Some(Arc::new(index)),
        Err(error) => {
            tracing::warn!(
                error_class = "DedupVectorIndexInitFailed",
                error_hash = %safe_runtime_error_hash(&error),
                "dedup vector index init failed; falling back to simhash-only dedup"
            );
            None
        }
    }
}

/// Cross-trace dedup helpers (shadow-only). Both are fail-open: `None`
/// index -> no-op/empty, and a live index still never returns an `Err` to
/// the caller — any usearch failure is logged hash-only and treated as "no
/// signal" so the simhash-only dedup path is unaffected.
///
/// Not yet called outside tests: Task 6 wires these into
/// `evaluate_and_record_gate`.
#[allow(dead_code)]
#[cfg(any(feature = "local-gpu-models", feature = "near-ai-scorer"))]
impl AppState {
    /// Query the dedup vector index for the `k` nearest neighbors of
    /// `embedding`. Returns `(decision_id, cosine_distance_micros)` pairs,
    /// nearest first (matching `UsearchVectorIndex::nearest`'s ordering).
    /// `cosine_distance_micros = round((1.0 - cosine_similarity) * 1e6)`,
    /// consistent with `dedup_assign::ClusterCandidate::embed_cosine_micros`
    /// and `DEDUP_CONSTANTS_V1.tau_e_micros`.
    ///
    /// Empty when the index is `None` (not configured / failed to init at
    /// startup) — the simhash signal still works without it. Each neighbor's
    /// usearch key (the high 8 bytes of the returned `Uuid`, which `insert`
    /// set to a unique counter) is resolved to the real decision_id via
    /// `dedup_vector_index_id_map`. A neighbor whose key has no map entry
    /// (process-restart gap; see that field's doc comment) is SKIPPED rather
    /// than fabricating an id — there are no silent wrong answers.
    fn dedup_index_query(&self, embedding: &[f32], k: usize) -> Vec<(Uuid, i64)> {
        let Some(index) = self.dedup_vector_index.as_ref() else {
            return Vec::new();
        };
        // All dedup traffic shares one logical tenant namespace so matching
        // is cross-tenant by construction (dedup dedups across tenants,
        // unlike novelty which is per-tenant).
        let neighbors = match trace_commons_gate_enclave::vector_index::VectorIndex::nearest(
            index.as_ref(),
            DEDUP_VECTOR_INDEX_NAMESPACE,
            embedding,
            k,
        ) {
            Ok(n) => n,
            Err(error) => {
                tracing::warn!(
                    error_class = "DedupVectorIndexQueryFailed",
                    error_hash = %safe_runtime_error_hash(&error),
                    "dedup vector index query failed (non-fatal)"
                );
                return Vec::new();
            }
        };
        let id_map = self
            .dedup_vector_index_id_map
            .lock()
            .expect("dedup_vector_index_id_map mutex poisoned");
        let mut out = Vec::with_capacity(neighbors.len());
        for n in &neighbors {
            let key_bytes: [u8; 8] = match n.entry_id.as_bytes()[0..8].try_into() {
                Ok(b) => b,
                Err(_) => continue,
            };
            let key = u64::from_be_bytes(key_bytes);
            let Some(&decision_id) = id_map.get(&key) else {
                continue;
            };
            let distance_micros = ((1.0 - n.similarity) * 1_000_000.0).round() as i64;
            out.push((decision_id, distance_micros));
        }
        out
    }

    /// Insert `embedding` under `id` into the dedup vector index. No-op when
    /// the index is `None`. Non-fatal on failure: logs hash-only and
    /// returns without propagating the error, matching the fail-open
    /// contract the rest of the dedup shadow-scoring path relies on.
    ///
    /// The usearch entry is keyed by a fresh unique monotonic counter
    /// (`dedup_vector_index_counter`), NOT by `uuid_to_key(id)`. Keying by the
    /// truncated UUID would collide two distinct decision_ids sharing the same
    /// 8-byte prefix, silently clobbering the reverse-map entry and letting a
    /// later query return a fabricated wrong decision_id. `VectorIndex::insert`
    /// takes a `Uuid` and internally keys usearch via `uuid_to_key` (the high 8
    /// bytes, big-endian), so we synthesize a `Uuid` whose high 8 bytes ARE the
    /// counter — `Uuid::from_u128((counter as u128) << 64)` — making the
    /// usearch key exactly `counter`. We record `counter -> id` so the query
    /// side resolves the real decision_id back.
    fn dedup_index_insert(&self, id: Uuid, embedding: &[f32]) {
        let Some(index) = self.dedup_vector_index.as_ref() else {
            return;
        };
        let key = self
            .dedup_vector_index_counter
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        // Synthesize a Uuid whose high 8 bytes (what `uuid_to_key` reads) equal
        // `key`, so the usearch entry is keyed by the unique counter.
        let key_uuid = Uuid::from_u128((key as u128) << 64);
        if let Err(error) = trace_commons_gate_enclave::vector_index::VectorIndex::insert(
            index.as_ref(),
            key_uuid,
            DEDUP_VECTOR_INDEX_NAMESPACE,
            embedding,
        ) {
            tracing::warn!(
                error_class = "DedupVectorIndexInsertFailed",
                error_hash = %safe_runtime_error_hash(&error),
                "dedup vector index insert failed (non-fatal)"
            );
            return;
        }
        self.dedup_vector_index_id_map
            .lock()
            .expect("dedup_vector_index_id_map mutex poisoned")
            .insert(key, id);
    }
}

/// Fixed `VectorIndex` tenant-namespace key for the dedup index. Dedup is
/// intentionally cross-tenant (it dedups traces across tenants), unlike the
/// per-tenant novelty index, so every insert/query in the dedup index goes
/// through this single shared namespace rather than the caller's real
/// tenant id.
#[allow(dead_code)]
#[cfg(any(feature = "local-gpu-models", feature = "near-ai-scorer"))]
const DEDUP_VECTOR_INDEX_NAMESPACE: &str = "trace_commons_cross_trace_dedup_v1";

/// Parse a required `u64` env var. Returns an error if the var is unset,
/// empty, or doesn't parse. Used for the three gate floors that the
/// orchestrator config refuses to default.
#[cfg(any(feature = "local-gpu-models", feature = "near-ai-scorer"))]
fn parse_required_u64_env(var: &'static str) -> anyhow::Result<u64> {
    let raw = std::env::var(var)
        .with_context(|| format!("{var} must be set on the production gate-service path"))?;
    let trimmed = raw.trim();
    anyhow::ensure!(!trimmed.is_empty(), "{var} must not be empty");
    trimmed
        .parse::<u64>()
        .with_context(|| format!("{var} must parse as a non-negative integer"))
}

/// Stable canonical-bytes hash of every dimension that influences the gate
/// decision: policy version, floors, top-k, both model identifiers + token
/// caps, the vector index dim, the chunking knobs, the chunk-SELECTION
/// algorithm, and the canonical event RENDERER. Operators rotating any of
/// these MUST see the audit trail break
/// — the previous fixed `"sha256:enclave_mock_v1"` value stamped every
/// decision regardless of configuration.
///
/// Not feature-gated (unlike the gate-service wiring that calls it), for the
/// same reason as `parse_usize_env` above: this is a pure function whose
/// output is an audit-visible stamp, and the plain `cargo test` CI path is
/// the only one that runs tests, so gating it would leave the stamp
/// untested.
#[allow(dead_code)]
#[allow(clippy::too_many_arguments)]
fn compute_gate_version_hash(
    policy_version: &str,
    perplexity_floor_micros: u64,
    tail_fraction_floor_micros: u64,
    novelty_floor_micros: u64,
    top_k: usize,
    perplexity_model_id: &str,
    perplexity_max_tokens: usize,
    perplexity_tail_cutoff: f32,
    embedder_model_id: &str,
    embedder_max_tokens: usize,
    embedder_matryoshka_dim: Option<usize>,
    vector_index_dim: usize,
    chunk_target_tokens: usize,
    chunk_max_tokens: usize,
    chunk_cap: usize,
    chunk_min_tokens: u64,
    embed_insert_novelty_micros: u64,
) -> String {
    let canonical = format!(
        "trace_commons_gate_version.v1\n\
         policy={policy_version}\n\
         floors={perplexity_floor_micros},{tail_fraction_floor_micros},{novelty_floor_micros}\n\
         top_k={top_k}\n\
         perplexity={perplexity_model_id}:{perplexity_max_tokens}:{perplexity_tail_cutoff}\n\
         embedder={embedder_model_id}:{embedder_max_tokens}:{embedder_matryoshka_dim:?}\n\
         vector_dim={vector_index_dim}\n\
         chunking={chunk_target_tokens},{chunk_max_tokens},{chunk_cap},{chunk_min_tokens},{embed_insert_novelty_micros}\n\
         chunk_selection={chunk_selection}\n\
         render={render}",
        chunk_selection = trace_commons_gate_enclave::chunker::CHUNK_SELECTION_ALGORITHM,
        // Which chunks survive the cap and what the text inside them says are
        // separate dimensions: two decisions can select identical chunks and
        // still be incomparable because the renderer changed underneath them.
        // Without this line the stamp claims a decision is reproducible when
        // re-rendering the same envelope would move every signal.
        render = trace_commons_gate_enclave::chunker::CANONICAL_RENDER_VERSION,
    );
    let mut h = Sha256::new();
    h.update(canonical.as_bytes());
    format!("sha256:{:x}", h.finalize())
}

/// Resolve the periodic vector-index flush cadence.
///
/// Unset → the spec default (60 s). `0` → `None`, which disables the
/// background flusher entirely; that is a deliberate operator escape hatch,
/// not a routine setting, because it makes a signal-killed process lose every
/// corpus write since the last inline flush.
#[allow(dead_code)]
fn vector_index_flush_interval_from_env() -> anyhow::Result<Option<std::time::Duration>> {
    let seconds = match std::env::var(TRACE_COMMONS_VECTOR_INDEX_FLUSH_INTERVAL_SECONDS) {
        Ok(raw) => {
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                TRACE_COMMONS_VECTOR_INDEX_DEFAULT_FLUSH_INTERVAL_SECONDS
            } else {
                trimmed.parse::<u64>().with_context(|| {
                    format!(
                        "{TRACE_COMMONS_VECTOR_INDEX_FLUSH_INTERVAL_SECONDS} must be a non-negative integer"
                    )
                })?
            }
        }
        Err(_) => TRACE_COMMONS_VECTOR_INDEX_DEFAULT_FLUSH_INTERVAL_SECONDS,
    };
    Ok(if seconds == 0 {
        None
    } else {
        Some(std::time::Duration::from_secs(seconds))
    })
}

/// Parse `T = usize` from an env var with a default fallback. Trim + strict
/// integer parse; empty / unset → default; malformed → fail-closed.
///
/// Not feature-gated (unlike its sibling gate-config parsers): the chunk-knob
/// parser that reuses this reads env unconditionally so its defaults are
/// exercised by the plain `cargo test` CI path regardless of which optional
/// gate-service feature (if any) is compiled in.
fn parse_usize_env(var: &'static str, default: usize) -> anyhow::Result<usize> {
    match std::env::var(var) {
        Ok(raw) => {
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                Ok(default)
            } else {
                trimmed
                    .parse::<usize>()
                    .with_context(|| format!("{var} must be a non-negative integer"))
            }
        }
        Err(_) => Ok(default),
    }
}

