fn trace_review_lease_action_name(action: StorageTraceReviewLeaseAuditAction) -> &'static str {
    match action {
        StorageTraceReviewLeaseAuditAction::Claim => "claim",
        StorageTraceReviewLeaseAuditAction::Release => "release",
    }
}

fn trace_audit_reason_value<'a>(reason: Option<&'a str>, key: &str) -> Option<&'a str> {
    let prefix = format!("{key}=");
    reason?
        .split(';')
        .find_map(|part| part.strip_prefix(&prefix))
}

fn trace_audit_reason_u32(reason: Option<&str>, key: &str) -> Option<u32> {
    trace_audit_reason_value(reason, key)?.parse::<u32>().ok()
}

fn trace_audit_reason_u64(reason: Option<&str>, key: &str) -> Option<u64> {
    trace_audit_reason_value(reason, key)?.parse::<u64>().ok()
}

fn trace_audit_reason_bool(reason: Option<&str>, key: &str) -> Option<bool> {
    trace_audit_reason_value(reason, key)?.parse::<bool>().ok()
}

fn trace_maintenance_audit_purpose_hash(reason: Option<&str>) -> Option<String> {
    match trace_audit_reason_value(reason, "purpose_hash") {
        Some(hash) if is_canonical_sha256_prefixed_hash(hash) => Some(hash.to_string()),
        Some(_) => None,
        None => trace_audit_reason_value(reason, "purpose").map(sha256_prefixed),
    }
}

fn trace_maintenance_audit_reason_has_invalid_hash(reason: Option<&str>) -> bool {
    trace_audit_reason_value(reason, "purpose_hash")
        .is_some_and(|hash| !is_canonical_sha256_prefixed_hash(hash))
}

fn trace_maintenance_audit_action_counts_from_reason(
    reason: Option<&str>,
) -> BTreeMap<String, u32> {
    let mut action_counts = BTreeMap::new();
    let Some(reason) = reason else {
        return action_counts;
    };
    for part in reason.split(';') {
        let Some((key, value)) = part.split_once('=') else {
            continue;
        };
        if matches!(key, "purpose" | "purpose_hash" | "dry_run") {
            continue;
        }
        if key == "action_counts" {
            if let Ok(counts) = serde_json::from_str::<BTreeMap<String, u32>>(value) {
                action_counts.extend(counts);
            }
            continue;
        }
        if let Ok(count) = value.parse::<u32>() {
            action_counts.insert(key.to_string(), count);
        }
    }
    action_counts
}

fn trace_maintenance_audit_metadata_from_reason(
    surface: &str,
    reason: Option<&str>,
) -> Option<StorageTraceAuditSafeMetadata> {
    if trace_maintenance_audit_reason_has_invalid_hash(reason) {
        return None;
    }
    let dry_run = trace_audit_reason_bool(reason, "dry_run")?;
    let action_counts = trace_maintenance_audit_action_counts_from_reason(reason);
    if action_counts.is_empty() {
        return None;
    }
    Some(StorageTraceAuditSafeMetadata::Maintenance {
        surface: Some(surface.to_string()),
        purpose_hash: trace_maintenance_audit_purpose_hash(reason),
        dry_run,
        action_counts,
    })
}

fn trace_maintenance_audit_kind(kind: &str) -> bool {
    matches!(
        kind,
        "maintenance"
            | "near_credit_outbox_submit"
            | "near_credit_outbox_confirm"
            | "benchmark_registry_outbox_submit"
            | "benchmark_registry_outbox_confirm"
            | "revocation_propagation"
            | "vector_index"
    )
}

fn trace_maintenance_audit_reason(
    purpose_hash: Option<&str>,
    dry_run: bool,
    action_counts: &BTreeMap<String, u32>,
) -> String {
    let mut parts = Vec::with_capacity(action_counts.len() + 2);
    if let Some(purpose_hash) = purpose_hash {
        parts.push(format!("purpose_hash={purpose_hash}"));
    }
    parts.push(format!("dry_run={dry_run}"));
    for (name, count) in action_counts {
        parts.push(format!("{name}={count}"));
    }
    parts.join(";")
}

fn trace_audit_reason_enum<T>(reason: Option<&str>, key: &str) -> Option<T>
where
    T: DeserializeOwned,
{
    serde_json::from_value(serde_json::Value::String(
        trace_audit_reason_value(reason, key)?.to_string(),
    ))
    .ok()
}

fn trace_credit_hold_audit_action_name(action: StorageTraceCreditHoldAuditAction) -> &'static str {
    match action {
        StorageTraceCreditHoldAuditAction::Placed => "placed",
        StorageTraceCreditHoldAuditAction::Released => "released",
    }
}

fn trace_credit_hold_audit_action_from_kind(
    kind: &str,
) -> Option<StorageTraceCreditHoldAuditAction> {
    match kind {
        "credit_hold" => Some(StorageTraceCreditHoldAuditAction::Placed),
        "credit_hold_release" => Some(StorageTraceCreditHoldAuditAction::Released),
        _ => None,
    }
}

fn trace_credit_hold_audit_action_from_reason(
    reason: Option<&str>,
    kind: &str,
) -> Option<StorageTraceCreditHoldAuditAction> {
    let kind_action = trace_credit_hold_audit_action_from_kind(kind)?;
    let Some(action) = trace_audit_reason_value(reason, "action") else {
        return Some(kind_action);
    };
    let parsed = match action {
        "placed" => Some(StorageTraceCreditHoldAuditAction::Placed),
        "released" => Some(StorageTraceCreditHoldAuditAction::Released),
        _ => None,
    }?;
    (parsed == kind_action).then_some(parsed)
}

fn trace_credit_hold_reason_name(reason: StorageTraceCreditHoldReason) -> &'static str {
    match reason {
        StorageTraceCreditHoldReason::DuplicateClusterUnderReview => {
            "duplicate_cluster_under_review"
        }
        StorageTraceCreditHoldReason::PrivacyRiskUnderReview => "privacy_risk_under_review",
        StorageTraceCreditHoldReason::SuspectedAbuse => "suspected_abuse",
        StorageTraceCreditHoldReason::RevocationPropagation => "revocation_propagation",
        StorageTraceCreditHoldReason::AttestationDispute => "attestation_dispute",
        StorageTraceCreditHoldReason::PolicyMigration => "policy_migration",
        StorageTraceCreditHoldReason::LegalCompliance => "legal_compliance",
    }
}

fn trace_credit_hold_reason_from_audit_reason(
    reason: Option<&str>,
) -> Option<StorageTraceCreditHoldReason> {
    let value = trace_audit_reason_value(reason, "hold_reason")?;
    let legacy_debug_reason = match value {
        "DuplicateClusterUnderReview" => {
            Some(StorageTraceCreditHoldReason::DuplicateClusterUnderReview)
        }
        "PrivacyRiskUnderReview" => Some(StorageTraceCreditHoldReason::PrivacyRiskUnderReview),
        "SuspectedAbuse" => Some(StorageTraceCreditHoldReason::SuspectedAbuse),
        "RevocationPropagation" => Some(StorageTraceCreditHoldReason::RevocationPropagation),
        "AttestationDispute" => Some(StorageTraceCreditHoldReason::AttestationDispute),
        "PolicyMigration" => Some(StorageTraceCreditHoldReason::PolicyMigration),
        "LegalCompliance" => Some(StorageTraceCreditHoldReason::LegalCompliance),
        _ => None,
    };
    serde_json::from_value(serde_json::Value::String(value.to_string()))
        .ok()
        .or(legacy_debug_reason)
}

fn trace_credit_hold_audit_reason_from_parts(
    action: StorageTraceCreditHoldAuditAction,
    hold_id: Uuid,
    credit_account_hash: &str,
    hold_reason: StorageTraceCreditHoldReason,
    reason_hash: &str,
) -> String {
    format!(
        "action={};hold_id={};credit_account_hash={};hold_reason={};reason_hash={}",
        trace_credit_hold_audit_action_name(action),
        hold_id,
        credit_account_hash,
        trace_credit_hold_reason_name(hold_reason),
        reason_hash
    )
}

fn trace_credit_hold_audit_metadata(
    hold: &TraceCreditHoldRecord,
    action: StorageTraceCreditHoldAuditAction,
    reason_hash: &str,
) -> StorageTraceAuditSafeMetadata {
    StorageTraceAuditSafeMetadata::CreditHold {
        action,
        hold_id: hold.hold_id,
        credit_account_hash: hold.credit_account_hash.clone(),
        hold_reason: hold.reason,
        reason_hash: reason_hash.to_string(),
    }
}

fn trace_credit_hold_audit_metadata_from_reason(
    kind: &str,
    reason: Option<&str>,
) -> Option<StorageTraceAuditSafeMetadata> {
    let action = trace_credit_hold_audit_action_from_reason(reason, kind)?;
    let hold_id =
        trace_audit_reason_value(reason, "hold_id").and_then(|id| Uuid::parse_str(id).ok())?;
    let credit_account_hash =
        trace_audit_reason_canonical_sha256_value(reason, "credit_account_hash")?;
    let hold_reason = trace_credit_hold_reason_from_audit_reason(reason)?;
    let reason_hash = trace_audit_reason_canonical_sha256_value(reason, "reason_hash")?;
    Some(StorageTraceAuditSafeMetadata::CreditHold {
        action,
        hold_id,
        credit_account_hash,
        hold_reason,
        reason_hash,
    })
}

fn trace_near_credit_outbox_status_transaction_hash_hash(
    near_transaction_hash: Option<&str>,
) -> Option<String> {
    near_transaction_hash
        .map(str::trim)
        .filter(|hash| !hash.is_empty())
        .map(sha256_prefixed)
}

fn trace_near_credit_outbox_status_audit_reason_from_parts(
    near_outbox_id: Uuid,
    settlement_batch_id: Uuid,
    credit_account_hash: &str,
    status: StorageTraceCreditSettlementNearStatus,
    near_transaction_hash_hash: Option<&str>,
    last_error_hash: Option<&str>,
) -> String {
    let mut reason = format!(
        "near_outbox_id={};settlement_batch_id={};credit_account_hash={};status={}",
        near_outbox_id,
        settlement_batch_id,
        credit_account_hash,
        serde_enum_tag(&status)
    );
    if let Some(near_transaction_hash_hash) = near_transaction_hash_hash {
        reason.push_str(";near_transaction_hash_hash=");
        reason.push_str(near_transaction_hash_hash);
    }
    if let Some(last_error_hash) = last_error_hash {
        reason.push_str(";last_error_hash=");
        reason.push_str(last_error_hash);
    }
    reason
}

fn trace_near_credit_outbox_status_audit_reason(item: &TraceNearCreditOutboxItem) -> String {
    trace_near_credit_outbox_status_audit_reason_from_parts(
        item.near_outbox_id,
        item.settlement_batch_id,
        &item.credit_account_hash,
        item.status,
        trace_near_credit_outbox_status_transaction_hash_hash(
            item.near_transaction_hash.as_deref(),
        )
        .as_deref(),
        item.last_error_hash.as_deref(),
    )
}

fn trace_near_credit_outbox_status_audit_metadata(
    item: &TraceNearCreditOutboxItem,
) -> StorageTraceAuditSafeMetadata {
    StorageTraceAuditSafeMetadata::NearCreditOutboxStatus {
        near_outbox_id: item.near_outbox_id,
        settlement_batch_id: item.settlement_batch_id,
        credit_account_hash: item.credit_account_hash.clone(),
        status: item.status,
        near_transaction_hash_hash: trace_near_credit_outbox_status_transaction_hash_hash(
            item.near_transaction_hash.as_deref(),
        ),
        last_error_hash: item.last_error_hash.clone(),
    }
}

fn trace_near_credit_outbox_status_audit_metadata_from_reason(
    reason: Option<&str>,
) -> Option<StorageTraceAuditSafeMetadata> {
    let near_outbox_id = trace_audit_reason_value(reason, "near_outbox_id")
        .and_then(|id| Uuid::parse_str(id).ok())?;
    let settlement_batch_id = trace_audit_reason_value(reason, "settlement_batch_id")
        .and_then(|id| Uuid::parse_str(id).ok())?;
    let credit_account_hash =
        trace_audit_reason_canonical_sha256_value(reason, "credit_account_hash")?;
    let status =
        trace_audit_reason_enum::<StorageTraceCreditSettlementNearStatus>(reason, "status")?;
    let near_transaction_hash_hash =
        match trace_audit_reason_value(reason, "near_transaction_hash_hash") {
            Some(hash) if is_canonical_sha256_prefixed_hash(hash) => Some(hash.to_string()),
            Some(_) => return None,
            None => None,
        };
    let last_error_hash = match trace_audit_reason_value(reason, "last_error_hash") {
        Some(hash) if is_canonical_sha256_prefixed_hash(hash) => Some(hash.to_string()),
        Some(_) => return None,
        None => None,
    };
    Some(StorageTraceAuditSafeMetadata::NearCreditOutboxStatus {
        near_outbox_id,
        settlement_batch_id,
        credit_account_hash,
        status,
        near_transaction_hash_hash,
        last_error_hash,
    })
}

