async fn credit_cycle_scheduler_run_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceCreditCycleSchedulerRunRequest>,
) -> ApiResult<Json<TraceCreditCycleSchedulerRunResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    require_credit_settlement_central_issuer_principal_if_configured(
        state.as_ref(),
        &tenant,
        body.dry_run || body.preflight_only,
    )?;
    let reason = validate_credit_cycle_scheduler_reason(&body.reason)?;
    let limit = validate_credit_cycle_scheduler_limit(body.limit)?;
    let model_version = optional_ranking_identifier(body.model_version, "model_version")?;
    let policy_version = optional_ranking_identifier(body.policy_version, "policy_version")?;
    let near_contract_id = resolve_credit_settlement_near_contract_id(
        state.as_ref(),
        body.dry_run || body.preflight_only,
        body.near_contract_id.as_deref(),
    )?;
    let central_issuer_profile_skip_reason = if !body.dry_run
        && state.credit_settlement_require_central_issuer_profile
        && !credit_settlement_central_issuer_profile_complete(state.as_ref())
    {
        Some("credit_settlement_central_issuer_profile_incomplete")
    } else {
        None
    };
    let rollout_smoke_skip_reason =
        if !body.dry_run && state.credit_settlement_require_rollout_smoke_ready {
            let tenant_ctx = TenantCtx::from_auth(tenant.clone());
            let summary = read_trace_operational_summary(state.as_ref(), &tenant_ctx, Utc::now())
                .await
                .map_err(internal_error)?;
            (!summary.rollout_smoke.ready).then_some("credit_settlement_rollout_smoke_not_ready")
        } else {
            None
        };
    let source_list_approval_skip_reason =
        if !body.dry_run && !body.preflight_only && state.credit_settlement_require_issuer_approval
        {
            Some("credit_settlement_source_list_approval_required")
        } else {
            None
        };

    let model_versions = read_ranking_model_versions_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let predictions = read_ranking_predictions_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let labels = read_ranking_labels_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let preference_labels = read_ranking_preference_labels_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let calibration_datasets = read_ranking_calibration_datasets_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let mut candidates = latest_ranking_model_versions(&model_versions)
        .into_iter()
        .filter(|model| {
            matches!(
                model.status,
                StorageTraceRankingModelStatus::Candidate | StorageTraceRankingModelStatus::Active
            )
        })
        .filter(|model| {
            model_version
                .as_ref()
                .is_none_or(|model_version| &model.model_version == model_version)
                && policy_version
                    .as_ref()
                    .is_none_or(|policy_version| &model.policy_version == policy_version)
        })
        .cloned()
        .collect::<Vec<_>>();
    candidates.sort_by(|left, right| {
        (
            credit_cycle_scheduler_model_status_priority(left.status),
            left.created_at,
            &left.model_version,
        )
            .cmp(&(
                credit_cycle_scheduler_model_status_priority(right.status),
                right.created_at,
                &right.model_version,
            ))
    });
    let candidate_count = candidates.len();

    let mut response = TraceCreditCycleSchedulerRunResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        dry_run: body.dry_run,
        preflight_only: body.preflight_only,
        submit_near_outbox: body.submit_near_outbox,
        confirm_near_outbox: body.confirm_near_outbox,
        target_use: body.target_use,
        model_version: model_version.clone(),
        policy_version: policy_version.clone(),
        reason_hash: sha256_prefixed(&reason),
        limit,
        checked_count: 0,
        eligible_count: 0,
        started_count: 0,
        skipped_active_count: 0,
        skipped_count: 0,
        pending_after_count: 0,
        skipped_reason_counts: BTreeMap::new(),
        decisions: Vec::new(),
        cycles: Vec::new(),
    };

    for candidate in candidates.into_iter().take(limit) {
        response.checked_count += 1;
        if has_overlapping_live_ranking_worker_run(
            state.as_ref(),
            &tenant,
            TraceRankingWorkerRunKind::CreditCycle,
            body.dry_run || body.preflight_only,
            Some(&candidate.model_version),
            Some(body.target_use),
            Some(&candidate.policy_version),
        )
        .await?
        {
            let skip_reason = "active_credit_cycle_claim";
            credit_cycle_scheduler_record_skip(&mut response, skip_reason);
            credit_cycle_scheduler_record_decision(
                &mut response,
                &candidate,
                body.target_use,
                TraceCreditCycleSchedulerDecisionAction::Skipped,
                Some(skip_reason.to_string()),
            );
            response.skipped_active_count += 1;
            continue;
        }
        if let Some(skip_reason) = central_issuer_profile_skip_reason {
            credit_cycle_scheduler_record_skip(&mut response, skip_reason);
            credit_cycle_scheduler_record_decision(
                &mut response,
                &candidate,
                body.target_use,
                TraceCreditCycleSchedulerDecisionAction::Skipped,
                Some(skip_reason.to_string()),
            );
            continue;
        }
        if let Some(skip_reason) = rollout_smoke_skip_reason {
            credit_cycle_scheduler_record_skip(&mut response, skip_reason);
            credit_cycle_scheduler_record_decision(
                &mut response,
                &candidate,
                body.target_use,
                TraceCreditCycleSchedulerDecisionAction::Skipped,
                Some(skip_reason.to_string()),
            );
            continue;
        }
        if let Some(skip_reason) = source_list_approval_skip_reason {
            credit_cycle_scheduler_record_skip(&mut response, skip_reason);
            credit_cycle_scheduler_record_decision(
                &mut response,
                &candidate,
                body.target_use,
                TraceCreditCycleSchedulerDecisionAction::Skipped,
                Some(skip_reason.to_string()),
            );
            continue;
        }
        if let Some(skip_reason) = credit_cycle_scheduler_candidate_skip_reason(
            state.as_ref(),
            &tenant,
            &candidate,
            body.target_use,
            CreditCycleSchedulerPreflightOptions {
                min_label_count: body.min_label_count,
                confidence_threshold: body.confidence_threshold,
                max_average_absolute_error_micros: body.max_average_absolute_error_micros,
                allow_at_risk_models: body.allow_at_risk_models,
            },
            CreditCycleSchedulerPreflightEvidence {
                predictions: &predictions,
                labels: &labels,
                preference_labels: &preference_labels,
                calibration_datasets: &calibration_datasets,
            },
        ) {
            credit_cycle_scheduler_record_skip(&mut response, &skip_reason);
            credit_cycle_scheduler_record_decision(
                &mut response,
                &candidate,
                body.target_use,
                TraceCreditCycleSchedulerDecisionAction::Skipped,
                Some(skip_reason),
            );
            continue;
        }
        if body.preflight_only {
            response.eligible_count += 1;
            credit_cycle_scheduler_record_decision(
                &mut response,
                &candidate,
                body.target_use,
                TraceCreditCycleSchedulerDecisionAction::Eligible,
                None,
            );
            continue;
        }

        match credit_cycle_worker_run_handler(
            State(state.clone()),
            headers.clone(),
            Json(TraceCreditCycleWorkerRunRequest {
                dry_run: body.dry_run,
                submit_near_outbox: body.submit_near_outbox,
                confirm_near_outbox: body.confirm_near_outbox,
                target_use: body.target_use,
                model_version: candidate.model_version.clone(),
                policy_version: candidate.policy_version.clone(),
                reason: reason.clone(),
                issuer_approval_evidence_hash: body.issuer_approval_evidence_hash.clone(),
                near_contract_id: near_contract_id.clone(),
                calibration_limit: body.calibration_limit,
                model_promotion_limit: body.model_promotion_limit,
                prediction_credit_limit: body.prediction_credit_limit,
                credit_settlement_limit: body.credit_settlement_limit,
                near_outbox_limit: body.near_outbox_limit,
                near_outbox_confirm_limit: body.near_outbox_confirm_limit,
                min_label_count: body.min_label_count,
                confidence_threshold: body.confidence_threshold,
                max_average_absolute_error_micros: body.max_average_absolute_error_micros,
                allow_at_risk_models: body.allow_at_risk_models,
            }),
        )
        .await
        {
            Ok(Json(cycle)) => {
                response.started_count += 1;
                credit_cycle_scheduler_record_decision(
                    &mut response,
                    &candidate,
                    body.target_use,
                    TraceCreditCycleSchedulerDecisionAction::Started,
                    None,
                );
                response.cycles.push(cycle);
            }
            Err((StatusCode::CONFLICT, Json(error)))
                if error.error
                    == ranking_worker_run_active_conflict_message(
                        TraceRankingWorkerRunKind::CreditCycle,
                    ) =>
            {
                let skip_reason = "active_credit_cycle_claim";
                credit_cycle_scheduler_record_skip(&mut response, skip_reason);
                credit_cycle_scheduler_record_decision(
                    &mut response,
                    &candidate,
                    body.target_use,
                    TraceCreditCycleSchedulerDecisionAction::Skipped,
                    Some(skip_reason.to_string()),
                );
                response.skipped_active_count += 1;
            }
            Err(error) => return Err(error),
        }
    }
    response.pending_after_count = candidate_count.saturating_sub(response.checked_count);
    Ok(Json(response))
}

/// Trim `value`, reject it when empty or longer than 1024 bytes, and return the
/// trimmed copy. The two rejection messages are supplied verbatim by the caller.
fn validate_free_text_field_messages(
    value: &str,
    empty_message: &str,
    too_long_message: &str,
) -> ApiResult<String> {
    let value = value.trim().to_string();
    if value.is_empty() {
        return Err(api_error(StatusCode::BAD_REQUEST, empty_message));
    }
    if value.len() > 1024 {
        return Err(api_error(StatusCode::BAD_REQUEST, too_long_message));
    }
    Ok(value)
}

/// [`validate_free_text_field_messages`] with the standard message pair:
/// `"{subject} requires a non-empty {field}"` and `"{subject} {field} is too long"`.
fn validate_free_text_field(value: &str, subject: &str, field: &str) -> ApiResult<String> {
    validate_free_text_field_messages(
        value,
        &format!("{subject} requires a non-empty {field}"),
        &format!("{subject} {field} is too long"),
    )
}

fn validate_credit_cycle_scheduler_reason(reason: &str) -> ApiResult<String> {
    validate_free_text_field(reason, "credit cycle scheduler", "reason")
}

fn validate_credit_settlement_scheduler_reason(reason: &str) -> ApiResult<String> {
    validate_free_text_field(reason, "credit settlement scheduler", "reason")
}

fn validate_credit_cycle_scheduler_limit(limit: Option<usize>) -> ApiResult<usize> {
    let limit = limit.unwrap_or(TRACE_CREDIT_CYCLE_SCHEDULER_DEFAULT_LIMIT);
    if !(1..=TRACE_CREDIT_CYCLE_SCHEDULER_MAX_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit cycle scheduler limit must be between 1 and 25",
        ));
    }
    Ok(limit)
}

fn credit_cycle_scheduler_model_status_priority(status: StorageTraceRankingModelStatus) -> u8 {
    match status {
        StorageTraceRankingModelStatus::Candidate => 0,
        StorageTraceRankingModelStatus::Active => 1,
        StorageTraceRankingModelStatus::Deprecated => 2,
        StorageTraceRankingModelStatus::Archived => 3,
    }
}

#[derive(Debug, Clone, Copy)]
struct CreditCycleSchedulerPreflightOptions {
    min_label_count: Option<usize>,
    confidence_threshold: Option<f32>,
    max_average_absolute_error_micros: Option<i64>,
    allow_at_risk_models: bool,
}

#[derive(Debug, Clone, Copy)]
struct CreditCycleSchedulerPreflightEvidence<'a> {
    predictions: &'a [TraceRankingPredictionRecord],
    labels: &'a [TraceRankingLabelRecord],
    preference_labels: &'a [TraceRankingPreferenceLabelRecord],
    calibration_datasets: &'a [TraceRankingCalibrationDatasetRecord],
}

fn credit_cycle_scheduler_candidate_skip_reason(
    state: &AppState,
    tenant: &TenantAuth,
    candidate: &TraceRankingModelVersionRecord,
    target_use: TraceAllowedUse,
    options: CreditCycleSchedulerPreflightOptions,
    evidence: CreditCycleSchedulerPreflightEvidence<'_>,
) -> Option<String> {
    let matching_prediction_count = evidence
        .predictions
        .iter()
        .filter(|prediction| {
            ranking_prediction_matches_model_target(prediction, candidate, target_use)
        })
        .count();
    if matching_prediction_count == 0 {
        return Some("missing_prediction_evidence".to_string());
    }
    let matching_label_count = evidence
        .labels
        .iter()
        .filter(|label| label.target_use == target_use)
        .count();
    if matching_label_count == 0 {
        return Some("missing_label_evidence".to_string());
    }
    let current = ranking_calibration_run_record(
        tenant,
        RankingCalibrationRunInputs {
            calibration_run_id: Uuid::new_v4(),
            model_version: candidate.model_version.clone(),
            target_use,
            policy_version: candidate.policy_version.clone(),
            feature_schema_version: candidate.feature_schema_version.clone(),
            evaluation_dataset_hash: candidate.calibration_dataset_hash.clone(),
            min_label_count: options
                .min_label_count
                .unwrap_or(state.ranking_min_label_count)
                .max(state.ranking_min_label_count),
            min_label_source_count: state.ranking_min_label_source_count,
            confidence_threshold: options
                .confidence_threshold
                .unwrap_or(state.ranking_min_confidence_threshold)
                .max(state.ranking_min_confidence_threshold),
            max_average_absolute_error_micros: options
                .max_average_absolute_error_micros
                .unwrap_or(state.ranking_max_average_absolute_error_micros)
                .min(state.ranking_max_average_absolute_error_micros),
            actor_principal_ref: tenant.principal_ref.clone(),
            created_at: Utc::now(),
        },
        evidence.predictions,
        evidence.labels,
        evidence.preference_labels,
    );
    if current.joined_label_prediction_count == 0 {
        return Some("missing_joined_label_evidence".to_string());
    }
    if !current.promotable {
        return Some(
            current
                .reason_codes
                .first()
                .cloned()
                .unwrap_or_else(|| "calibration_not_promotable".to_string()),
        );
    }
    if ranking_model_training_calibration_datasets_overlap(candidate) {
        return Some("training_calibration_dataset_overlap".to_string());
    }
    if let Some(reason) = ranking_calibration_dataset_gate_reason(
        evidence.calibration_datasets,
        &candidate.calibration_dataset_hash,
        target_use,
        &candidate.policy_version,
        ranking_calibration_dataset_gate_config(state, current.min_label_count),
    ) {
        return Some(reason.to_string());
    }
    if let Some(reason) = ranking_calibration_labeler_reliability_reason_codes(
        state,
        &tenant.tenant_id,
        candidate,
        target_use,
        evidence.predictions,
        evidence.labels,
        evidence.preference_labels,
    )
    .into_iter()
    .next()
    {
        return Some(reason);
    }
    if !options.allow_at_risk_models {
        let pairwise = ranking_pairwise_evaluation_model_report(
            candidate,
            target_use,
            evidence.predictions,
            evidence.preference_labels,
        );
        if pairwise.joined_pair_prediction_count < state.ranking_min_pairwise_label_count {
            return Some("pairwise_evidence_below_threshold".to_string());
        }
        let pairwise_diversity_required = state.ranking_min_pairwise_label_count > 0
            && state.ranking_min_label_source_count > 1
            && pairwise.joined_pair_prediction_count >= state.ranking_min_pairwise_label_count;
        if pairwise_diversity_required
            && pairwise.joined_label_source_count < state.ranking_min_label_source_count
        {
            return Some("pairwise_label_source_underdiverse".to_string());
        }
        if pairwise_diversity_required
            && pairwise.joined_label_actor_count < state.ranking_min_label_source_count
        {
            return Some("pairwise_label_actor_underdiverse".to_string());
        }
        if pairwise.joined_pair_prediction_count > 0
            && pairwise
                .pairwise_accuracy_micros
                .is_some_and(|accuracy| accuracy < state.ranking_min_pairwise_accuracy_micros)
        {
            return Some("pairwise_accuracy_below_threshold".to_string());
        }
    }
    None
}

fn credit_cycle_scheduler_record_decision(
    response: &mut TraceCreditCycleSchedulerRunResponse,
    candidate: &TraceRankingModelVersionRecord,
    target_use: TraceAllowedUse,
    action: TraceCreditCycleSchedulerDecisionAction,
    skip_reason: Option<String>,
) {
    response
        .decisions
        .push(TraceCreditCycleSchedulerCandidateDecision {
            model_version: candidate.model_version.clone(),
            model_status: candidate.status,
            target_use,
            policy_version: candidate.policy_version.clone(),
            action,
            skip_reason,
        });
}

fn credit_cycle_scheduler_record_skip(
    response: &mut TraceCreditCycleSchedulerRunResponse,
    reason: &str,
) {
    response.skipped_count += 1;
    *response
        .skipped_reason_counts
        .entry(reason.to_string())
        .or_insert(0) += 1;
}

async fn credit_cycle_worker_run_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceCreditCycleWorkerRunRequest>,
) -> ApiResult<Json<TraceCreditCycleWorkerRunResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let model_version = validate_ranking_identifier(&body.model_version, "model_version")?;
    let policy_version = validate_ranking_identifier(&body.policy_version, "policy_version")?;
    let reason = validate_credit_cycle_worker_reason(&body.reason)?;
    let issuer_approval_evidence_hash = validate_credit_settlement_issuer_approval_evidence_hash(
        body.issuer_approval_evidence_hash.as_deref(),
    )?;
    require_credit_settlement_central_issuer_principal_if_configured(
        state.as_ref(),
        &tenant,
        body.dry_run,
    )?;
    require_credit_settlement_central_issuer_profile_if_configured(state.as_ref(), body.dry_run)?;
    require_credit_settlement_issuer_approval_if_configured(
        state.as_ref(),
        body.dry_run,
        issuer_approval_evidence_hash.as_deref(),
    )?;
    reject_live_credit_cycle_when_recorded_issuer_approval_is_required(
        state.as_ref(),
        body.dry_run,
    )?;
    let near_contract_id = resolve_credit_settlement_near_contract_id(
        state.as_ref(),
        body.dry_run,
        body.near_contract_id.as_deref(),
    )?;
    require_credit_settlement_rollout_smoke_ready_if_configured(
        state.as_ref(),
        &tenant,
        body.dry_run,
    )
    .await?;

    ensure_no_overlapping_live_ranking_worker_run(
        state.as_ref(),
        &tenant,
        TraceRankingWorkerRunKind::CreditCycle,
        body.dry_run,
        Some(&model_version),
        Some(body.target_use),
        Some(&policy_version),
    )
    .await?;

    let mut cycle_worker_run = TraceRankingWorkerRunRecord {
        ranking_worker_run_id: Uuid::new_v4(),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        run_kind: TraceRankingWorkerRunKind::CreditCycle,
        status: TraceRankingWorkerRunStatus::Running,
        dry_run: body.dry_run,
        reason_hash: sha256_prefixed(&reason),
        model_version: Some(model_version.clone()),
        target_use: Some(body.target_use),
        policy_version: Some(policy_version.clone()),
        limit: credit_cycle_worker_run_total_limit(&body),
        checked_count: 0,
        succeeded_count: 0,
        skipped_existing_count: 0,
        skipped_model_risk_count: 0,
        skipped_ineligible_count: 0,
        pending_after_count: 0,
        result_refs: Vec::new(),
        reason_counts: BTreeMap::new(),
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: db_mirrored_now(),
        completed_at: None,
        last_error_hash: None,
    };
    append_ranking_worker_run_with_db_mirror(state.as_ref(), &tenant, &cycle_worker_run)
        .await
        .map_err(internal_error)?;

    macro_rules! run_credit_cycle_step {
        ($step:expr, $future:expr) => {
            match $future.await {
                Ok(Json(response)) => response,
                Err(error) => {
                    cycle_worker_run.checked_count = $step;
                    let public_error = error.1.0.error.clone();
                    finalize_failed_ranking_worker_run_with_db_mirror(
                        state.as_ref(),
                        &tenant,
                        &mut cycle_worker_run,
                        error.0,
                        &public_error,
                    )
                    .await?;
                    return Err(error);
                }
            }
        };
    }

    let calibration = run_credit_cycle_step!(
        1,
        ranking_calibration_run_worker_handler(
            State(state.clone()),
            headers.clone(),
            Json(TraceRankingCalibrationRunWorkerRequest {
                dry_run: body.dry_run,
                target_use: body.target_use,
                reason: reason.clone(),
                limit: body.calibration_limit,
                model_version: Some(model_version.clone()),
                policy_version: Some(policy_version.clone()),
                min_label_count: body.min_label_count,
                confidence_threshold: body.confidence_threshold,
                max_average_absolute_error_micros: body.max_average_absolute_error_micros,
            }),
        )
    );
    let model_promotion = run_credit_cycle_step!(
        2,
        ranking_model_promotion_worker_run_handler(
            State(state.clone()),
            headers.clone(),
            Json(TraceRankingModelPromotionRunRequest {
                dry_run: body.dry_run,
                target_use: body.target_use,
                reason: reason.clone(),
                limit: body.model_promotion_limit,
                model_version: Some(model_version.clone()),
                policy_version: Some(policy_version.clone()),
            }),
        )
    );
    let prediction_credit = run_credit_cycle_step!(
        3,
        ranking_prediction_credit_run_handler(
            State(state.clone()),
            headers.clone(),
            Json(TraceRankingPredictionCreditRunRequest {
                dry_run: body.dry_run,
                allow_at_risk_models: body.allow_at_risk_models,
                reason: reason.clone(),
                limit: body.prediction_credit_limit,
                model_version: Some(model_version.clone()),
                target_use: Some(body.target_use),
                policy_version: Some(policy_version.clone()),
            }),
        )
    );
    let settlement = run_credit_cycle_step!(
        4,
        credit_settlement_worker_run_handler(
            State(state.clone()),
            headers.clone(),
            Json(TraceCreditSettlementWorkerRunRequest {
                request: TraceCreditSettlementRunRequest {
                    dry_run: body.dry_run,
                    policy_version: policy_version.clone(),
                    reason: reason.clone(),
                    issuer_approval_evidence_hash: issuer_approval_evidence_hash.clone(),
                    near_contract_id: near_contract_id.clone(),
                    ranking_model_version: Some(model_version.clone()),
                    ranking_target_use: Some(body.target_use),
                },
                limit: body.credit_settlement_limit,
            }),
        )
    );
    let near_outbox_submit = run_credit_cycle_step!(
        5,
        near_credit_outbox_submit_worker_handler(
            State(state.clone()),
            headers.clone(),
            Json(TraceNearCreditOutboxSubmitWorkerRequest {
                purpose: Some("trace_commons_credit_cycle_near_outbox".to_string()),
                dry_run: body.dry_run || !body.submit_near_outbox,
                limit: body
                    .near_outbox_limit
                    .unwrap_or(TRACE_NEAR_CREDIT_OUTBOX_SUBMIT_DEFAULT_LIMIT),
            }),
        )
    );
    let near_outbox_confirm = run_credit_cycle_step!(
        6,
        near_credit_outbox_confirm_worker_handler(
            State(state.clone()),
            headers,
            Json(TraceNearCreditOutboxConfirmWorkerRequest {
                purpose: Some("trace_commons_credit_cycle_near_outbox_confirm".to_string()),
                dry_run: body.dry_run || !body.confirm_near_outbox,
                limit: body
                    .near_outbox_confirm_limit
                    .or(body.near_outbox_limit)
                    .unwrap_or(TRACE_NEAR_CREDIT_OUTBOX_CONFIRM_DEFAULT_LIMIT),
            }),
        )
    );

    let response = TraceCreditCycleWorkerRunResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        dry_run: body.dry_run,
        submit_near_outbox: body.submit_near_outbox,
        confirm_near_outbox: body.confirm_near_outbox,
        target_use: body.target_use,
        model_version,
        policy_version,
        reason_hash: sha256_prefixed(&reason),
        near_contract_id,
        calibration,
        model_promotion,
        prediction_credit,
        settlement,
        near_outbox_submit,
        near_outbox_confirm,
    };
    update_credit_cycle_worker_run_from_response(&mut cycle_worker_run, &response);
    cycle_worker_run.status = TraceRankingWorkerRunStatus::Completed;
    cycle_worker_run.completed_at = Some(db_mirrored_now());
    append_ranking_worker_run_with_db_mirror(state.as_ref(), &tenant, &cycle_worker_run)
        .await
        .map_err(internal_error)?;

    Ok(Json(response))
}

fn validate_credit_cycle_worker_reason(reason: &str) -> ApiResult<String> {
    validate_free_text_field(reason, "credit cycle worker run", "reason")
}

fn credit_cycle_worker_run_total_limit(body: &TraceCreditCycleWorkerRunRequest) -> usize {
    body.calibration_limit
        .unwrap_or(TRACE_RANKING_CALIBRATION_RUN_DEFAULT_LIMIT)
        .saturating_add(
            body.model_promotion_limit
                .unwrap_or(TRACE_RANKING_MODEL_PROMOTION_RUN_DEFAULT_LIMIT),
        )
        .saturating_add(
            body.prediction_credit_limit
                .unwrap_or(DEFAULT_RANKING_PREDICTION_CREDIT_RUN_LIMIT),
        )
        .saturating_add(
            body.credit_settlement_limit
                .unwrap_or(TRACE_CREDIT_SETTLEMENT_WORKER_RUN_DEFAULT_LIMIT),
        )
        .saturating_add(
            body.near_outbox_limit
                .unwrap_or(TRACE_NEAR_CREDIT_OUTBOX_SUBMIT_DEFAULT_LIMIT) as usize,
        )
        .saturating_add(
            body.near_outbox_confirm_limit
                .or(body.near_outbox_limit)
                .unwrap_or(TRACE_NEAR_CREDIT_OUTBOX_CONFIRM_DEFAULT_LIMIT) as usize,
        )
}

fn update_credit_cycle_worker_run_from_response(
    worker_run: &mut TraceRankingWorkerRunRecord,
    response: &TraceCreditCycleWorkerRunResponse,
) {
    worker_run.checked_count = TRACE_CREDIT_CYCLE_WORKER_STEP_COUNT;
    worker_run.succeeded_count = TRACE_CREDIT_CYCLE_WORKER_STEP_COUNT;
    worker_run.skipped_existing_count = response.calibration.skipped_existing_count
        + response.prediction_credit.skipped_existing_count
        + response.near_outbox_submit.skipped
        + response.near_outbox_confirm.skipped;
    worker_run.skipped_model_risk_count = response.prediction_credit.skipped_model_risk_count;
    worker_run.skipped_ineligible_count = response.calibration.skipped_ineligible_count
        + response.model_promotion.skipped_ineligible_count
        + response.prediction_credit.skipped_ineligible_count;
    worker_run.pending_after_count = response.calibration.pending_after_count
        + response.model_promotion.pending_after_count
        + response.prediction_credit.pending_after_count
        + response.settlement.pending_after_count
        + response.near_outbox_submit.pending
        + response.near_outbox_confirm.pending;
    worker_run.result_refs = if response.dry_run {
        Vec::new()
    } else {
        vec![
            format!(
                "ranking_worker_run:{}",
                response.calibration.ranking_worker_run_id
            ),
            format!(
                "ranking_worker_run:{}",
                response.model_promotion.ranking_worker_run_id
            ),
            format!(
                "ranking_worker_run:{}",
                response.prediction_credit.ranking_worker_run_id
            ),
            format!(
                "credit_settlement_batch:{}",
                response.settlement.settlement_batch_id
            ),
        ]
    };
    worker_run.reason_counts = credit_cycle_worker_run_reason_counts(response);
}

fn credit_cycle_worker_run_reason_counts(
    response: &TraceCreditCycleWorkerRunResponse,
) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    extend_prefixed_counts(
        &mut counts,
        "calibration",
        &response.calibration.skipped_reason_counts,
    );
    extend_prefixed_counts(
        &mut counts,
        "model_promotion",
        &response.model_promotion.skipped_reason_counts,
    );
    extend_prefixed_counts(
        &mut counts,
        "model_risk",
        &response.prediction_credit.blocked_model_risk_reason_counts,
    );
    if response.near_outbox_submit.failed > 0 {
        counts.insert(
            "near_outbox_failed".to_string(),
            response.near_outbox_submit.failed,
        );
    }
    if response.near_outbox_confirm.failed > 0 {
        counts.insert(
            "near_outbox_confirm_failed".to_string(),
            response.near_outbox_confirm.failed,
        );
    }
    counts
}

fn extend_prefixed_counts(
    counts: &mut BTreeMap<String, usize>,
    prefix: &str,
    source: &BTreeMap<String, usize>,
) {
    for (reason, count) in source {
        counts.insert(format!("{prefix}:{reason}"), *count);
    }
}

async fn run_credit_settlement_drill(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceCreditSettlementDrillRequest,
) -> ApiResult<TraceCreditSettlementDrillResponse> {
    let generated_at = Utc::now();
    let purpose = request
        .purpose
        .as_deref()
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .unwrap_or("trace_commons_credit_settlement_drill")
        .to_string();
    let account_limit = validate_credit_risk_summary_account_limit(request.account_limit)?;
    let source_event_limit = validate_credit_settlement_run_limit(request.source_event_limit)?;
    let require_pending = request.require_pending.unwrap_or(true);
    let require_near_contract = request.require_near_contract.unwrap_or(true);
    let require_near_submitter = request
        .require_near_submitter
        .unwrap_or(require_near_contract);
    let require_near_confirmer = request
        .require_near_confirmer
        .unwrap_or(require_near_contract);
    let require_near_adapter_auth = request
        .require_near_adapter_auth
        .unwrap_or(state.near_credit_require_adapter_auth);
    let require_account_cap = request.require_account_cap.unwrap_or(true);
    let require_issuer_approval = request
        .require_issuer_approval
        .unwrap_or(state.credit_settlement_require_issuer_approval);
    let settlement_account_cap_configured =
        state.credit_settlement_max_micros_per_account.is_some();
    let near_submitter_configured = state.near_credit_submitter.is_some();
    let near_confirmer_configured = state.near_credit_confirmer.is_some();
    let near_submitter_auth_configured = state.near_credit_submitter_auth_configured;
    let near_confirmer_auth_configured = state.near_credit_confirmer_auth_configured;
    let central_issuer_profile_config =
        credit_settlement_central_issuer_profile_config_from_state(state);
    let central_issuer_profile_missing_controls =
        credit_settlement_central_issuer_profile_missing_config(&central_issuer_profile_config);
    let central_issuer_profile_ready = central_issuer_profile_missing_controls.is_empty();
    let issuer_approval_evidence_hash = validate_credit_settlement_issuer_approval_evidence_hash(
        request.issuer_approval_evidence_hash.as_deref(),
    )?;
    let near_contract_id = resolve_credit_settlement_near_contract_id(
        state,
        true,
        request.near_contract_id.as_deref(),
    )?;

    let risk_summary = build_credit_risk_summary(state, tenant, account_limit).await?;
    let settlement = run_credit_settlement(
        state,
        tenant,
        TraceCreditSettlementRunRequest {
            dry_run: true,
            policy_version: request.policy_version,
            reason: purpose.clone(),
            issuer_approval_evidence_hash: issuer_approval_evidence_hash.clone(),
            near_contract_id: near_contract_id.clone(),
            ranking_model_version: request.ranking_model_version,
            ranking_target_use: request.ranking_target_use,
        },
        source_event_limit,
    )
    .await?;
    let issuer_approval_check =
        if let Some(issuer_approval_evidence_hash) = issuer_approval_evidence_hash.as_deref() {
            credit_settlement_issuer_approval_check(
                state,
                tenant,
                &settlement.policy_version,
                &settlement.source_list_hash,
                issuer_approval_evidence_hash,
            )
            .await
            .map_err(internal_error)?
        } else {
            TraceCreditSettlementIssuerApprovalCheck::default()
        };
    let readiness = TraceCreditSettlementDrillReadiness {
        require_pending,
        require_near_contract,
        near_contract_configured: near_contract_id.is_some(),
        require_near_submitter,
        near_submitter_configured,
        require_near_confirmer,
        near_confirmer_configured,
        require_near_adapter_auth,
        near_submitter_auth_configured,
        near_confirmer_auth_configured,
        require_account_cap,
        settlement_account_cap_configured,
        require_issuer_approval,
        issuer_approval_evidence_configured: issuer_approval_evidence_hash.is_some(),
        issuer_approval_evidence_recorded: issuer_approval_check.recorded,
        issuer_approval_max_age: state.credit_settlement_issuer_approval_max_age,
        issuer_approval_evidence_fresh: issuer_approval_check.fresh,
        central_issuer_profile_required: state.credit_settlement_require_central_issuer_profile,
        central_issuer_profile_ready,
    };
    let blocking_gaps =
        credit_settlement_drill_blocking_gaps(&risk_summary, &settlement, &readiness);
    let evidence_hash =
        credit_settlement_drill_evidence_hash(TraceCreditSettlementDrillEvidenceHashInputs {
            tenant,
            purpose: &purpose,
            readiness,
            risk_summary: &risk_summary,
            settlement: &settlement,
            blocking_gaps: &blocking_gaps,
            central_issuer_profile_missing_controls: &central_issuer_profile_missing_controls,
        });
    let mut response = TraceCreditSettlementDrillResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        generated_at,
        purpose: purpose.clone(),
        ready: blocking_gaps.is_empty(),
        evidence_hash,
        require_pending: readiness.require_pending,
        require_near_contract: readiness.require_near_contract,
        near_contract_configured: readiness.near_contract_configured,
        require_near_submitter: readiness.require_near_submitter,
        near_submitter_configured: readiness.near_submitter_configured,
        require_near_confirmer: readiness.require_near_confirmer,
        near_confirmer_configured: readiness.near_confirmer_configured,
        require_near_adapter_auth: readiness.require_near_adapter_auth,
        near_submitter_auth_configured: readiness.near_submitter_auth_configured,
        near_confirmer_auth_configured: readiness.near_confirmer_auth_configured,
        require_account_cap: readiness.require_account_cap,
        settlement_account_cap_configured: readiness.settlement_account_cap_configured,
        require_issuer_approval: readiness.require_issuer_approval,
        issuer_approval_evidence_configured: readiness.issuer_approval_evidence_configured,
        issuer_approval_evidence_recorded: readiness.issuer_approval_evidence_recorded,
        issuer_approval_max_age_hours: readiness
            .issuer_approval_max_age
            .map(|max_age| max_age.num_hours()),
        issuer_approval_evidence_fresh: readiness.issuer_approval_evidence_fresh,
        credit_settlement_central_issuer_profile_required: readiness
            .central_issuer_profile_required,
        credit_settlement_central_issuer_profile_ready: readiness.central_issuer_profile_ready,
        credit_settlement_central_issuer_profile_missing_controls:
            central_issuer_profile_missing_controls,
        risk_summary,
        settlement,
        blocking_gaps,
        recorded_evidence: None,
    };

    if request.record_evidence {
        let evidence = TraceRolloutSmokeEvidenceResponse {
            event_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            check_name: "credit_settlement".to_string(),
            status: if response.ready {
                TraceRolloutSmokeEvidenceStatus::Passed
            } else {
                TraceRolloutSmokeEvidenceStatus::Failed
            },
            evidence_hash: response.evidence_hash.clone(),
            evidence_ref_hash: Some(sha256_prefixed(&purpose)),
            actor_principal_ref: tenant.principal_ref.clone(),
            recorded_at: Utc::now(),
        };
        append_audit_event_with_db_mirror(
            state,
            tenant,
            TraceCommonsAuditEvent::rollout_smoke_evidence(&evidence),
            StorageTraceAuditAction::Read,
            StorageTraceAuditSafeMetadata::Empty,
        )
        .await
        .map_err(internal_error)?;
        response.recorded_evidence = Some(evidence);
    }

    Ok(response)
}

#[derive(Clone, Copy)]
struct TraceCreditSettlementDrillReadiness {
    require_pending: bool,
    require_near_contract: bool,
    near_contract_configured: bool,
    require_near_submitter: bool,
    near_submitter_configured: bool,
    require_near_confirmer: bool,
    near_confirmer_configured: bool,
    require_near_adapter_auth: bool,
    near_submitter_auth_configured: bool,
    near_confirmer_auth_configured: bool,
    require_account_cap: bool,
    settlement_account_cap_configured: bool,
    require_issuer_approval: bool,
    issuer_approval_evidence_configured: bool,
    issuer_approval_evidence_recorded: bool,
    issuer_approval_max_age: Option<Duration>,
    issuer_approval_evidence_fresh: bool,
    central_issuer_profile_required: bool,
    central_issuer_profile_ready: bool,
}

fn credit_settlement_drill_blocking_gaps(
    risk_summary: &TraceCreditRiskSummaryResponse,
    settlement: &TraceCreditSettlementRunResponse,
    readiness: &TraceCreditSettlementDrillReadiness,
) -> Vec<String> {
    let mut blocking_gaps = Vec::new();
    if readiness.require_near_contract && !readiness.near_contract_configured {
        blocking_gaps.push("near_contract_id_missing".to_string());
    }
    if readiness.require_near_submitter && !readiness.near_submitter_configured {
        blocking_gaps.push("near_credit_submitter_missing".to_string());
    }
    if readiness.require_near_confirmer && !readiness.near_confirmer_configured {
        blocking_gaps.push("near_credit_confirmer_missing".to_string());
    }
    if readiness.require_near_adapter_auth
        && readiness.near_submitter_configured
        && !readiness.near_submitter_auth_configured
    {
        blocking_gaps.push("near_credit_submitter_auth_missing".to_string());
    }
    if readiness.require_near_adapter_auth
        && readiness.near_confirmer_configured
        && !readiness.near_confirmer_auth_configured
    {
        blocking_gaps.push("near_credit_confirmer_auth_missing".to_string());
    }
    if readiness.require_issuer_approval && !readiness.issuer_approval_evidence_configured {
        blocking_gaps.push("issuer_approval_evidence_hash_missing".to_string());
    } else if readiness.require_issuer_approval && !readiness.issuer_approval_evidence_recorded {
        blocking_gaps.push("issuer_approval_evidence_hash_unrecorded".to_string());
    } else if readiness.require_issuer_approval
        && readiness.issuer_approval_max_age.is_some()
        && !readiness.issuer_approval_evidence_fresh
    {
        blocking_gaps.push("issuer_approval_evidence_hash_stale".to_string());
    }
    if readiness.central_issuer_profile_required && !readiness.central_issuer_profile_ready {
        blocking_gaps.push("credit_settlement_central_issuer_profile_incomplete".to_string());
    }
    if !settlement.policy_version_allowed {
        blocking_gaps.push("credit_settlement_policy_version_not_allowed".to_string());
    }
    if readiness.require_pending && risk_summary.pending_credit_micros <= 0 {
        blocking_gaps.push("pending_credit_events_missing".to_string());
    }
    if readiness.require_account_cap && !readiness.settlement_account_cap_configured {
        blocking_gaps.push("settlement_account_cap_missing".to_string());
    }
    push_gap_count(
        &mut blocking_gaps,
        "held_credit_accounts_present",
        risk_summary.held_account_count,
    );
    push_gap_count(
        &mut blocking_gaps,
        "over_cap_credit_accounts_present",
        risk_summary.over_cap_account_count,
    );
    if risk_summary.truncated {
        blocking_gaps.push("credit_risk_summary_truncated".to_string());
    }
    push_gap_count(
        &mut blocking_gaps,
        "settlement_policy_excluded_source_events",
        settlement.settlement_policy_excluded_source_event_count,
    );
    push_gap_count(
        &mut blocking_gaps,
        "ranking_credit_events_excluded",
        settlement.ranking_credit_events_excluded_count,
    );
    blocking_gaps
}

struct TraceCreditSettlementDrillEvidenceHashInputs<'a> {
    tenant: &'a TenantAuth,
    purpose: &'a str,
    readiness: TraceCreditSettlementDrillReadiness,
    risk_summary: &'a TraceCreditRiskSummaryResponse,
    settlement: &'a TraceCreditSettlementRunResponse,
    blocking_gaps: &'a [String],
    central_issuer_profile_missing_controls: &'a [&'static str],
}

fn credit_settlement_drill_evidence_hash(
    inputs: TraceCreditSettlementDrillEvidenceHashInputs<'_>,
) -> String {
    let TraceCreditSettlementDrillEvidenceHashInputs {
        tenant,
        purpose,
        readiness,
        risk_summary,
        settlement,
        blocking_gaps,
        central_issuer_profile_missing_controls,
    } = inputs;
    let mut evidence = serde_json::json!({
            "schema": "trace_commons_credit_settlement_drill.v4",
            "tenant_storage_ref": tenant_storage_ref(&tenant.tenant_id),
            "actor_principal_ref": tenant.principal_ref,
            "purpose_hash": sha256_prefixed(purpose),
            "policy_version": &settlement.policy_version,
            "require_pending": readiness.require_pending,
            "require_near_contract": readiness.require_near_contract,
            "near_contract_configured": readiness.near_contract_configured,
            "require_near_submitter": readiness.require_near_submitter,
            "near_submitter_configured": readiness.near_submitter_configured,
            "require_near_confirmer": readiness.require_near_confirmer,
            "near_confirmer_configured": readiness.near_confirmer_configured,
            "require_near_adapter_auth": readiness.require_near_adapter_auth,
            "near_submitter_auth_configured": readiness.near_submitter_auth_configured,
            "near_confirmer_auth_configured": readiness.near_confirmer_auth_configured,
            "require_account_cap": readiness.require_account_cap,
            "settlement_account_cap_configured": readiness.settlement_account_cap_configured,
            "require_issuer_approval": readiness.require_issuer_approval,
            "issuer_approval_evidence_configured": readiness.issuer_approval_evidence_configured,
            "issuer_approval_evidence_recorded": readiness.issuer_approval_evidence_recorded,
            "issuer_approval_max_age_hours": readiness
                .issuer_approval_max_age
                .map(|max_age| max_age.num_hours()),
            "issuer_approval_evidence_fresh": readiness.issuer_approval_evidence_fresh,
            "credit_settlement_central_issuer_profile_required":
                readiness.central_issuer_profile_required,
            "credit_settlement_central_issuer_profile_ready":
                readiness.central_issuer_profile_ready,
            "risk_account_count": risk_summary.account_count,
            "risk_pending_account_count": risk_summary.pending_account_count,
            "risk_held_account_count": risk_summary.held_account_count,
            "risk_over_cap_account_count": risk_summary.over_cap_account_count,
            "risk_pending_credit_micros": risk_summary.pending_credit_micros,
            "risk_held_credit_micros": risk_summary.held_credit_micros,
            "risk_over_cap_credit_micros": risk_summary.over_cap_credit_micros,
            "risk_truncated": risk_summary.truncated,
            "settled_source_event_count": settlement.settled_source_event_count,
            "eligible_source_event_count": settlement.eligible_source_event_count,
            "pending_after_count": settlement.pending_after_count,
            "settled_account_count": settlement.settled_account_count,
            "settlement_policy_excluded_source_event_count":
                settlement.settlement_policy_excluded_source_event_count,
            "settlement_policy_excluded_reason_counts":
                &settlement.settlement_policy_excluded_reason_counts,
            "ranking_credit_events_excluded_count":
                settlement.ranking_credit_events_excluded_count,
            "ranking_credit_events_excluded_reason_counts":
                &settlement.ranking_credit_events_excluded_reason_counts,
            "blocking_gaps": blocking_gaps,
    });
    if let serde_json::Value::Object(fields) = &mut evidence {
        fields.insert(
            "policy_version_allowed".to_string(),
            serde_json::Value::Bool(settlement.policy_version_allowed),
        );
        fields.insert(
            "source_event_limit".to_string(),
            serde_json::json!(settlement.limit),
        );
        fields.insert(
            "source_list_hash".to_string(),
            serde_json::Value::String(settlement.source_list_hash.clone()),
        );
        fields.insert(
            "credit_settlement_central_issuer_profile_missing_controls".to_string(),
            serde_json::Value::Array(
                central_issuer_profile_missing_controls
                    .iter()
                    .map(|control| serde_json::Value::String((*control).to_string()))
                    .collect(),
            ),
        );
    }
    json_evidence_hash(&evidence)
}

async fn run_credit_settlement(
    state: &AppState,
    tenant: &TenantAuth,
    body: TraceCreditSettlementRunRequest,
    limit: Option<usize>,
) -> ApiResult<TraceCreditSettlementRunResponse> {
    // Live settlement serializes per tenant so two overlapping runs cannot both
    // pass the source-event conflict check and finalize divergent batches (or
    // leave a half-written outbox). Dry-runs stay unlocked — they write nothing.
    let settlement_locks = if body.dry_run {
        None
    } else {
        Some(acquire_credit_settlement_run_locks(state, &tenant.tenant_id).await?)
    };
    let result = run_credit_settlement_unlocked(state, tenant, body, limit).await;
    if let Some(locks) = settlement_locks {
        // Settlement may already be durable; never convert a successful finalize into
        // a caller-visible failure because advisory unlock hiccuped.
        if let Err(error) = locks.release().await {
            tracing::warn!(
                error_hash = %safe_runtime_error_hash(&error),
                tenant_id = %tenant.tenant_id,
                "failed to release credit settlement run locks after settlement"
            );
        }
    }
    result
}

async fn run_credit_settlement_unlocked(
    state: &AppState,
    tenant: &TenantAuth,
    body: TraceCreditSettlementRunRequest,
    limit: Option<usize>,
) -> ApiResult<TraceCreditSettlementRunResponse> {
    let policy_version = validate_credit_settlement_policy_version(&body.policy_version)?;
    let policy_version_allowed = credit_settlement_policy_version_allowed(state, &policy_version);
    require_credit_settlement_policy_version_allowed_for_live(
        state,
        body.dry_run,
        &policy_version,
    )?;
    let reason = body.reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit settlement requires a non-empty reason",
        ));
    }
    let issuer_approval_evidence_hash = validate_credit_settlement_issuer_approval_evidence_hash(
        body.issuer_approval_evidence_hash.as_deref(),
    )?;
    require_credit_settlement_central_issuer_principal_if_configured(state, tenant, body.dry_run)?;
    require_credit_settlement_central_issuer_profile_if_configured(state, body.dry_run)?;
    require_credit_settlement_issuer_approval_if_configured(
        state,
        body.dry_run,
        issuer_approval_evidence_hash.as_deref(),
    )?;
    let near_contract_id = resolve_credit_settlement_near_contract_id(
        state,
        body.dry_run,
        body.near_contract_id.as_deref(),
    )?;
    require_credit_settlement_rollout_smoke_ready_if_configured(state, tenant, body.dry_run)
        .await?;
    let ranking_model_version = match body.ranking_model_version.as_deref().map(str::trim) {
        Some("") => {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "credit settlement ranking_model_version cannot be empty",
            ));
        }
        Some(model_version) => Some(validate_ranking_identifier(
            model_version,
            "ranking_model_version",
        )?),
        None => None,
    };
    if body.ranking_target_use.is_some() && ranking_model_version.is_none() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit settlement ranking_target_use requires ranking_model_version",
        ));
    }
    let ranking_target_use = body
        .ranking_target_use
        .unwrap_or(TraceAllowedUse::RankingModelTraining);

    let records = read_reviewer_metadata_view(state, tenant)
        .await
        .map_err(internal_error)?
        .records;
    let records_by_submission = records
        .iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    let existing_batches = read_credit_settlement_batches_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    if !body.dry_run {
        let repaired_outbox_count = repair_missing_near_credit_outbox_items_for_finalized_batches(
            state,
            tenant,
            &existing_batches,
        )
        .await
        .map_err(internal_error)?;
        if repaired_outbox_count > 0 {
            tracing::warn!(
                repaired_outbox_count,
                tenant_id = %tenant.tenant_id,
                "repaired missing NEAR credit outbox items for finalized settlement batches"
            );
        }
    }
    let held_credit_accounts = active_credit_hold_account_refs_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let already_settled_event_ids = existing_batches
        .iter()
        .filter(|batch| batch.status == StorageTraceCreditSettlementBatchStatus::Finalized)
        .flat_map(|batch| batch.source_credit_event_ids.iter().copied())
        .collect::<BTreeSet<_>>();
    let credit_events = read_credit_events_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let candidate_events = credit_events
        .into_iter()
        .filter(|event| trace_credit_event_type_is_settlement_eligible(event.event_type))
        .filter(|event| event.credit_points_delta > 0.0)
        .filter(|event| !already_settled_event_ids.contains(&event.event_id))
        .filter(|event| {
            records_by_submission
                .get(&event.submission_id)
                .is_some_and(|record| {
                    record.status == TraceCorpusStatus::Accepted
                        && delayed_credit_applies_to_record(record)
                })
        })
        .filter(|event| !held_credit_accounts.contains(&event.auth_principal_ref))
        .collect::<Vec<_>>();
    let ranking_candidate_count = candidate_events
        .iter()
        .filter(|event| event.event_type == TraceCreditLedgerEventType::RankingUtility)
        .count();
    let ranking_calibration_gate = if ranking_candidate_count > 0 {
        ranking_settlement_calibration_gate(
            state,
            tenant,
            &policy_version,
            ranking_model_version.as_deref(),
            ranking_target_use,
        )
        .await?
    } else {
        None
    };
    let ranking_predictions = if ranking_candidate_count > 0 && ranking_calibration_gate.is_some() {
        read_ranking_predictions_for_admin(state, tenant)
            .await
            .map_err(internal_error)?
    } else {
        Vec::new()
    };
    let ranking_features = if ranking_candidate_count > 0
        && ranking_calibration_gate.is_some()
        && state.ranking_require_server_feature_provenance
    {
        read_ranking_features_for_admin(state, tenant)
            .await
            .map_err(internal_error)?
    } else {
        Vec::new()
    };
    let mut ranking_credit_events_excluded_count = 0usize;
    let mut ranking_credit_events_excluded_reason_counts = BTreeMap::new();
    let mut selected_events = Vec::new();
    for event in candidate_events {
        if event.event_type != TraceCreditLedgerEventType::RankingUtility {
            selected_events.push(event);
            continue;
        }
        let exclusion_reason_codes = ranking_credit_event_exclusion_reason_codes(
            state,
            &event,
            &ranking_features,
            &ranking_predictions,
            ranking_calibration_gate.as_ref(),
            &policy_version,
        );
        if exclusion_reason_codes.is_empty() {
            selected_events.push(event);
        } else {
            ranking_credit_events_excluded_count += 1;
            for code in exclusion_reason_codes {
                *ranking_credit_events_excluded_reason_counts
                    .entry(code)
                    .or_insert(0) += 1;
            }
        }
    }
    let eligible_source_event_count = selected_events.len();

    // Resolve principals to their durable accounts BEFORE capping. The cap is
    // a per-account bound, and principals fold into accounts a few lines
    // below; capping first would bound each principal separately and then
    // merge them, so a contributor holding N principals under one account
    // would settle up to N times the cap in a single account line item.
    // Resolving first makes the cap key and the payout key the same key.
    //
    // The resolve only runs when a DB mirror is present; without one there is
    // no account linkage to fold up, the map stays empty, and both the cap and
    // the grouping fall back to per-principal exactly as before.
    let principal_to_account: HashMap<String, Uuid> = if let Some(db) = state.db_mirror.as_ref() {
        let distinct_refs = selected_events
            .iter()
            .map(|event| event.auth_principal_ref.clone())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        db.resolve_principals_to_accounts(&tenant.tenant_id, &distinct_refs)
            .await
            .context("failed to resolve contributor principals to accounts for settlement")
            .map_err(internal_error)?
    } else {
        HashMap::new()
    };

    let (
        mut selected_events,
        settlement_policy_excluded_source_event_count,
        settlement_policy_excluded_reason_counts,
    ) = apply_credit_settlement_account_cap(
        selected_events,
        state.credit_settlement_max_micros_per_account,
        &principal_to_account,
    );
    selected_events.sort_by_key(|event| event.event_id);
    if let Some(limit) = limit {
        selected_events.truncate(limit);
    }
    let pending_after_count = if body.dry_run {
        eligible_source_event_count
    } else {
        eligible_source_event_count.saturating_sub(selected_events.len())
    };

    let source_credit_event_ids = selected_events
        .iter()
        .map(|event| event.event_id)
        .collect::<Vec<_>>();
    let source_submission_ids = selected_events
        .iter()
        .map(|event| event.submission_id)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let source_list_hash = source_credit_event_ids_hash(&policy_version, &source_credit_event_ids);
    require_recorded_credit_settlement_issuer_approval_if_configured(
        state,
        tenant,
        body.dry_run,
        &policy_version,
        &source_list_hash,
        issuer_approval_evidence_hash.as_deref(),
    )
    .await?;
    let settlement_batch_id = Uuid::new_v4();
    let tenant_storage_ref = tenant_storage_ref(&tenant.tenant_id);
    let reason_hash = sha256_prefixed(&reason);
    // Batch-resolve distinct contributing principals to their durable accounts in
    // one RLS-scoped query, then re-key settlement groups by account so multiple
    // principals belonging to the same account collapse into a single line item
    // (and a single on-chain payout). Principals with no active account link keep
    // their own key and settle exactly as before. The resolve only runs when a DB
    // mirror is present; without one there is no account linkage to fold up and we
    // preserve the legacy per-principal behavior.
    //
    const ACCOUNT_KEY_PREFIX: &str = ACCOUNT_SETTLEMENT_KEY_PREFIX;

    let mut grouped = BTreeMap::<String, Vec<TraceCommonsCreditLedgerRecord>>::new();
    for event in selected_events {
        let resolved_key = settlement_group_key(&event.auth_principal_ref, &principal_to_account);
        grouped.entry(resolved_key).or_default().push(event);
    }

    let mut line_items = Vec::with_capacity(grouped.len());
    let mut near_outbox_items = Vec::new();
    for (credit_account_ref, events) in grouped {
        let settled_credit_micros = events
            .iter()
            .map(|event| credit_delta_micros(event.credit_points_delta))
            .sum::<i64>();
        if settled_credit_micros <= 0 {
            continue;
        }
        let source_credit_event_ids = events
            .iter()
            .map(|event| event.event_id)
            .collect::<Vec<_>>();
        let source_submission_ids = events
            .iter()
            .map(|event| event.submission_id)
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        let item_source_list_hash =
            source_credit_event_ids_hash(&policy_version, &source_credit_event_ids);
        let credit_account_hash = sha256_prefixed(&credit_account_ref);

        // For account groups, resolve the on-chain payout target fail-closed. A
        // `Hold` withholds the outbox row (the credit is still finalized
        // internally) and records a coarse hold label on the line item. Unlinked
        // principal groups settle as before with no payout lookup.
        let account_id = credit_account_ref
            .strip_prefix(ACCOUNT_KEY_PREFIX)
            .and_then(|raw| Uuid::parse_str(raw).ok());
        let (payout_near_account_id, near_payout_hold_reason) = if let Some(account_id) = account_id
        {
            // Resolve fail-closed. An account-keyed group can only exist when the
            // mirror was present above, but guard the impossible mirror-less branch
            // by HOLDING (never pay, never panic) rather than `.expect`-ing on the
            // money path: a future edit must not be able to arm a settlement-run
            // 500 or a silent pay here.
            debug_assert!(
                state.db_mirror.is_some(),
                "account-keyed group implies a resolved DB mirror"
            );
            let resolution = match state.db_mirror.as_ref() {
                Some(db) => db
                    .resolve_payout_near_account_id(&tenant.tenant_id, account_id)
                    .await
                    .context("failed to resolve account payout target for settlement")
                    .map_err(internal_error)?,
                None => PayoutResolution::Hold(PayoutHoldReason::NoneEnrolled),
            };
            match resolution {
                PayoutResolution::Designated(near) | PayoutResolution::SoleActive(near) => {
                    (Some(near), None)
                }
                PayoutResolution::Hold(reason) => {
                    let label = match reason {
                        PayoutHoldReason::NoneEnrolled => "none_enrolled",
                        PayoutHoldReason::AmbiguousNoDesignation => "ambiguous_no_designation",
                    };
                    (None, Some(label.to_string()))
                }
            }
        } else {
            (None, None)
        };

        // Withhold the on-chain outbox row when the account's payout is held; the
        // internal credit line item is still finalized.
        let payout_held = near_payout_hold_reason.is_some();
        let near_outbox_id = if near_contract_id.is_some() && !body.dry_run && !payout_held {
            Some(Uuid::new_v4())
        } else {
            None
        };
        let near_status = if near_contract_id.is_some() {
            StorageTraceCreditSettlementNearStatus::Pending
        } else {
            StorageTraceCreditSettlementNearStatus::Disabled
        };
        if let (Some(contract_id), Some(near_outbox_id)) = (&near_contract_id, near_outbox_id) {
            let receipt = NearCreditReceipt {
                settlement_batch_id,
                credit_account_hash: credit_account_hash.clone(),
                policy_version: policy_version.clone(),
                source_list_hash: item_source_list_hash.clone(),
                attestation_hash: trace_credit_settlement_attestation_hash(
                    &item_source_list_hash,
                    issuer_approval_evidence_hash.as_deref(),
                ),
                amount_micros: settled_credit_micros,
                issuer_signature_hash: trace_credit_settlement_issuer_signature_hash(
                    settlement_batch_id,
                    &item_source_list_hash,
                    issuer_approval_evidence_hash.as_deref(),
                ),
            };
            let near_call = NearCreditReceiptCall::settle(contract_id, receipt)
                .map_err(|error| api_error(StatusCode::BAD_REQUEST, error.to_string()))?;
            near_outbox_items.push(TraceNearCreditOutboxItem {
                near_outbox_id,
                tenant_id: tenant.tenant_id.clone(),
                tenant_storage_ref: tenant_storage_ref.clone(),
                settlement_batch_id,
                credit_account_hash: credit_account_hash.clone(),
                near_call,
                status: StorageTraceCreditSettlementNearStatus::Pending,
                payout_near_account_id: payout_near_account_id.clone(),
                created_at: Utc::now(),
                submitted_at: None,
                near_transaction_hash: None,
                last_error_hash: None,
                confirmed_at: None,
            });
        }
        line_items.push(StorageTraceCreditAccountSettlementLineItem {
            credit_account_ref,
            credit_account_hash,
            settled_credit_delta_micros: settled_credit_micros,
            source_credit_event_ids,
            source_submission_ids,
            source_list_hash: item_source_list_hash,
            near_status,
            near_outbox_id,
            near_payout_hold_reason,
        });
    }

    let settled_credit_micros = line_items
        .iter()
        .map(|item| item.settled_credit_delta_micros)
        .sum::<i64>();
    let settled_credit_points = settled_credit_micros as f32 / 1_000_000.0;
    if !body.dry_run && !line_items.is_empty() {
        let batch = TraceCreditSettlementBatchRecord {
            settlement_batch_id,
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref.clone(),
            policy_version: policy_version.clone(),
            status: StorageTraceCreditSettlementBatchStatus::Finalized,
            reason_hash,
            issuer_approval_evidence_hash: issuer_approval_evidence_hash.clone(),
            source_credit_event_ids: source_credit_event_ids.clone(),
            source_submission_ids: source_submission_ids.clone(),
            source_list_hash: source_list_hash.clone(),
            settled_credit_points,
            settled_credit_micros,
            line_items: line_items.clone(),
            near_contract_id: near_contract_id.clone(),
            ranking_model_version: ranking_calibration_gate
                .as_ref()
                .map(|gate| gate.model_version.clone()),
            ranking_target_use: ranking_calibration_gate
                .as_ref()
                .map(|gate| gate.target_use),
            ranking_calibration_run_id: ranking_calibration_gate
                .as_ref()
                .map(|gate| gate.calibration_run_id),
            ranking_calibration_report_hash: ranking_calibration_gate
                .as_ref()
                .map(|gate| gate.report_hash.clone()),
            ranking_calibration_joined_evidence_hash: ranking_calibration_gate
                .as_ref()
                .map(|gate| gate.joined_evidence_hash.clone()),
            ranking_credit_events_excluded_count,
            ranking_credit_events_excluded_reason_counts:
                ranking_credit_events_excluded_reason_counts.clone(),
            actor_principal_ref: tenant.principal_ref.clone(),
            created_at: Utc::now(),
        };
        append_credit_settlement_finalize_with_db_mirror(state, tenant, &batch, &near_outbox_items)
            .await
            .map_err(internal_error)?;
    }

    Ok(TraceCreditSettlementRunResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref,
        settlement_batch_id,
        dry_run: body.dry_run,
        policy_version,
        policy_version_allowed,
        source_list_hash,
        issuer_approval_evidence_hash,
        limit,
        settled_source_event_count: source_credit_event_ids.len(),
        eligible_source_event_count,
        pending_after_count,
        settled_account_count: line_items.len(),
        settled_credit_points,
        near_outbox_item_count: near_outbox_items.len(),
        ranking_model_version: ranking_calibration_gate
            .as_ref()
            .map(|gate| gate.model_version.clone()),
        ranking_target_use: ranking_calibration_gate
            .as_ref()
            .map(|gate| gate.target_use),
        ranking_calibration_run_id: ranking_calibration_gate
            .as_ref()
            .map(|gate| gate.calibration_run_id),
        ranking_calibration_report_hash: ranking_calibration_gate
            .as_ref()
            .map(|gate| gate.report_hash.clone()),
        ranking_calibration_joined_evidence_hash: ranking_calibration_gate
            .as_ref()
            .map(|gate| gate.joined_evidence_hash.clone()),
        ranking_credit_events_excluded_count,
        ranking_credit_events_excluded_reason_counts,
        settlement_max_credit_micros_per_account: state.credit_settlement_max_micros_per_account,
        settlement_policy_excluded_source_event_count,
        settlement_policy_excluded_reason_counts,
    })
}

fn validate_credit_settlement_run_limit(limit: Option<usize>) -> ApiResult<Option<usize>> {
    if let Some(limit) = limit {
        if !(1..=TRACE_CREDIT_SETTLEMENT_WORKER_RUN_MAX_LIMIT).contains(&limit) {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "credit settlement run limit must be between 1 and 500",
            ));
        }
        Ok(Some(limit))
    } else {
        Ok(None)
    }
}

fn validate_credit_risk_summary_account_limit(limit: Option<usize>) -> ApiResult<usize> {
    let limit = limit.unwrap_or(TRACE_CREDIT_RISK_SUMMARY_DEFAULT_ACCOUNT_LIMIT);
    if !(1..=TRACE_CREDIT_RISK_SUMMARY_MAX_ACCOUNT_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit risk summary limit must be between 1 and 500",
        ));
    }
    Ok(limit)
}

/// The key a credit event settles under: its contributor account when the
/// principal resolves to one, else the raw principal.
///
/// Single definition on purpose. The settlement cap and the line-item
/// grouping must agree on this key exactly -- if the cap groups by principal
/// while the payout groups by account, a contributor holding several
/// principals under one account is capped once per principal and paid once
/// per account.
fn settlement_group_key(
    auth_principal_ref: &str,
    principal_to_account: &HashMap<String, Uuid>,
) -> String {
    principal_to_account
        .get(auth_principal_ref)
        .map(|account_id| format!("{ACCOUNT_SETTLEMENT_KEY_PREFIX}{account_id}"))
        .unwrap_or_else(|| auth_principal_ref.to_string())
}

fn apply_credit_settlement_account_cap(
    events: Vec<TraceCommonsCreditLedgerRecord>,
    max_micros_per_account: Option<i64>,
    principal_to_account: &HashMap<String, Uuid>,
) -> (
    Vec<TraceCommonsCreditLedgerRecord>,
    usize,
    BTreeMap<String, usize>,
) {
    let Some(max_micros_per_account) = max_micros_per_account else {
        return (events, 0, BTreeMap::new());
    };
    let mut account_totals = BTreeMap::<String, i64>::new();
    for event in &events {
        *account_totals
            .entry(settlement_group_key(
                &event.auth_principal_ref,
                principal_to_account,
            ))
            .or_insert(0) += credit_delta_micros(event.credit_points_delta);
    }
    let blocked_accounts = account_totals
        .into_iter()
        .filter_map(|(account, total)| (total > max_micros_per_account).then_some(account))
        .collect::<BTreeSet<_>>();
    if blocked_accounts.is_empty() {
        return (events, 0, BTreeMap::new());
    }
    let mut excluded_count = 0usize;
    let selected = events
        .into_iter()
        .filter(|event| {
            let excluded = blocked_accounts.contains(&settlement_group_key(
                &event.auth_principal_ref,
                principal_to_account,
            ));
            if excluded {
                excluded_count += 1;
            }
            !excluded
        })
        .collect::<Vec<_>>();
    let mut reason_counts = BTreeMap::new();
    reason_counts.insert(
        "account_settlement_amount_exceeds_cap".to_string(),
        excluded_count,
    );
    (selected, excluded_count, reason_counts)
}

async fn repair_missing_near_credit_outbox_items_for_finalized_batches(
    state: &AppState,
    tenant: &TenantAuth,
    settlement_batches: &[TraceCreditSettlementBatchRecord],
) -> anyhow::Result<usize> {
    // Run when there is either a missing-but-expected outbox row (a line item that
    // already carries a `near_outbox_id`) OR a HELD line item that may now resolve
    // a payout (no `near_outbox_id`, `near_payout_hold_reason` set). Both are
    // gated on the batch being finalized with a NEAR contract configured.
    let has_repairable = settlement_batches.iter().any(|batch| {
        batch.status == StorageTraceCreditSettlementBatchStatus::Finalized
            && batch.near_contract_id.is_some()
            && batch
                .line_items
                .iter()
                .any(|item| item.near_outbox_id.is_some() || item.near_payout_hold_reason.is_some())
    });
    if !has_repairable {
        return Ok(0);
    }

    let existing_items = read_near_credit_outbox_items_for_admin(state, tenant).await?;
    let mut existing_outbox_ids = existing_items
        .iter()
        .map(|item| item.near_outbox_id)
        .collect::<BTreeSet<_>>();
    // Held re-emission keys on (settlement_batch_id, credit_account_hash), which is
    // the table's UNIQUE constraint. The mirror upsert only conflicts on
    // near_outbox_id, so a fresh id for an already-emitted (batch, account) pair
    // would otherwise hit the unique violation; dedup here keeps re-runs idempotent.
    let mut existing_batch_account_keys = existing_items
        .iter()
        .map(|item| (item.settlement_batch_id, item.credit_account_hash.clone()))
        .collect::<BTreeSet<_>>();
    let mut repaired = 0usize;
    for batch in settlement_batches
        .iter()
        .filter(|batch| batch.status == StorageTraceCreditSettlementBatchStatus::Finalized)
    {
        let Some(contract_id) = batch.near_contract_id.as_deref() else {
            continue;
        };
        for item in &batch.line_items {
            match item.near_outbox_id {
                Some(near_outbox_id) => {
                    if existing_outbox_ids.contains(&near_outbox_id) {
                        continue;
                    }
                    let outbox_item = near_credit_outbox_item_from_settlement_line_item(
                        tenant,
                        batch,
                        item,
                        contract_id,
                        near_outbox_id,
                    )?;
                    append_near_credit_outbox_item_with_db_mirror(state, tenant, &outbox_item)
                        .await?;
                    existing_outbox_ids.insert(near_outbox_id);
                    existing_batch_account_keys
                        .insert((batch.settlement_batch_id, item.credit_account_hash.clone()));
                    repaired += 1;
                }
                None => {
                    // Hold recovery: a finalized account line item whose on-chain
                    // payout was previously withheld. Re-resolve the account's payout
                    // target fail-closed; once it resolves (`Designated`/`SoleActive`)
                    // enqueue a fresh `pending` outbox row carrying the payout target.
                    if item.near_payout_hold_reason.is_none() {
                        continue;
                    }
                    let key = (batch.settlement_batch_id, item.credit_account_hash.clone());
                    if existing_batch_account_keys.contains(&key) {
                        continue;
                    }
                    let Some(account_id) = item
                        .credit_account_ref
                        .strip_prefix(ACCOUNT_SETTLEMENT_KEY_PREFIX)
                        .and_then(|raw| Uuid::parse_str(raw).ok())
                    else {
                        continue;
                    };
                    let Some(db) = state.db_mirror.as_ref() else {
                        continue;
                    };
                    let resolution = db
                        .resolve_payout_near_account_id(&tenant.tenant_id, account_id)
                        .await
                        .context("failed to re-resolve held account payout target")?;
                    let payout_near_account_id = match resolution {
                        PayoutResolution::Designated(near) | PayoutResolution::SoleActive(near) => {
                            near
                        }
                        // Still held: leave the line item held, no outbox row.
                        PayoutResolution::Hold(_) => continue,
                    };
                    let near_outbox_id = Uuid::new_v4();
                    let mut outbox_item = near_credit_outbox_item_from_settlement_line_item(
                        tenant,
                        batch,
                        item,
                        contract_id,
                        near_outbox_id,
                    )?;
                    outbox_item.payout_near_account_id = Some(payout_near_account_id);
                    append_near_credit_outbox_item_with_db_mirror(state, tenant, &outbox_item)
                        .await?;
                    existing_outbox_ids.insert(near_outbox_id);
                    existing_batch_account_keys.insert(key);
                    repaired += 1;
                }
            }
        }
    }
    Ok(repaired)
}

fn near_credit_outbox_item_from_settlement_line_item(
    tenant: &TenantAuth,
    batch: &TraceCreditSettlementBatchRecord,
    item: &StorageTraceCreditAccountSettlementLineItem,
    contract_id: &str,
    near_outbox_id: Uuid,
) -> anyhow::Result<TraceNearCreditOutboxItem> {
    let receipt = NearCreditReceipt {
        settlement_batch_id: batch.settlement_batch_id,
        credit_account_hash: item.credit_account_hash.clone(),
        policy_version: batch.policy_version.clone(),
        source_list_hash: item.source_list_hash.clone(),
        attestation_hash: trace_credit_settlement_attestation_hash(
            &item.source_list_hash,
            batch.issuer_approval_evidence_hash.as_deref(),
        ),
        amount_micros: item.settled_credit_delta_micros,
        issuer_signature_hash: trace_credit_settlement_issuer_signature_hash(
            batch.settlement_batch_id,
            &item.source_list_hash,
            batch.issuer_approval_evidence_hash.as_deref(),
        ),
    };
    let near_call = NearCreditReceiptCall::settle(contract_id, receipt)?;
    Ok(TraceNearCreditOutboxItem {
        near_outbox_id,
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        settlement_batch_id: batch.settlement_batch_id,
        credit_account_hash: item.credit_account_hash.clone(),
        near_call,
        status: StorageTraceCreditSettlementNearStatus::Pending,
        // Repair path rebuilds a missing outbox row from the persisted line item,
        // which does not carry the resolved payout target. Leave unset rather than
        // guess; the primary settle path is where designation is resolved.
        payout_near_account_id: None,
        created_at: batch.created_at,
        submitted_at: None,
        near_transaction_hash: None,
        last_error_hash: None,
        confirmed_at: None,
    })
}

fn trace_credit_settlement_attestation_hash(
    source_list_hash: &str,
    issuer_approval_evidence_hash: Option<&str>,
) -> String {
    if let Some(approval_hash) = issuer_approval_evidence_hash {
        sha256_prefixed(&format!(
            "trace-credit-attestation:v2:{source_list_hash}:{approval_hash}"
        ))
    } else {
        sha256_prefixed(&format!("trace-credit-attestation:v1:{source_list_hash}"))
    }
}

fn trace_credit_settlement_issuer_signature_hash(
    settlement_batch_id: Uuid,
    source_list_hash: &str,
    issuer_approval_evidence_hash: Option<&str>,
) -> String {
    if let Some(approval_hash) = issuer_approval_evidence_hash {
        sha256_prefixed(&format!(
            "trace-credit-settlement:v2:{settlement_batch_id}:{source_list_hash}:{approval_hash}"
        ))
    } else {
        sha256_prefixed(&format!(
            "trace-credit-settlement:v1:{settlement_batch_id}:{source_list_hash}"
        ))
    }
}

fn validate_credit_settlement_issuer_approval_evidence_hash(
    value: Option<&str>,
) -> ApiResult<Option<String>> {
    value
        .map(str::trim)
        .filter(|hash| !hash.is_empty())
        .map(|hash| validate_trace_sha256_hash(hash, "issuer_approval_evidence_hash"))
        .transpose()
}

impl TraceCreditSettlementIssuerApprovalResponse {
    fn from_request(
        tenant: &TenantAuth,
        request: TraceCreditSettlementIssuerApprovalRequest,
    ) -> ApiResult<Self> {
        let policy_version =
            validate_credit_settlement_issuer_approval_policy_version(&request.policy_version)?;
        let source_list_hash =
            validate_trace_sha256_hash(&request.source_list_hash, "source_list_hash")?;
        let evidence_hash =
            validate_trace_sha256_hash(&request.evidence_hash, "issuer approval evidence_hash")?;
        let reason_hash = validate_credit_settlement_issuer_approval_reason(&request.reason)?;
        let evidence_ref_hash = request
            .evidence_ref
            .as_deref()
            .map(str::trim)
            .filter(|evidence_ref| !evidence_ref.is_empty())
            .map(sha256_prefixed);
        Ok(Self {
            event_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            policy_version,
            source_list_hash,
            evidence_hash,
            reason_hash,
            evidence_ref_hash,
            actor_principal_ref: tenant.principal_ref.clone(),
            recorded_at: Utc::now(),
        })
    }
}

fn validate_credit_settlement_policy_version(value: &str) -> ApiResult<String> {
    validate_credit_policy_version(value, "credit settlement")
}

fn validate_utility_attestation_use_category(value: &str) -> ApiResult<String> {
    let value = value.trim();
    if value.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "utility attestations require use_category",
        ));
    }
    if value.len() > 128 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "utility attestations use_category is too long",
        ));
    }
    if !value
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.' | ':'))
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "utility attestations use_category contains unsupported characters",
        ));
    }
    Ok(value.to_string())
}

fn credit_settlement_policy_version_allowed(state: &AppState, policy_version: &str) -> bool {
    state.credit_settlement_allowed_policy_versions.is_empty()
        || state
            .credit_settlement_allowed_policy_versions
            .contains(policy_version)
}

fn require_credit_settlement_policy_version_allowed_for_live(
    state: &AppState,
    dry_run: bool,
    policy_version: &str,
) -> ApiResult<()> {
    if dry_run || credit_settlement_policy_version_allowed(state, policy_version) {
        return Ok(());
    }
    Err(api_error(
        StatusCode::CONFLICT,
        format!(
            "live credit settlement policy_version is not listed in {TRACE_COMMONS_CREDIT_SETTLEMENT_ALLOWED_POLICY_VERSIONS}"
        ),
    ))
}

fn require_credit_settlement_issuer_approval_policy_version_allowed_if_configured(
    state: &AppState,
    policy_version: &str,
) -> ApiResult<()> {
    if credit_settlement_policy_version_allowed(state, policy_version) {
        return Ok(());
    }
    Err(api_error(
        StatusCode::CONFLICT,
        format!(
            "credit settlement issuer approval policy_version is not listed in {TRACE_COMMONS_CREDIT_SETTLEMENT_ALLOWED_POLICY_VERSIONS}"
        ),
    ))
}

fn validate_credit_settlement_issuer_approval_policy_version(value: &str) -> ApiResult<String> {
    validate_credit_policy_version(value, "issuer approval")
}

fn validate_credit_policy_version(value: &str, surface: &str) -> ApiResult<String> {
    let value = value.trim();
    if value.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("{surface} requires policy_version"),
        ));
    }
    if value.len() > 256 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("{surface} policy_version is too long"),
        ));
    }
    if !value
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.' | ':'))
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("{surface} policy_version contains unsupported characters"),
        ));
    }
    Ok(value.to_string())
}

fn validate_credit_settlement_issuer_approval_reason(reason: &str) -> ApiResult<String> {
    Ok(sha256_prefixed(&validate_free_text_field(
        reason,
        "issuer approval",
        "reason",
    )?))
}

fn trace_credit_settlement_issuer_approval_audit_reason(
    approval: &TraceCreditSettlementIssuerApprovalResponse,
) -> String {
    trace_credit_settlement_issuer_approval_audit_reason_from_parts(
        &approval.policy_version,
        &approval.source_list_hash,
        &approval.evidence_hash,
        &approval.reason_hash,
        approval.evidence_ref_hash.as_deref(),
    )
}

fn trace_credit_settlement_issuer_approval_audit_reason_from_parts(
    policy_version: &str,
    source_list_hash: &str,
    evidence_hash: &str,
    reason_hash: &str,
    evidence_ref_hash: Option<&str>,
) -> String {
    let mut reason = format!(
        "surface=credit_settlement_issuer_approval;policy_version={};source_list_hash={};evidence_hash={};reason_hash={}",
        policy_version, source_list_hash, evidence_hash, reason_hash
    );
    if let Some(evidence_ref_hash) = evidence_ref_hash {
        reason.push_str(";evidence_ref_hash=");
        reason.push_str(evidence_ref_hash);
    }
    reason
}

fn trace_credit_settlement_issuer_approval_audit_metadata(
    approval: &TraceCreditSettlementIssuerApprovalResponse,
) -> StorageTraceAuditSafeMetadata {
    StorageTraceAuditSafeMetadata::CreditSettlementIssuerApproval {
        policy_version: approval.policy_version.clone(),
        source_list_hash: approval.source_list_hash.clone(),
        evidence_hash: approval.evidence_hash.clone(),
        reason_hash: approval.reason_hash.clone(),
        evidence_ref_hash: approval.evidence_ref_hash.clone(),
    }
}

fn trace_credit_settlement_issuer_approval_audit_metadata_from_reason(
    reason: Option<&str>,
) -> Option<StorageTraceAuditSafeMetadata> {
    if !trace_audit_reason_is_credit_settlement_issuer_approval(reason) {
        return None;
    }
    let policy_version = trace_audit_reason_value(reason, "policy_version")?.to_string();
    let source_list_hash = trace_audit_reason_value(reason, "source_list_hash")?.to_string();
    let evidence_hash = trace_audit_reason_value(reason, "evidence_hash")?.to_string();
    let reason_hash = trace_audit_reason_value(reason, "reason_hash")?.to_string();
    if !is_canonical_sha256_prefixed_hash(&source_list_hash)
        || !is_canonical_sha256_prefixed_hash(&evidence_hash)
        || !is_canonical_sha256_prefixed_hash(&reason_hash)
    {
        return None;
    }
    let evidence_ref_hash = match trace_audit_reason_value(reason, "evidence_ref_hash") {
        Some(hash) if is_canonical_sha256_prefixed_hash(hash) => Some(hash.to_string()),
        Some(_) => return None,
        None => None,
    };
    Some(
        StorageTraceAuditSafeMetadata::CreditSettlementIssuerApproval {
            policy_version,
            source_list_hash,
            evidence_hash,
            reason_hash,
            evidence_ref_hash,
        },
    )
}

fn trace_audit_reason_is_credit_settlement_issuer_approval(reason: Option<&str>) -> bool {
    trace_audit_reason_value(reason, "surface") == Some("credit_settlement_issuer_approval")
}

fn trace_credit_settlement_issuer_approval_from_audit_event(
    event: &TraceCommonsAuditEvent,
) -> Option<anyhow::Result<TraceCreditSettlementIssuerApprovalResponse>> {
    let reason = event.reason.as_deref();
    if event.kind != "credit_settlement_issuer_approval"
        && !trace_audit_reason_is_credit_settlement_issuer_approval(reason)
    {
        return None;
    }
    Some((|| {
        let policy_version = trace_audit_reason_value(reason, "policy_version")
            .context("credit settlement issuer approval audit missing policy_version")?
            .to_string();
        let source_list_hash = trace_audit_reason_value(reason, "source_list_hash")
            .context("credit settlement issuer approval audit missing source_list_hash")?
            .to_string();
        let evidence_hash = trace_audit_reason_value(reason, "evidence_hash")
            .context("credit settlement issuer approval audit missing evidence_hash")?
            .to_string();
        let reason_hash = trace_audit_reason_value(reason, "reason_hash")
            .context("credit settlement issuer approval audit missing reason_hash")?
            .to_string();
        anyhow::ensure!(
            is_canonical_sha256_prefixed_hash(&source_list_hash),
            "credit settlement issuer approval source_list_hash must be a canonical sha256-prefixed hex digest"
        );
        anyhow::ensure!(
            is_canonical_sha256_prefixed_hash(&evidence_hash),
            "credit settlement issuer approval evidence_hash must be a canonical sha256-prefixed hex digest"
        );
        anyhow::ensure!(
            is_canonical_sha256_prefixed_hash(&reason_hash),
            "credit settlement issuer approval reason_hash must be a canonical sha256-prefixed hex digest"
        );
        let evidence_ref_hash =
            trace_audit_reason_value(reason, "evidence_ref_hash").map(ToOwned::to_owned);
        if let Some(evidence_ref_hash) = evidence_ref_hash.as_deref() {
            anyhow::ensure!(
                is_canonical_sha256_prefixed_hash(evidence_ref_hash),
                "credit settlement issuer approval evidence_ref_hash must be a canonical sha256-prefixed hex digest"
            );
        }
        Ok(TraceCreditSettlementIssuerApprovalResponse {
            event_id: event.event_id,
            tenant_id: event.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&event.tenant_id),
            policy_version,
            source_list_hash,
            evidence_hash,
            reason_hash,
            evidence_ref_hash,
            actor_principal_ref: event.actor_principal_ref.clone().unwrap_or_default(),
            recorded_at: event.created_at,
        })
    })())
}

async fn read_credit_settlement_issuer_approvals_for_admin(
    state: &AppState,
    tenant: &TenantAuth,
) -> anyhow::Result<Vec<TraceCreditSettlementIssuerApprovalResponse>> {
    let events = if state.db_audit_reads_for_tenant(&tenant.tenant_id) {
        read_audit_events_from_db(state, tenant).await?
    } else {
        read_all_audit_events(&state.root, &tenant.tenant_id)?
    };
    events
        .iter()
        .filter_map(trace_credit_settlement_issuer_approval_from_audit_event)
        .collect()
}

#[derive(Debug, Default, Clone, Copy)]
struct TraceCreditSettlementIssuerApprovalCheck {
    recorded: bool,
    fresh: bool,
}

async fn credit_settlement_issuer_approval_check(
    state: &AppState,
    tenant: &TenantAuth,
    policy_version: &str,
    source_list_hash: &str,
    evidence_hash: &str,
) -> anyhow::Result<TraceCreditSettlementIssuerApprovalCheck> {
    let now = Utc::now();
    let mut check = TraceCreditSettlementIssuerApprovalCheck::default();
    for approval in read_credit_settlement_issuer_approvals_for_admin(state, tenant).await? {
        if approval.policy_version == policy_version
            && approval.source_list_hash == source_list_hash
            && approval.evidence_hash == evidence_hash
        {
            check.recorded = true;
            if credit_settlement_issuer_approval_is_fresh(state, &approval, now) {
                check.fresh = true;
                break;
            }
        }
    }
    Ok(check)
}

fn credit_settlement_issuer_approval_is_fresh(
    state: &AppState,
    approval: &TraceCreditSettlementIssuerApprovalResponse,
    now: DateTime<Utc>,
) -> bool {
    state
        .credit_settlement_issuer_approval_max_age
        .is_none_or(|max_age| now.signed_duration_since(approval.recorded_at) <= max_age)
}

