async fn credit_hold_release_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    AxumPath(hold_id): AxumPath<Uuid>,
    Json(body): Json<TraceCreditHoldReleaseRequest>,
) -> ApiResult<Json<TraceCreditHoldRecord>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    require_credit_hold_control_principal_if_configured(state.as_ref(), &tenant)?;
    let reason_detail = body.reason_detail.trim();
    if reason_detail.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit hold release requires reason_detail",
        ));
    }
    let holds = read_credit_holds_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let mut hold = holds
        .iter()
        .find(|hold| hold.hold_id == hold_id)
        .cloned()
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "credit hold not found"))?;
    if hold.released_at.is_some() {
        return Ok(Json(hold));
    }
    hold.released_at = Some(db_mirrored_now());
    let release_reason_hash = sha256_prefixed(reason_detail);
    let should_enqueue_near_unfreeze = state.credit_settlement_near_contract_id.is_some()
        && !active_credit_hold_exists_for_account(
            &holds,
            &hold.credit_account_hash,
            Some(hold.hold_id),
        );
    if should_enqueue_near_unfreeze {
        require_near_credit_hold_account_transition_principal_if_configured(
            state.as_ref(),
            &tenant,
        )?;
    }
    append_credit_hold_with_db_mirror(state.as_ref(), &tenant, &hold)
        .await
        .map_err(internal_error)?;
    if should_enqueue_near_unfreeze {
        append_credit_hold_near_account_outbox_item(
            state.as_ref(),
            &tenant,
            &hold,
            false,
            &release_reason_hash,
        )
        .await
        .map_err(internal_error)?;
    }
    append_credit_hold_audit_event(
        state.as_ref(),
        &tenant,
        &hold,
        "credit_hold_release",
        &release_reason_hash,
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(hold))
}

async fn append_credit_hold_audit_event(
    state: &AppState,
    tenant: &TenantAuth,
    hold: &TraceCreditHoldRecord,
    kind: &str,
    reason_hash: &str,
) -> anyhow::Result<()> {
    let action = trace_credit_hold_audit_action_from_kind(kind)
        .context("unsupported credit hold audit kind")?;
    append_audit_event_with_db_mirror(
        state,
        tenant,
        TraceCommonsAuditEvent::credit_hold(tenant, hold, kind, reason_hash),
        StorageTraceAuditAction::CreditMutate,
        trace_credit_hold_audit_metadata(hold, action, reason_hash),
    )
    .await
}

fn active_credit_hold_exists_for_account(
    holds: &[TraceCreditHoldRecord],
    credit_account_hash: &str,
    except_hold_id: Option<Uuid>,
) -> bool {
    holds.iter().any(|hold| {
        hold.credit_account_hash == credit_account_hash
            && hold.released_at.is_none()
            && Some(hold.hold_id) != except_hold_id
    })
}

async fn credit_account_ref_exists_for_admin(
    state: &AppState,
    tenant: &TenantAuth,
    credit_account_ref: &str,
) -> anyhow::Result<bool> {
    let credit_events = read_credit_events_for_admin(state, tenant).await?;
    Ok(credit_events
        .iter()
        .any(|event| event.auth_principal_ref == credit_account_ref))
}

async fn append_credit_hold_near_account_outbox_item(
    state: &AppState,
    tenant: &TenantAuth,
    hold: &TraceCreditHoldRecord,
    freeze: bool,
    reason_hash: &str,
) -> anyhow::Result<Option<Uuid>> {
    let Some(contract_id) = state.credit_settlement_near_contract_id.as_deref() else {
        return Ok(None);
    };
    let near_call = if freeze {
        NearCreditReceiptCall::freeze_account(
            contract_id,
            hold.credit_account_hash.clone(),
            reason_hash.to_string(),
        )?
    } else {
        NearCreditReceiptCall::unfreeze_account(
            contract_id,
            hold.credit_account_hash.clone(),
            reason_hash.to_string(),
        )?
    };
    let near_outbox_id = Uuid::new_v4();
    let item = TraceNearCreditOutboxItem {
        near_outbox_id,
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        settlement_batch_id: hold.hold_id,
        credit_account_hash: hold.credit_account_hash.clone(),
        near_call,
        status: StorageTraceCreditSettlementNearStatus::Pending,
        // Account freeze/unfreeze flow; not a settlement payout.
        payout_near_account_id: None,
        created_at: Utc::now(),
        submitted_at: None,
        near_transaction_hash: None,
        last_error_hash: None,
        confirmed_at: None,
    };
    append_near_credit_outbox_item_with_db_mirror(state, tenant, &item).await?;
    Ok(Some(near_outbox_id))
}

