async fn mark_near_credit_outbox_status_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceNearCreditOutboxStatusRequest>,
) -> ApiResult<Json<TraceNearCreditOutboxItem>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let status = body.status;
    if !matches!(
        status,
        StorageTraceCreditSettlementNearStatus::Submitted
            | StorageTraceCreditSettlementNearStatus::Confirmed
            | StorageTraceCreditSettlementNearStatus::Failed
    ) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "NEAR credit outbox workers may mark submitted, confirmed, or failed status",
        ));
    }

    let near_transaction_hash = body
        .near_transaction_hash
        .as_deref()
        .map(normalize_near_transaction_hash)
        .transpose()
        .map_err(|error| api_error(StatusCode::BAD_REQUEST, error.to_string()))?;
    if matches!(
        status,
        StorageTraceCreditSettlementNearStatus::Submitted
            | StorageTraceCreditSettlementNearStatus::Confirmed
    ) && near_transaction_hash.is_none()
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "submitted or confirmed NEAR credit outbox status requires near_transaction_hash",
        ));
    }
    let last_error_hash = if status == StorageTraceCreditSettlementNearStatus::Failed {
        let error_detail = body.error_detail.as_deref().unwrap_or_default();
        Some(
            outbox_error_detail_hash(error_detail, "failed status")
                .map_err(|error| api_error(StatusCode::BAD_REQUEST, error.to_string()))?,
        )
    } else {
        None
    };
    require_near_credit_outbox_status_principal_if_configured(state.as_ref(), &tenant)?;
    require_near_credit_manual_status_adapter_auth(state.as_ref(), status)?;
    let existing = read_near_credit_outbox_items_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?
        .into_iter()
        .find(|item| item.near_outbox_id == body.near_outbox_id)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "NEAR credit outbox item not found"))?;
    ensure_near_manual_status_transition(&existing, status)?;
    ensure_near_status_transaction_hash_matches_existing(
        &existing,
        status,
        near_transaction_hash.as_deref(),
    )?;
    let updated = update_near_credit_outbox_item_status_with_db_mirror(
        state.as_ref(),
        &tenant,
        body.near_outbox_id,
        status,
        near_transaction_hash,
        last_error_hash,
        None,
    )
    .await
    .map_err(internal_error)?
    .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "NEAR credit outbox item not found"))?;
    append_near_credit_outbox_status_audit(state.as_ref(), &tenant, &updated)
        .await
        .map_err(internal_error)?;
    Ok(Json(updated))
}

async fn append_near_credit_outbox_status_audit(
    state: &AppState,
    tenant: &TenantAuth,
    item: &TraceNearCreditOutboxItem,
) -> anyhow::Result<()> {
    append_audit_event_with_db_mirror(
        state,
        tenant,
        TraceCommonsAuditEvent {
            event_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            submission_id: Uuid::nil(),
            kind: "near_credit_outbox_status".to_string(),
            created_at: Utc::now(),
            status: None,
            actor_role: Some(tenant.role),
            actor_principal_ref: Some(tenant.principal_ref.clone()),
            reason: Some(trace_near_credit_outbox_status_audit_reason(item)),
            export_count: None,
            export_id: None,
            decision_inputs_hash: None,
            previous_event_hash: None,
            event_hash: None,
        },
        StorageTraceAuditAction::CreditMutate,
        trace_near_credit_outbox_status_audit_metadata(item),
    )
    .await
}

fn require_near_credit_manual_status_adapter_auth(
    state: &AppState,
    status: StorageTraceCreditSettlementNearStatus,
) -> ApiResult<()> {
    if !state.near_credit_require_adapter_auth {
        return Ok(());
    }
    match status {
        StorageTraceCreditSettlementNearStatus::Submitted
            if state.near_credit_submitter.is_none()
                || !state.near_credit_submitter_auth_configured =>
        {
            Err(api_error(
                StatusCode::SERVICE_UNAVAILABLE,
                "manual submitted NEAR credit outbox status requires TRACE_COMMONS_NEAR_CREDIT_SUBMITTER_URL and TRACE_COMMONS_NEAR_CREDIT_SUBMITTER_BEARER_TOKEN when TRACE_COMMONS_NEAR_CREDIT_REQUIRE_ADAPTER_AUTH is enabled",
            ))
        }
        StorageTraceCreditSettlementNearStatus::Confirmed
            if state.near_credit_confirmer.is_none()
                || !state.near_credit_confirmer_auth_configured =>
        {
            Err(api_error(
                StatusCode::SERVICE_UNAVAILABLE,
                "manual confirmed NEAR credit outbox status requires TRACE_COMMONS_NEAR_CREDIT_CONFIRMATION_URL and TRACE_COMMONS_NEAR_CREDIT_CONFIRMATION_BEARER_TOKEN when TRACE_COMMONS_NEAR_CREDIT_REQUIRE_ADAPTER_AUTH is enabled",
            ))
        }
        _ => Ok(()),
    }
}

