fn ensure_near_manual_status_transition(
    item: &TraceNearCreditOutboxItem,
    status: StorageTraceCreditSettlementNearStatus,
) -> ApiResult<()> {
    let valid = match status {
        StorageTraceCreditSettlementNearStatus::Submitted => matches!(
            item.status,
            StorageTraceCreditSettlementNearStatus::Pending
                | StorageTraceCreditSettlementNearStatus::Failed
                | StorageTraceCreditSettlementNearStatus::Submitted
        ),
        StorageTraceCreditSettlementNearStatus::Confirmed => {
            matches!(
                item.status,
                StorageTraceCreditSettlementNearStatus::Submitted
                    | StorageTraceCreditSettlementNearStatus::Confirmed
            ) && item.near_transaction_hash.is_some()
        }
        StorageTraceCreditSettlementNearStatus::Failed => matches!(
            item.status,
            StorageTraceCreditSettlementNearStatus::Pending
                | StorageTraceCreditSettlementNearStatus::Submitted
                | StorageTraceCreditSettlementNearStatus::Failed
        ),
        StorageTraceCreditSettlementNearStatus::Pending
        | StorageTraceCreditSettlementNearStatus::Disabled => false,
    };
    if valid {
        return Ok(());
    }
    Err(api_error(
        StatusCode::CONFLICT,
        "manual NEAR credit outbox status update is not valid for the current item state",
    ))
}

fn ensure_benchmark_registry_manual_status_transition(
    item: &TraceBenchmarkRegistryOutboxItem,
    status: StorageTraceBenchmarkRegistryOutboxStatus,
) -> ApiResult<()> {
    let valid = match status {
        StorageTraceBenchmarkRegistryOutboxStatus::Submitted => matches!(
            item.status,
            StorageTraceBenchmarkRegistryOutboxStatus::Pending
                | StorageTraceBenchmarkRegistryOutboxStatus::Failed
                | StorageTraceBenchmarkRegistryOutboxStatus::Submitted
        ),
        StorageTraceBenchmarkRegistryOutboxStatus::Confirmed => {
            matches!(
                item.status,
                StorageTraceBenchmarkRegistryOutboxStatus::Submitted
                    | StorageTraceBenchmarkRegistryOutboxStatus::Confirmed
            ) && item.external_receipt_ref.is_some()
        }
        StorageTraceBenchmarkRegistryOutboxStatus::Failed => matches!(
            item.status,
            StorageTraceBenchmarkRegistryOutboxStatus::Pending
                | StorageTraceBenchmarkRegistryOutboxStatus::Submitted
                | StorageTraceBenchmarkRegistryOutboxStatus::Failed
        ),
        StorageTraceBenchmarkRegistryOutboxStatus::Pending => false,
    };
    if valid {
        return Ok(());
    }
    Err(api_error(
        StatusCode::CONFLICT,
        "manual benchmark registry outbox status update is not valid for the current item state",
    ))
}

async fn mark_benchmark_registry_outbox_status_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceBenchmarkRegistryOutboxStatusRequest>,
) -> ApiResult<Json<TraceBenchmarkRegistryOutboxItem>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_benchmark_worker_operator(&tenant)?;
    let status = body.status;
    if !matches!(
        status,
        StorageTraceBenchmarkRegistryOutboxStatus::Submitted
            | StorageTraceBenchmarkRegistryOutboxStatus::Confirmed
            | StorageTraceBenchmarkRegistryOutboxStatus::Failed
    ) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "benchmark registry outbox workers may mark submitted, confirmed, or failed status",
        ));
    }

    let external_receipt_ref = body
        .external_receipt_ref
        .as_deref()
        .map(normalize_external_registry_receipt_ref)
        .transpose()
        .map_err(|error| api_error(StatusCode::BAD_REQUEST, error.to_string()))?;
    if matches!(
        status,
        StorageTraceBenchmarkRegistryOutboxStatus::Submitted
            | StorageTraceBenchmarkRegistryOutboxStatus::Confirmed
    ) && external_receipt_ref.is_none()
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "submitted or confirmed benchmark registry outbox status requires external_receipt_ref",
        ));
    }
    let last_error_hash = if status == StorageTraceBenchmarkRegistryOutboxStatus::Failed {
        let error_detail = body.error_detail.as_deref().unwrap_or_default();
        Some(
            outbox_error_detail_hash(error_detail, "failed status")
                .map_err(|error| api_error(StatusCode::BAD_REQUEST, error.to_string()))?,
        )
    } else {
        None
    };
    require_benchmark_registry_outbox_status_principal_if_configured(state.as_ref(), &tenant)?;
    require_benchmark_registry_manual_status_adapter_auth(state.as_ref(), status)?;
    let existing = read_benchmark_registry_outbox_items_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?
        .into_iter()
        .find(|item| item.benchmark_outbox_id == body.benchmark_outbox_id)
        .ok_or_else(|| {
            api_error(
                StatusCode::NOT_FOUND,
                "benchmark registry outbox item not found",
            )
        })?;
    ensure_benchmark_registry_manual_status_transition(&existing, status)?;
    let updated = update_benchmark_registry_outbox_item_status_with_db_mirror(
        state.as_ref(),
        &tenant,
        body.benchmark_outbox_id,
        status,
        external_receipt_ref,
        last_error_hash,
    )
    .await
    .map_err(internal_error)?
    .ok_or_else(|| {
        api_error(
            StatusCode::NOT_FOUND,
            "benchmark registry outbox item not found",
        )
    })?;
    append_benchmark_registry_outbox_status_audit(state.as_ref(), &tenant, &updated)
        .await
        .map_err(internal_error)?;
    Ok(Json(updated))
}

async fn append_benchmark_registry_outbox_status_audit(
    state: &AppState,
    tenant: &TenantAuth,
    item: &TraceBenchmarkRegistryOutboxItem,
) -> anyhow::Result<()> {
    append_audit_event_with_db_mirror(
        state,
        tenant,
        TraceCommonsAuditEvent {
            event_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            submission_id: Uuid::nil(),
            kind: "benchmark_registry_outbox_status".to_string(),
            created_at: Utc::now(),
            status: None,
            actor_role: Some(tenant.role),
            actor_principal_ref: Some(tenant.principal_ref.clone()),
            reason: Some(trace_benchmark_registry_outbox_status_audit_reason(item)),
            export_count: None,
            export_id: None,
            decision_inputs_hash: None,
            previous_event_hash: None,
            event_hash: None,
        },
        StorageTraceAuditAction::BenchmarkConvert,
        trace_benchmark_registry_outbox_status_audit_metadata(item),
    )
    .await
}

async fn run_benchmark_registry_outbox_submit_worker(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceBenchmarkRegistryOutboxSubmitWorkerRequest,
) -> anyhow::Result<TraceBenchmarkRegistryOutboxSubmitWorkerResponse> {
    let purpose = normalized_export_purpose(
        request.purpose.as_deref(),
        "trace_commons_benchmark_registry_submit_worker",
    );
    let limit = request
        .limit
        .clamp(1, TRACE_BENCHMARK_REGISTRY_OUTBOX_SUBMIT_MAX_LIMIT) as usize;
    let items = read_benchmark_registry_outbox_items_for_admin(state, tenant).await?;
    let pending_total = items
        .iter()
        .filter(|item| benchmark_registry_outbox_item_is_submit_candidate(item))
        .count();
    let candidates: Vec<_> = items
        .into_iter()
        .filter(benchmark_registry_outbox_item_is_submit_candidate)
        .take(limit)
        .collect();
    let mut response = TraceBenchmarkRegistryOutboxSubmitWorkerResponse {
        purpose,
        dry_run: request.dry_run,
        checked: candidates.len(),
        submitted: 0,
        failed: 0,
        skipped: pending_total.saturating_sub(candidates.len()),
        pending: pending_total,
    };
    if request.dry_run {
        append_benchmark_registry_outbox_submit_audit(state, tenant, &response).await?;
        log_benchmark_registry_outbox_submit_worker_summary(tenant, &response);
        return Ok(response);
    }

    let submitter = state
        .benchmark_registry_submitter
        .as_ref()
        .context("benchmark registry outbox submitter is not configured")?
        .clone();
    for item in candidates {
        let submit_request = benchmark_registry_submitter_request_from_outbox_item(&item);
        match submitter.submit(submit_request).await {
            Ok(submit_response) => {
                let external_receipt_ref = match normalize_external_registry_receipt_ref(
                    &submit_response.external_receipt_ref,
                ) {
                    Ok(external_receipt_ref) => external_receipt_ref,
                    Err(error) => {
                        let last_error_hash = sha256_prefixed(&safe_worker_error(&error));
                        tracing::warn!(
                            tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                            benchmark_outbox_id = %item.benchmark_outbox_id,
                            error_hash = %last_error_hash,
                            "Trace Commons benchmark registry outbox submit rejected adapter receipt"
                        );
                        update_benchmark_registry_outbox_item_status_with_db_mirror(
                            state,
                            tenant,
                            item.benchmark_outbox_id,
                            StorageTraceBenchmarkRegistryOutboxStatus::Failed,
                            None,
                            Some(last_error_hash),
                        )
                        .await?
                        .with_context(|| {
                            format!(
                                "benchmark registry outbox item {} disappeared before invalid-receipt status update",
                                item.benchmark_outbox_id
                            )
                        })?;
                        response.failed += 1;
                        continue;
                    }
                };
                let updated = update_benchmark_registry_outbox_item_status_with_db_mirror(
                    state,
                    tenant,
                    item.benchmark_outbox_id,
                    StorageTraceBenchmarkRegistryOutboxStatus::Submitted,
                    Some(external_receipt_ref),
                    None,
                )
                .await?
                .with_context(|| {
                    format!(
                        "benchmark registry outbox item {} disappeared before submitted status update",
                        item.benchmark_outbox_id
                    )
                })?;
                anyhow::ensure!(
                    updated.status == StorageTraceBenchmarkRegistryOutboxStatus::Submitted,
                    "benchmark registry outbox item {} did not update to submitted status",
                    item.benchmark_outbox_id
                );
                response.submitted += 1;
            }
            Err(error) => {
                let last_error_hash = sha256_prefixed(&safe_worker_error(&error));
                tracing::warn!(
                    tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                    benchmark_outbox_id = %item.benchmark_outbox_id,
                    error_hash = %last_error_hash,
                    "Trace Commons benchmark registry outbox submit failed"
                );
                update_benchmark_registry_outbox_item_status_with_db_mirror(
                    state,
                    tenant,
                    item.benchmark_outbox_id,
                    StorageTraceBenchmarkRegistryOutboxStatus::Failed,
                    None,
                    Some(last_error_hash),
                )
                .await?
                .with_context(|| {
                    format!(
                        "benchmark registry outbox item {} disappeared before failed status update",
                        item.benchmark_outbox_id
                    )
                })?;
                response.failed += 1;
            }
        }
    }
    response.pending = pending_total.saturating_sub(response.submitted);
    append_benchmark_registry_outbox_submit_audit(state, tenant, &response).await?;
    log_benchmark_registry_outbox_submit_worker_summary(tenant, &response);
    Ok(response)
}

async fn run_benchmark_registry_outbox_confirm_worker(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceBenchmarkRegistryOutboxConfirmWorkerRequest,
) -> anyhow::Result<TraceBenchmarkRegistryOutboxConfirmWorkerResponse> {
    let purpose = normalized_export_purpose(
        request.purpose.as_deref(),
        "trace_commons_benchmark_registry_confirm_worker",
    );
    let limit = request
        .limit
        .clamp(1, TRACE_BENCHMARK_REGISTRY_OUTBOX_CONFIRM_MAX_LIMIT) as usize;
    let items = read_benchmark_registry_outbox_items_for_admin(state, tenant).await?;
    let pending_total = items
        .iter()
        .filter(|item| benchmark_registry_outbox_item_is_confirm_candidate(item))
        .count();
    let candidates: Vec<_> = items
        .into_iter()
        .filter(benchmark_registry_outbox_item_is_confirm_candidate)
        .take(limit)
        .collect();
    let mut response = TraceBenchmarkRegistryOutboxConfirmWorkerResponse {
        purpose,
        dry_run: request.dry_run,
        checked: candidates.len(),
        confirmed: 0,
        failed: 0,
        skipped: pending_total.saturating_sub(candidates.len()),
        pending: pending_total,
    };
    if request.dry_run {
        append_benchmark_registry_outbox_confirm_audit(state, tenant, &response).await?;
        log_benchmark_registry_outbox_confirm_worker_summary(tenant, &response);
        return Ok(response);
    }

    let confirmer = state
        .benchmark_registry_confirmer
        .as_ref()
        .context("benchmark registry outbox confirmer is not configured")?
        .clone();
    for item in candidates {
        let confirm_request = match benchmark_registry_confirmation_request_from_outbox_item(&item)
        {
            Ok(request) => request,
            Err(error) => {
                let last_error_hash = sha256_prefixed(&safe_worker_error(&error));
                tracing::warn!(
                    tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                    benchmark_outbox_id = %item.benchmark_outbox_id,
                    error_hash = %last_error_hash,
                    "Trace Commons benchmark registry outbox confirmation skipped invalid receipt"
                );
                let external_receipt_ref = item
                    .external_receipt_ref
                    .as_deref()
                    .and_then(|receipt| normalize_external_registry_receipt_ref(receipt).ok());
                update_benchmark_registry_outbox_item_status_with_db_mirror(
                    state,
                    tenant,
                    item.benchmark_outbox_id,
                    StorageTraceBenchmarkRegistryOutboxStatus::Failed,
                    external_receipt_ref,
                    Some(last_error_hash),
                )
                .await?
                .with_context(|| {
                    format!(
                        "benchmark registry outbox item {} disappeared before invalid-confirmation status update",
                        item.benchmark_outbox_id
                    )
                })?;
                response.failed += 1;
                response.pending = response.pending.saturating_sub(1);
                continue;
            }
        };
        match confirmer.confirm(confirm_request).await {
            Ok(confirm_response) => match confirm_response.status {
                TraceBenchmarkRegistryConfirmationStatus::Confirmed => {
                    let external_receipt_ref = match confirm_response
                        .external_receipt_ref
                        .as_deref()
                        .or(item.external_receipt_ref.as_deref())
                        .context(
                            "confirmed benchmark registry response requires external_receipt_ref",
                        )
                        .and_then(normalize_external_registry_receipt_ref)
                    {
                        Ok(external_receipt_ref) => external_receipt_ref,
                        Err(error) => {
                            let last_error_hash = sha256_prefixed(&safe_worker_error(&error));
                            tracing::warn!(
                                tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                                benchmark_outbox_id = %item.benchmark_outbox_id,
                                error_hash = %last_error_hash,
                                "Trace Commons benchmark registry outbox confirmation rejected adapter receipt"
                            );
                            let existing_receipt_ref =
                                item.external_receipt_ref.as_deref().and_then(|receipt| {
                                    normalize_external_registry_receipt_ref(receipt).ok()
                                });
                            update_benchmark_registry_outbox_item_status_with_db_mirror(
                                state,
                                tenant,
                                item.benchmark_outbox_id,
                                StorageTraceBenchmarkRegistryOutboxStatus::Submitted,
                                existing_receipt_ref,
                                Some(last_error_hash),
                            )
                            .await?
                            .with_context(|| {
                                format!(
                                    "benchmark registry outbox item {} disappeared before confirmation error update",
                                    item.benchmark_outbox_id
                                )
                            })?;
                            response.failed += 1;
                            continue;
                        }
                    };
                    let updated = update_benchmark_registry_outbox_item_status_with_db_mirror(
                        state,
                        tenant,
                        item.benchmark_outbox_id,
                        StorageTraceBenchmarkRegistryOutboxStatus::Confirmed,
                        Some(external_receipt_ref),
                        None,
                    )
                    .await?
                    .with_context(|| {
                        format!(
                            "benchmark registry outbox item {} disappeared before confirmed status update",
                            item.benchmark_outbox_id
                        )
                    })?;
                    anyhow::ensure!(
                        updated.status == StorageTraceBenchmarkRegistryOutboxStatus::Confirmed,
                        "benchmark registry outbox item {} did not update to confirmed status",
                        item.benchmark_outbox_id
                    );
                    response.confirmed += 1;
                    response.pending = response.pending.saturating_sub(1);
                }
                TraceBenchmarkRegistryConfirmationStatus::Failed => {
                    let error_detail = match normalize_outbox_error_detail(
                        confirm_response.error_detail.as_deref().unwrap_or_default(),
                        "failed benchmark registry response",
                    ) {
                        Ok(error_detail) => error_detail,
                        Err(error) => {
                            let last_error_hash = sha256_prefixed(&safe_worker_error(&error));
                            tracing::warn!(
                                tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                                benchmark_outbox_id = %item.benchmark_outbox_id,
                                error_hash = %last_error_hash,
                                "Trace Commons benchmark registry outbox confirmation returned malformed failure"
                            );
                            let external_receipt_ref =
                                item.external_receipt_ref.as_deref().and_then(|receipt| {
                                    normalize_external_registry_receipt_ref(receipt).ok()
                                });
                            update_benchmark_registry_outbox_item_status_with_db_mirror(
                                state,
                                tenant,
                                item.benchmark_outbox_id,
                                StorageTraceBenchmarkRegistryOutboxStatus::Submitted,
                                external_receipt_ref,
                                Some(last_error_hash),
                            )
                            .await?
                            .with_context(|| {
                                format!(
                                    "benchmark registry outbox item {} disappeared before malformed-failure status update",
                                    item.benchmark_outbox_id
                                )
                            })?;
                            response.failed += 1;
                            continue;
                        }
                    };
                    let last_error_hash = sha256_prefixed(&error_detail);
                    tracing::warn!(
                        tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                        benchmark_outbox_id = %item.benchmark_outbox_id,
                        error_hash = %last_error_hash,
                        "Trace Commons benchmark registry outbox confirmation failed at adapter"
                    );
                    let external_receipt_ref = match confirm_response
                        .external_receipt_ref
                        .as_deref()
                        .map(normalize_external_registry_receipt_ref)
                        .transpose()
                    {
                        Ok(Some(receipt_ref)) => Some(receipt_ref),
                        Ok(None) => item
                            .external_receipt_ref
                            .as_deref()
                            .map(normalize_external_registry_receipt_ref)
                            .transpose()?,
                        Err(error) => {
                            let receipt_error_hash = sha256_prefixed(&safe_worker_error(&error));
                            tracing::warn!(
                                tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                                benchmark_outbox_id = %item.benchmark_outbox_id,
                                error_hash = %receipt_error_hash,
                                "Trace Commons benchmark registry outbox confirmation ignored invalid failure receipt"
                            );
                            item.external_receipt_ref.as_deref().and_then(|receipt| {
                                normalize_external_registry_receipt_ref(receipt).ok()
                            })
                        }
                    };
                    update_benchmark_registry_outbox_item_status_with_db_mirror(
                        state,
                        tenant,
                        item.benchmark_outbox_id,
                        StorageTraceBenchmarkRegistryOutboxStatus::Failed,
                        external_receipt_ref,
                        Some(last_error_hash),
                    )
                    .await?
                    .with_context(|| {
                        format!(
                            "benchmark registry outbox item {} disappeared before failed status update",
                            item.benchmark_outbox_id
                        )
                    })?;
                    response.failed += 1;
                    response.pending = response.pending.saturating_sub(1);
                }
                TraceBenchmarkRegistryConfirmationStatus::Pending => {}
            },
            Err(error) => {
                let error_hash = sha256_prefixed(&safe_worker_error(&error));
                tracing::warn!(
                    tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                    benchmark_outbox_id = %item.benchmark_outbox_id,
                    error_hash = %error_hash,
                    "Trace Commons benchmark registry confirmation poll failed"
                );
                response.failed += 1;
            }
        }
    }
    append_benchmark_registry_outbox_confirm_audit(state, tenant, &response).await?;
    log_benchmark_registry_outbox_confirm_worker_summary(tenant, &response);
    Ok(response)
}

