fn benchmark_registry_outbox_item_is_submit_candidate(
    item: &TraceBenchmarkRegistryOutboxItem,
) -> bool {
    matches!(
        item.status,
        StorageTraceBenchmarkRegistryOutboxStatus::Pending
            | StorageTraceBenchmarkRegistryOutboxStatus::Failed
    )
}

fn benchmark_registry_outbox_item_is_confirm_candidate(
    item: &TraceBenchmarkRegistryOutboxItem,
) -> bool {
    item.status == StorageTraceBenchmarkRegistryOutboxStatus::Submitted
        && item.external_receipt_ref.is_some()
}

fn benchmark_registry_submitter_request_from_outbox_item(
    item: &TraceBenchmarkRegistryOutboxItem,
) -> TraceBenchmarkRegistrySubmitterRequest {
    TraceBenchmarkRegistrySubmitterRequest {
        tenant_storage_ref: item.tenant_storage_ref.clone(),
        benchmark_outbox_id: item.benchmark_outbox_id,
        conversion_id: item.conversion_id,
        operation: item.operation,
        registry_ref: item.registry_ref.clone(),
        artifact_payload_hash: item.artifact_payload_hash.clone(),
        source_submission_ids_hash: item.source_submission_ids_hash.clone(),
        evaluator_ref: item.evaluator_ref.clone(),
        evaluation_score: item.evaluation_score,
    }
}

fn benchmark_registry_confirmation_request_from_outbox_item(
    item: &TraceBenchmarkRegistryOutboxItem,
) -> anyhow::Result<TraceBenchmarkRegistryConfirmationRequest> {
    let external_receipt_ref = item
        .external_receipt_ref
        .as_deref()
        .context("benchmark registry confirmation requires external_receipt_ref")
        .and_then(normalize_external_registry_receipt_ref)?;
    Ok(TraceBenchmarkRegistryConfirmationRequest {
        tenant_storage_ref: item.tenant_storage_ref.clone(),
        benchmark_outbox_id: item.benchmark_outbox_id,
        conversion_id: item.conversion_id,
        operation: item.operation,
        registry_ref: item.registry_ref.clone(),
        external_receipt_ref,
        artifact_payload_hash: item.artifact_payload_hash.clone(),
        source_submission_ids_hash: item.source_submission_ids_hash.clone(),
    })
}

async fn run_near_credit_outbox_submit_worker(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceNearCreditOutboxSubmitWorkerRequest,
) -> anyhow::Result<TraceNearCreditOutboxSubmitWorkerResponse> {
    let purpose = normalized_export_purpose(
        request.purpose.as_deref(),
        "trace_commons_near_credit_submit_worker",
    );
    let limit = request
        .limit
        .clamp(1, TRACE_NEAR_CREDIT_OUTBOX_SUBMIT_MAX_LIMIT) as usize;
    // Preview snapshot, used ONLY for the dry_run report. The live submit path
    // re-reads candidates UNDER the advisory lock below so a run that waited on the
    // lock observes the prior run's committed writes (never a stale pre-lock read).
    let preview_items = read_near_credit_outbox_items_for_admin(state, tenant).await?;
    let preview_pending_total = preview_items
        .iter()
        .filter(|item| near_credit_outbox_item_is_submit_candidate(item))
        .count();
    let preview_candidate_count = preview_items
        .iter()
        .filter(|item| near_credit_outbox_item_is_submit_candidate(item))
        .take(limit)
        .count();
    let mut response = TraceNearCreditOutboxSubmitWorkerResponse {
        purpose,
        dry_run: request.dry_run,
        checked: preview_candidate_count,
        submitted: 0,
        failed: 0,
        skipped: preview_pending_total.saturating_sub(preview_candidate_count),
        pending: preview_pending_total,
    };
    if request.dry_run {
        append_near_credit_outbox_submit_audit(state, tenant, &response).await?;
        log_near_credit_outbox_submit_worker_summary(tenant, &response);
        return Ok(response);
    }

    let submitter = state
        .near_credit_submitter
        .as_ref()
        .context("NEAR credit outbox submitter is not configured")?
        .clone();

    // Serialize the live submit pass per-tenant with a session-level Postgres
    // advisory lock held across the external submitter call and the status writes.
    // Without it, two overlapping submit runs (scheduler tick racing a manual
    // worker POST, or a slow run) could both observe the same `pending` row and
    // both call the external submitter before either `pending -> submitted` flip
    // lands — a money-path double on-chain submit. If the lock is already held by
    // another run, no-op (leave rows pending for that run to drive); fail-closed.
    let submit_lock = match state.db_mirror.as_ref() {
        Some(db) => match db
            .try_acquire_near_credit_submit_lock(&tenant.tenant_id)
            .await
            .context("failed to acquire NEAR credit submit advisory lock")?
        {
            Some(lock) => Some(lock),
            None => {
                tracing::info!(
                    tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                    "Trace Commons NEAR credit submit worker yielded: another submit run holds the lock"
                );
                append_near_credit_outbox_submit_audit(state, tenant, &response).await?;
                log_near_credit_outbox_submit_worker_summary(tenant, &response);
                return Ok(response);
            }
        },
        // No DB mirror configured: live submit cannot be serialized. The live
        // submit path requires the mirror in practice; proceed without a lock only
        // for the mirror-less (test/file-only) shape.
        None => None,
    };

    // Run the entire pass UNDER the held lock, capturing the result so the lock is
    // always released (success OR error) before propagation. Critically, the
    // candidate read lives INSIDE this guarded block: a read error must not escape
    // between acquire and release, or the session lock would leak (Drop only warns)
    // and wedge future runs.
    let pass_result: anyhow::Result<()> = async {
        // Re-read candidates UNDER the held lock, DB-authoritatively when a mirror
        // is present. A run that waited on the lock now reads AFTER the prior holder
        // committed its `pending -> submitted` writes, so an already-submitted row is
        // no longer a candidate and is never re-submitted. (The status predicate on
        // the update below is the defense-in-depth second layer.)
        let mut candidates =
            read_near_credit_outbox_submit_candidates_authoritative(state, tenant).await?;
        let pending_total = candidates.len();
        candidates.truncate(limit);
        response.checked = candidates.len();
        response.skipped = pending_total.saturating_sub(candidates.len());
        response.pending = pending_total;

        for item in candidates {
            let submit_request = match near_credit_submitter_request_from_outbox_item(&item) {
                Ok(request) => request,
                Err(error) => {
                    let last_error_hash = sha256_prefixed(&safe_worker_error(&error));
                    tracing::warn!(
                        tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                        near_outbox_id = %item.near_outbox_id,
                        error_hash = %last_error_hash,
                        "Trace Commons NEAR credit outbox submit skipped invalid method call"
                    );
                    update_near_credit_outbox_item_status_with_db_mirror(
                    state,
                    tenant,
                    item.near_outbox_id,
                    StorageTraceCreditSettlementNearStatus::Failed,
                    None,
                    Some(last_error_hash),
                    Some(&[
                        StorageTraceCreditSettlementNearStatus::Pending,
                        StorageTraceCreditSettlementNearStatus::Failed,
                    ]),
                )
                .await?
                .with_context(|| {
                    format!(
                        "NEAR credit outbox item {} disappeared before invalid-call status update",
                        item.near_outbox_id
                    )
                })?;
                    response.failed += 1;
                    continue;
                }
            };
            match submitter.submit(submit_request).await {
                Ok(submit_response) => {
                    let near_transaction_hash =
                        normalize_near_transaction_hash(&submit_response.near_transaction_hash)?;
                    let updated = update_near_credit_outbox_item_status_with_db_mirror(
                        state,
                        tenant,
                        item.near_outbox_id,
                        StorageTraceCreditSettlementNearStatus::Submitted,
                        Some(near_transaction_hash),
                        None,
                        Some(&[
                            StorageTraceCreditSettlementNearStatus::Pending,
                            StorageTraceCreditSettlementNearStatus::Failed,
                        ]),
                    )
                    .await?
                    .with_context(|| {
                        format!(
                            "NEAR credit outbox item {} disappeared before submitted status update",
                            item.near_outbox_id
                        )
                    })?;
                    anyhow::ensure!(
                        updated.status == StorageTraceCreditSettlementNearStatus::Submitted,
                        "NEAR credit outbox item {} did not update to submitted status",
                        item.near_outbox_id
                    );
                    response.submitted += 1;
                }
                Err(error) => {
                    let last_error_hash = sha256_prefixed(&safe_worker_error(&error));
                    tracing::warn!(
                        tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                        near_outbox_id = %item.near_outbox_id,
                        error_hash = %last_error_hash,
                        "Trace Commons NEAR credit outbox submit failed"
                    );
                    update_near_credit_outbox_item_status_with_db_mirror(
                        state,
                        tenant,
                        item.near_outbox_id,
                        StorageTraceCreditSettlementNearStatus::Failed,
                        None,
                        Some(last_error_hash),
                        Some(&[
                            StorageTraceCreditSettlementNearStatus::Pending,
                            StorageTraceCreditSettlementNearStatus::Failed,
                        ]),
                    )
                    .await?
                    .with_context(|| {
                        format!(
                            "NEAR credit outbox item {} disappeared before failed status update",
                            item.near_outbox_id
                        )
                    })?;
                    response.failed += 1;
                }
            }
        }
        response.pending = pending_total.saturating_sub(response.submitted);
        Ok(())
    }
    .await;

    if let Some(lock) = submit_lock {
        lock.release()
            .await
            .context("failed to release NEAR credit submit advisory lock")?;
    }
    pass_result?;

    append_near_credit_outbox_submit_audit(state, tenant, &response).await?;
    log_near_credit_outbox_submit_worker_summary(tenant, &response);
    Ok(response)
}

async fn run_near_credit_outbox_confirm_worker(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceNearCreditOutboxConfirmWorkerRequest,
) -> anyhow::Result<TraceNearCreditOutboxConfirmWorkerResponse> {
    let purpose = normalized_export_purpose(
        request.purpose.as_deref(),
        "trace_commons_near_credit_confirm_worker",
    );
    let limit = request
        .limit
        .clamp(1, TRACE_NEAR_CREDIT_OUTBOX_CONFIRM_MAX_LIMIT) as usize;
    let items = read_near_credit_outbox_items_for_admin(state, tenant).await?;
    let pending_total = items
        .iter()
        .filter(|item| near_credit_outbox_item_is_confirm_candidate(item))
        .count();
    let candidates: Vec<_> = items
        .into_iter()
        .filter(near_credit_outbox_item_is_confirm_candidate)
        .take(limit)
        .collect();
    let mut response = TraceNearCreditOutboxConfirmWorkerResponse {
        purpose,
        dry_run: request.dry_run,
        checked: candidates.len(),
        confirmed: 0,
        failed: 0,
        skipped: pending_total.saturating_sub(candidates.len()),
        pending: pending_total,
    };
    if request.dry_run {
        append_near_credit_outbox_confirm_audit(state, tenant, &response).await?;
        log_near_credit_outbox_confirm_worker_summary(tenant, &response);
        return Ok(response);
    }

    let confirmer = state
        .near_credit_confirmer
        .as_ref()
        .context("NEAR credit outbox confirmer is not configured")?
        .clone();
    for item in candidates {
        let confirm_request = match near_credit_confirmation_request_from_outbox_item(&item) {
            Ok(request) => request,
            Err(error) => {
                let last_error_hash = sha256_prefixed(&safe_worker_error(&error));
                tracing::warn!(
                    tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                    near_outbox_id = %item.near_outbox_id,
                    error_hash = %last_error_hash,
                    "Trace Commons NEAR credit outbox confirmation skipped invalid method call"
                );
                let near_transaction_hash = item
                    .near_transaction_hash
                    .as_deref()
                    .and_then(|hash| normalize_near_transaction_hash(hash).ok());
                update_near_credit_outbox_item_status_with_db_mirror(
                    state,
                    tenant,
                    item.near_outbox_id,
                    StorageTraceCreditSettlementNearStatus::Failed,
                    near_transaction_hash,
                    Some(last_error_hash),
                    None,
                )
                .await?
                .with_context(|| {
                    format!(
                        "NEAR credit outbox item {} disappeared before invalid-confirmation status update",
                        item.near_outbox_id
                    )
                })?;
                response.failed += 1;
                response.pending = response.pending.saturating_sub(1);
                continue;
            }
        };
        match confirmer.confirm(confirm_request).await {
            Ok(confirm_response) => match confirm_response.status {
                TraceNearCreditConfirmationStatus::Confirmed => {
                    match confirmed_near_transaction_hash_for_outbox_item(&item, &confirm_response)
                    {
                        Ok(near_transaction_hash) => {
                            let updated = update_near_credit_outbox_item_status_with_db_mirror(
                                state,
                                tenant,
                                item.near_outbox_id,
                                StorageTraceCreditSettlementNearStatus::Confirmed,
                                Some(near_transaction_hash),
                                None,
                                None,
                            )
                            .await?
                            .with_context(|| {
                                format!(
                                    "NEAR credit outbox item {} disappeared before confirmed status update",
                                    item.near_outbox_id
                                )
                            })?;
                            anyhow::ensure!(
                                updated.status == StorageTraceCreditSettlementNearStatus::Confirmed,
                                "NEAR credit outbox item {} did not update to confirmed status",
                                item.near_outbox_id
                            );
                            response.confirmed += 1;
                            response.pending = response.pending.saturating_sub(1);
                        }
                        Err(error) => {
                            let near_transaction_hash = item
                                .near_transaction_hash
                                .as_deref()
                                .context("NEAR credit confirmation requires near_transaction_hash")
                                .and_then(normalize_near_transaction_hash)?;
                            let last_error_hash = sha256_prefixed(&safe_worker_error(&error));
                            tracing::warn!(
                                tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                                near_outbox_id = %item.near_outbox_id,
                                error_hash = %last_error_hash,
                                "Trace Commons NEAR credit outbox confirmation rejected adapter receipt"
                            );
                            update_near_credit_outbox_item_status_with_db_mirror(
                                state,
                                tenant,
                                item.near_outbox_id,
                                StorageTraceCreditSettlementNearStatus::Submitted,
                                Some(near_transaction_hash),
                                Some(last_error_hash),
                                None,
                            )
                            .await?
                            .with_context(|| {
                                format!(
                                    "NEAR credit outbox item {} disappeared before confirmation error update",
                                    item.near_outbox_id
                                )
                            })?;
                            response.failed += 1;
                        }
                    }
                }
                TraceNearCreditConfirmationStatus::Failed => {
                    let error_detail = match normalize_outbox_error_detail(
                        confirm_response.error_detail.as_deref().unwrap_or_default(),
                        "failed NEAR credit response",
                    ) {
                        Ok(error_detail) => error_detail,
                        Err(error) => {
                            let last_error_hash = sha256_prefixed(&safe_worker_error(&error));
                            tracing::warn!(
                                tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                                near_outbox_id = %item.near_outbox_id,
                                error_hash = %last_error_hash,
                                "Trace Commons NEAR credit outbox confirmation returned malformed failure"
                            );
                            let near_transaction_hash = item
                                .near_transaction_hash
                                .as_deref()
                                .and_then(|hash| normalize_near_transaction_hash(hash).ok());
                            update_near_credit_outbox_item_status_with_db_mirror(
                                state,
                                tenant,
                                item.near_outbox_id,
                                StorageTraceCreditSettlementNearStatus::Submitted,
                                near_transaction_hash,
                                Some(last_error_hash),
                                None,
                            )
                            .await?
                            .with_context(|| {
                                format!(
                                    "NEAR credit outbox item {} disappeared before malformed-failure status update",
                                    item.near_outbox_id
                                )
                            })?;
                            response.failed += 1;
                            continue;
                        }
                    };
                    let last_error_hash = sha256_prefixed(&error_detail);
                    tracing::warn!(
                        tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                        near_outbox_id = %item.near_outbox_id,
                        error_hash = %last_error_hash,
                        "Trace Commons NEAR credit outbox confirmation failed at adapter"
                    );
                    update_near_credit_outbox_item_status_with_db_mirror(
                        state,
                        tenant,
                        item.near_outbox_id,
                        StorageTraceCreditSettlementNearStatus::Failed,
                        confirm_response
                            .near_transaction_hash
                            .as_deref()
                            .or(item.near_transaction_hash.as_deref())
                            .map(normalize_near_transaction_hash)
                            .transpose()?,
                        Some(last_error_hash),
                        None,
                    )
                    .await?
                    .with_context(|| {
                        format!(
                            "NEAR credit outbox item {} disappeared before failed status update",
                            item.near_outbox_id
                        )
                    })?;
                    response.failed += 1;
                    response.pending = response.pending.saturating_sub(1);
                }
                TraceNearCreditConfirmationStatus::Pending => {}
            },
            Err(error) => {
                let error_hash = sha256_prefixed(&safe_worker_error(&error));
                tracing::warn!(
                    tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
                    near_outbox_id = %item.near_outbox_id,
                    error_hash = %error_hash,
                    "Trace Commons NEAR credit confirmation poll failed"
                );
                response.failed += 1;
            }
        }
    }
    append_near_credit_outbox_confirm_audit(state, tenant, &response).await?;
    log_near_credit_outbox_confirm_worker_summary(tenant, &response);
    Ok(response)
}

