async fn ensure_benchmark_registry_outbox_item_with_db_mirror(
    state: &AppState,
    tenant: &TenantAuth,
    item: &TraceBenchmarkRegistryOutboxItem,
) -> anyhow::Result<()> {
    let mirror_result = mirror_benchmark_registry_outbox_item_to_db(state, item).await;
    if state.require_db_mirror_writes {
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_runtime_error_hash(error),
                benchmark_outbox_id = %item.benchmark_outbox_id,
                "Trace Commons DB dual-write benchmark registry outbox mirror failed"
            );
        }
        enforce_db_mirror_write_result(state, "benchmark registry outbox item", mirror_result)?;
        upsert_benchmark_registry_outbox_item(&state.root, &tenant.tenant_id, item)?;
        return Ok(());
    }
    upsert_benchmark_registry_outbox_item(&state.root, &tenant.tenant_id, item)?;
    if let Err(error) = &mirror_result {
        tracing::warn!(
            error_hash = %safe_runtime_error_hash(error),
            benchmark_outbox_id = %item.benchmark_outbox_id,
            "Trace Commons DB dual-write benchmark registry outbox mirror failed"
        );
    }
    enforce_db_mirror_write_result(state, "benchmark registry outbox item", mirror_result)
}

async fn update_near_credit_outbox_item_status_with_db_mirror(
    state: &AppState,
    tenant: &TenantAuth,
    near_outbox_id: Uuid,
    status: StorageTraceCreditSettlementNearStatus,
    near_transaction_hash: Option<String>,
    last_error_hash: Option<String>,
    expected_prior_statuses: Option<&[StorageTraceCreditSettlementNearStatus]>,
) -> anyhow::Result<Option<TraceNearCreditOutboxItem>> {
    let now = Utc::now();
    if state.require_db_mirror_writes {
        let db_updated = mirror_near_credit_outbox_item_status_to_db(
            state,
            &tenant.tenant_id,
            near_outbox_id,
            status,
            near_transaction_hash.clone(),
            last_error_hash.clone(),
            expected_prior_statuses,
        )
        .await
        .context("required Trace Commons DB mirror write failed: NEAR credit outbox status")?;
        if state.db_mirror.is_none() {
            anyhow::bail!(
                "TRACE_COMMONS_REQUIRE_DB_MIRROR_WRITES requires TRACE_COMMONS_DB_DUAL_WRITE for NEAR credit outbox status"
            );
        }
        let file_updated = update_near_credit_outbox_item_status(
            &state.root,
            &tenant.tenant_id,
            near_outbox_id,
            status,
            near_transaction_hash,
            last_error_hash,
            now,
            expected_prior_statuses,
        )?;
        return Ok(file_updated.or(db_updated));
    }

    let file_updated = update_near_credit_outbox_item_status(
        &state.root,
        &tenant.tenant_id,
        near_outbox_id,
        status,
        near_transaction_hash.clone(),
        last_error_hash.clone(),
        now,
        expected_prior_statuses,
    )?;
    let mirror_result = mirror_near_credit_outbox_item_status_to_db(
        state,
        &tenant.tenant_id,
        near_outbox_id,
        status,
        near_transaction_hash,
        last_error_hash,
        expected_prior_statuses,
    )
    .await;
    if let Err(error) = &mirror_result {
        tracing::warn!(
            error_hash = %safe_runtime_error_hash(error),
            %near_outbox_id,
            "Trace Commons DB dual-write NEAR credit outbox status mirror failed"
        );
    }
    let db_updated = mirror_result.unwrap_or(None);
    Ok(file_updated.or(db_updated))
}

