async fn finalize_failed_ranking_worker_run_with_db_mirror(
    state: &AppState,
    tenant: &TenantAuth,
    worker_run: &mut TraceRankingWorkerRunRecord,
    http_status: StatusCode,
    public_error: &str,
) -> ApiResult<()> {
    worker_run.status = TraceRankingWorkerRunStatus::Failed;
    worker_run.completed_at = Some(db_mirrored_now());
    worker_run.last_error_hash = Some(ranking_worker_run_error_hash(http_status, public_error));
    append_ranking_worker_run_with_db_mirror(state, tenant, worker_run)
        .await
        .map_err(internal_error)
}

fn ranking_prediction_credit_event_id(
    tenant: &TenantAuth,
    prediction: &TraceRankingPredictionRecord,
) -> Uuid {
    deterministic_trace_uuid_for_external_ref(
        TraceCreditLedgerEventType::RankingUtility.utility_idempotency_label(),
        &tenant.tenant_id,
        prediction.submission_id,
        &ranking_prediction_external_ref(prediction.ranking_prediction_id),
    )
}

async fn ranking_prediction_credit_already_exists(
    state: &AppState,
    tenant: &TenantAuth,
    prediction: &TraceRankingPredictionRecord,
) -> anyhow::Result<bool> {
    let event_id = ranking_prediction_credit_event_id(tenant, prediction);
    Ok(read_credit_events_for_admin(state, tenant)
        .await?
        .into_iter()
        .any(|event| event.event_id == event_id))
}

async fn count_pending_ranking_prediction_credits(
    state: &AppState,
    tenant: &TenantAuth,
    model_version: Option<&str>,
    target_use: Option<TraceAllowedUse>,
    policy_version: Option<&str>,
) -> anyhow::Result<usize> {
    let predictions = read_ranking_predictions_for_admin(state, tenant).await?;
    let existing_event_ids = read_credit_events_for_admin(state, tenant)
        .await?
        .into_iter()
        .map(|event| event.event_id)
        .collect::<BTreeSet<_>>();
    let mut pending_count = 0usize;
    for prediction in predictions.iter().filter(|prediction| {
        prediction.settlement_score_micros > 0
            && model_version.is_none_or(|model_version| prediction.model_version == model_version)
            && target_use.is_none_or(|target_use| prediction.target_use == target_use)
            && policy_version
                .is_none_or(|policy_version| prediction.prediction_policy_version == policy_version)
            && !existing_event_ids.contains(&ranking_prediction_credit_event_id(tenant, prediction))
    }) {
        match read_ranking_source_submission(
            state,
            tenant,
            prediction.submission_id,
            prediction.target_use,
        )
        .await
        {
            Ok(_) => pending_count += 1,
            Err((status, _)) if ranking_prediction_credit_run_can_skip_status(status) => {}
            Err((status, error)) => {
                anyhow::bail!(
                    "failed to count pending ranking prediction credit: status={}, error={}",
                    status.as_u16(),
                    error.0.error
                );
            }
        }
    }
    Ok(pending_count)
}

async fn ranking_prediction_model_risk_codes(
    state: &AppState,
    tenant: &TenantAuth,
    prediction: &TraceRankingPredictionRecord,
) -> ApiResult<Vec<String>> {
    let model_versions = read_ranking_model_versions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let predictions = read_ranking_predictions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let labels = read_ranking_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let preference_labels = read_ranking_preference_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let calibration_datasets = read_ranking_calibration_datasets_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let calibration_runs = read_ranking_calibration_runs_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let risk_key = ranking_prediction_risk_lookup_key(prediction);
    Ok(ranking_model_risk_report(
        state,
        tenant,
        &model_versions,
        RankingModelRiskEvidence {
            predictions: &predictions,
            labels: &labels,
            preference_labels: &preference_labels,
            calibration_datasets: &calibration_datasets,
            calibration_runs: &calibration_runs,
        },
    )
    .models
    .into_iter()
    .find(|model| {
        ranking_model_risk_lookup_key(
            &model.model_version,
            model.target_use,
            &model.policy_version,
        ) == risk_key
    })
    .map(|model| model.risk_codes)
    .unwrap_or_default())
}

async fn append_ranking_prediction_credit_for_record(
    state: &AppState,
    tenant: &TenantAuth,
    prediction: TraceRankingPredictionRecord,
    reason: &str,
    dry_run: bool,
    allow_at_risk_model: bool,
) -> ApiResult<TraceRankingPredictionCreditResponse> {
    if prediction.settlement_score_micros <= 0 {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit requires a positive settlement score",
        ));
    }
    if !dry_run {
        require_positive_credit_issuance_principal_if_configured(state, tenant, 1.0)?;
    }

    let submission = read_ranking_source_submission(
        state,
        tenant,
        prediction.submission_id,
        prediction.target_use,
    )
    .await?;
    if submission.trace_id != prediction.trace_id {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit source does not match the referenced trace",
        ));
    }

    let model_versions = read_ranking_model_versions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let model = latest_ranking_model_version(&model_versions, &prediction.model_version)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "ranking prediction model not found"))?;
    if model.status != StorageTraceRankingModelStatus::Active {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit requires an active model version",
        ));
    }
    ensure_ranking_model_dataset_isolation(
        model,
        RankingModelDatasetIsolationContext::PredictionCredit,
    )?;
    if model.feature_schema_version != prediction.feature_schema_version {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit feature schema does not match the active model",
        ));
    }
    if model.policy_version != prediction.prediction_policy_version {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit policy does not match the active model",
        ));
    }
    if state.ranking_require_server_feature_provenance {
        let features = read_ranking_features_for_admin(state, tenant)
            .await
            .map_err(internal_error)?;
        if !ranking_prediction_has_server_feature_provenance(&features, &prediction) {
            return Err(api_error(
                StatusCode::CONFLICT,
                "ranking prediction credit requires server-provenanced ranking feature evidence",
            ));
        }
    }
    let calibration_run = latest_promotable_ranking_calibration_run(
        state,
        tenant,
        &prediction.model_version,
        prediction.target_use,
        &prediction.prediction_policy_version,
        &model.calibration_dataset_hash,
        RankingCalibrationGateContext::PredictionCredit,
    )
    .await?;
    let calibration_thresholds =
        effective_ranking_calibration_thresholds(state, Some(&calibration_run));
    if state.ranking_max_labeler_issue_rate_micros.is_some()
        || state.ranking_min_labeler_reliability_label_count.is_some()
    {
        let predictions = read_ranking_predictions_for_admin(state, tenant)
            .await
            .map_err(internal_error)?;
        let labels = read_ranking_labels_for_admin(state, tenant)
            .await
            .map_err(internal_error)?;
        let preference_labels = read_ranking_preference_labels_for_admin(state, tenant)
            .await
            .map_err(internal_error)?;
        let reason_codes = ranking_calibration_labeler_reliability_reason_codes(
            state,
            &tenant.tenant_id,
            model,
            prediction.target_use,
            &predictions,
            &labels,
            &preference_labels,
        );
        if !reason_codes.is_empty() {
            return Err(api_error(
                StatusCode::CONFLICT,
                format!(
                    "ranking prediction credit requires calibration labeler reliability: reason_codes={}",
                    reason_codes.join(",")
                ),
            ));
        }
    }
    if prediction.confidence < calibration_thresholds.confidence_threshold {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit requires prediction confidence to meet the calibration threshold",
        ));
    }
    if !allow_at_risk_model {
        let risk_codes = ranking_prediction_model_risk_codes(state, tenant, &prediction).await?;
        if !risk_codes.is_empty() {
            return Err(api_error(
                StatusCode::CONFLICT,
                format!(
                    "ranking prediction credit requires model risk to be clear: {}",
                    risk_codes.join(",")
                ),
            ));
        }
    }

    let credit_points_delta = prediction.settlement_score_micros as f32 / 1_000_000.0;
    if !credit_points_delta.is_finite() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking prediction credit delta must be finite",
        ));
    }
    if credit_points_delta.abs() > MAX_DELAYED_CREDIT_POINTS_DELTA {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit exceeds the delayed credit policy limit",
        ));
    }

    let external_ref = ranking_prediction_external_ref(prediction.ranking_prediction_id);
    let counts = if dry_run {
        AutomaticUtilityCreditAppendCounts::default()
    } else {
        append_automatic_utility_credit_events_once_with_counts(
            state,
            tenant,
            AutomaticUtilityCreditConfig {
                idempotency_label: TraceCreditLedgerEventType::RankingUtility
                    .utility_idempotency_label(),
                idempotency_ref: Some(external_ref.clone()),
                event_type: TraceCreditLedgerEventType::RankingUtility,
                credit_points_delta,
                reason: format!("ranking prediction credit: {reason}"),
                external_ref: external_ref.clone(),
            },
            [AutomaticUtilityCreditSource {
                submission_id: submission.submission_id,
                trace_id: submission.trace_id,
                auth_principal_ref: submission.auth_principal_ref,
            }],
        )
        .await?
    };

    Ok(TraceRankingPredictionCreditResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        ranking_prediction_id: prediction.ranking_prediction_id,
        submission_id: prediction.submission_id,
        model_version: prediction.model_version,
        target_use: prediction.target_use,
        policy_version: prediction.prediction_policy_version,
        credit_points_delta,
        external_ref,
        appended_count: counts.appended,
        skipped_existing_count: counts.skipped_existing,
    })
}

