async fn create_ranking_calibration_run(
    state: &AppState,
    tenant: &TenantAuth,
    body: TraceRankingCalibrationRunRequest,
    persist: bool,
) -> ApiResult<TraceRankingCalibrationRunRecord> {
    let model_version = validate_ranking_identifier(&body.model_version, "model_version")?;
    let policy_version = validate_ranking_identifier(&body.policy_version, "policy_version")?;
    let evaluation_dataset_hash =
        validate_sha256_hash(&body.evaluation_dataset_hash, "evaluation_dataset_hash")?;
    let confidence_threshold = body
        .confidence_threshold
        .unwrap_or(TRACE_RANKING_DEFAULT_CONFIDENCE_THRESHOLD);
    validate_unit_score(confidence_threshold, "confidence_threshold")?;
    let confidence_threshold = confidence_threshold.max(state.ranking_min_confidence_threshold);
    let min_label_count = body
        .min_label_count
        .unwrap_or(TRACE_RANKING_DEFAULT_MIN_LABEL_COUNT);
    if min_label_count > MAX_TRACE_RANKING_MIN_LABEL_COUNT {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking min_label_count is too large",
        ));
    }
    let min_label_count = min_label_count.max(state.ranking_min_label_count);
    let max_average_absolute_error_micros = body
        .max_average_absolute_error_micros
        .unwrap_or(TRACE_RANKING_DEFAULT_MAX_AVERAGE_ABSOLUTE_ERROR_MICROS);
    validate_nonnegative_micros(
        max_average_absolute_error_micros,
        "max_average_absolute_error_micros",
    )?;
    let max_average_absolute_error_micros =
        max_average_absolute_error_micros.min(state.ranking_max_average_absolute_error_micros);

    let model_versions = read_ranking_model_versions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let model = latest_ranking_model_version(&model_versions, &model_version)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "ranking model version not found"))?;
    ensure_ranking_model_accepts_evidence(model)?;
    if model.policy_version != policy_version {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking calibration policy does not match the registered model",
        ));
    }
    if model.calibration_dataset_hash != evaluation_dataset_hash {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking calibration dataset does not match the registered model",
        ));
    }
    let calibration_datasets = read_ranking_calibration_datasets_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    ensure_ranking_calibration_dataset_can_feed_run(
        &calibration_datasets,
        &evaluation_dataset_hash,
        body.target_use,
        &policy_version,
        ranking_calibration_dataset_gate_config(state, min_label_count),
    )?;
    let feature_schema_version = model.feature_schema_version.clone();
    let predictions = read_ranking_predictions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let labels = read_ranking_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let preference_labels = read_ranking_preference_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let mut record = ranking_calibration_run_record(
        tenant,
        RankingCalibrationRunInputs {
            calibration_run_id: Uuid::new_v4(),
            model_version,
            target_use: body.target_use,
            policy_version,
            feature_schema_version,
            evaluation_dataset_hash,
            min_label_count,
            min_label_source_count: state.ranking_min_label_source_count,
            confidence_threshold,
            max_average_absolute_error_micros,
            actor_principal_ref: tenant.principal_ref.clone(),
            created_at: Utc::now(),
        },
        &predictions,
        &labels,
        &preference_labels,
    );
    record.report_hash = ranking_calibration_run_report_hash(&record);
    if persist {
        append_ranking_calibration_run_with_db_mirror(state, tenant, &record)
            .await
            .map_err(internal_error)?;
    }
    Ok(record)
}

fn ensure_ranking_calibration_dataset_can_feed_run(
    datasets: &[TraceRankingCalibrationDatasetRecord],
    evaluation_dataset_hash: &str,
    target_use: TraceAllowedUse,
    policy_version: &str,
    gate: TraceRankingCalibrationDatasetGateConfig,
) -> ApiResult<()> {
    if let Some(reason) = ranking_calibration_dataset_gate_reason(
        datasets,
        evaluation_dataset_hash,
        target_use,
        policy_version,
        gate,
    ) {
        return Err(api_error(
            StatusCode::CONFLICT,
            ranking_calibration_dataset_gate_error_message(reason),
        ));
    }
    Ok(())
}

#[derive(Debug, Clone, Copy)]
struct TraceRankingCalibrationDatasetGateConfig {
    require_registered: bool,
    require_active: bool,
    min_source_count: usize,
    min_label_source_count: usize,
}

fn ranking_calibration_dataset_gate_config(
    state: &AppState,
    min_source_count: usize,
) -> TraceRankingCalibrationDatasetGateConfig {
    TraceRankingCalibrationDatasetGateConfig {
        require_registered: state.ranking_require_calibration_dataset_registry,
        require_active: state.ranking_require_active_calibration_dataset,
        min_source_count,
        min_label_source_count: state.ranking_min_label_source_count,
    }
}

fn ranking_calibration_dataset_gate_reason(
    datasets: &[TraceRankingCalibrationDatasetRecord],
    calibration_dataset_hash: &str,
    target_use: TraceAllowedUse,
    policy_version: &str,
    gate: TraceRankingCalibrationDatasetGateConfig,
) -> Option<&'static str> {
    let Some(dataset) = datasets.iter().find(|dataset| {
        dataset.calibration_dataset_hash == calibration_dataset_hash
            && dataset.target_use == target_use
            && dataset.policy_version == policy_version
    }) else {
        return gate
            .require_registered
            .then_some("calibration_dataset_not_registered");
    };
    if ranking_calibration_dataset_status_is_retired(dataset.status) {
        return Some("calibration_dataset_retired");
    }
    if gate.require_active && dataset.status != StorageTraceRankingCalibrationDatasetStatus::Active
    {
        return Some("calibration_dataset_not_active");
    }
    if (dataset.source_count as usize) < gate.min_source_count {
        return Some("calibration_dataset_source_count_underdiverse");
    }
    if (dataset.label_source_count as usize) < gate.min_label_source_count {
        return Some("calibration_dataset_label_source_count_underdiverse");
    }
    if (dataset.label_actor_count as usize) < gate.min_label_source_count {
        return Some("calibration_dataset_label_actor_count_underdiverse");
    }
    None
}

fn ranking_calibration_dataset_status_is_retired(
    status: StorageTraceRankingCalibrationDatasetStatus,
) -> bool {
    matches!(
        status,
        StorageTraceRankingCalibrationDatasetStatus::Deprecated
            | StorageTraceRankingCalibrationDatasetStatus::Archived
    )
}

fn ranking_calibration_dataset_gate_error_message(reason: &str) -> &'static str {
    match reason {
        "calibration_dataset_not_registered" => {
            "ranking calibration dataset is not registered for this target use and policy"
        }
        "calibration_dataset_retired" => {
            "ranking calibration dataset is retired for this target use and policy"
        }
        "calibration_dataset_not_active" => {
            "ranking calibration dataset must be active for this target use and policy"
        }
        "calibration_dataset_source_count_underdiverse" => {
            "ranking calibration dataset source_count below configured threshold"
        }
        "calibration_dataset_label_source_count_underdiverse" => {
            "ranking calibration dataset label_source_count below configured threshold"
        }
        "calibration_dataset_label_actor_count_underdiverse" => {
            "ranking calibration dataset label_actor_count below configured threshold"
        }
        _ => "ranking calibration dataset cannot support this target use and policy",
    }
}

async fn ranking_calibration_run_worker_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingCalibrationRunWorkerRequest>,
) -> ApiResult<Json<TraceRankingCalibrationRunWorkerResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let reason = validate_ranking_calibration_run_reason(&body.reason)?;
    let limit = body
        .limit
        .unwrap_or(TRACE_RANKING_CALIBRATION_RUN_DEFAULT_LIMIT);
    if !(1..=TRACE_RANKING_CALIBRATION_RUN_MAX_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking calibration run limit must be between 1 and 100",
        ));
    }
    let model_version = optional_ranking_identifier(body.model_version, "model_version")?;
    let policy_version = optional_ranking_identifier(body.policy_version, "policy_version")?;
    ensure_no_overlapping_live_ranking_worker_run(
        state.as_ref(),
        &tenant,
        TraceRankingWorkerRunKind::Calibration,
        body.dry_run,
        model_version.as_deref(),
        Some(body.target_use),
        policy_version.as_deref(),
    )
    .await?;

    let model_versions = read_ranking_model_versions_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let mut candidates = latest_ranking_model_versions(&model_versions)
        .into_iter()
        .filter(|model| {
            matches!(
                model.status,
                StorageTraceRankingModelStatus::Candidate | StorageTraceRankingModelStatus::Active
            )
        })
        .filter(|model| {
            model_version
                .as_ref()
                .is_none_or(|model_version| &model.model_version == model_version)
                && policy_version
                    .as_ref()
                    .is_none_or(|policy_version| &model.policy_version == policy_version)
        })
        .collect::<Vec<_>>();
    candidates.sort_by(|left, right| {
        (left.created_at, &left.model_version).cmp(&(right.created_at, &right.model_version))
    });
    let candidate_count = candidates.len();

    let mut response = TraceRankingCalibrationRunWorkerResponse {
        ranking_worker_run_id: Uuid::new_v4(),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        dry_run: body.dry_run,
        limit,
        target_use: body.target_use,
        reason_hash: sha256_prefixed(&reason),
        model_version: model_version.clone(),
        policy_version: policy_version.clone(),
        checked_count: 0,
        calibrated_count: 0,
        skipped_existing_count: 0,
        skipped_ineligible_count: 0,
        skipped_reason_counts: BTreeMap::new(),
        pending_after_count: 0,
        calibration_runs: Vec::new(),
    };
    let mut existing_calibration_report_hashes =
        read_ranking_calibration_runs_for_admin(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?
            .into_iter()
            .map(|run| run.report_hash)
            .collect::<BTreeSet<_>>();
    let mut worker_run = TraceRankingWorkerRunRecord {
        ranking_worker_run_id: response.ranking_worker_run_id,
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        run_kind: TraceRankingWorkerRunKind::Calibration,
        status: TraceRankingWorkerRunStatus::Running,
        dry_run: response.dry_run,
        reason_hash: response.reason_hash.clone(),
        model_version: response.model_version.clone(),
        target_use: Some(response.target_use),
        policy_version: response.policy_version.clone(),
        limit: response.limit,
        checked_count: 0,
        succeeded_count: 0,
        skipped_existing_count: 0,
        skipped_model_risk_count: 0,
        skipped_ineligible_count: 0,
        pending_after_count: 0,
        result_refs: Vec::new(),
        reason_counts: BTreeMap::new(),
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: db_mirrored_now(),
        completed_at: None,
        last_error_hash: None,
    };
    append_ranking_worker_run_with_db_mirror(state.as_ref(), &tenant, &worker_run)
        .await
        .map_err(internal_error)?;

    for model in candidates.into_iter().take(limit) {
        response.checked_count += 1;
        let calibration_request = TraceRankingCalibrationRunRequest {
            model_version: model.model_version.clone(),
            target_use: body.target_use,
            policy_version: model.policy_version.clone(),
            evaluation_dataset_hash: model.calibration_dataset_hash.clone(),
            min_label_count: body.min_label_count,
            confidence_threshold: body.confidence_threshold,
            max_average_absolute_error_micros: body.max_average_absolute_error_micros,
        };
        match create_ranking_calibration_run(state.as_ref(), &tenant, calibration_request, false)
            .await
        {
            Ok(run) => {
                if !existing_calibration_report_hashes.insert(run.report_hash.clone()) {
                    response.skipped_existing_count += 1;
                    continue;
                }
                if !body.dry_run
                    && let Err(error) =
                        append_ranking_calibration_run_with_db_mirror(state.as_ref(), &tenant, &run)
                            .await
                {
                    update_calibration_worker_run_from_response(&mut worker_run, &response);
                    let api_error = internal_error(error);
                    let public_error = api_error.1.0.error.clone();
                    finalize_failed_ranking_worker_run_with_db_mirror(
                        state.as_ref(),
                        &tenant,
                        &mut worker_run,
                        api_error.0,
                        &public_error,
                    )
                    .await?;
                    return Err(api_error);
                }
                response.calibrated_count += 1;
                if !run.promotable {
                    for reason in &run.reason_codes {
                        increment_count(&mut response.skipped_reason_counts, reason);
                    }
                }
                response.calibration_runs.push(run);
            }
            Err((status, Json(error)))
                if ranking_calibration_run_worker_can_skip_status(status) =>
            {
                response.skipped_ineligible_count += 1;
                *response
                    .skipped_reason_counts
                    .entry(error.error)
                    .or_insert(0) += 1;
            }
            Err(error) => {
                update_calibration_worker_run_from_response(&mut worker_run, &response);
                let public_error = error.1.0.error.clone();
                finalize_failed_ranking_worker_run_with_db_mirror(
                    state.as_ref(),
                    &tenant,
                    &mut worker_run,
                    error.0,
                    &public_error,
                )
                .await?;
                return Err(error);
            }
        }
    }
    response.pending_after_count = candidate_count.saturating_sub(limit);

    update_calibration_worker_run_from_response(&mut worker_run, &response);
    worker_run.status = TraceRankingWorkerRunStatus::Completed;
    worker_run.completed_at = Some(db_mirrored_now());
    append_ranking_worker_run_with_db_mirror(state.as_ref(), &tenant, &worker_run)
        .await
        .map_err(internal_error)?;

    Ok(Json(response))
}

fn ranking_calibration_run_worker_can_skip_status(status: StatusCode) -> bool {
    matches!(status, StatusCode::NOT_FOUND | StatusCode::CONFLICT)
}

