async fn mirror_ranking_calibration_run_to_db(
    state: &AppState,
    record: &TraceRankingCalibrationRunRecord,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    let max_error_label_source = record
        .max_error_label_source
        .map(|source| serde_storage_string(&source))
        .transpose()?;
    db.upsert_trace_ranking_calibration_run(StorageTraceRankingCalibrationRunWrite {
        tenant_id: record.tenant_id.clone(),
        calibration_run_id: record.calibration_run_id,
        model_version: record.model_version.clone(),
        target_use: serde_storage_string(&record.target_use)?,
        policy_version: record.policy_version.clone(),
        evaluation_dataset_hash: record.evaluation_dataset_hash.clone(),
        prediction_count: u32::try_from(record.prediction_count)
            .context("ranking calibration prediction_count exceeds u32")?,
        label_count: u32::try_from(record.label_count)
            .context("ranking calibration label_count exceeds u32")?,
        joined_label_prediction_count: u32::try_from(record.joined_label_prediction_count)
            .context("ranking calibration joined_label_prediction_count exceeds u32")?,
        joined_label_source_count: u32::try_from(record.joined_label_source_count)
            .context("ranking calibration joined_label_source_count exceeds u32")?,
        joined_label_actor_count: u32::try_from(record.joined_label_actor_count)
            .context("ranking calibration joined_label_actor_count exceeds u32")?,
        joined_evidence_hash: record.joined_evidence_hash.clone(),
        average_predicted_utility_micros: record.average_predicted_utility_micros,
        average_label_utility_delta_micros: record.average_label_utility_delta_micros,
        average_absolute_error_micros: record.average_absolute_error_micros,
        max_label_source_average_absolute_error_micros: record
            .max_label_source_average_absolute_error_micros,
        max_error_label_source,
        mean_signed_error_micros: record.mean_signed_error_micros,
        low_confidence_prediction_count: u32::try_from(record.low_confidence_prediction_count)
            .context("ranking calibration low_confidence_prediction_count exceeds u32")?,
        confidence_threshold: record.confidence_threshold,
        min_label_count: u32::try_from(record.min_label_count)
            .context("ranking calibration min_label_count exceeds u32")?,
        min_label_source_count: u32::try_from(record.min_label_source_count)
            .context("ranking calibration min_label_source_count exceeds u32")?,
        max_average_absolute_error_micros: record.max_average_absolute_error_micros,
        promotable: record.promotable,
        reason_codes: record.reason_codes.clone(),
        report_hash: record.report_hash.clone(),
        actor_principal_ref: record.actor_principal_ref.clone(),
    })
    .await
    .context("failed to mirror ranking calibration run to DB")?;
    Ok(())
}

async fn mirror_ranking_worker_run_to_db(
    state: &AppState,
    record: &TraceRankingWorkerRunRecord,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    db.upsert_trace_ranking_worker_run(StorageTraceRankingWorkerRunWrite {
        tenant_id: record.tenant_id.clone(),
        ranking_worker_run_id: record.ranking_worker_run_id,
        run_kind: record.run_kind,
        status: record.status,
        dry_run: record.dry_run,
        reason_hash: record.reason_hash.clone(),
        model_version: record.model_version.clone(),
        target_use: record
            .target_use
            .map(|target_use| serde_storage_string(&target_use))
            .transpose()?,
        policy_version: record.policy_version.clone(),
        limit: ranking_worker_run_count_to_u32(record.limit, "limit")?,
        checked_count: ranking_worker_run_count_to_u32(record.checked_count, "checked_count")?,
        succeeded_count: ranking_worker_run_count_to_u32(
            record.succeeded_count,
            "succeeded_count",
        )?,
        skipped_existing_count: ranking_worker_run_count_to_u32(
            record.skipped_existing_count,
            "skipped_existing_count",
        )?,
        skipped_model_risk_count: ranking_worker_run_count_to_u32(
            record.skipped_model_risk_count,
            "skipped_model_risk_count",
        )?,
        skipped_ineligible_count: ranking_worker_run_count_to_u32(
            record.skipped_ineligible_count,
            "skipped_ineligible_count",
        )?,
        pending_after_count: ranking_worker_run_count_to_u32(
            record.pending_after_count,
            "pending_after_count",
        )?,
        result_refs: record.result_refs.clone(),
        reason_counts: ranking_worker_run_reason_counts_to_u32(&record.reason_counts)?,
        actor_principal_ref: record.actor_principal_ref.clone(),
        created_at: record.created_at,
        completed_at: record.completed_at,
        last_error_hash: record.last_error_hash.clone(),
    })
    .await
    .context("failed to mirror ranking worker run to DB")?;
    Ok(())
}

fn ranking_worker_run_count_to_u32(value: usize, label: &str) -> anyhow::Result<u32> {
    u32::try_from(value).with_context(|| format!("ranking worker run {label} exceeds u32"))
}

fn ranking_worker_run_reason_counts_to_u32(
    counts: &BTreeMap<String, usize>,
) -> anyhow::Result<BTreeMap<String, u32>> {
    counts
        .iter()
        .map(|(reason, count)| {
            Ok((
                reason.clone(),
                ranking_worker_run_count_to_u32(*count, "reason count")?,
            ))
        })
        .collect()
}

async fn read_ranking_model_versions_for_admin(
    state: &AppState,
    tenant: &TenantAuth,
) -> anyhow::Result<Vec<TraceRankingModelVersionRecord>> {
    if state.db_reviewer_reads_for_tenant(&tenant.tenant_id) {
        let db = state
            .db_mirror
            .as_ref()
            .context("TRACE_COMMONS_DB_REVIEWER_READS is enabled without a DB mirror")?;
        return Ok(db
            .list_trace_ranking_model_versions(&tenant.tenant_id)
            .await
            .context("failed to read ranking model versions from DB mirror")?
            .into_iter()
            .map(ranking_model_version_from_storage)
            .collect());
    }
    read_all_ranking_model_versions(&state.root, &tenant.tenant_id)
}

