fn validate_review_lease_ttl_seconds(ttl_seconds: Option<i64>) -> ApiResult<i64> {
    let ttl_seconds = ttl_seconds.unwrap_or(DEFAULT_REVIEW_LEASE_TTL_SECONDS);
    if !(1..=MAX_REVIEW_LEASE_TTL_SECONDS).contains(&ttl_seconds) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "review lease ttl must be between 1 second and 24 hours",
        ));
    }
    Ok(ttl_seconds)
}

fn validate_review_lease_batch_limit(limit: Option<usize>) -> ApiResult<usize> {
    let limit = limit.unwrap_or(DEFAULT_REVIEW_LEASE_BATCH_LIMIT);
    if !(1..=MAX_REVIEW_LEASE_BATCH_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "review lease batch limit must be between 1 and 50",
        ));
    }
    Ok(limit)
}

async fn prioritized_available_review_lease_candidates(
    state: &AppState,
    tenant: &TenantAuth,
    privacy_risk: Option<ResidualPiiRisk>,
    now: DateTime<Utc>,
) -> anyhow::Result<Vec<Uuid>> {
    let TraceCommonsMetadataView { records, .. } =
        read_reviewer_metadata_view(state, tenant).await?;
    let mut records = records
        .into_iter()
        .filter(|record| record.status == TraceCorpusStatus::Quarantined)
        .filter(|record| !record.is_revoked())
        .filter(|record| privacy_risk.is_none_or(|risk| record.privacy_risk == risk))
        .filter(|record| {
            trace_review_lease_filter_matches(
                record,
                &tenant.principal_ref,
                now,
                TraceReviewLeaseFilter::Available,
            )
        })
        .collect::<Vec<_>>();
    records.sort_by(|left, right| {
        let left_escalation = trace_review_escalation(left, now);
        let right_escalation = trace_review_escalation(right, now);
        right_escalation
            .state
            .rank()
            .cmp(&left_escalation.state.rank())
            .then_with(|| right_escalation.age_hours.cmp(&left_escalation.age_hours))
            .then_with(|| left.received_at.cmp(&right.received_at))
    });
    Ok(records
        .into_iter()
        .map(|record| record.submission_id)
        .collect())
}

fn require_db_reviewer_lease_store<'a>(
    state: &'a AppState,
    tenant: &TenantAuth,
) -> ApiResult<&'a dyn Database> {
    if !state.db_reviewer_reads_for_tenant(&tenant.tenant_id) {
        return Err(api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "review leases require TRACE_COMMONS_DB_REVIEWER_READS=true",
        ));
    }
    state.db_mirror.as_deref().ok_or_else(|| {
        api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "review leases require a configured Trace Commons DB mirror",
        )
    })
}

async fn review_lease_claim_conflict(
    state: &AppState,
    tenant: &TenantAuth,
    submission_id: Uuid,
) -> ApiResult<Json<TraceReviewLeaseResponse>> {
    let record = read_reviewer_submission_record(state, tenant, submission_id)
        .await
        .map_err(internal_error)?
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "trace submission not found"))?;
    if record.status != TraceCorpusStatus::Quarantined {
        return Err(api_error(
            StatusCode::CONFLICT,
            "review leases can only be claimed for quarantined traces",
        ));
    }
    if review_lease_held_by_other(&record, tenant, Utc::now()) {
        return Err(api_error(
            StatusCode::CONFLICT,
            "trace review lease is held by another reviewer",
        ));
    }
    Err(api_error(
        StatusCode::CONFLICT,
        "trace review lease could not be claimed",
    ))
}

async fn review_lease_release_conflict(
    state: &AppState,
    tenant: &TenantAuth,
    submission_id: Uuid,
) -> ApiResult<Json<TraceReviewLeaseResponse>> {
    let record = read_reviewer_submission_record(state, tenant, submission_id)
        .await
        .map_err(internal_error)?
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "trace submission not found"))?;
    if record.status != TraceCorpusStatus::Quarantined {
        return Err(api_error(
            StatusCode::CONFLICT,
            "review leases can only be released for quarantined traces",
        ));
    }
    if review_lease_held_by_other(&record, tenant, Utc::now()) {
        return Err(api_error(
            StatusCode::CONFLICT,
            "trace review lease is held by another reviewer",
        ));
    }
    Err(api_error(
        StatusCode::CONFLICT,
        "no active review lease is owned by this reviewer",
    ))
}

fn review_lease_held_by_other(
    record: &TraceCommonsSubmissionRecord,
    tenant: &TenantAuth,
    now: DateTime<Utc>,
) -> bool {
    record
        .review_assigned_to_principal_ref
        .as_deref()
        .is_some_and(|assigned| {
            assigned != tenant.principal_ref
                && record
                    .review_lease_expires_at
                    .is_some_and(|expires_at| expires_at > now)
        })
}

fn clear_review_lease_metadata(record: &mut TraceCommonsSubmissionRecord) {
    record.review_assigned_to_principal_ref = None;
    record.review_assigned_at = None;
    record.review_lease_expires_at = None;
    record.review_due_at = None;
}

#[derive(Debug, Deserialize)]
struct DatasetExportQuery {
    limit: Option<usize>,
    purpose: Option<String>,
    status: Option<TraceCorpusStatus>,
    privacy_risk: Option<ResidualPiiRisk>,
    consent_scope: Option<String>,
}

async fn dataset_replay_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<DatasetExportQuery>,
) -> ApiResult<Json<TraceReplayDatasetExport>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_exporter(&tenant)?;
    let now = Utc::now();
    let purpose =
        normalized_export_purpose(query.purpose.as_deref(), "trace_commons_replay_dataset");
    let grant = create_one_shot_export_grant(
        state.as_ref(),
        &tenant,
        TraceExportDatasetKind::ReplayDataset,
        purpose,
        query.limit,
        now,
    );
    run_dataset_replay_export_with_grant(state.as_ref(), &tenant, query, grant, now).await
}

async fn worker_replay_export_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<DatasetExportQuery>,
) -> ApiResult<Json<TraceReplayDatasetExport>> {
    run_worker_replay_export(state, headers, query).await
}

async fn worker_replay_export_body_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(query): Json<DatasetExportQuery>,
) -> ApiResult<Json<TraceReplayDatasetExport>> {
    run_worker_replay_export(state, headers, query).await
}

async fn run_worker_replay_export(
    state: Arc<AppState>,
    headers: HeaderMap,
    query: DatasetExportQuery,
) -> ApiResult<Json<TraceReplayDatasetExport>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_export_worker_operator(&tenant)?;
    let now = Utc::now();
    let purpose = normalized_export_purpose(
        query.purpose.as_deref(),
        "trace_commons_worker_replay_dataset",
    );
    let grant = create_one_shot_export_grant(
        state.as_ref(),
        &tenant,
        TraceExportDatasetKind::ReplayDataset,
        purpose,
        query.limit,
        now,
    );
    run_dataset_replay_export_with_grant(state.as_ref(), &tenant, query, grant, now).await
}

async fn run_dataset_replay_export_with_grant(
    state: &AppState,
    tenant: &TenantAuth,
    query: DatasetExportQuery,
    grant: TraceExportAccessGrant,
    now: DateTime<Utc>,
) -> ApiResult<Json<TraceReplayDatasetExport>> {
    let (consent_scope, tenant_policy, purpose) =
        prepare_replay_export_execution(state, tenant, &query).await?;
    let job = create_validated_export_job_slice(
        state,
        tenant,
        TraceExportJobRequest {
            requested_dataset_kind: TraceExportDatasetKind::ReplayDataset,
            purpose: purpose.clone(),
            requested_limit: query.limit,
            grant: grant.clone(),
            metadata: export_job_request_metadata(
                query.limit,
                query.status,
                query.privacy_risk,
                consent_scope,
                None,
            ),
        },
        now,
    )?;
    enforce_export_job_mirror_result(
        state,
        "replay export job start",
        mirror_export_job_started_to_db(state, tenant, &grant, &job).await,
    )
    .await
    .map_err(internal_error)?;
    run_dataset_replay_export_job(
        state,
        tenant,
        query,
        job,
        consent_scope,
        tenant_policy,
        purpose,
    )
    .await
}

async fn prepare_replay_export_execution(
    state: &AppState,
    tenant: &TenantAuth,
    query: &DatasetExportQuery,
) -> ApiResult<(Option<ConsentScope>, Option<TenantSubmissionPolicy>, String)> {
    let consent_scope = parse_consent_scope_filter(query.consent_scope.as_deref())?;
    enforce_dataset_export_guardrails(
        state,
        "replay dataset",
        query.purpose.as_deref(),
        query.status,
        query.privacy_risk,
        consent_scope,
    )?;
    let tenant_policy = tenant_export_policy_for_request(
        state,
        tenant,
        "replay dataset",
        consent_scope,
        TraceAllowedUse::Evaluation,
    )
    .await?;
    let purpose =
        normalized_export_purpose(query.purpose.as_deref(), "trace_commons_replay_dataset");
    Ok((consent_scope, tenant_policy, purpose))
}

async fn run_dataset_replay_export_job(
    state: &AppState,
    tenant: &TenantAuth,
    query: DatasetExportQuery,
    job: TraceExportJobSlice,
    consent_scope: Option<ConsentScope>,
    tenant_policy: Option<TenantSubmissionPolicy>,
    purpose: String,
) -> ApiResult<Json<TraceReplayDatasetExport>> {
    let TraceCommonsMetadataView { records, derived } =
        match read_replay_export_metadata_view(state, tenant).await {
            Ok(view) => view,
            Err(error) => {
                return fail_export_job_with_internal_error(
                    state,
                    &job,
                    "replay export job failure",
                    error,
                )
                .await;
            }
        };
    let derived_by_submission = derived
        .into_iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    let limit = job.max_item_cap;
    let mut items = Vec::new();
    let mut candidate_records = Vec::new();
    for record in records
        .into_iter()
        .filter(|record| query.status.is_none_or(|status| record.status == status))
        .filter(|record| {
            query
                .privacy_risk
                .is_none_or(|risk| record.privacy_risk == risk)
        })
        .filter(|record| consent_scope.is_none_or(|scope| record.consent_scopes.contains(&scope)))
        .filter(|record| {
            record_matches_export_policy_abac(
                record,
                tenant,
                tenant_policy.as_ref(),
                TraceAllowedUse::Evaluation,
            )
        })
    {
        if let Err(error) = ensure_retention_metadata_within_server_policy(&record) {
            return fail_export_job_with_internal_error(
                state,
                &job,
                "replay export job failure",
                error,
            )
            .await;
        }
        if record.is_export_eligible() {
            candidate_records.push(record);
        }
    }
    for record in candidate_records.into_iter().take(limit) {
        let body_read = match read_envelope_for_replay_export(
            state,
            tenant,
            &record,
            "replay_dataset_export",
            Some(&purpose),
        )
        .await
        {
            Ok(body_read) => body_read,
            Err(error) => {
                return fail_export_job_with_internal_error(
                    state,
                    &job,
                    "replay export job failure",
                    error,
                )
                .await;
            }
        };
        items.push(TraceReplayDatasetItem::from_record(
            &record,
            derived_by_submission.get(&record.submission_id),
            &body_read.envelope,
            body_read.object_ref_id,
        ));
    }
    let source_submission_ids = items
        .iter()
        .map(|item| item.submission_id)
        .collect::<Vec<_>>();
    let source_submission_ids_hash =
        source_submission_ids_hash("replay_dataset", &source_submission_ids);

    let export_id = Uuid::new_v4();
    let audit_event = TraceCommonsAuditEvent::dataset_export(
        tenant,
        export_id,
        items.len(),
        source_submission_ids_hash.clone(),
    );
    let audit_event_id = audit_event.event_id;
    let manifest = TraceReplayExportManifest::from_items(
        &tenant.tenant_id,
        export_id,
        audit_event_id,
        purpose,
        TraceReplayExportFilters {
            limit,
            consent_scope,
            status: query.status,
            privacy_risk: query.privacy_risk,
        },
        &items,
        source_submission_ids_hash,
    );
    if state.require_db_mirror_writes {
        let mirror_result = mirror_export_manifest_to_db(
            state,
            StorageTraceObjectArtifactKind::ExportArtifact,
            &manifest,
            &items,
        )
        .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_display_error_hash(error),
                export_id = %manifest.export_id,
                "Trace Commons DB dual-write export manifest mirror failed"
            );
        }
        enforce_db_mirror_write_result(state, "replay export manifest", mirror_result)
            .map_err(internal_error)?;
        write_export_manifest(&state.root, &tenant.tenant_id, &manifest).map_err(internal_error)?;
    } else {
        write_export_manifest(&state.root, &tenant.tenant_id, &manifest).map_err(internal_error)?;
        let mirror_result = mirror_export_manifest_to_db(
            state,
            StorageTraceObjectArtifactKind::ExportArtifact,
            &manifest,
            &items,
        )
        .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_display_error_hash(error),
                export_id = %manifest.export_id,
                "Trace Commons DB dual-write export manifest mirror failed"
            );
        }
        enforce_db_mirror_write_result(state, "replay export manifest", mirror_result)
            .map_err(internal_error)?;
    }
    let audit_result = append_audit_event_with_db_mirror(
        state,
        tenant,
        audit_event.clone(),
        StorageTraceAuditAction::Export,
        StorageTraceAuditSafeMetadata::Export {
            artifact_kind: StorageTraceObjectArtifactKind::ExportArtifact,
            purpose_code: Some(manifest.purpose.clone()),
            item_count: items.len().min(u32::MAX as usize) as u32,
        },
    )
    .await;
    if let Err(error) = audit_result {
        if state.require_db_mirror_writes {
            let manifest_path =
                export_artifact_dir(&state.root, &tenant.tenant_id, manifest.export_id)
                    .join("manifest.json");
            remove_file_if_exists(&manifest_path).map_err(internal_error)?;
            rollback_db_export_manifest_publication(state, &tenant.tenant_id, manifest.export_id)
                .await
                .map_err(internal_error)?;
            remove_audit_event_by_id(&state.root, &tenant.tenant_id, audit_event.event_id)
                .map_err(internal_error)?;
        }
        return Err(internal_error(error));
    }
    enforce_export_job_mirror_result(
        state,
        "replay export job completion",
        mirror_export_job_finished_to_db(state, &job, export_id, items.len()).await,
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(TraceReplayDatasetExport {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        export_id,
        audit_event_id,
        created_at: Utc::now(),
        item_count: items.len(),
        manifest,
        items,
    }))
}

