async fn worker_export_job_claim_next_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceExportJobClaimNextRequest>,
) -> ApiResult<Json<TraceExportJobClaimNextResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_export_worker_operator(&tenant)?;
    let db = trace_export_control_db(state.as_ref())?;
    let requested_dataset_kind = body
        .dataset_kind
        .as_deref()
        .map(trace_export_dataset_kind_from_storage_name)
        .transpose()?;
    require_export_job_claim_central_issuer_if_configured(
        state.as_ref(),
        &tenant,
        requested_dataset_kind,
    )?;
    let dataset_kind = requested_dataset_kind.map(|dataset_kind| dataset_kind.storage_name());
    let claimed = db
        .claim_next_trace_export_job(
            &tenant.tenant_id,
            dataset_kind,
            Utc::now(),
            &tenant.principal_ref,
        )
        .await
        .map_err(internal_error)?;
    let claimed_count = usize::from(claimed.is_some());
    append_audit_event_with_db_mirror(
        state.as_ref(),
        &tenant,
        TraceCommonsAuditEvent::read(&tenant, "export_job_claim_next", claimed_count),
        StorageTraceAuditAction::Read,
        trace_read_audit_metadata("export_job_claim_next", claimed_count),
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(TraceExportJobClaimNextResponse {
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        tenant_id: tenant.tenant_id,
        claimed_job: claimed.map(TraceExportJobSummary::from_storage_record),
    }))
}

async fn worker_export_job_claim_and_run_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceExportJobClaimAndRunRequest>,
) -> ApiResult<Json<TraceExportJobClaimAndRunResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_export_worker_operator(&tenant)?;
    let requested_dataset_kind = body
        .dataset_kind
        .as_deref()
        .map(trace_export_dataset_kind_from_storage_name)
        .transpose()?
        .unwrap_or(TraceExportDatasetKind::ReplayDataset);
    require_export_job_claim_central_issuer_if_configured(
        state.as_ref(),
        &tenant,
        Some(requested_dataset_kind),
    )?;
    let db = trace_export_control_db(state.as_ref())?;
    let claimed = db
        .claim_next_trace_export_job(
            &tenant.tenant_id,
            Some(requested_dataset_kind.storage_name()),
            Utc::now(),
            &tenant.principal_ref,
        )
        .await
        .map_err(internal_error)?;
    let claimed_count = usize::from(claimed.is_some());
    append_audit_event_with_db_mirror(
        state.as_ref(),
        &tenant,
        TraceCommonsAuditEvent::read(&tenant, "export_job_claim_and_run", claimed_count),
        StorageTraceAuditAction::Read,
        trace_read_audit_metadata("export_job_claim_and_run", claimed_count),
    )
    .await
    .map_err(internal_error)?;

    let Some(claimed) = claimed else {
        return Ok(Json(TraceExportJobClaimAndRunResponse {
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            tenant_id: tenant.tenant_id,
            executed_job: None,
            replay_export: None,
            benchmark_artifact: None,
            ranker_candidate_export: None,
            ranker_pair_export: None,
        }));
    };

    let execution = match execute_claimed_export_job(state.as_ref(), &tenant, claimed.clone()).await
    {
        Ok(execution) => execution,
        Err(error) => {
            let error_message = error.1.0.error.clone();
            mark_claimed_export_job_failed(state.as_ref(), &claimed, &error_message)
                .await
                .map_err(internal_error)?;
            return Err(error);
        }
    };
    let executed_job = current_trace_export_job_or_claimed(&db, claimed).await?;
    Ok(Json(TraceExportJobClaimAndRunResponse {
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        tenant_id: tenant.tenant_id,
        executed_job: Some(TraceExportJobSummary::from_storage_record(executed_job)),
        replay_export: execution.replay_export,
        benchmark_artifact: execution.benchmark_artifact,
        ranker_candidate_export: execution.ranker_candidate_export,
        ranker_pair_export: execution.ranker_pair_export,
    }))
}

async fn worker_export_jobs_run_queued_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceExportJobsRunQueuedRequest>,
) -> ApiResult<Json<TraceExportJobsRunQueuedResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_export_worker_operator(&tenant)?;
    let requested_dataset_kind = body
        .dataset_kind
        .as_deref()
        .map(trace_export_dataset_kind_from_storage_name)
        .transpose()?;
    require_export_job_claim_central_issuer_if_configured(
        state.as_ref(),
        &tenant,
        requested_dataset_kind,
    )?;
    let requested_dataset_kind_storage =
        requested_dataset_kind.map(|dataset_kind| dataset_kind.storage_name().to_string());
    let max_jobs = validate_usize_worker_limit(
        body.max_jobs,
        TRACE_EXPORT_JOBS_RUN_QUEUED_DEFAULT_MAX_JOBS,
        TRACE_EXPORT_JOBS_RUN_QUEUED_MAX_JOBS_LIMIT,
        "export jobs run-queued worker",
    )?;
    let db = trace_export_control_db(state.as_ref())?;
    let mut completed_jobs = Vec::new();
    let mut failed_jobs = Vec::new();

    for _ in 0..max_jobs {
        let claimed = db
            .claim_next_trace_export_job(
                &tenant.tenant_id,
                requested_dataset_kind_storage.as_deref(),
                Utc::now(),
                &tenant.principal_ref,
            )
            .await
            .map_err(internal_error)?;
        let Some(claimed) = claimed else {
            break;
        };

        match execute_claimed_export_job(state.as_ref(), &tenant, claimed.clone()).await {
            Ok(_execution) => {
                completed_jobs.push(TraceExportJobSummary::from_storage_record(
                    current_trace_export_job_or_claimed(&db, claimed).await?,
                ));
            }
            Err(error) => {
                let error_message = error.1.0.error.clone();
                mark_claimed_export_job_failed(state.as_ref(), &claimed, &error_message)
                    .await
                    .map_err(internal_error)?;
                failed_jobs.push(TraceExportJobSummary::from_storage_record(
                    current_trace_export_job_or_claimed(&db, claimed).await?,
                ));
            }
        }
    }

    let claimed_count = completed_jobs.len() + failed_jobs.len();
    let pending_after_count = count_pending_export_jobs(
        &db,
        &tenant.tenant_id,
        requested_dataset_kind_storage.as_deref(),
        Utc::now(),
    )
    .await?;
    append_audit_event_with_db_mirror(
        state.as_ref(),
        &tenant,
        TraceCommonsAuditEvent::read(&tenant, "export_jobs_run_queued", claimed_count),
        StorageTraceAuditAction::Read,
        trace_read_audit_metadata("export_jobs_run_queued", claimed_count),
    )
    .await
    .map_err(internal_error)?;

    Ok(Json(TraceExportJobsRunQueuedResponse {
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        tenant_id: tenant.tenant_id,
        requested_dataset_kind: requested_dataset_kind_storage,
        max_jobs,
        claimed_count,
        completed_count: completed_jobs.len(),
        failed_count: failed_jobs.len(),
        pending_after_count,
        completed_jobs,
        failed_jobs,
    }))
}

async fn worker_export_jobs_retry_failed_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceExportJobsRetryFailedRequest>,
) -> ApiResult<Json<TraceExportJobsRetryFailedResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_export_worker_operator(&tenant)?;
    let requested_dataset_kind = body
        .dataset_kind
        .as_deref()
        .map(trace_export_dataset_kind_from_storage_name)
        .transpose()?;
    let requested_dataset_kind_storage =
        requested_dataset_kind.map(|dataset_kind| dataset_kind.storage_name().to_string());
    let max_jobs = validate_usize_worker_limit(
        body.max_jobs,
        TRACE_EXPORT_JOB_RETRY_DEFAULT_MAX_JOBS,
        TRACE_EXPORT_JOB_RETRY_MAX_JOBS_LIMIT,
        "export jobs retry-failed worker",
    )?;
    let max_retry_count = validate_export_job_retry_count_limit(body.max_retry_count)?;
    let base_delay_seconds = validate_export_job_retry_delay_seconds(
        body.base_delay_seconds,
        TRACE_EXPORT_JOB_RETRY_DEFAULT_BASE_DELAY_SECONDS,
        "base_delay_seconds",
    )?;
    let max_delay_seconds = validate_export_job_retry_delay_seconds(
        body.max_delay_seconds,
        TRACE_EXPORT_JOB_RETRY_DEFAULT_MAX_DELAY_SECONDS,
        "max_delay_seconds",
    )?;
    if max_delay_seconds < base_delay_seconds {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "export jobs retry-failed max_delay_seconds must be greater than or equal to base_delay_seconds",
        ));
    }
    let reason = validate_export_job_retry_reason(
        body.reason
            .as_deref()
            .unwrap_or("scheduled export job retry"),
    )?;
    let now = Utc::now();
    let db = trace_export_control_db(state.as_ref())?;
    let mut failed_jobs = db
        .list_trace_export_jobs(&tenant.tenant_id)
        .await
        .map_err(internal_error)?
        .into_iter()
        .filter(|job| job.status == StorageTraceExportJobStatus::Failed)
        .filter(|job| job.expires_at > now)
        .filter(|job| {
            requested_dataset_kind_storage
                .as_deref()
                .is_none_or(|dataset_kind| job.requested_dataset_kind == dataset_kind)
        })
        .collect::<Vec<_>>();
    failed_jobs.sort_by(|left, right| {
        left.finished_at
            .unwrap_or(left.updated_at)
            .cmp(&right.finished_at.unwrap_or(right.updated_at))
            .then_with(|| left.requested_at.cmp(&right.requested_at))
    });

    let mut retried_jobs = Vec::new();
    let mut skipped_not_due_count = 0;
    let mut skipped_ineligible_count = 0;
    for job in failed_jobs {
        if retried_jobs.len() >= max_jobs {
            break;
        }
        if !export_job_has_replayable_request_metadata(&job)
            || current_export_job_retry_count(&job.metadata) >= max_retry_count
        {
            skipped_ineligible_count += 1;
            continue;
        }
        if export_job_retry_due_at(&job, base_delay_seconds, max_delay_seconds) > now {
            skipped_not_due_count += 1;
            continue;
        }
        let retried =
            retry_failed_export_job_record(state.as_ref(), &tenant, &db, job, &reason, now).await?;
        retried_jobs.push(TraceExportJobSummary::from_storage_record(retried));
    }

    let failed_after_count = count_failed_export_jobs(
        &db,
        &tenant.tenant_id,
        requested_dataset_kind_storage.as_deref(),
        Utc::now(),
    )
    .await?;
    append_audit_event_with_db_mirror(
        state.as_ref(),
        &tenant,
        TraceCommonsAuditEvent::read(&tenant, "export_jobs_retry_failed", retried_jobs.len()),
        StorageTraceAuditAction::Read,
        trace_read_audit_metadata("export_jobs_retry_failed", retried_jobs.len()),
    )
    .await
    .map_err(internal_error)?;

    Ok(Json(TraceExportJobsRetryFailedResponse {
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        tenant_id: tenant.tenant_id,
        requested_dataset_kind: requested_dataset_kind_storage,
        max_jobs,
        max_retry_count,
        base_delay_seconds,
        max_delay_seconds,
        retried_count: retried_jobs.len(),
        skipped_not_due_count,
        skipped_ineligible_count,
        failed_after_count,
        retried_jobs,
    }))
}

fn validate_export_job_retry_count_limit(max_retry_count: Option<u32>) -> ApiResult<u32> {
    let max_retry_count = max_retry_count.unwrap_or(TRACE_EXPORT_JOB_RETRY_DEFAULT_MAX_RETRY_COUNT);
    if !(1..=TRACE_EXPORT_JOB_RETRY_MAX_RETRY_COUNT_LIMIT).contains(&max_retry_count) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!(
                "export jobs retry-failed max_retry_count must be between 1 and {}",
                TRACE_EXPORT_JOB_RETRY_MAX_RETRY_COUNT_LIMIT
            ),
        ));
    }
    Ok(max_retry_count)
}

fn validate_export_job_retry_delay_seconds(
    delay_seconds: Option<i64>,
    default_delay_seconds: i64,
    field_name: &str,
) -> ApiResult<i64> {
    let delay_seconds = delay_seconds.unwrap_or(default_delay_seconds);
    if !(0..=TRACE_EXPORT_JOB_RETRY_MAX_DELAY_SECONDS_LIMIT).contains(&delay_seconds) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!(
                "export jobs retry-failed {field_name} must be between 0 and {}",
                TRACE_EXPORT_JOB_RETRY_MAX_DELAY_SECONDS_LIMIT
            ),
        ));
    }
    Ok(delay_seconds)
}

