async fn rollout_smoke_evidence_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<TraceRolloutSmokeEvidenceQuery>,
) -> ApiResult<Json<Vec<TraceRolloutSmokeEvidenceResponse>>> {
    let tenant = authenticate_ctx_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(tenant.auth())?;
    let mut evidence = read_rollout_smoke_evidence_for_admin(state.as_ref(), tenant.auth())
        .await
        .map_err(internal_error)?;
    if query.latest_only.unwrap_or(false) {
        evidence = latest_rollout_smoke_evidence_by_check(evidence);
    }
    append_audit_event_with_db_mirror(
        state.as_ref(),
        tenant.auth(),
        TraceCommonsAuditEvent::read(tenant.auth(), "rollout_smoke_evidence_list", evidence.len()),
        StorageTraceAuditAction::Read,
        trace_read_audit_metadata("rollout_smoke_evidence_list", evidence.len()),
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(evidence))
}

/// #438: "last successful tick at T" is a single value that makes a five-day
/// outage obvious at a glance; 6,999 warnings do not.
///
/// Admin-gated rather than on `/health`, which is unauthenticated: which
/// subsystem is currently dead, and for how long, is operational intelligence
/// -- it tells an anonymous caller when the PII backstop is not running.
///
/// Deliberately does no DB read, no tenant scoping, and no audit write.
/// Driver health is process-global and tenant-independent, and this should
/// stay cheap enough to poll.
async fn driver_liveness_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> ApiResult<Json<Vec<trace_commons_server::driver_liveness::DriverLivenessSnapshot>>> {
    let tenant = authenticate_ctx_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(tenant.auth())?;
    Ok(Json(state.driver_liveness.snapshot(Utc::now())))
}

async fn rollout_smoke_preflight_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> ApiResult<Json<TraceRolloutSmokePreflightResponse>> {
    let tenant = authenticate_ctx_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(tenant.auth())?;
    let generated_at = Utc::now();
    let operational = read_trace_operational_summary(state.as_ref(), &tenant, generated_at)
        .await
        .map_err(internal_error)?;
    let latest_evidence = latest_rollout_smoke_evidence_by_check(
        read_rollout_smoke_evidence_for_admin(state.as_ref(), tenant.auth())
            .await
            .map_err(internal_error)?,
    );
    let item_count = latest_evidence.len();
    let TraceOperationalSummaryResponse {
        tenant_id,
        tenant_storage_ref,
        generated_at,
        rollout_smoke,
        ..
    } = operational;
    let response = TraceRolloutSmokePreflightResponse {
        tenant_id,
        tenant_storage_ref,
        generated_at,
        rollout_smoke,
        latest_evidence,
    };
    append_audit_event_with_db_mirror(
        state.as_ref(),
        tenant.auth(),
        TraceCommonsAuditEvent::read(tenant.auth(), "rollout_smoke_preflight", item_count),
        StorageTraceAuditAction::Read,
        trace_read_audit_metadata("rollout_smoke_preflight", item_count),
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(response))
}

