fn rollout_smoke_check_metric_state(
    rollout_smoke: &TraceOperationalRolloutSmokeSummary,
    check_name: &str,
) -> &'static str {
    if rollout_smoke
        .passed_evidence_checks
        .iter()
        .any(|check| check == check_name)
    {
        "passed"
    } else if rollout_smoke
        .failed_evidence_checks
        .iter()
        .any(|check| check == check_name)
    {
        "failed"
    } else if rollout_smoke
        .stale_evidence_checks
        .iter()
        .any(|check| check == check_name)
    {
        "stale"
    } else {
        "missing"
    }
}

fn push_prometheus_gauge(
    body: &mut String,
    metric_count: &mut usize,
    name: &str,
    labels: &[(&str, &str)],
    value: usize,
) {
    body.push_str(name);
    if !labels.is_empty() {
        body.push('{');
        for (index, (label, label_value)) in labels.iter().enumerate() {
            if index > 0 {
                body.push(',');
            }
            body.push_str(label);
            body.push_str("=\"");
            body.push_str(&prometheus_label_value(label_value));
            body.push('"');
        }
        body.push('}');
    }
    body.push(' ');
    body.push_str(&value.to_string());
    body.push('\n');
    *metric_count += 1;
}

fn prometheus_label_value(value: &str) -> String {
    value
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
}

fn operational_summary_read_audit_event(
    tenant: &TenantAuth,
    response: &TraceOperationalSummaryResponse,
) -> TraceCommonsAuditEvent {
    let mut event =
        TraceCommonsAuditEvent::read(tenant, "operational_summary", response.submissions.total);
    event.reason = Some(format!(
        "{};ready={};blocking_count={};warning_count={};ranking_worker_run_actionable_skip_count={}",
        trace_read_audit_reason("operational_summary", response.submissions.total),
        response.promotion_gates.ready,
        response.promotion_gates.blocking_count,
        response.promotion_gates.warning_count,
        response
            .promotion_gates
            .ranking_worker_run_actionable_skip_count
    ));
    event
}

#[derive(Debug, PartialEq, Eq)]
struct TraceOperationalPromotionGateLogFields {
    tenant_storage_ref: String,
    ready: bool,
    blocking_count: usize,
    warning_count: usize,
    blocking_gates: String,
    warning_gates: String,
    ranking_worker_run_actionable_skip_count: usize,
}

#[derive(Debug, PartialEq, Eq)]
struct TraceOperationalPromotionGateMetricFields {
    tenant_storage_ref: String,
    ready: bool,
    gate_severity: &'static str,
    gate_name: String,
    gate_value: usize,
}

fn operational_summary_promotion_gate_log_fields(
    response: &TraceOperationalSummaryResponse,
) -> Option<TraceOperationalPromotionGateLogFields> {
    let gates = &response.promotion_gates;
    if gates.blocking_count == 0 && gates.warning_count == 0 {
        return None;
    }
    Some(TraceOperationalPromotionGateLogFields {
        tenant_storage_ref: response.tenant_storage_ref.clone(),
        ready: gates.ready,
        blocking_count: gates.blocking_count,
        warning_count: gates.warning_count,
        blocking_gates: gates.blocking_gates.join(","),
        warning_gates: gates.warning_gates.join(","),
        ranking_worker_run_actionable_skip_count: gates.ranking_worker_run_actionable_skip_count,
    })
}

fn operational_summary_promotion_gate_metric_fields(
    response: &TraceOperationalSummaryResponse,
) -> Vec<TraceOperationalPromotionGateMetricFields> {
    let mut fields = Vec::new();
    for gate in &response.promotion_gates.blocking_gates {
        fields.push(operational_summary_promotion_gate_metric_field(
            response, "blocking", gate,
        ));
    }
    for gate in &response.promotion_gates.warning_gates {
        fields.push(operational_summary_promotion_gate_metric_field(
            response, "warning", gate,
        ));
    }
    fields
}

fn operational_summary_promotion_gate_metric_field(
    response: &TraceOperationalSummaryResponse,
    gate_severity: &'static str,
    gate: &str,
) -> TraceOperationalPromotionGateMetricFields {
    let (gate_name, gate_value) = operational_summary_promotion_gate_metric_name_value(gate);
    TraceOperationalPromotionGateMetricFields {
        tenant_storage_ref: response.tenant_storage_ref.clone(),
        ready: response.promotion_gates.ready,
        gate_severity,
        gate_name,
        gate_value,
    }
}

fn operational_summary_promotion_gate_metric_name_value(gate: &str) -> (String, usize) {
    match gate.rsplit_once('=') {
        Some((name, value)) => match value.parse::<usize>() {
            Ok(parsed) => (name.to_string(), parsed),
            Err(_) => (gate.to_string(), 1),
        },
        None => (gate.to_string(), 1),
    }
}

fn log_operational_summary_promotion_gates(response: &TraceOperationalSummaryResponse) {
    let Some(fields) = operational_summary_promotion_gate_log_fields(response) else {
        return;
    };
    tracing::warn!(
        tenant_storage_ref = %fields.tenant_storage_ref,
        ready = fields.ready,
        blocking_count = fields.blocking_count,
        warning_count = fields.warning_count,
        blocking_gates = %fields.blocking_gates,
        warning_gates = %fields.warning_gates,
        ranking_worker_run_actionable_skip_count = fields.ranking_worker_run_actionable_skip_count,
        "Trace Commons operational promotion gates need attention"
    );
    for metric_fields in operational_summary_promotion_gate_metric_fields(response) {
        tracing::warn!(
            tenant_storage_ref = %metric_fields.tenant_storage_ref,
            ready = metric_fields.ready,
            gate_severity = metric_fields.gate_severity,
            gate_name = %metric_fields.gate_name,
            gate_value = metric_fields.gate_value,
            "Trace Commons operational promotion gate metric"
        );
    }
}

fn normalized_export_dataset_kind_filter(value: &str) -> String {
    value.trim().replace('-', "_")
}

async fn read_operational_credit_events(
    state: &AppState,
    tenant: &TenantAuth,
    records: &[TraceCommonsSubmissionRecord],
) -> anyhow::Result<Vec<TraceCommonsCreditLedgerRecord>> {
    if state.db_contributor_reads_for_tenant(&tenant.tenant_id) {
        return read_contributor_credit_events_from_db(state, tenant, None, records).await;
    }

    Ok(credit_events_for_records(
        records,
        visible_credit_events(
            tenant,
            None,
            read_all_credit_events(&state.root, &tenant.tenant_id)?,
        ),
    ))
}

async fn read_operational_ranking_summary(
    state: &AppState,
    tenant: &TenantAuth,
    credit_events: &[TraceCommonsCreditLedgerRecord],
    generated_at: DateTime<Utc>,
) -> anyhow::Result<TraceOperationalRankingSummary> {
    let settlement_batches = read_credit_settlement_batches_for_admin(state, tenant).await?;
    let held_credit_accounts = active_credit_hold_account_refs_for_admin(state, tenant).await?;
    let model_versions = read_ranking_model_versions_for_admin(state, tenant).await?;
    let features = read_ranking_features_for_admin(state, tenant).await?;
    let predictions = read_ranking_predictions_for_admin(state, tenant).await?;
    let labels = read_ranking_labels_for_admin(state, tenant).await?;
    let preference_labels = read_ranking_preference_labels_for_admin(state, tenant).await?;
    let calibration_dataset_read =
        read_ranking_calibration_datasets_for_admin_reconciliation(state, tenant).await?;
    let calibration_dataset_manifest_conflict_count =
        calibration_dataset_read.manifest_conflict_keys.len();
    let calibration_datasets = calibration_dataset_read.records;
    let calibration_runs = read_ranking_calibration_runs_for_admin(state, tenant).await?;
    let worker_runs = read_ranking_worker_runs_for_admin(state, tenant).await?;
    Ok(TraceOperationalRankingSummary::from_inputs(
        TraceOperationalRankingInputs {
            state,
            tenant,
            credit_events,
            settlement_batches: &settlement_batches,
            held_credit_accounts: &held_credit_accounts,
            model_versions: &model_versions,
            features: &features,
            predictions: &predictions,
            labels: &labels,
            preference_labels: &preference_labels,
            calibration_datasets: &calibration_datasets,
            calibration_dataset_manifest_conflict_count,
            calibration_runs: &calibration_runs,
            worker_runs: &worker_runs,
            generated_at,
        },
    ))
}

#[derive(Debug, Default)]
struct TraceOperationalDbSummary {
    db_available: bool,
    trace_corpus_rls: Option<TraceCorpusRlsDiagnostics>,
    export_manifests: Vec<StorageTraceExportManifestRecord>,
    export_jobs: Vec<StorageTraceExportJobRecord>,
    retention_jobs: Vec<StorageTraceRetentionJobRecord>,
    vector_entries: Vec<StorageTraceVectorEntryRecord>,
}

async fn read_operational_db_summary(
    state: &AppState,
    tenant: &TenantAuth,
) -> anyhow::Result<TraceOperationalDbSummary> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(TraceOperationalDbSummary::default());
    };
    let tenant_id = &tenant.tenant_id;
    Ok(TraceOperationalDbSummary {
        db_available: true,
        trace_corpus_rls: db
            .trace_corpus_rls_diagnostics()
            .await
            .context("failed to read Trace Commons PostgreSQL RLS diagnostics")?,
        export_manifests: db
            .list_trace_export_manifests(tenant_id)
            .await
            .context("failed to read Trace Commons operational export manifests")?,
        export_jobs: db
            .list_trace_export_jobs(tenant_id)
            .await
            .context("failed to read Trace Commons operational export jobs")?,
        retention_jobs: db
            .list_trace_retention_jobs(tenant_id)
            .await
            .context("failed to read Trace Commons operational retention jobs")?,
        vector_entries: db
            .list_trace_vector_entries(tenant_id)
            .await
            .context("failed to read Trace Commons operational vector entries")?,
    })
}

fn trace_operational_artifact_kind_name(kind: StorageTraceObjectArtifactKind) -> &'static str {
    match kind {
        StorageTraceObjectArtifactKind::SubmittedEnvelope => "submitted_envelope",
        StorageTraceObjectArtifactKind::RescrubbedEnvelope => "rescrubbed_envelope",
        StorageTraceObjectArtifactKind::ReviewSnapshot => "review_snapshot",
        StorageTraceObjectArtifactKind::BenchmarkArtifact => "benchmark_artifact",
        StorageTraceObjectArtifactKind::ExportArtifact => "export_artifact",
        StorageTraceObjectArtifactKind::WorkerIntermediate => "worker_intermediate",
    }
}

fn trace_operational_export_job_status_name(status: StorageTraceExportJobStatus) -> &'static str {
    match status {
        StorageTraceExportJobStatus::Queued => "queued",
        StorageTraceExportJobStatus::Running => "running",
        StorageTraceExportJobStatus::Complete => "complete",
        StorageTraceExportJobStatus::Failed => "failed",
        StorageTraceExportJobStatus::Cancelled => "cancelled",
        StorageTraceExportJobStatus::Expired => "expired",
    }
}

fn trace_operational_retention_job_status_name(
    status: StorageTraceRetentionJobStatus,
) -> &'static str {
    match status {
        StorageTraceRetentionJobStatus::Planned => "planned",
        StorageTraceRetentionJobStatus::Running => "running",
        StorageTraceRetentionJobStatus::DryRun => "dry_run",
        StorageTraceRetentionJobStatus::Complete => "complete",
        StorageTraceRetentionJobStatus::Failed => "failed",
        StorageTraceRetentionJobStatus::Paused => "paused",
    }
}

fn trace_operational_credit_event_type_name(
    event_type: TraceCreditLedgerEventType,
) -> &'static str {
    match event_type {
        TraceCreditLedgerEventType::BenchmarkConversion => "benchmark_conversion",
        TraceCreditLedgerEventType::RegressionCatch => "regression_catch",
        TraceCreditLedgerEventType::TrainingUtility => "training_utility",
        TraceCreditLedgerEventType::RankingUtility => "ranking_utility",
        TraceCreditLedgerEventType::ReviewerBonus => "reviewer_bonus",
        TraceCreditLedgerEventType::AbusePenalty => "abuse_penalty",
        TraceCreditLedgerEventType::NoveltyUtility => "novelty_utility",
    }
}

