async fn benchmark_evaluation_worker_run_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<BenchmarkEvaluationWorkerRunRequest>,
) -> ApiResult<Json<BenchmarkEvaluationWorkerRunResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_benchmark_worker_operator(&tenant)?;
    run_benchmark_evaluation_worker(state.as_ref(), &tenant, body)
        .await
        .map(Json)
}

async fn run_benchmark_evaluation_worker(
    state: &AppState,
    tenant: &TenantAuth,
    body: BenchmarkEvaluationWorkerRunRequest,
) -> ApiResult<BenchmarkEvaluationWorkerRunResponse> {
    let limit = validate_benchmark_evaluation_worker_limit(body.limit)?;
    let dry_run = body.dry_run.unwrap_or(false);
    let evaluator_ref = normalize_required_benchmark_evaluator_ref(body.evaluator_ref)?;
    let require_external_evaluator = body.require_external_evaluator.unwrap_or(false);
    if require_external_evaluator && state.benchmark_evaluator.is_none() {
        return Err(api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "benchmark evaluation worker requires TRACE_COMMONS_BENCHMARK_EVALUATOR_URL",
        ));
    }
    let external_evaluator = state.benchmark_evaluator.clone();
    let reason = normalize_benchmark_evaluation_worker_reason(body.reason)?;
    let min_score = body.min_score.unwrap_or(1.0);
    validate_unit_score(min_score, "benchmark evaluation min_score")?;
    let artifacts = list_benchmark_conversion_artifacts_for_worker(state, tenant)
        .await
        .map_err(internal_error)?;
    let mut response = BenchmarkEvaluationWorkerRunResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        dry_run,
        limit,
        evaluator_ref: evaluator_ref.clone(),
        min_score,
        reason_hash: sha256_prefixed(&reason),
        checked_count: 0,
        evaluated_count: 0,
        passed_count: 0,
        failed_count: 0,
        skipped_existing_count: 0,
        skipped_ineligible_count: 0,
        pending_after_count: 0,
        evaluated_conversion_ids: Vec::new(),
        failed_conversion_ids: Vec::new(),
        skipped_reason_counts: BTreeMap::new(),
    };
    let initial_pending_count = artifacts
        .iter()
        .filter(|artifact| benchmark_artifact_is_pending_evaluation(artifact))
        .count();

    for artifact in artifacts.iter().take(limit) {
        response.checked_count += 1;
        if artifact.registry.status != TraceBenchmarkRegistryStatus::Candidate {
            response.skipped_ineligible_count += 1;
            increment_count(
                &mut response.skipped_reason_counts,
                "registry_not_candidate",
            );
            continue;
        }
        if artifact.evaluation.status != TraceBenchmarkEvaluationStatus::NotRun {
            response.skipped_existing_count += 1;
            increment_count(
                &mut response.skipped_reason_counts,
                "evaluation_already_recorded",
            );
            continue;
        }
        if artifact.candidates.is_empty() {
            response.skipped_ineligible_count += 1;
            increment_count(&mut response.skipped_reason_counts, "empty_benchmark");
            continue;
        }
        if dry_run && external_evaluator.is_some() {
            response.skipped_ineligible_count += 1;
            increment_count(
                &mut response.skipped_reason_counts,
                "external_evaluator_dry_run",
            );
            continue;
        }
        let decision = if let Some(evaluator) = external_evaluator.as_ref() {
            let evaluator_request =
                benchmark_evaluator_request_from_artifact(artifact, &evaluator_ref, min_score)
                    .map_err(internal_error)?;
            match evaluator.evaluate(evaluator_request).await {
                Ok(evaluator_response) => {
                    match benchmark_evaluation_worker_decision_from_external_response(
                        &evaluator_response,
                    ) {
                        Ok(decision) => decision,
                        Err(error) => {
                            tracing::warn!(
                                error_hash = %safe_display_error_hash(&error),
                                conversion_id = %artifact.conversion_id,
                                "Trace Commons benchmark evaluator response was rejected"
                            );
                            response.skipped_ineligible_count += 1;
                            increment_count(
                                &mut response.skipped_reason_counts,
                                "evaluator_adapter_error",
                            );
                            continue;
                        }
                    }
                }
                Err(error) => {
                    tracing::warn!(
                        error_hash = %safe_display_error_hash(&error),
                        conversion_id = %artifact.conversion_id,
                        "Trace Commons benchmark evaluator call failed"
                    );
                    response.skipped_ineligible_count += 1;
                    increment_count(
                        &mut response.skipped_reason_counts,
                        "evaluator_adapter_error",
                    );
                    continue;
                }
            }
        } else {
            evaluate_benchmark_artifact_for_worker(artifact, min_score)
                .expect("non-empty benchmark artifact evaluates structurally")
        };
        if !dry_run {
            let _ = update_benchmark_lifecycle(
                state,
                tenant,
                artifact.conversion_id,
                BenchmarkLifecycleUpdateRequest {
                    registry: None,
                    evaluation: Some(TraceBenchmarkEvaluationPatch {
                        status: Some(decision.status),
                        evaluator_ref: Some(evaluator_ref.clone()),
                        evaluated_at: Some(Utc::now()),
                        score: Some(decision.score),
                        pass_count: Some(decision.pass_count),
                        fail_count: Some(decision.fail_count),
                    }),
                    reason: Some(reason.clone()),
                },
            )
            .await?;
        }
        response.evaluated_count += 1;
        response
            .evaluated_conversion_ids
            .push(artifact.conversion_id);
        match decision.status {
            TraceBenchmarkEvaluationStatus::Passed => {
                response.passed_count += 1;
            }
            TraceBenchmarkEvaluationStatus::Failed => {
                response.failed_count += 1;
                response.failed_conversion_ids.push(artifact.conversion_id);
            }
            TraceBenchmarkEvaluationStatus::NotRun
            | TraceBenchmarkEvaluationStatus::Queued
            | TraceBenchmarkEvaluationStatus::Running
            | TraceBenchmarkEvaluationStatus::Inconclusive => {}
        }
    }
    response.pending_after_count =
        initial_pending_count.saturating_sub(if dry_run { 0 } else { response.evaluated_count });
    Ok(response)
}

fn validate_benchmark_evaluation_worker_limit(limit: Option<usize>) -> ApiResult<usize> {
    let limit = limit.unwrap_or(TRACE_BENCHMARK_EVALUATION_WORKER_RUN_DEFAULT_LIMIT);
    if !(1..=TRACE_BENCHMARK_EVALUATION_WORKER_RUN_MAX_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "benchmark evaluation worker limit must be between 1 and 100",
        ));
    }
    Ok(limit)
}

fn normalize_required_benchmark_evaluator_ref(value: Option<String>) -> ApiResult<String> {
    let Some(value) = value else {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "benchmark evaluation worker requires evaluator_ref",
        ));
    };
    normalize_benchmark_lifecycle_ref(value)?.ok_or_else(|| {
        api_error(
            StatusCode::BAD_REQUEST,
            "benchmark evaluation worker requires evaluator_ref",
        )
    })
}

fn normalize_benchmark_evaluation_worker_reason(value: Option<String>) -> ApiResult<String> {
    let Some(value) = value
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
    else {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "benchmark evaluation worker requires reason",
        ));
    };
    Ok(value)
}

async fn benchmark_registry_publication_worker_run_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<BenchmarkRegistryPublicationWorkerRunRequest>,
) -> ApiResult<Json<BenchmarkRegistryPublicationWorkerRunResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_benchmark_worker_operator(&tenant)?;
    run_benchmark_registry_publication_worker(state.as_ref(), &tenant, body)
        .await
        .map(Json)
}

async fn run_benchmark_registry_publication_worker(
    state: &AppState,
    tenant: &TenantAuth,
    body: BenchmarkRegistryPublicationWorkerRunRequest,
) -> ApiResult<BenchmarkRegistryPublicationWorkerRunResponse> {
    let limit = validate_benchmark_registry_publication_worker_limit(body.limit)?;
    let dry_run = body.dry_run.unwrap_or(false);
    let registry_ref_prefix = normalize_benchmark_registry_ref_prefix(body.registry_ref_prefix)?;
    let reason = normalize_benchmark_registry_publication_worker_reason(body.reason)?;
    let artifacts = list_benchmark_conversion_artifacts_for_worker(state, tenant)
        .await
        .map_err(internal_error)?;
    let mut response = BenchmarkRegistryPublicationWorkerRunResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        dry_run,
        limit,
        registry_ref_prefix: registry_ref_prefix.clone(),
        reason_hash: sha256_prefixed(&reason),
        checked_count: 0,
        published_count: 0,
        skipped_existing_count: 0,
        skipped_ineligible_count: 0,
        pending_after_count: 0,
        published_conversion_ids: Vec::new(),
        skipped_reason_counts: BTreeMap::new(),
    };

    for artifact in artifacts.iter().take(limit) {
        response.checked_count += 1;
        if artifact.registry.status == TraceBenchmarkRegistryStatus::Published {
            response.skipped_existing_count += 1;
            increment_count(
                &mut response.skipped_reason_counts,
                "registry_already_published",
            );
            continue;
        }
        if artifact.registry.status != TraceBenchmarkRegistryStatus::Candidate {
            response.skipped_ineligible_count += 1;
            increment_count(
                &mut response.skipped_reason_counts,
                "registry_not_candidate",
            );
            continue;
        }
        if artifact.evaluation.status != TraceBenchmarkEvaluationStatus::Passed {
            response.skipped_ineligible_count += 1;
            increment_count(&mut response.skipped_reason_counts, "evaluation_not_passed");
            continue;
        }
        if !benchmark_artifact_has_publishable_evaluation_metadata(artifact) {
            response.skipped_ineligible_count += 1;
            increment_count(
                &mut response.skipped_reason_counts,
                "evaluator_metadata_incomplete",
            );
            continue;
        }
        let registry_ref =
            benchmark_registry_publication_ref(&registry_ref_prefix, artifact.conversion_id)?;
        if !dry_run {
            let _ = update_benchmark_lifecycle(
                state,
                tenant,
                artifact.conversion_id,
                BenchmarkLifecycleUpdateRequest {
                    registry: Some(TraceBenchmarkRegistryPatch {
                        status: Some(TraceBenchmarkRegistryStatus::Published),
                        registry_ref: Some(registry_ref),
                        published_at: Some(Utc::now()),
                    }),
                    evaluation: None,
                    reason: Some(reason.clone()),
                },
            )
            .await?;
        }
        response.published_count += 1;
        response
            .published_conversion_ids
            .push(artifact.conversion_id);
    }
    response.pending_after_count = artifacts
        .iter()
        .skip(limit)
        .filter(|artifact| benchmark_artifact_is_publishable_by_worker(artifact))
        .count();
    Ok(response)
}

fn validate_benchmark_registry_publication_worker_limit(limit: Option<usize>) -> ApiResult<usize> {
    let limit = limit.unwrap_or(TRACE_BENCHMARK_REGISTRY_PUBLICATION_WORKER_RUN_DEFAULT_LIMIT);
    if !(1..=TRACE_BENCHMARK_REGISTRY_PUBLICATION_WORKER_RUN_MAX_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "benchmark registry publication worker limit must be between 1 and 100",
        ));
    }
    Ok(limit)
}

fn normalize_benchmark_registry_ref_prefix(value: Option<String>) -> ApiResult<String> {
    let Some(value) = value
        .map(|value| value.trim().trim_end_matches(':').to_string())
        .filter(|value| !value.is_empty())
    else {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "benchmark registry publication worker requires registry_ref_prefix",
        ));
    };
    if value.len() > 400 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "benchmark registry_ref_prefix is limited to 400 characters",
        ));
    }
    Ok(value)
}

fn normalize_benchmark_registry_publication_worker_reason(
    value: Option<String>,
) -> ApiResult<String> {
    let Some(value) = value
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
    else {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "benchmark registry publication worker requires reason",
        ));
    };
    Ok(value)
}

fn benchmark_registry_publication_ref(
    registry_ref_prefix: &str,
    conversion_id: Uuid,
) -> ApiResult<String> {
    normalize_benchmark_lifecycle_ref(format!("{registry_ref_prefix}:{conversion_id}"))?.ok_or_else(
        || {
            api_error(
                StatusCode::BAD_REQUEST,
                "benchmark registry publication worker requires registry_ref_prefix",
            )
        },
    )
}

fn increment_count(counts: &mut BTreeMap<String, usize>, label: &str) {
    *counts.entry(label.to_string()).or_insert(0) += 1;
}

async fn run_benchmark_conversion(
    state: &AppState,
    tenant: &TenantAuth,
    body: BenchmarkConversionRequest,
) -> ApiResult<Json<TraceBenchmarkConversionArtifact>> {
    require_positive_credit_issuance_principal_if_configured(state, tenant, 1.0)?;
    let now = Utc::now();
    let purpose = normalized_export_purpose(
        body.purpose.as_deref(),
        "trace_commons_benchmark_candidate_conversion",
    );
    let grant = create_one_shot_export_grant(
        state,
        tenant,
        TraceExportDatasetKind::BenchmarkConversion,
        purpose,
        body.limit,
        now,
    );
    run_benchmark_conversion_with_grant(state, tenant, body, grant, now).await
}

async fn run_benchmark_conversion_with_grant(
    state: &AppState,
    tenant: &TenantAuth,
    body: BenchmarkConversionRequest,
    grant: TraceExportAccessGrant,
    now: DateTime<Utc>,
) -> ApiResult<Json<TraceBenchmarkConversionArtifact>> {
    require_positive_credit_issuance_principal_if_configured(state, tenant, 1.0)?;
    let (consent_scope, tenant_policy, purpose) =
        prepare_benchmark_conversion_execution(state, tenant, &body).await?;
    let job = create_validated_export_job_slice(
        state,
        tenant,
        TraceExportJobRequest {
            requested_dataset_kind: TraceExportDatasetKind::BenchmarkConversion,
            purpose: purpose.clone(),
            requested_limit: body.limit,
            grant: grant.clone(),
            metadata: export_job_request_metadata(
                body.limit,
                body.status,
                body.privacy_risk,
                consent_scope,
                body.external_ref.as_deref(),
            ),
        },
        now,
    )?;
    enforce_export_job_mirror_result(
        state,
        "benchmark export job start",
        mirror_export_job_started_to_db(state, tenant, &grant, &job).await,
    )
    .await
    .map_err(internal_error)?;
    run_benchmark_conversion_job(
        state,
        tenant,
        body,
        job,
        consent_scope,
        tenant_policy,
        purpose,
    )
    .await
}

async fn prepare_benchmark_conversion_execution(
    state: &AppState,
    tenant: &TenantAuth,
    body: &BenchmarkConversionRequest,
) -> ApiResult<(Option<ConsentScope>, Option<TenantSubmissionPolicy>, String)> {
    let consent_scope = parse_consent_scope_filter(body.consent_scope.as_deref())?;
    enforce_dataset_export_guardrails(
        state,
        "benchmark conversion",
        body.purpose.as_deref(),
        body.status,
        body.privacy_risk,
        consent_scope,
    )?;
    let tenant_policy = tenant_export_policy_for_request(
        state,
        tenant,
        "benchmark conversion",
        consent_scope,
        TraceAllowedUse::BenchmarkGeneration,
    )
    .await?;
    let purpose = normalized_export_purpose(
        body.purpose.as_deref(),
        "trace_commons_benchmark_candidate_conversion",
    );
    Ok((consent_scope, tenant_policy, purpose))
}

async fn run_benchmark_conversion_job(
    state: &AppState,
    tenant: &TenantAuth,
    body: BenchmarkConversionRequest,
    job: TraceExportJobSlice,
    consent_scope: Option<ConsentScope>,
    tenant_policy: Option<TenantSubmissionPolicy>,
    purpose: String,
) -> ApiResult<Json<TraceBenchmarkConversionArtifact>> {
    let TraceCommonsMetadataView { records, derived } = fail_export_job_on_error(
        state,
        &job,
        "benchmark export job failure",
        read_reviewer_metadata_view(state, tenant).await,
    )
    .await?;
    let mut accepted_by_submission = BTreeMap::new();
    for record in records
        .into_iter()
        .filter(|record| body.status.is_none_or(|status| record.status == status))
        .filter(|record| {
            body.privacy_risk
                .is_none_or(|risk| record.privacy_risk == risk)
        })
        .filter(|record| consent_scope.is_none_or(|scope| record.consent_scopes.contains(&scope)))
        .filter(|record| {
            record_matches_export_policy_abac(
                record,
                tenant,
                tenant_policy.as_ref(),
                TraceAllowedUse::BenchmarkGeneration,
            )
        })
    {
        if let Err(error) = ensure_retention_metadata_within_server_policy(&record) {
            return fail_export_job_with_internal_error(
                state,
                &job,
                "benchmark export job failure",
                error,
            )
            .await;
        }
        if record.is_benchmark_eligible() {
            accepted_by_submission.insert(record.submission_id, record);
        }
    }
    let limit = job.max_item_cap;

    let mut candidates = Vec::new();
    for derived in derived
        .into_iter()
        .filter(|record| record.status == TraceCorpusStatus::Accepted)
    {
        let Some(submission) = accepted_by_submission.get(&derived.submission_id) else {
            continue;
        };
        candidates.push(TraceBenchmarkCandidate::from_records(submission, &derived));
    }
    let mut candidates = dedupe_benchmark_candidates_by_summary_hash(candidates);
    candidates.truncate(limit);
    let conversion_id = Uuid::new_v4();
    let source_submission_ids = candidates
        .iter()
        .map(|candidate| candidate.submission_id)
        .collect::<Vec<_>>();
    let source_object_refs = fail_export_job_on_error(
        state,
        &job,
        "benchmark export job failure",
        revalidate_db_export_sources(
            state,
            tenant,
            &source_submission_ids,
            state.require_derived_export_object_refs_for_tenant(&tenant.tenant_id),
        )
        .await,
    )
    .await?;
    fail_export_job_on_error(
        state,
        &job,
        "benchmark export job failure",
        append_derived_source_read_audits(
            state,
            tenant,
            &source_submission_ids,
            &source_object_refs,
            "benchmark_conversion",
            Some(&purpose),
        )
        .await,
    )
    .await?;
    let source_submission_ids_hash =
        source_submission_ids_hash("benchmark_conversion", &source_submission_ids);
    let audit_event = TraceCommonsAuditEvent::benchmark_conversion(
        tenant,
        conversion_id,
        candidates.len(),
        source_submission_ids_hash.clone(),
    );
    let audit_event_id = audit_event.event_id;
    let artifact = TraceBenchmarkConversionArtifact {
        artifact_schema_version: TRACE_BENCHMARK_CONVERSION_SCHEMA_VERSION.to_string(),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        conversion_id,
        audit_event_id,
        purpose,
        registry: TraceBenchmarkRegistryMetadata::default(),
        evaluation: TraceBenchmarkEvaluationMetadata::default(),
        filters: TraceBenchmarkConversionFilters {
            limit,
            consent_scope,
            status: body.status,
            privacy_risk: body.privacy_risk,
            external_ref: body.external_ref,
        },
        source_submission_ids,
        source_submission_ids_hash,
        generated_at: db_mirrored_now(),
        item_count: candidates.len(),
        candidates,
    };
    let provenance = TraceExportProvenanceManifest::new(
        &tenant.tenant_id,
        conversion_id,
        audit_event_id,
        TraceExportProvenanceKind::BenchmarkConversion,
        artifact.purpose.clone(),
        artifact.source_submission_ids.clone(),
        artifact.source_submission_ids_hash.clone(),
    );
    let artifact_path = benchmark_artifact_path(&state.root, &tenant.tenant_id, conversion_id);
    let provenance_path = benchmark_provenance_path(&state.root, &tenant.tenant_id, conversion_id);
    let mut required_artifact_object_ref_material = None;
    let object_primary_derived_exports =
        state.object_primary_derived_exports_for_tenant(&tenant.tenant_id);
    if state.require_db_mirror_writes {
        let artifact_object_ref_material = if state.db_mirror.is_some() {
            Some(
                trace_export_artifact_object_ref_material(
                    state,
                    &tenant.tenant_id,
                    TraceArtifactKind::BenchmarkConversion,
                    conversion_id,
                    &artifact_path,
                    &artifact,
                )
                .map_err(internal_error)?,
            )
        } else {
            None
        };
        let mirror_result = mirror_benchmark_export_provenance_to_db(
            state,
            &artifact,
            artifact_object_ref_material.as_ref(),
        )
        .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_display_error_hash(error),
                export_id = %conversion_id,
                "Trace Commons DB dual-write benchmark provenance mirror failed"
            );
            cleanup_export_artifact_publication(
                state,
                &tenant.tenant_id,
                TraceArtifactKind::BenchmarkConversion,
                artifact_object_ref_material.as_ref(),
                &[artifact_path.clone(), provenance_path.clone()],
            )
            .map_err(internal_error)?;
        }
        enforce_db_mirror_write_result(state, "benchmark provenance", mirror_result)
            .map_err(internal_error)?;
        required_artifact_object_ref_material = artifact_object_ref_material;
        if !object_primary_derived_exports {
            write_benchmark_artifact(&state.root, &tenant.tenant_id, &artifact)
                .map_err(internal_error)?;
            write_export_provenance(&provenance_path, &tenant.tenant_id, &provenance)
                .map_err(internal_error)?;
        }
    } else {
        if !object_primary_derived_exports {
            write_benchmark_artifact(&state.root, &tenant.tenant_id, &artifact)
                .map_err(internal_error)?;
            write_export_provenance(&provenance_path, &tenant.tenant_id, &provenance)
                .map_err(internal_error)?;
        }
        let artifact_object_ref_material = if state.db_mirror.is_some() {
            Some(
                trace_export_artifact_object_ref_material(
                    state,
                    &tenant.tenant_id,
                    TraceArtifactKind::BenchmarkConversion,
                    conversion_id,
                    &artifact_path,
                    &artifact,
                )
                .map_err(internal_error)?,
            )
        } else {
            None
        };
        let mirror_result = mirror_benchmark_export_provenance_to_db(
            state,
            &artifact,
            artifact_object_ref_material.as_ref(),
        )
        .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_display_error_hash(error),
                export_id = %conversion_id,
                "Trace Commons DB dual-write benchmark provenance mirror failed"
            );
        }
        enforce_db_mirror_write_result(state, "benchmark provenance", mirror_result)
            .map_err(internal_error)?;
    }
    let audit_result = append_audit_event_with_db_mirror(
        state,
        tenant,
        audit_event.clone(),
        StorageTraceAuditAction::BenchmarkConvert,
        StorageTraceAuditSafeMetadata::Export {
            artifact_kind: StorageTraceObjectArtifactKind::BenchmarkArtifact,
            purpose_code: Some(artifact.purpose.clone()),
            item_count: artifact.item_count.min(u32::MAX as usize) as u32,
        },
    )
    .await;
    if let Err(error) = audit_result {
        if state.require_db_mirror_writes {
            cleanup_export_artifact_publication(
                state,
                &tenant.tenant_id,
                TraceArtifactKind::BenchmarkConversion,
                required_artifact_object_ref_material.as_ref(),
                &[artifact_path.clone(), provenance_path.clone()],
            )
            .map_err(internal_error)?;
            rollback_db_export_manifest_publication(state, &tenant.tenant_id, conversion_id)
                .await
                .map_err(internal_error)?;
            remove_audit_event_by_id(&state.root, &tenant.tenant_id, audit_event.event_id)
                .map_err(internal_error)?;
        }
        return Err(internal_error(error));
    }
    append_automatic_utility_credit_events_once(
        state,
        tenant,
        AutomaticUtilityCreditConfig {
            idempotency_label: "benchmark-conversion-credit",
            idempotency_ref: None,
            event_type: TraceCreditLedgerEventType::BenchmarkConversion,
            credit_points_delta: BENCHMARK_CONVERSION_CREDIT_POINTS_DELTA,
            reason: format!(
                "Converted into benchmark artifact {}.",
                artifact.conversion_id
            ),
            external_ref: artifact
                .filters
                .external_ref
                .clone()
                .unwrap_or_else(|| format!("benchmark_conversion:{}", artifact.conversion_id)),
        },
        artifact
            .candidates
            .iter()
            .map(AutomaticUtilityCreditSource::from_benchmark_candidate),
    )
    .await?;
    enforce_export_job_mirror_result(
        state,
        "benchmark export job completion",
        mirror_export_job_finished_to_db(state, &job, artifact.conversion_id, artifact.item_count)
            .await,
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(artifact))
}

async fn update_benchmark_lifecycle(
    state: &AppState,
    tenant: &TenantAuth,
    conversion_id: Uuid,
    body: BenchmarkLifecycleUpdateRequest,
) -> ApiResult<Json<TraceBenchmarkConversionArtifact>> {
    if body.registry.is_none() && body.evaluation.is_none() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "benchmark lifecycle update requires registry or evaluation metadata",
        ));
    }

    let mut artifact = read_benchmark_conversion_artifact(state, tenant, conversion_id)
        .await
        .map_err(internal_error)?
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "benchmark artifact not found"))?;
    let previous_registry_status = artifact.registry.status;
    apply_benchmark_lifecycle_update(&mut artifact, body)?;

    persist_benchmark_lifecycle_artifact(state, tenant, &artifact, "benchmark lifecycle")
        .await
        .map_err(internal_error)?;
    if artifact.registry.status == TraceBenchmarkRegistryStatus::Published {
        ensure_benchmark_registry_publish_outbox_item_with_db_mirror(state, tenant, &artifact)
            .await
            .map_err(internal_error)?;
    } else if previous_registry_status == TraceBenchmarkRegistryStatus::Published
        && artifact.registry.status == TraceBenchmarkRegistryStatus::Revoked
    {
        ensure_benchmark_registry_revoke_outbox_item_with_db_mirror(state, tenant, &artifact)
            .await
            .map_err(internal_error)?;
    }

    Ok(Json(artifact))
}

async fn persist_benchmark_lifecycle_artifact(
    state: &AppState,
    tenant: &TenantAuth,
    artifact: &TraceBenchmarkConversionArtifact,
    operation: &str,
) -> anyhow::Result<()> {
    let artifact_path =
        benchmark_artifact_path(&state.root, &tenant.tenant_id, artifact.conversion_id);
    if state.require_db_mirror_writes {
        let staged_artifact_object_id = Uuid::new_v4();
        let artifact_object_ref_material = if state.db_mirror.is_some() {
            Some(trace_export_artifact_object_ref_material(
                state,
                &tenant.tenant_id,
                TraceArtifactKind::BenchmarkConversion,
                staged_artifact_object_id,
                &artifact_path,
                artifact,
            )?)
        } else {
            None
        };
        let mirror_result = mirror_benchmark_export_provenance_to_db(
            state,
            artifact,
            artifact_object_ref_material.as_ref(),
        )
        .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_display_error_hash(error),
                export_id = %artifact.conversion_id,
                "Trace Commons DB dual-write benchmark lifecycle mirror failed"
            );
            cleanup_export_artifact_publication(
                state,
                &tenant.tenant_id,
                TraceArtifactKind::BenchmarkConversion,
                artifact_object_ref_material.as_ref(),
                &[],
            )?;
        }
        enforce_db_mirror_write_result(state, operation, mirror_result)?;
        let object_primary_derived_exports =
            state.object_primary_derived_exports_for_tenant(&tenant.tenant_id);
        if !object_primary_derived_exports {
            write_benchmark_artifact(&state.root, &tenant.tenant_id, artifact)?;
        }
    } else {
        let object_primary_derived_exports =
            state.object_primary_derived_exports_for_tenant(&tenant.tenant_id);
        if !object_primary_derived_exports {
            write_benchmark_artifact(&state.root, &tenant.tenant_id, artifact)?;
        }
        let artifact_object_ref_material = if state.db_mirror.is_some() {
            Some(trace_export_artifact_object_ref_material(
                state,
                &tenant.tenant_id,
                TraceArtifactKind::BenchmarkConversion,
                artifact.conversion_id,
                &artifact_path,
                artifact,
            )?)
        } else {
            None
        };
        let mirror_result = mirror_benchmark_export_provenance_to_db(
            state,
            artifact,
            artifact_object_ref_material.as_ref(),
        )
        .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_display_error_hash(error),
                export_id = %artifact.conversion_id,
                "Trace Commons DB dual-write benchmark lifecycle mirror failed"
            );
        }
        enforce_db_mirror_write_result(state, operation, mirror_result)?;
    }

    append_audit_event_with_db_mirror(
        state,
        tenant,
        TraceCommonsAuditEvent::benchmark_lifecycle_update(tenant, artifact),
        StorageTraceAuditAction::BenchmarkConvert,
        StorageTraceAuditSafeMetadata::Export {
            artifact_kind: StorageTraceObjectArtifactKind::BenchmarkArtifact,
            purpose_code: Some("benchmark_lifecycle_update".to_string()),
            item_count: artifact.item_count.min(u32::MAX as usize) as u32,
        },
    )
    .await?;
    Ok(())
}

