/// Query params for the dedup recluster batch admin route. `limit` bounds a
/// run (useful for a `?limit=5` pilot smoke before a full pass); absent means
/// the whole decision backlog.
#[derive(Debug, Deserialize)]
struct ReclusterDedupQuery {
    #[serde(default)]
    limit: Option<i64>,
}

/// Hash-only acknowledgement for the dedup recluster batch admin route. The
/// work runs in a spawned background task; the route returns immediately.
#[derive(Debug, Serialize)]
struct ReclusterDedupAck {
    accepted: bool,
    limit: Option<i64>,
}

/// Running tally for one dedup recluster batch pass.
#[derive(Debug, Default)]
struct ReclusterDedupSummary {
    /// Decision rows whose dedup columns were recomputed and updated.
    reclustered: u64,
    /// Decision rows skipped because the write failed (left as-is).
    failed: u64,
}

/// One full dedup recluster batch pass. SIMHASH-ONLY in v1 (embedding-side
/// recluster is a follow-up, consistent with the inline gate path in
/// `evaluate_and_record_gate`).
///
/// Enumerates dedup signal rows cross-tenant (`decided_at ASC`, per
/// `list_dedup_signals`), then recomputes cluster assignments over that whole
/// snapshot in a SINGLE deterministic sweep: walking rows in order, each row
/// with a recorded simhash is assigned against the clusters formed so far
/// (via `assign_cluster`, simhash-only candidates — `embed_cosine_micros:
/// None`), joining an existing cluster or minting a new one. Rows without a
/// recorded simhash cannot be clustered and are left untouched (not counted,
/// not written).
///
/// Candidates are scoped to the row's own `dedup_signal_version` (V57) by
/// `assign_cluster` itself: the pass reads stored simhashes and never
/// re-renders, so two values derived by different renderers or different
/// simhash algorithms are not comparable and must never fuse. `NULL` is read
/// as the legacy v1 stamp, so a corpus that has not yet been re-derived
/// clusters exactly as it did before V57 -- and is left NULL, because reading
/// a row as v1 is not the same as recording that it is v1. The pass writes
/// the two cluster columns and nothing else.
///
/// Final cluster sizes are computed AFTER the full sweep completes, so every
/// member of a cluster is written with the same total membership count — not
/// its position-in-sweep size. A write failure on one decision is logged
/// hash-only and skipped; the pass never aborts on one failure.
async fn run_recluster_dedup_pass(
    state: Arc<AppState>,
    limit: Option<i64>,
) -> anyhow::Result<ReclusterDedupSummary> {
    let db = state
        .db_mirror
        .as_ref()
        .ok_or_else(|| anyhow::anyhow!("dedup recluster requires a configured DB mirror"))?;
    let effective_limit = limit.unwrap_or(i64::MAX).max(0);
    let rows = db.list_dedup_signals(effective_limit).await?;

    // Pass 1: single deterministic sweep building cluster assignments over
    // the snapshot. `reps` holds each cluster's representative simhash AND
    // the signal version it was derived under (both taken from the row that
    // created the cluster); `counts` holds each cluster's running (and, after
    // the loop, final) membership.
    let mut reps: std::collections::HashMap<uuid::Uuid, (u64, &str)> =
        std::collections::HashMap::new();
    let mut counts: std::collections::HashMap<uuid::Uuid, i64> = std::collections::HashMap::new();
    /// One row the sweep placed, carrying what pass 2 needs to write it --
    /// which is the cluster and nothing else. The simhash and the stamp are
    /// deliberately absent: the pass read them, it did not derive them, so it
    /// has nothing to say about them.
    struct AssignedRow<'a> {
        row: &'a trace_commons_server::trace_corpus_storage::DedupSignalRow,
        cluster_id: uuid::Uuid,
    }
    let mut assigned: Vec<AssignedRow<'_>> = Vec::new();

    for row in &rows {
        let Some(simhash_i64) = row.dedup_simhash else {
            // No simhash recorded yet: cannot cluster this row. Skip it —
            // leave it as-is, do not write it.
            continue;
        };
        let simhash_u64 = simhash_i64 as u64;
        // NULL reads as the legacy v1 stamp, never as unknown (V57, D2), so a
        // pre-V57 row and a freshly stamped v1 row still cluster together.
        // Borrowed from `rows`, which outlives every map built from it.
        let row_version = row.effective_signal_version();
        // No version filter here: `assign_cluster` refuses a differently
        // stamped candidate itself. That gate is what keeps the transition
        // window honest — the pass reads stored simhashes and never
        // re-renders, so without it a corpus holding both versions would fuse
        // them silently.
        let candidates: Vec<trace_commons_server::dedup_assign::ClusterCandidate<'_>> = reps
            .iter()
            .map(|(cluster_id, (simhash, version))| {
                trace_commons_server::dedup_assign::ClusterCandidate {
                    cluster_id: *cluster_id,
                    size: *counts.get(cluster_id).unwrap_or(&0),
                    simhash: *simhash,
                    embed_cosine_micros: None,
                    signal_version: version,
                }
            })
            .collect();
        let cluster_id = match trace_commons_server::dedup_assign::assign_cluster(
            simhash_u64,
            row_version,
            &candidates,
            &trace_commons_server::dedup_assign::DEDUP_CONSTANTS_V1,
        ) {
            trace_commons_server::dedup_assign::ClusterAssignment::Existing(id) => id,
            trace_commons_server::dedup_assign::ClusterAssignment::New => {
                let id = uuid::Uuid::new_v4();
                reps.insert(id, (simhash_u64, row_version));
                id
            }
        };
        *counts.entry(cluster_id).or_insert(0) += 1;
        assigned.push(AssignedRow { row, cluster_id });
    }

    // Pass 2: write every assigned row with its cluster's FINAL total
    // membership count (computed after the whole sweep above).
    let mut summary = ReclusterDedupSummary::default();
    for assignment in assigned {
        let row = assignment.row;
        let cluster_id = assignment.cluster_id;
        let final_size =
            i32::try_from(counts.get(&cluster_id).copied().unwrap_or(1)).unwrap_or(i32::MAX);
        // Cluster columns only. The pass derives neither the simhash nor the
        // stamp, so it writes neither -- and in particular it does not
        // materialise the legacy literal into a row whose stamp is NULL.
        // That row is READ as the legacy version; writing the reading back
        // would make it indistinguishable from a row the re-derivation pass
        // has actually re-stamped, which is the precise reason V57 refuses a
        // column DEFAULT.
        match db
            .update_trace_gate_decision_dedup_cluster(
                &row.tenant_id,
                row.decision_id,
                cluster_id,
                final_size,
            )
            .await
        {
            Ok(()) => summary.reclustered += 1,
            Err(error) => {
                summary.failed += 1;
                tracing::warn!(
                    tenant_hash = %sha256_prefixed(&row.tenant_id),
                    decision_hash = %sha256_prefixed(&row.decision_id.to_string()),
                    error_hash = %safe_display_error_hash(&error),
                    "shadow dedup recluster skipped one decision"
                );
            }
        }
    }

    Ok(summary)
}

/// Admin route: trigger a batch backfill/recompute of cross-trace dedup
/// cluster assignments and size snapshots over the whole corpus.
/// SIMHASH-ONLY in v1 (embedding-side recluster is a follow-up).
///
/// Auth: reuses the admin bearer credential (`require_admin`), matching the
/// other `/v1/admin/*` maintenance routes; no new gate is introduced. Spawns
/// a background task and returns a hash-only ack immediately. An optional
/// `?limit=N` bounds the run.
#[derive(Debug, Deserialize)]
struct ClearStalePriorRiskQuery {
    /// Bounded on purpose; an omitted limit is a sample, never everything.
    #[serde(default)]
    limit: Option<i64>,
}

/// Counts only. No submission ids, no tenant content, no risk values.
#[derive(Debug, Serialize)]
struct ClearStalePriorRiskAck {
    cleared: u64,
    failed: u64,
}

/// Clear a stale prior risk so the backstop can re-decide from scratch.
///
/// Residual risk is a ratchet: `max(prior, derived)` unless `can_downgrade`,
/// which requires the classifier to have FOUND something. A trace whose
/// credential PR #506 already removed therefore cannot clear itself -- the
/// re-run finds nothing, so the stale High survives every pass.
///
/// Relaxing the ratchet was attempted and rejected. Redefining
/// `useful_classifier_result` as "a classifier examined this" reinstates a
/// bypass this repository already removed: a classifier can pass the canary and
/// still silently fail on real content, which is what the
/// `CanaryHealthyButFindsNoRealPii` fixture exists to demonstrate. So the
/// ratchet is untouched here, and the escape hatch is this: an operator
/// asserting that the cause was fixed, which is a claim a person is accountable
/// for rather than an inference from silence.
///
/// Prior risk lives in the envelope artifact, not a column, so clearing it
/// rewrites the envelope and re-holds the submission on `AwaitingPiiBackstop`.
/// The trace is HELD throughout, never released: this buys it a fair
/// re-assessment, not a pass. A cause that is still present re-derives and
/// re-quarantines.
async fn pii_backstop_clear_stale_prior_risk_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<ClearStalePriorRiskQuery>,
) -> ApiResult<Json<ClearStalePriorRiskAck>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;

    let db = state.db_mirror.as_ref().ok_or_else(|| {
        api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "clearing stale prior risk requires a configured DB mirror",
        )
    })?;

    let limit = query.limit.unwrap_or(10).clamp(1, 1_000);
    let targets = db
        .list_quarantined_with_only_residual_survivor(&tenant.tenant_id, limit)
        .await
        .map_err(|error| {
            tracing::warn!(
                error_hash = %safe_display_error_hash(&anyhow::Error::new(error)),
                "Trace Commons stale-prior-risk enumeration failed"
            );
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "stale prior risk enumeration failed",
            )
        })?;

    let mut cleared = 0u64;
    let mut failed = 0u64;
    for (target_tenant, submission_id) in targets {
        match clear_one_stale_prior_risk(state.as_ref(), db, &target_tenant, submission_id).await {
            Ok(()) => cleared += 1,
            Err(error) => {
                failed += 1;
                // Hash-only: one submission failing must not abort the batch,
                // and must not put anything identifying in the log.
                tracing::warn!(
                    error_hash = %safe_display_error_hash(&error),
                    "Trace Commons stale prior risk clear failed for one submission"
                );
            }
        }
    }

    tracing::info!(
        cleared,
        failed,
        limit,
        "Trace Commons stale prior risk cleared"
    );
    Ok(Json(ClearStalePriorRiskAck { cleared, failed }))
}

/// Rewrite one envelope's prior risk to `Low` and re-hold the submission.
///
/// Mirrors the ordering `process_one_pii_backstop` uses when it stores a
/// rescrubbed artifact, with one simplification: the target status here is
/// `AwaitingPiiBackstop`, which is MORE restrictive than the current
/// `Quarantined`. The concurrent-read hazard that ordering guards against is a
/// status becoming consumer-visible as released before the new artifact is
/// active; moving to a held status cannot do that.
async fn clear_one_stale_prior_risk(
    state: &AppState,
    db: &Arc<dyn Database>,
    tenant_id: &str,
    submission_id: uuid::Uuid,
) -> anyhow::Result<()> {
    let mut record = read_submission_record(&state.root, tenant_id, submission_id)?
        .ok_or_else(|| anyhow::anyhow!("submission record not found"))?;
    let mut envelope = read_envelope_by_record(state, &record)?;

    // The ONLY mutation. Redaction state, findings, and the recorded
    // `residual_risk_basis` are all left exactly as they are: the basis is the
    // evidence for whether this action was justified, and blanking it would
    // destroy the ability to tell later.
    envelope.privacy.residual_pii_risk = ResidualPiiRisk::Low;

    let stored = store_envelope(
        state,
        tenant_id,
        TraceCorpusStatus::AwaitingPiiBackstop,
        PII_BACKSTOP_REDACTION_LABEL,
        &envelope,
    )?;
    record.object_key = stored.object_key;
    record.artifact_receipt = stored.artifact_receipt;
    record.artifact_object_store = stored.artifact_object_store;
    record.status = TraceCorpusStatus::AwaitingPiiBackstop;
    write_submission_record(&state.root, &record)?;

    db.upsert_trace_submission(storage_submission_write_from_record(
        &record, &envelope, None,
    )?)
    .await?;
    db.update_trace_submission_status(
        tenant_id,
        submission_id,
        storage_corpus_status(TraceCorpusStatus::AwaitingPiiBackstop),
        PII_BACKSTOP_DRIVER_ACTOR_REF,
        Some(PII_BACKSTOP_REDACTION_LABEL),
    )
    .await?;
    Ok(())
}

#[derive(Debug, Deserialize)]
struct RequeueQuarantinedQuery {
    /// Bounded on purpose. The first use of this route is a SAMPLE: re-run a
    /// handful of quarantined submissions and compare the new verdict against
    /// the recorded one before requeueing the rest.
    #[serde(default)]
    limit: Option<i64>,
}

/// Count-only acknowledgement. No submission ids, no tenant, no reasons.
#[derive(Debug, Serialize)]
struct RequeueQuarantinedAck {
    requeued: u64,
}

/// Move quarantined submissions back to `AwaitingPiiBackstop` for re-assessment.
///
/// Quarantine is not always a verdict about the trace. A submission is
/// quarantined when its POST-backstop residual risk is Medium or High, and that
/// assessment is only as good as the classifier that produced it -- the pilot's
/// 114 quarantined submissions were all assessed between 2026-08-25 and 08-27,
/// inside the window when the hosted classifier's token ceiling was collapsing.
/// A window that failed leaves its PII unredacted, which then presents as a
/// `residual_survivor` and reads exactly like a genuine finding.
///
/// So this exists to let a better classifier re-decide. It does not clear
/// quarantine and it does not change any risk verdict: it puts submissions back
/// in the queue and lets the backstop reach its own conclusion, which may well
/// be quarantine again.
///
/// Bounded by `limit` so the first run can be a sample rather than all of them.
async fn pii_backstop_requeue_quarantined_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<RequeueQuarantinedQuery>,
) -> ApiResult<Json<RequeueQuarantinedAck>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;

    // Bounded, and never unbounded by omission: a missing limit is a small
    // sample, not "every quarantined submission".
    let limit = query.limit.unwrap_or(10).clamp(1, 1_000);

    let db = state.db_mirror.as_ref().ok_or_else(|| {
        api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "quarantined requeue requires a configured DB mirror",
        )
    })?;

    let requeued = db
        .requeue_quarantined_for_pii_backstop(&tenant.tenant_id, limit)
        .await
        .map_err(|error| {
            tracing::warn!(
                error_hash = %safe_display_error_hash(&anyhow::Error::new(error)),
                "Trace Commons quarantined requeue failed"
            );
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "quarantined requeue failed",
            )
        })?;

    // Hash-only: a count and nothing identifying.
    tracing::info!(
        requeued,
        limit,
        "Trace Commons quarantined submissions requeued for PII backstop"
    );
    Ok(Json(RequeueQuarantinedAck { requeued }))
}

async fn recluster_dedup_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<ReclusterDedupQuery>,
) -> ApiResult<Json<ReclusterDedupAck>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    if state.db_mirror.is_none() {
        return Err(api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "dedup recluster requires a configured DB mirror",
        ));
    }
    let limit = query.limit;
    let task_state = state.clone();
    tokio::spawn(async move {
        match run_recluster_dedup_pass(task_state, limit).await {
            Ok(summary) => {
                tracing::info!(
                    reclustered = summary.reclustered,
                    failed = summary.failed,
                    "Trace Commons dedup recluster pass completed"
                );
            }
            Err(error) => {
                tracing::warn!(
                    error_hash = %safe_display_error_hash(&error),
                    "Trace Commons dedup recluster pass failed"
                );
            }
        }
    });
    Ok(Json(ReclusterDedupAck {
        accepted: true,
        limit,
    }))
}

/// Query params for the per-contributor cap recompute batch admin route.
/// `limit` bounds a run (useful for a `?limit=5` pilot smoke before a full
/// pass); absent means the whole decision backlog.
#[derive(Debug, Deserialize)]
struct RecomputeContributorCapsQuery {
    #[serde(default)]
    limit: Option<i64>,
}

/// Hash-only acknowledgement for the contributor-cap recompute batch admin
/// route. The work runs in a spawned background task; the route returns
/// immediately.
#[derive(Debug, Serialize)]
struct RecomputeContributorCapsAck {
    accepted: bool,
    limit: Option<i64>,
}

/// Running tally for one contributor-cap recompute batch pass.
#[derive(Debug, Default)]
struct RecomputeContributorCapsSummary {
    updated: u64,
    failed: u64,
}

/// One full per-contributor cap recompute pass. A single forward sweep over the
/// gate-driver enumeration (already ordered by `auth_principal_ref, decided_at`)
/// accumulates in-epoch `R` per `(auth_principal_ref, epoch_index)`, resetting at
/// each contributor or epoch boundary, and writes each decision's marginal
/// factor + cumulative snapshot. Each factor depends only on prior in-epoch
/// decisions, so one pass is correct (no dedup-style second pass).
async fn run_recompute_contributor_caps_pass(
    state: Arc<AppState>,
    limit: Option<i64>,
) -> anyhow::Result<RecomputeContributorCapsSummary> {
    use trace_commons_server::contributor_cap as cap;
    let db = state.db_mirror.as_ref().ok_or_else(|| {
        anyhow::anyhow!("contributor-cap recompute requires a configured DB mirror")
    })?;
    let effective_limit = limit.unwrap_or(i64::MAX).max(0);
    let rows = db.list_contributor_cap_signals(effective_limit).await?;
    let k = &cap::CONTRIBUTOR_CAP_CONSTANTS_V1;

    let mut summary = RecomputeContributorCapsSummary::default();
    // Group key = (auth_principal_ref, epoch_index); reset R when it changes.
    let mut cur_key: Option<(String, i64)> = None;
    let mut r_before: i64 = 0;
    for row in &rows {
        let epoch = cap::epoch_index(row.decided_at.timestamp(), k.epoch_days);
        let key = (row.auth_principal_ref.clone(), epoch);
        if cur_key.as_ref() != Some(&key) {
            cur_key = Some(key);
            r_before = 0;
        }
        let r = cap::increment_micros(row.credit_quality_micros, row.dedup_cluster_size);
        let factor = cap::contributor_factor_micros(r_before, r, k);
        let cumulative = r_before.saturating_add(r);
        let factor_i32 = i32::try_from(factor).unwrap_or(i32::MAX);
        match db
            .update_trace_gate_decision_contributor_cap(
                &row.tenant_id,
                row.decision_id,
                factor_i32,
                cumulative,
                epoch,
                k.version,
            )
            .await
        {
            Ok(()) => {
                summary.updated += 1;
                r_before = cumulative;
            }
            Err(error) => {
                summary.failed += 1;
                // Do NOT advance r_before on a failed write: the snapshot for
                // this decision was not persisted, so later decisions in the
                // group must accumulate as if this one is retried next pass.
                tracing::warn!(
                    tenant_hash = %sha256_prefixed(&row.tenant_id),
                    decision_hash = %sha256_prefixed(&row.decision_id.to_string()),
                    error_hash = %safe_display_error_hash(&error),
                    "shadow contributor-cap recompute skipped one decision"
                );
            }
        }
    }
    Ok(summary)
}

/// Admin route: trigger a batch backfill/recompute of per-contributor cap
/// factors and cumulative-total snapshots over the whole corpus.
///
/// Auth: reuses the admin bearer credential (`require_admin`), matching the
/// other `/v1/admin/*` maintenance routes; no new gate is introduced. Spawns
/// a background task and returns a hash-only ack immediately. An optional
/// `?limit=N` bounds the run.
async fn recompute_contributor_caps_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<RecomputeContributorCapsQuery>,
) -> ApiResult<Json<RecomputeContributorCapsAck>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    if state.db_mirror.is_none() {
        return Err(api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "contributor-cap recompute requires a configured DB mirror",
        ));
    }
    let limit = query.limit;
    let task_state = state.clone();
    tokio::spawn(async move {
        match run_recompute_contributor_caps_pass(task_state, limit).await {
            Ok(summary) => {
                tracing::info!(
                    updated = summary.updated,
                    failed = summary.failed,
                    "Trace Commons contributor-cap recompute pass completed"
                );
            }
            Err(error) => {
                tracing::warn!(
                    error_hash = %safe_display_error_hash(&error),
                    "Trace Commons contributor-cap recompute pass failed"
                );
            }
        }
    });
    Ok(Json(RecomputeContributorCapsAck {
        accepted: true,
        limit,
    }))
}

/// Devfolio score read-back request: the envelope ids a competition operator
/// collected from participants' upload manifests.
#[derive(Debug, Clone, Serialize, Deserialize)]
struct ScoresBySubmissionRequest {
    submission_ids: Vec<Uuid>,
}

/// Score bundle reported per envelope id. `credit_quality_micros` is the
/// headline graded credit quality `q`; it is `None` when the submission has a
/// gate decision but the shadow-mode credit-quality pass has not scored it
/// yet. Ids with no gate decision at all are omitted from the response.
#[derive(Debug, Clone, Serialize, Deserialize)]
struct SubmissionScoreBundle {
    submission_id: Uuid,
    credit_quality_micros: Option<i64>,
    perplexity_micros: i64,
    novelty_score_micros: i64,
    gate_passed: bool,
}

/// Maximum envelope ids per score read-back request, mirroring the
/// submission-status batch cap.
const SCORES_BY_SUBMISSION_MAX_IDS: usize = 500;

async fn scores_by_submission_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<ScoresBySubmissionRequest>,
) -> ApiResult<Json<Vec<SubmissionScoreBundle>>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_competition_operator(&tenant)?;
    if body.submission_ids.len() > SCORES_BY_SUBMISSION_MAX_IDS {
        return Err(api_error(
            StatusCode::PAYLOAD_TOO_LARGE,
            "score read-back requests are limited to 500 ids",
        ));
    }
    let Some(db) = state.db_mirror.as_ref() else {
        return Err(api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "score read-back requires a configured DB mirror",
        ));
    };
    let rows = db
        .list_scores_by_submission_ids(&body.submission_ids)
        .await
        .map_err(|error| match error {
            // The cross-tenant read runs only through the narrow gate-driver
            // pool; an unconfigured pool is a missing control, not an
            // internal fault, so surface the same fail-closed 503 as a
            // missing DB mirror rather than a 500.
            DatabaseError::Pool(_) => api_error(
                StatusCode::SERVICE_UNAVAILABLE,
                "score read-back requires a configured gate-driver pool",
            ),
            other => internal_error(other),
        })?;
    let scores = rows
        .into_iter()
        .map(|row| SubmissionScoreBundle {
            submission_id: row.submission_id,
            credit_quality_micros: row.credit_quality_micros,
            perplexity_micros: row.perplexity_micros,
            novelty_score_micros: row.novelty_score_micros,
            gate_passed: row.gate_passed,
        })
        .collect::<Vec<_>>();
    append_control_plane_read_audit(
        state.as_ref(),
        &tenant,
        "scores_by_submission",
        scores.len(),
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(scores))
}

/// Per-submission cost-control knobs for the in-process perplexity-scoring
/// driver's `score_one_submission` wrapper (Task 4).
#[derive(Debug, Clone, Copy)]
#[allow(dead_code)]
struct PerplexityDriverKnobs {
    /// When true, a submission whose derived `duplicate_score` is at or
    /// above `skip_duplicate_threshold_micros` is recorded as a
    /// `SkippedDuplicate` decision without ever invoking the gate service.
    skip_duplicates: bool,
    /// Threshold, expressed in micros (`duplicate_score * 1_000_000.0 as
    /// i64`), at or above which a duplicate short-circuits scoring.
    skip_duplicate_threshold_micros: i64,
    /// Attempt ceiling consulted by the enumeration query
    /// (`list_submissions_needing_gate_decision`). Carried here so the
    /// driver's cost-control knobs live in one place; `score_one_submission`
    /// does not itself re-check this — the enumeration query already
    /// excludes submissions at or above the ceiling.
    max_attempts: i32,
}

/// Stamp the caller-supplied `submission_id`/`decided_at`/`credit_withheld_reason`
/// onto an otherwise-complete decision-row template and mint a fresh
/// `decision_id`. Shared by the skip-duplicate and cross-submission-cache
/// branches of `score_one_submission`, both of which build most of a
/// `trace_gate_decisions` row up front (either from the derived record's
/// scores or by copying a cached row) and only need these three fields
/// overridden before insert. `vector_entry_id` is always forced to `None`:
/// reusing the source row's vector-index entry id would make two
/// submissions appear to own the same vector-index entry, which would
/// corrupt per-submission revocation propagation.
fn build_cost_control_decision_row(
    submission_id: Uuid,
    decided_at: DateTime<Utc>,
    credit_withheld_reason: &'static str,
    template: StorageTraceGateDecisionRow,
) -> StorageTraceGateDecisionRow {
    StorageTraceGateDecisionRow {
        decision_id: Uuid::new_v4(),
        submission_id,
        decided_at,
        vector_entry_id: None,
        credit_withheld_reason: Some(credit_withheld_reason.to_string()),
        ..template
    }
}

/// Bumps the submission's `trace_gate_evaluation_attempts` row and, when the
/// resulting attempt count reaches `max_attempts`, emits a hash-only
/// `gate_scoring_exhausted` warning. Once a submission's attempt count
/// reaches `max_attempts`, the enumeration query's `MAX_ATTEMPTS` filter
/// (migration V36) permanently excludes it from future ticks, so this is the
/// only observability signal that the submission dropped out of the
/// gate-scoring set without ever being scored. Hash-only per repo policy —
/// never logs the raw tenant id or submission id.
async fn bump_gate_evaluation_attempt_and_log_exhaustion(
    db: &Arc<dyn Database>,
    tenant_id: &str,
    submission_id: Uuid,
    now: DateTime<Utc>,
    label: &str,
    max_attempts: i32,
) {
    if let Ok(attempts) = db
        .bump_gate_evaluation_attempt(tenant_id, submission_id, now, label)
        .await
    {
        if attempts >= max_attempts {
            tracing::warn!(
                tenant_hash = %sha256_prefixed(tenant_id),
                submission_hash = %sha256_prefixed(&submission_id.to_string()),
                attempts,
                max_attempts,
                "gate_scoring_exhausted"
            );
        }
    }
}

/// Applies the perplexity-scoring driver's per-submission cost controls
/// (skip-duplicate short-circuit, then cross-submission cache) before
/// delegating to `evaluate_and_record_gate`. On a hard failure — including a
/// scoring failure from the delegated call — bumps the submission's
/// `trace_gate_evaluation_attempts` row so the enumeration query's
/// exponential backoff (migration V36) can pace retries, logging
/// `gate_scoring_exhausted` (hash-only) once the attempt ceiling is reached.
///
/// The one exception is a TRANSIENT scoring failure — the upstream backend was
/// unavailable, so nothing is wrong with the trace. That returns
/// `GateOutcome::TransientFailed` WITHOUT bumping, because a bump there walks
/// a perfectly good submission to `max_attempts` and out of the enumeration
/// query for good (see
/// docs/superpowers/specs/2026-08-26-scoring-driver-transient-policy-design.md).
/// The remaining bump sites on this path are `db_mirror` failures, which are
/// left charging the trace as before.
#[allow(dead_code)]
async fn score_one_submission(
    state: &AppState,
    item: &GateWorkItem,
    knobs: &PerplexityDriverKnobs,
) -> GateOutcome {
    let now = Utc::now();

    let db = match state.db_mirror.as_ref() {
        Some(db) => db,
        None => {
            return GateOutcome::Failed {
                label: "trace gate driver requires a configured DB mirror".to_string(),
            };
        }
    };

    // Branch 1: skip-duplicate short-circuit. Never touches the gate
    // service — a duplicate at or above the configured threshold is
    // recorded directly.
    if knobs.skip_duplicates {
        let derived = match db.list_trace_derived_records(&item.tenant_id).await {
            Ok(records) => records
                .into_iter()
                .find(|record| record.submission_id == item.submission_id),
            Err(err) => {
                let label = format!("{err}");
                bump_gate_evaluation_attempt_and_log_exhaustion(
                    db,
                    &item.tenant_id,
                    item.submission_id,
                    now,
                    &label,
                    knobs.max_attempts,
                )
                .await;
                return GateOutcome::Failed { label };
            }
        };
        if let Some(derived) = derived {
            let duplicate_micros = derived
                .duplicate_score
                .map(|score| (score * 1_000_000.0) as i64);
            if let Some(duplicate_micros) = duplicate_micros {
                if duplicate_micros >= knobs.skip_duplicate_threshold_micros {
                    let novelty_micros = derived
                        .novelty_score
                        .map(|score| (score * 1_000_000.0) as i64)
                        .unwrap_or(0);
                    let row = build_cost_control_decision_row(
                        item.submission_id,
                        now,
                        "skipped_duplicate",
                        StorageTraceGateDecisionRow {
                            decision_id: Uuid::nil(),
                            submission_id: item.submission_id,
                            gate_policy_version: "skip_duplicate".to_string(),
                            gate_version_hash: String::new(),
                            perplexity_micros: 0,
                            tail_fraction_micros: 0,
                            perplexity_passed: true,
                            novelty_score_micros: novelty_micros,
                            nearest_neighbor_hash: String::new(),
                            novelty_passed: true,
                            embedding_evidence_hash: String::new(),
                            attestation_chain_hash: String::new(),
                            decided_at: now,
                            vector_entry_id: None,
                            credit_withheld_reason: None,
                            peak_perplexity_micros: None,
                            peak_novelty_micros: None,
                            chunk_count: None,
                            total_chunk_count: None,
                            chunks_capped: None,
                            // Same: no chunks were scored, so there is no
                            // per-chunk distribution to take a share of.
                            qualifying_token_fraction_micros: None,
                            // Not instrumented, and it never can be: this
                            // branch short-circuits before the gate service
                            // runs, so no composite was computed and no index
                            // was consulted. A skipped duplicate must not
                            // enter the #199 sample.
                            composite_score_micros: None,
                            vector_index_snapshot_id: None,
                            index_cardinality_at_scoring: None,
                        },
                    );
                    let decision_id = row.decision_id;
                    return match db.insert_trace_gate_decision(&item.tenant_id, row).await {
                        Ok(()) => GateOutcome::SkippedDuplicate { decision_id },
                        Err(err) => {
                            let label = format!("{err}");
                            bump_gate_evaluation_attempt_and_log_exhaustion(
                                db,
                                &item.tenant_id,
                                item.submission_id,
                                now,
                                &label,
                                knobs.max_attempts,
                            )
                            .await;
                            GateOutcome::Failed { label }
                        }
                    };
                }
            }
        }
    }

    // Branch 2: cross-submission cache. Reuses a prior decision recorded for
    // a different submission in the same tenant sharing this submission's
    // `canonical_summary_hash`, when one exists.
    let canonical_summary_hash = match db
        .get_trace_submission(&item.tenant_id, item.submission_id)
        .await
    {
        Ok(Some(submission)) => submission.canonical_summary_hash,
        Ok(None) => {
            let label = "trace submission not found".to_string();
            bump_gate_evaluation_attempt_and_log_exhaustion(
                db,
                &item.tenant_id,
                item.submission_id,
                now,
                &label,
                knobs.max_attempts,
            )
            .await;
            return GateOutcome::Failed { label };
        }
        Err(err) => {
            let label = format!("{err}");
            bump_gate_evaluation_attempt_and_log_exhaustion(
                db,
                &item.tenant_id,
                item.submission_id,
                now,
                &label,
                knobs.max_attempts,
            )
            .await;
            return GateOutcome::Failed { label };
        }
    };

    if let Some(hash) = canonical_summary_hash {
        match db
            .find_gate_decision_by_canonical_hash(&item.tenant_id, &hash, item.submission_id)
            .await
        {
            Ok(Some(cached)) => {
                let row =
                    build_cost_control_decision_row(item.submission_id, now, "cached", cached);
                let decision_id = row.decision_id;
                return match db.insert_trace_gate_decision(&item.tenant_id, row).await {
                    Ok(()) => GateOutcome::Cached { decision_id },
                    Err(err) => {
                        let label = format!("{err}");
                        bump_gate_evaluation_attempt_and_log_exhaustion(
                            db,
                            &item.tenant_id,
                            item.submission_id,
                            now,
                            &label,
                            knobs.max_attempts,
                        )
                        .await;
                        GateOutcome::Failed { label }
                    }
                };
            }
            Ok(None) => {}
            Err(err) => {
                let label = format!("{err}");
                bump_gate_evaluation_attempt_and_log_exhaustion(
                    db,
                    &item.tenant_id,
                    item.submission_id,
                    now,
                    &label,
                    knobs.max_attempts,
                )
                .await;
                return GateOutcome::Failed { label };
            }
        }
    }

    // Branch 3: delegate to the real scorer.
    match evaluate_and_record_gate(state, &item.tenant_id, item.submission_id).await {
        Ok(outcome) => outcome,
        Err(err) => {
            // `{err:#}` records the full anyhow chain (outer context + inner
            // cause), so a scorer failure surfaces the specific hash-safe label
            // (e.g. `NearAiScorerHttpStatusError status=400 body_len=N`) rather
            // than the generic `PerplexityScorerInferenceFailed` wrapper. All
            // leaf errors on this path are hash-only by construction (reqwest
            // URLs are stripped at the scorer).
            let label = format!("{err:#}");

            // A transient upstream failure is the scoring backend's, not the
            // trace's: log it hash-only and leave the attempt counter alone,
            // so the submission is re-enumerated on a later tick. Only a
            // permanent failure -- a request this trace can never satisfy, or
            // anything else about the trace itself -- may spend the trace's
            // budget and eventually exclude it from scoring for good.
            if is_transient_gate_scoring_failure(&err) {
                tracing::warn!(
                    error_hash = %safe_runtime_error_hash(&err),
                    submission_hash = %sha256_prefixed(&item.submission_id.to_string()),
                    tenant_hash = %sha256_prefixed(&item.tenant_id),
                    "Trace Commons gate scoring upstream unavailable; \
                     submission left in backlog, attempt not charged"
                );
                return GateOutcome::TransientFailed { label };
            }

            bump_gate_evaluation_attempt_and_log_exhaustion(
                db,
                &item.tenant_id,
                item.submission_id,
                now,
                &label,
                knobs.max_attempts,
            )
            .await;
            GateOutcome::Failed { label }
        }
    }
}

/// Worker route that scores a single submission through the configured
/// `TraceGateService` and writes a `trace_gate_decisions` audit row.
///
/// Scope: standalone callsite. Not yet wired into the orchestrator —
/// future deployments will trigger it post-ingest or post-review. The
/// vector-worker bearer-token gate is reused because the gate evaluation
/// is the upstream step of the same indexing pipeline.
async fn gate_evaluate_worker_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceGateEvaluateWorkerRequest>,
) -> ApiResult<Json<TraceGateEvaluateWorkerResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_vector_operator(&tenant)?;

    let outcome = evaluate_and_record_gate(state.as_ref(), &tenant.tenant_id, body.submission_id)
        .await
        .map_err(|err| {
            let msg = format!("{err}");
            if msg.contains("DstackGateServiceUnavailable") {
                api_error(StatusCode::SERVICE_UNAVAILABLE, msg)
            } else if msg == TRACE_GATE_WORKER_AUTH_MISSING_OBJECT_REF
                || msg == "trace submission not found"
            {
                api_error(StatusCode::NOT_FOUND, msg)
            } else if msg == "trace gate worker requires a configured DB mirror"
                || msg == "trace gate worker requires a configured artifact store"
                || msg == "trace gate worker requires an encrypted trace object store"
                || msg == TRACE_OBJECT_REF_STORE_MISMATCH
                || msg == "trace gate worker requires a v2 KEK-wrapped envelope"
            {
                api_error(StatusCode::SERVICE_UNAVAILABLE, msg)
            } else {
                internal_error(err)
            }
        })?;

    let (
        decision_id,
        perplexity_passed,
        novelty_passed,
        vector_entry_id,
        gate_policy_version,
        gate_version_hash,
        chunk_count,
        total_chunk_count,
        chunks_capped,
    ) = match outcome {
        GateOutcome::Scored {
            decision_id,
            perplexity_passed,
            novelty_passed,
            vector_entry_id,
            gate_policy_version,
            gate_version_hash,
            chunk_count,
            total_chunk_count,
            chunks_capped,
        } => (
            decision_id,
            perplexity_passed,
            novelty_passed,
            vector_entry_id,
            gate_policy_version,
            gate_version_hash,
            chunk_count,
            total_chunk_count,
            chunks_capped,
        ),
        GateOutcome::Failed { label } => {
            return Err(api_error(StatusCode::INTERNAL_SERVER_ERROR, label));
        }
        GateOutcome::SkippedDuplicate { .. }
        | GateOutcome::Cached { .. }
        | GateOutcome::TransientFailed { .. } => {
            // evaluate_and_record_gate never produces these variants; the
            // cost-control wrapper that would is not yet wired into this
            // HTTP handler.
            return Err(internal_error(anyhow::anyhow!(
                "unexpected gate outcome variant from evaluate_and_record_gate"
            )));
        }
    };

    // Phase A5: if the gate passed, attempt to mint a `novelty_utility`
    // credit-ledger event through the same pipeline that the operator-facing
    // utility-credit handler uses. ABAC failures do NOT fail gate evaluation
    // overall — the decision row still lands so the operator can audit; we
    // only annotate `credit_withheld_reason` with a stable label-only string.
    let db = state.db_mirror.as_ref().ok_or_else(|| {
        api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "trace gate worker requires a configured DB mirror",
        )
    })?;
    let (credit_emitted, credit_withheld_reason) = if perplexity_passed && novelty_passed {
        let decision = GateDecision {
            gate_policy_version: gate_policy_version.clone(),
            gate_version_hash: gate_version_hash.clone(),
            perplexity_micros: 0,
            tail_fraction_micros: 0,
            perplexity_passed,
            novelty_score_micros: 0,
            nearest_neighbor_hash: String::new(),
            novelty_passed,
            embedding_evidence_hash: String::new(),
            attestation_chain_hash: String::new(),
            vector_entry_id,
            peak_perplexity_micros: 0,
            peak_novelty_micros: 0,
            chunk_count: 1,
            total_chunk_count: 1,
            chunks_capped: false,
            // Same reason as the hashes below: this copy never touches the
            // per-chunk scores the statistic is computed from, and the real
            // decision row already carries it. Unknown, not zero.
            qualifying_token_fraction_micros: None,
            chunk_vector_entries: Vec::new(),
            // This is a synthetic re-hydration of the already-persisted
            // decision for the credit-emission call below (no ciphertext or
            // plaintext in scope here) — dedup clustering already ran inline
            // in `evaluate_and_record_gate` against the real decision, so
            // there is nothing meaningful to compute for this throwaway copy.
            dedup_simhash: 0,
            // Same reason: with no simhash to describe, there is no
            // derivation to name. A stamp no derivation produces, so that if
            // this copy ever does reach a row, `dedup_simhash: 0` above joins
            // nothing -- under the legacy stamp it would be Hamming-close to
            // every low-weight v1 signal in the corpus.
            dedup_signal_version:
                trace_commons_server::dedup_assign::PLACEHOLDER_DEDUP_SIGNAL_VERSION.to_string(),
            // Same reason: this throwaway copy carries no plaintext, and the
            // correction value already ran inline against the real decision.
            correction_simhash: None,
            // Same reason again: the real decision row already carries the
            // #199 instrumentation. This copy exists only to call the credit
            // emitter and is never persisted, so it claims no index state.
            vector_index_snapshot_id: None,
            index_cardinality_at_scoring: None,
        };
        let emit_result = attempt_emit_novelty_utility_credit(
            state.as_ref(),
            &tenant,
            &decision,
            body.submission_id,
        )
        .await;
        let (emitted, withheld_reason) = match emit_result {
            Ok((emitted, withheld_reason)) => (emitted, withheld_reason),
            Err(err) => {
                // Credit computation hit a hard error (e.g. tenant-policy or
                // utility-record DB failure). The audit row was already
                // written by `evaluate_and_record_gate` with
                // `credit_withheld_reason = None`, which would misrepresent a
                // failed request as a clean non-withheld outcome. Best-effort
                // patch the row to a fixed sentinel so the persisted audit
                // trail is honest, then propagate the *original* error
                // unchanged (identical client-visible status/body). The patch
                // is best-effort: if it too fails we still surface the
                // original error rather than masking it.
                let _ = db
                    .update_trace_gate_decision_credit_withheld_reason(
                        &tenant.tenant_id,
                        decision_id,
                        Some(CREDIT_CHECK_ERROR_LABEL.to_string()),
                    )
                    .await;
                return Err(err);
            }
        };
        if withheld_reason.is_some() {
            // The initial row written inside `evaluate_and_record_gate` was
            // recorded before credit eligibility was known (credit emission
            // needs `TenantAuth`, which the non-auth core doesn't have).
            // Update the row now so the persisted audit trail matches what
            // the response reports, exactly as the pre-extraction single
            // insert did.
            db.update_trace_gate_decision_credit_withheld_reason(
                &tenant.tenant_id,
                decision_id,
                withheld_reason.clone(),
            )
            .await
            .map_err(internal_error)?;
        }
        (emitted, withheld_reason)
    } else {
        // #444: the decision did not pass a floor. Say WHY credit is withheld.
        // A capped decision judged only the part of the trace we could afford
        // to score, so an unexplained failure misrepresents it as a verdict on
        // the whole. Credit is withheld either way -- we cannot vouch for what
        // we did not read -- but the label makes the two distinguishable in
        // the audit row and to the contributor.
        (false, gate_failure_withheld_reason(Some(chunks_capped)))
    };

    Ok(Json(TraceGateEvaluateWorkerResponse {
        tenant_id: tenant.tenant_id.clone(),
        submission_id: body.submission_id,
        decision_id,
        gate_policy_version,
        gate_version_hash,
        perplexity_passed,
        novelty_passed,
        vector_entry_id,
        credit_emitted,
        credit_withheld_reason,
        coverage_explanation: coverage_explanation(
            ScoreAttestationCoverage::from_decision_columns(
                Some(chunk_count as i32),
                Some(total_chunk_count as i32),
                Some(chunks_capped),
            ),
        ),
    }))
}

/// Phase A5: helper called from `gate_evaluate_worker_handler` when both
/// gate floors pass. Routes through the same central-issuer ABAC,
/// tenant-policy allowed-uses, and idempotent-emit pipeline that
/// `utility_credit_handler` uses for the operator-facing utility-credit
/// kinds. Returns `(credit_emitted, credit_withheld_reason)`:
/// - `(true, None)` — credit minted via
///   `append_automatic_utility_credit_events_once_with_counts` (`appended > 0`)
/// - `(false, None)` — idempotent hit (`skipped_existing > 0`); no new credit
///   minted, but the prior emission is the audit trail
/// - `(false, Some(label))` — credit withheld; the decision row records the
///   stable label-only reason
async fn attempt_emit_novelty_utility_credit(
    state: &AppState,
    tenant: &TenantAuth,
    decision: &GateDecision,
    submission_id: Uuid,
) -> ApiResult<(bool, Option<String>)> {
    // (1) Production-gate guard. When `TRACE_COMMONS_NOVELTY_UTILITY_REQUIRE_PRODUCTION_GATE`
    // is truthy, only `enclave_local_gpu` (real local-GPU enclave) and `dstack`
    // (production trust boundary) may mint credit. Stubs and dev backends
    // produce decision rows but no credit.
    if state.novelty_utility_require_production_gate
        && !is_production_gate_service_kind(&state.gate_service.safe_status().kind)
    {
        return Ok((false, Some("non_production_gate".to_string())));
    }

    // (2) Central-issuer ABAC. Returns `Err` when the central-issuer
    // allowlist is configured and the gate-worker principal is not in it.
    // Unlike the operator API path where this propagates as 403, here we
    // convert it to a withheld-reason label so the decision row still lands.
    if require_positive_credit_issuance_principal_if_configured(
        state,
        tenant,
        state.novelty_utility_credit_points_delta,
    )
    .is_err()
    {
        return Ok((false, Some("central_issuer_denied".to_string())));
    }

    let event_type = TraceCreditLedgerEventType::NoveltyUtility;
    let required_uses = utility_credit_required_allowed_uses(event_type);

    // (3) Tenant policy fetch. Errors here are surfaced as ApiErrors (e.g.,
    // scoped-token claim mismatch is a hard rejection, not a withheld reason).
    let tenant_policy =
        tenant_utility_credit_policy_for_request(state, tenant, required_uses).await?;

    // (4) Load the submission record. Treat a missing record as a real not-found
    // failure rather than withholding silently — the gate route already loaded
    // the storage row from the same backend earlier in the handler, so this
    // path should normally succeed.
    let Some(submission_record) = read_utility_submission_record(state, tenant, submission_id)
        .await
        .map_err(internal_error)?
    else {
        return Err(api_error(
            StatusCode::NOT_FOUND,
            "trace submission not found",
        ));
    };

    // (5) Defense-in-depth submission status check. The gate route only
    // operates on already-loaded submissions but the operator pipeline
    // requires Accepted status before crediting.
    if submission_record.status != TraceCorpusStatus::Accepted {
        return Ok((false, Some("submission_not_accepted".to_string())));
    }

    // (6) Per-submission ABAC: required allowed-use must appear on both the
    // submission record AND, if configured, the tenant policy.
    if !record_matches_utility_credit_policy_abac(
        &submission_record,
        tenant,
        tenant_policy.as_ref(),
        required_uses,
    ) {
        return Ok((false, Some("policy_mismatch".to_string())));
    }

    // (7) Emit. `external_ref` binds the gate version to the submission id —
    // NOT the decision id, which is freshly minted on every gate-worker call.
    // Keying on `(gate_version_hash, submission_id)` makes route retries
    // idempotent at the ledger level (per the spec's open-question
    // resolution: "allow duplicate decision rows on retry; ledger idempotency
    // on external_ref handles the credit side"). The `decision_id` itself is
    // not lost — the trace_gate_decisions row carries it and the audit log
    // links the two via the `reason` and the row's `decided_at` ordering.
    let external_ref = format!(
        "novelty_utility:{}:{}",
        decision.gate_version_hash, submission_id,
    );
    let reason = format!("novelty_utility:{}", decision.gate_policy_version);
    let counts = append_automatic_utility_credit_events_once_with_counts(
        state,
        tenant,
        AutomaticUtilityCreditConfig {
            idempotency_label: event_type.utility_idempotency_label(),
            idempotency_ref: Some(external_ref.clone()),
            event_type,
            credit_points_delta: state.novelty_utility_credit_points_delta,
            reason,
            external_ref,
        },
        vec![AutomaticUtilityCreditSource {
            submission_id: submission_record.submission_id,
            trace_id: submission_record.trace_id,
            auth_principal_ref: submission_record.auth_principal_ref.clone(),
        }],
    )
    .await?;

    Ok((counts.appended > 0, None))
}

/// Returns true when `kind` (as returned by `TraceGateService::safe_status()`)
/// names a production trust boundary. Mirrors the spec's enumeration: the only
/// production-trust kinds today are `enclave_local_gpu` (Phase A2 real local
/// GPU) and `dstack` (Phase A2/A3 enclave deployment). Stubs
/// (`in_memory`, `enclave_mock`, `legacy_deterministic`, `dstack_stub`) are
/// explicitly non-production.
fn is_production_gate_service_kind(kind: &str) -> bool {
    matches!(kind, "enclave_local_gpu" | "dstack")
}

async fn vector_index_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceVectorIndexRequest>,
) -> ApiResult<Json<TraceVectorIndexResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_vector_operator(&tenant)?;
    let limit = validate_vector_index_worker_limit(body.limit)?;
    if state.require_external_vector_embedder && state.vector_embedder.is_none() {
        return Err(api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "trace vector index worker requires TRACE_COMMONS_VECTOR_EMBEDDER_URL",
        ));
    }
    if state.require_external_vector_searcher && state.vector_searcher.is_none() {
        return Err(api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "trace vector index worker requires TRACE_COMMONS_VECTOR_SEARCH_URL",
        ));
    }
    if state.db_mirror.is_none() {
        return Err(api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "trace vector index worker requires configured DB mirror",
        ));
    }
    let vector_tenant_policy = tenant_vector_policy_for_request(state.as_ref(), &tenant).await?;
    let response = run_vector_index_worker(
        state.as_ref(),
        &tenant,
        body,
        limit,
        vector_tenant_policy.as_ref(),
    )
    .await
    .map_err(maintenance_error)?;
    Ok(Json(response))
}

fn validate_vector_index_worker_limit(limit: Option<usize>) -> ApiResult<usize> {
    let limit = limit.unwrap_or(TRACE_VECTOR_INDEX_WORKER_DEFAULT_LIMIT);
    if !(1..=TRACE_VECTOR_INDEX_WORKER_MAX_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "vector index worker limit must be between 1 and 500",
        ));
    }
    Ok(limit)
}

fn validate_u32_worker_limit(limit: u32, max_limit: u32, worker_name: &str) -> ApiResult<()> {
    if !(1..=max_limit).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("{worker_name} limit must be between 1 and {max_limit}"),
        ));
    }
    Ok(())
}

#[derive(Debug, Deserialize)]
struct AuditEventsQuery {
    limit: Option<usize>,
}

async fn audit_events_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<AuditEventsQuery>,
) -> ApiResult<Json<Vec<TraceCommonsAuditEvent>>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_reviewer(&tenant)?;
    let limit = validate_trace_read_limit(query.limit)?;
    let events = read_recent_audit_events(state.as_ref(), &tenant, limit)
        .await
        .map_err(internal_error)?;
    append_control_plane_read_audit(state.as_ref(), &tenant, "audit_events", events.len())
        .await
        .map_err(internal_error)?;
    Ok(Json(events))
}

fn trace_matches_derived_filters(
    derived: Option<&TraceCommonsDerivedRecord>,
    coverage_tag: Option<&str>,
    tool: Option<&str>,
) -> bool {
    let Some(derived) = derived else {
        return coverage_tag.is_none() && tool.is_none();
    };
    let coverage_matches = coverage_tag.is_none_or(|coverage_tag| {
        derived
            .coverage_tags
            .iter()
            .any(|tag| tag.eq_ignore_ascii_case(coverage_tag))
    });
    let tool_matches = tool.is_none_or(|tool| {
        derived
            .tool_sequence
            .iter()
            .chain(derived.tool_categories.iter())
            .any(|candidate| candidate.eq_ignore_ascii_case(tool))
    });
    coverage_matches && tool_matches
}

async fn collect_ranker_training_candidates(
    state: &AppState,
    tenant: &TenantAuth,
    query: &RankerTrainingExportQuery,
    consent_scope: Option<ConsentScope>,
    tenant_policy: Option<&TenantSubmissionPolicy>,
) -> anyhow::Result<Vec<TraceRankerTrainingCandidate>> {
    let TraceCommonsMetadataView { records, derived } =
        read_reviewer_metadata_view(state, tenant).await?;
    let derived_by_submission = derived
        .into_iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    let limit = query
        .limit
        .unwrap_or(DEFAULT_TRACE_COMMONS_MAX_EXPORT_ITEMS_PER_REQUEST);
    let requested_status = query.status.unwrap_or(TraceCorpusStatus::Accepted);
    let mut candidates = Vec::new();
    for record in records
        .into_iter()
        .filter(|record| record.status == requested_status)
        .filter(|record| matches!(record.status, TraceCorpusStatus::Accepted))
        .filter(|record| !record.is_revoked())
        .filter(|record| {
            query
                .privacy_risk
                .is_none_or(|risk| record.privacy_risk == risk)
        })
        .filter(|record| ranker_consent_matches(&record.consent_scopes, consent_scope))
        .filter(|record| {
            record_matches_export_policy_abac(
                record,
                tenant,
                tenant_policy,
                TraceAllowedUse::RankingModelTraining,
            )
        })
    {
        ensure_retention_metadata_within_server_policy(&record)?;
        if let Some(derived) = derived_by_submission.get(&record.submission_id) {
            candidates.push(TraceRankerTrainingCandidate::from_records(&record, derived));
        }
    }
    let mut candidates = dedupe_ranker_training_candidates_by_summary_hash(candidates);
    candidates.sort_by(|left, right| {
        right
            .ranker_score
            .total_cmp(&left.ranker_score)
            .then_with(|| left.received_at.cmp(&right.received_at))
    });
    candidates.truncate(limit);
    Ok(candidates)
}

fn dedupe_ranker_training_candidates_by_summary_hash(
    candidates: Vec<TraceRankerTrainingCandidate>,
) -> Vec<TraceRankerTrainingCandidate> {
    let mut keyed = BTreeMap::<String, TraceRankerTrainingCandidate>::new();
    let mut unkeyed = Vec::new();
    for candidate in candidates {
        let Some(key) = trace_candidate_summary_dedupe_key(&candidate.canonical_summary_hash)
        else {
            unkeyed.push(candidate);
            continue;
        };
        match keyed.entry(key) {
            std::collections::btree_map::Entry::Occupied(mut entry) => {
                if ranker_training_candidate_replaces_summary_representative(
                    &candidate,
                    entry.get(),
                ) {
                    entry.insert(candidate);
                }
            }
            std::collections::btree_map::Entry::Vacant(entry) => {
                entry.insert(candidate);
            }
        }
    }
    unkeyed.extend(keyed.into_values());
    unkeyed
}

fn trace_candidate_summary_dedupe_key(canonical_summary_hash: &str) -> Option<String> {
    let canonical_summary_hash = canonical_summary_hash.trim();
    if is_canonical_sha256_prefixed_hash(canonical_summary_hash) {
        Some(canonical_summary_hash.to_string())
    } else {
        None
    }
}

fn ranker_training_candidate_replaces_summary_representative(
    candidate: &TraceRankerTrainingCandidate,
    current: &TraceRankerTrainingCandidate,
) -> bool {
    let duplicate_cmp = candidate
        .duplicate_score
        .total_cmp(&current.duplicate_score);
    if duplicate_cmp != std::cmp::Ordering::Equal {
        return duplicate_cmp.is_lt();
    }
    let novelty_cmp = candidate.novelty_score.total_cmp(&current.novelty_score);
    if novelty_cmp != std::cmp::Ordering::Equal {
        return novelty_cmp.is_gt();
    }
    let ranker_cmp = candidate.ranker_score.total_cmp(&current.ranker_score);
    if ranker_cmp != std::cmp::Ordering::Equal {
        return ranker_cmp.is_gt();
    }
    (candidate.received_at, candidate.submission_id) < (current.received_at, current.submission_id)
}

fn ranker_consent_matches(scopes: &[ConsentScope], requested: Option<ConsentScope>) -> bool {
    if let Some(requested) = requested {
        return is_ranker_training_consent_scope(requested) && scopes.contains(&requested);
    }
    scopes.iter().copied().any(is_ranker_training_consent_scope)
}

fn parse_ranker_consent_scope_filter(value: Option<&str>) -> ApiResult<Option<ConsentScope>> {
    let scope = parse_consent_scope_filter(value)?;
    if let Some(scope) = scope
        && !is_ranker_training_consent_scope(scope)
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranker training exports require ranking-training or model-training consent",
        ));
    }
    Ok(scope)
}

fn is_ranker_training_consent_scope(scope: ConsentScope) -> bool {
    matches!(
        scope,
        ConsentScope::RankingTraining | ConsentScope::ModelTraining
    )
}

fn build_ranker_training_pairs(
    candidates: &[TraceRankerTrainingCandidate],
    preference_labels: &[TraceRankingPreferenceLabelRecord],
    limit: usize,
) -> Vec<TraceRankerTrainingPair> {
    let candidates_by_submission = candidates
        .iter()
        .map(|candidate| (candidate.submission_id, candidate))
        .collect::<BTreeMap<_, _>>();
    let mut preference_labels = preference_labels.iter().collect::<Vec<_>>();
    preference_labels.sort_by(|left, right| {
        left.created_at
            .cmp(&right.created_at)
            .then_with(|| left.preference_label_id.cmp(&right.preference_label_id))
    });
    let mut seen_unordered_pairs = BTreeSet::new();
    let mut pairs = Vec::new();
    for label in preference_labels {
        if pairs.len() >= limit {
            return pairs;
        }
        if label.target_use != TraceAllowedUse::RankingModelTraining {
            continue;
        }
        let Some(preferred) = candidates_by_submission.get(&label.preferred_submission_id) else {
            continue;
        };
        let Some(rejected) = candidates_by_submission.get(&label.rejected_submission_id) else {
            continue;
        };
        if preferred.submission_id == rejected.submission_id {
            continue;
        }
        if !seen_unordered_pairs.insert(ranker_pair_unordered_key(
            preferred.submission_id,
            rejected.submission_id,
        )) {
            continue;
        }
        pairs.push(TraceRankerTrainingPair::from_preference_label(
            preferred, rejected, label,
        ));
    }

    for window in candidates.windows(2) {
        if pairs.len() >= limit {
            break;
        }
        let Some(pair) = (|| {
            let [preferred, rejected] = window else {
                return None;
            };
            if preferred.submission_id == rejected.submission_id {
                return None;
            }
            if !seen_unordered_pairs.insert(ranker_pair_unordered_key(
                preferred.submission_id,
                rejected.submission_id,
            )) {
                return None;
            }
            Some(TraceRankerTrainingPair::from_candidates(
                preferred, rejected,
            ))
        })() else {
            continue;
        };
        pairs.push(pair);
    }
    pairs
}

fn ranker_pair_unordered_key(left: Uuid, right: Uuid) -> (Uuid, Uuid) {
    if left <= right {
        (left, right)
    } else {
        (right, left)
    }
}

fn source_submission_ids_hash(kind: &str, source_submission_ids: &[Uuid]) -> String {
    let mut payload = String::from(kind);
    for submission_id in source_submission_ids {
        payload.push('\n');
        payload.push_str(&submission_id.to_string());
    }
    sha256_prefixed(&payload)
}

fn ranker_pair_list_hash(pairs: &[TraceRankerTrainingPair]) -> String {
    let mut payload = String::from("ranker_training_pairs_export");
    for pair in pairs {
        payload.push('\n');
        payload.push_str(&pair.preferred_submission_id.to_string());
        payload.push('>');
        payload.push_str(&pair.rejected_submission_id.to_string());
        payload.push(':');
        payload.push_str(&pair.reason);
        if let Some(preference_label_id) = pair.preference_label_id {
            payload.push(':');
            payload.push_str(&preference_label_id.to_string());
        }
    }
    sha256_prefixed(&payload)
}

fn ranker_pair_source_submission_ids(pairs: &[TraceRankerTrainingPair]) -> Vec<Uuid> {
    pairs
        .iter()
        .flat_map(|pair| [pair.preferred_submission_id, pair.rejected_submission_id])
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect()
}

fn normalized_export_purpose(value: Option<&str>, default: &str) -> String {
    value
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .unwrap_or(default)
        .to_string()
}

fn resolve_export_limit(state: &AppState, requested_limit: Option<usize>) -> usize {
    requested_limit
        .unwrap_or(100)
        .clamp(1, state.max_export_items_per_request)
}

fn create_one_shot_export_grant(
    state: &AppState,
    tenant: &TenantAuth,
    requested_dataset_kind: TraceExportDatasetKind,
    purpose: impl Into<String>,
    requested_limit: Option<usize>,
    now: DateTime<Utc>,
) -> TraceExportAccessGrant {
    TraceExportAccessGrant::one_shot(
        tenant,
        requested_dataset_kind,
        purpose,
        resolve_export_limit(state, requested_limit),
        now,
    )
}

fn create_validated_export_job_slice(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceExportJobRequest,
    now: DateTime<Utc>,
) -> ApiResult<TraceExportJobSlice> {
    let TraceExportJobRequest {
        requested_dataset_kind,
        purpose,
        requested_limit,
        grant,
        mut metadata,
    } = request;
    validate_export_access_grant(&grant, tenant, requested_dataset_kind, &purpose, now)?;
    let max_item_cap = resolve_export_limit(state, requested_limit).min(grant.max_item_cap);
    metadata.insert(
        "request_schema_version".to_string(),
        "trace_export_job_request.v1".to_string(),
    );
    metadata.insert(
        "dataset_kind".to_string(),
        requested_dataset_kind.storage_name().to_string(),
    );
    metadata
        .entry("requested_limit".to_string())
        .or_insert_with(|| requested_limit_label(requested_limit));
    metadata.insert("effective_limit".to_string(), max_item_cap.to_string());
    Ok(TraceExportJobSlice {
        job_id: Uuid::new_v4(),
        grant_id: grant.grant_id,
        tenant_id: tenant.tenant_id.clone(),
        caller_principal_ref: tenant.principal_ref.clone(),
        requested_dataset_kind,
        purpose,
        expires_at: grant.expires_at,
        max_item_cap,
        status: TraceExportJobStatus::InProgress,
        requested_at: now,
        started_at: Some(now),
        finished_at: None,
        metadata,
    })
}

fn export_job_request_metadata(
    requested_limit: Option<usize>,
    status: Option<TraceCorpusStatus>,
    privacy_risk: Option<ResidualPiiRisk>,
    consent_scope: Option<ConsentScope>,
    external_ref: Option<&str>,
) -> BTreeMap<String, String> {
    let mut metadata = BTreeMap::new();
    metadata.insert(
        "requested_limit".to_string(),
        requested_limit_label(requested_limit),
    );
    metadata.insert(
        "filter_status".to_string(),
        status
            .map(TraceCorpusStatus::as_str)
            .unwrap_or("any")
            .to_string(),
    );
    metadata.insert(
        "filter_privacy_risk".to_string(),
        privacy_risk
            .map(residual_pii_risk_name)
            .unwrap_or("any")
            .to_string(),
    );
    metadata.insert(
        "filter_consent_scope".to_string(),
        consent_scope
            .map(consent_scope_name)
            .unwrap_or("any")
            .to_string(),
    );
    if let Some(external_ref) = external_ref
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        metadata.insert(
            "external_ref_hash".to_string(),
            sha256_prefixed(external_ref),
        );
    }
    metadata
}

fn requested_limit_label(requested_limit: Option<usize>) -> String {
    requested_limit
        .map(|limit| limit.to_string())
        .unwrap_or_else(|| "default".to_string())
}

fn residual_pii_risk_name(privacy_risk: ResidualPiiRisk) -> &'static str {
    match privacy_risk {
        ResidualPiiRisk::Low => "low",
        ResidualPiiRisk::Medium => "medium",
        ResidualPiiRisk::High => "high",
    }
}

fn consent_scope_name(consent_scope: ConsentScope) -> &'static str {
    match consent_scope {
        ConsentScope::DebuggingEvaluation => "debugging_evaluation",
        ConsentScope::BenchmarkOnly => "benchmark_only",
        ConsentScope::RankingTraining => "ranking_training",
        ConsentScope::ModelTraining => "model_training",
        ConsentScope::PublicAttribution => "public_attribution",
    }
}

fn export_job_status_metadata(
    job: &TraceExportJobSlice,
    state: impl Into<String>,
) -> BTreeMap<String, String> {
    let mut metadata = job.metadata.clone();
    metadata.insert("state".to_string(), state.into());
    metadata
}

async fn mirror_export_job_started_to_db(
    state: &AppState,
    tenant: &TenantAuth,
    grant: &TraceExportAccessGrant,
    job: &TraceExportJobSlice,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    let mut grant_metadata = BTreeMap::new();
    grant_metadata.insert("grant_type".to_string(), "one_shot".to_string());
    grant_metadata.insert(
        "dataset_kind".to_string(),
        job.requested_dataset_kind.storage_name().to_string(),
    );
    db.upsert_trace_export_access_grant(StorageTraceExportAccessGrantWrite {
        tenant_id: tenant.tenant_id.clone(),
        export_job_id: job.job_id,
        grant_id: grant.grant_id,
        caller_principal_ref: tenant.principal_ref.clone(),
        requested_dataset_kind: grant.requested_dataset_kind.storage_name().to_string(),
        purpose: grant.purpose.clone(),
        max_item_cap: Some(grant.max_item_cap.min(u32::MAX as usize) as u32),
        status: storage_export_grant_status(grant.status),
        requested_at: job.requested_at,
        expires_at: grant.expires_at,
        metadata: grant_metadata,
    })
    .await
    .context("failed to mirror trace export access grant")?;

    db.upsert_trace_export_job(StorageTraceExportJobWrite {
        tenant_id: job.tenant_id.clone(),
        export_job_id: job.job_id,
        grant_id: job.grant_id,
        caller_principal_ref: job.caller_principal_ref.clone(),
        requested_dataset_kind: job.requested_dataset_kind.storage_name().to_string(),
        purpose: job.purpose.clone(),
        max_item_cap: Some(job.max_item_cap.min(u32::MAX as usize) as u32),
        status: storage_export_job_status(job.status),
        requested_at: job.requested_at,
        started_at: job.started_at,
        finished_at: job.finished_at,
        expires_at: job.expires_at,
        result_manifest_id: None,
        item_count: None,
        last_error: None,
        metadata: export_job_status_metadata(job, "started"),
    })
    .await
    .context("failed to mirror trace export job start")?;
    Ok(())
}

async fn mirror_export_job_finished_to_db(
    state: &AppState,
    job: &TraceExportJobSlice,
    result_manifest_id: Uuid,
    item_count: usize,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    let updated = db
        .update_trace_export_job_status(
            &job.tenant_id,
            job.job_id,
            StorageTraceExportJobStatusUpdate {
                status: StorageTraceExportJobStatus::Complete,
                started_at: job.started_at,
                finished_at: Some(Utc::now()),
                result_manifest_id: Some(result_manifest_id),
                item_count: Some(item_count.min(u32::MAX as usize) as u32),
                last_error: None,
                metadata: export_job_status_metadata(job, "completed"),
            },
        )
        .await
        .context("failed to mirror trace export job completion")?;
    if updated.is_none() {
        anyhow::bail!(
            "trace export job {} was not found for completion mirror",
            job.job_id
        );
    }
    Ok(())
}

async fn mirror_export_job_failed_to_db(
    state: &AppState,
    job: &TraceExportJobSlice,
    error: &anyhow::Error,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    let updated = db
        .update_trace_export_job_status(
            &job.tenant_id,
            job.job_id,
            StorageTraceExportJobStatusUpdate {
                status: StorageTraceExportJobStatus::Failed,
                started_at: job.started_at,
                finished_at: Some(Utc::now()),
                result_manifest_id: None,
                item_count: None,
                last_error: Some(safe_worker_error(error)),
                metadata: export_job_status_metadata(job, "failed"),
            },
        )
        .await
        .context("failed to mirror trace export job failure")?;
    if updated.is_none() {
        anyhow::bail!(
            "trace export job {} was not found for failure mirror",
            job.job_id
        );
    }
    Ok(())
}

async fn fail_export_job_with_internal_error<T>(
    state: &AppState,
    job: &TraceExportJobSlice,
    operation: &str,
    error: anyhow::Error,
) -> ApiResult<T> {
    let api_error = internal_error(&error);
    enforce_export_job_mirror_result(
        state,
        operation,
        mirror_export_job_failed_to_db(state, job, &error).await,
    )
    .await
    .map_err(internal_error)?;
    Err(api_error)
}

async fn fail_export_job_on_error<T>(
    state: &AppState,
    job: &TraceExportJobSlice,
    operation: &str,
    result: anyhow::Result<T>,
) -> ApiResult<T> {
    match result {
        Ok(value) => Ok(value),
        Err(error) => fail_export_job_with_internal_error(state, job, operation, error).await,
    }
}

async fn enforce_export_job_mirror_result(
    state: &AppState,
    operation: &str,
    result: anyhow::Result<()>,
) -> anyhow::Result<()> {
    if let Err(error) = &result {
        tracing::warn!(
            error_hash = %safe_display_error_hash(error),
            operation,
            "Trace Commons DB export job mirror failed"
        );
    }
    enforce_db_mirror_write_result(state, operation, result)
}

fn storage_export_grant_status(
    status: TraceExportGrantStatus,
) -> StorageTraceExportAccessGrantStatus {
    match status {
        TraceExportGrantStatus::Active => StorageTraceExportAccessGrantStatus::Active,
        TraceExportGrantStatus::Consumed => StorageTraceExportAccessGrantStatus::Consumed,
        TraceExportGrantStatus::Expired => StorageTraceExportAccessGrantStatus::Expired,
        TraceExportGrantStatus::Revoked => StorageTraceExportAccessGrantStatus::Revoked,
    }
}

fn storage_export_job_status(status: TraceExportJobStatus) -> StorageTraceExportJobStatus {
    match status {
        TraceExportJobStatus::Pending => StorageTraceExportJobStatus::Queued,
        TraceExportJobStatus::InProgress => StorageTraceExportJobStatus::Running,
        TraceExportJobStatus::Completed => StorageTraceExportJobStatus::Complete,
        TraceExportJobStatus::Failed => StorageTraceExportJobStatus::Failed,
        TraceExportJobStatus::Rejected => StorageTraceExportJobStatus::Cancelled,
    }
}

fn validate_export_access_grant(
    grant: &TraceExportAccessGrant,
    tenant: &TenantAuth,
    requested_dataset_kind: TraceExportDatasetKind,
    purpose: &str,
    now: DateTime<Utc>,
) -> ApiResult<()> {
    if grant.status != TraceExportGrantStatus::Active {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            format!(
                "{} export grant is not active",
                requested_dataset_kind.label()
            ),
        ));
    }
    if grant.expires_at <= now {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            format!("{} export grant is expired", requested_dataset_kind.label()),
        ));
    }
    if grant.tenant_id != tenant.tenant_id {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            format!(
                "{} export grant does not belong to the authenticated tenant",
                requested_dataset_kind.label()
            ),
        ));
    }
    if grant.caller_principal_ref != tenant.principal_ref {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            format!(
                "{} export grant does not belong to the authenticated principal",
                requested_dataset_kind.label()
            ),
        ));
    }
    if grant.requested_dataset_kind != requested_dataset_kind {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            format!(
                "{} export grant was issued for a different dataset kind",
                requested_dataset_kind.label()
            ),
        ));
    }
    if grant.purpose != purpose {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            format!(
                "{} export grant purpose does not match the request",
                requested_dataset_kind.label()
            ),
        ));
    }
    if grant.max_item_cap == 0 {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            format!(
                "{} export grant has no remaining item capacity",
                requested_dataset_kind.label()
            ),
        ));
    }
    Ok(())
}

fn enforce_dataset_export_guardrails(
    state: &AppState,
    export_kind: &str,
    purpose: Option<&str>,
    status: Option<TraceCorpusStatus>,
    privacy_risk: Option<ResidualPiiRisk>,
    consent_scope: Option<ConsentScope>,
) -> ApiResult<()> {
    if !state.require_export_guardrails {
        return Ok(());
    }

    if purpose
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .is_none()
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("{export_kind} export requires an explicit purpose"),
        ));
    }
    if status != Some(TraceCorpusStatus::Accepted) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("{export_kind} export requires status=accepted"),
        ));
    }
    if privacy_risk != Some(ResidualPiiRisk::Low) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("{export_kind} export requires privacy_risk=low"),
        ));
    }
    if consent_scope.is_none() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("{export_kind} export requires an explicit consent_scope"),
        ));
    }

    Ok(())
}

fn enforce_ranker_export_guardrails(
    state: &AppState,
    purpose: Option<&str>,
    status: Option<TraceCorpusStatus>,
    privacy_risk: Option<ResidualPiiRisk>,
    consent_scope: Option<ConsentScope>,
) -> ApiResult<()> {
    if !state.require_export_guardrails {
        return Ok(());
    }

    if purpose
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .is_none()
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranker training export requires an explicit purpose",
        ));
    }
    if status != Some(TraceCorpusStatus::Accepted) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranker training export requires status=accepted",
        ));
    }
    if privacy_risk != Some(ResidualPiiRisk::Low) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranker training export requires privacy_risk=low",
        ));
    }
    if consent_scope.is_none() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranker training export requires explicit ranking-training or model-training consent_scope",
        ));
    }

    Ok(())
}

fn parse_consent_scope_filter(value: Option<&str>) -> ApiResult<Option<ConsentScope>> {
    let Some(value) = value.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    let scope = match value {
        "debugging_evaluation" | "debugging-evaluation" => ConsentScope::DebuggingEvaluation,
        "benchmark_only" | "benchmark-only" => ConsentScope::BenchmarkOnly,
        "ranking_training" | "ranking-training" => ConsentScope::RankingTraining,
        "model_training" | "model-training" => ConsentScope::ModelTraining,
        _ => {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                format!("unsupported consent_scope filter: {value}"),
            ));
        }
    };
    Ok(Some(scope))
}

fn validate_envelope(envelope: &TraceContributionEnvelope) -> ApiResult<()> {
    if envelope.schema_version != TRACE_CONTRIBUTION_SCHEMA_VERSION {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "unsupported trace contribution schema version",
        ));
    }
    if !envelope.consent.revocable {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "trace contribution consent must be revocable",
        ));
    }
    if envelope
        .contributor
        .pseudonymous_contributor_id
        .as_deref()
        .unwrap_or_default()
        .trim()
        .is_empty()
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "trace contribution requires a pseudonymous contributor id",
        ));
    }
    // Contributor-supplied confidence aggregates. They already reach a tag on
    // the corpus, so an out-of-range value would propagate rather than sit
    // inert; reject at the boundary instead of teaching every later consumer
    // to distrust the range.
    if let Some(training_dynamics) = &envelope.training_dynamics
        && let Some(field) = training_dynamics.validation_error()
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("trace contribution training dynamics {field} must be between 0.0 and 1.0"),
        ));
    }
    Ok(())
}

fn ensure_not_revoked_by_tombstone(
    tombstones: &[TraceCommonsRevocation],
    submission_id: Uuid,
    redaction_hash: &str,
    canonical_summary_hash: &str,
) -> ApiResult<()> {
    let redaction_hash = redaction_hash.trim();
    let canonical_summary_hash = canonical_summary_hash.trim();
    let revoked_match = tombstones.iter().any(|tombstone| {
        tombstone.submission_id == submission_id
            || (!redaction_hash.is_empty()
                && tombstone.redaction_hash.as_deref() == Some(redaction_hash))
            || tombstone.canonical_summary_hash.as_deref() == Some(canonical_summary_hash)
    });
    if revoked_match {
        return Err(api_error(
            StatusCode::CONFLICT,
            "trace content was previously revoked for this tenant",
        ));
    }
    Ok(())
}

fn redaction_hash_for_record(
    state: &AppState,
    record: &TraceCommonsSubmissionRecord,
) -> Option<String> {
    match read_envelope_by_record(state, record) {
        Ok(envelope) => Some(envelope.privacy.redaction_hash),
        Err(error) => {
            tracing::warn!(
                error_hash = %safe_display_error_hash(&error),
                submission_id = %record.submission_id,
                "Trace Commons revocation could not read stored envelope redaction hash"
            );
            None
        }
    }
}

async fn tenant_submission_policy_for_request(
    state: &AppState,
    tenant: &TenantAuth,
) -> ApiResult<Option<TenantSubmissionPolicy>> {
    if state.db_tenant_policy_reads_for_tenant(&tenant.tenant_id) {
        let db = state
            .db_mirror
            .as_ref()
            .ok_or_else(|| internal_error("DB tenant policy reads require DB mirror"))?;
        let policy = db
            .get_trace_tenant_policy(&tenant.tenant_id)
            .await
            .map_err(internal_error)?;
        return policy
            .map(tenant_submission_policy_from_storage)
            .transpose()
            .map_err(internal_error);
    }

    Ok(state.tenant_policies.get(&tenant.tenant_id).cloned())
}

fn tenant_submission_policy_from_storage(
    policy: StorageTraceTenantPolicyRecord,
) -> anyhow::Result<TenantSubmissionPolicy> {
    Ok(TenantSubmissionPolicy {
        allowed_consent_scopes: parse_storage_policy_values(
            &policy.allowed_consent_scopes,
            "allowed_consent_scopes",
        )?,
        allowed_uses: parse_storage_policy_values(&policy.allowed_uses, "allowed_uses")?,
    })
}

fn parse_storage_policy_values<T>(values: &[String], label: &str) -> anyhow::Result<BTreeSet<T>>
where
    T: for<'de> Deserialize<'de> + Ord,
{
    values
        .iter()
        .map(|value| {
            serde_json::from_value::<T>(serde_json::Value::String(value.clone()))
                .with_context(|| format!("failed to parse trace tenant policy {label} value"))
        })
        .collect()
}

fn enforce_signed_claim_submission_restrictions(
    tenant: &TenantCtx,
    envelope: &TraceContributionEnvelope,
) -> ApiResult<()> {
    if !tenant.allowed_consent_scopes().is_empty() {
        let mut requested_scopes = envelope
            .consent
            .scopes
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        requested_scopes.insert(envelope.trace_card.consent_scope);
        if let Some(scope) = requested_scopes
            .iter()
            .find(|scope| !tenant.allowed_consent_scopes().contains(scope))
        {
            tracing::warn!(
                tenant_id = %tenant.tenant_id(),
                ?scope,
                "Trace Commons signed token rejected disallowed consent scope"
            );
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "signed tenant token does not allow this trace contribution consent scope",
            ));
        }
    }

    if !tenant.allowed_uses().is_empty() {
        if envelope.trace_card.allowed_uses.is_empty() {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "signed tenant token requires trace contribution allowed uses",
            ));
        }
        if let Some(allowed_use) = envelope
            .trace_card
            .allowed_uses
            .iter()
            .find(|allowed_use| !tenant.allowed_uses().contains(allowed_use))
        {
            tracing::warn!(
                tenant_id = %tenant.tenant_id(),
                ?allowed_use,
                "Trace Commons signed token rejected disallowed allowed use"
            );
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "signed tenant token does not allow this trace contribution allowed use",
            ));
        }
    }

    Ok(())
}

async fn authorize_tenant_access_grant_ctx(
    state: &AppState,
    tenant: TenantCtx,
) -> ApiResult<TenantCtx> {
    authorize_tenant_access_grant(state, tenant.auth)
        .await
        .map(TenantCtx::from_auth)
}

async fn authorize_tenant_access_grant(
    state: &AppState,
    mut auth: TenantAuth,
) -> ApiResult<TenantAuth> {
    if !state.require_tenant_access_grants {
        return Ok(auth);
    }
    let db = state
        .db_mirror
        .as_ref()
        .ok_or_else(|| internal_error("tenant access grant enforcement requires DB mirror"))?;
    let mut grants = Vec::new();
    for principal_ref in auth.principal_aliases() {
        let matched = db
            .list_active_trace_tenant_access_grants_for_principal(
                &auth.tenant_id,
                principal_ref,
                Utc::now(),
            )
            .await
            .map_err(internal_error)?;
        for grant in matched {
            if grants
                .iter()
                .all(|existing: &StorageTraceTenantAccessGrantRecord| {
                    existing.grant_id != grant.grant_id
                })
            {
                grants.push(grant);
            }
        }
    }
    let expected_role = trace_tenant_access_grant_role_for_token(auth.role);
    let matching_grants = grants
        .iter()
        .filter(|grant| grant.role == expected_role)
        .filter(|grant| tenant_access_grant_matches_signed_claim_binding(&auth, grant))
        .collect::<Vec<_>>();
    if matching_grants.is_empty() {
        tracing::warn!(
            tenant_id = %auth.tenant_id,
            principal_ref = %auth.principal_ref,
            role = auth.role.storage_name(),
            "Trace Commons rejected request without active tenant access grant binding"
        );
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "active tenant access grant required",
        ));
    }

    for grant in matching_grants {
        apply_tenant_access_grant_scope(&mut auth, grant)?;
    }
    Ok(auth)
}

fn tenant_access_grant_matches_signed_claim_binding(
    auth: &TenantAuth,
    grant: &StorageTraceTenantAccessGrantRecord,
) -> bool {
    if auth.auth_method != TraceAuthMethod::SignedClaim {
        return true;
    }
    if let Some(issuer) = grant.issuer.as_deref().and_then(non_empty_trimmed)
        && auth.signed_claim_issuer.as_deref() != Some(issuer)
    {
        return false;
    }
    if let Some(audience) = grant.audience.as_deref().and_then(non_empty_trimmed)
        && !auth.signed_claim_audiences.contains(audience)
    {
        return false;
    }
    if let Some(subject) = grant.subject.as_deref().and_then(non_empty_trimmed)
        && auth.signed_claim_subject.as_deref() != Some(subject)
    {
        return false;
    }
    true
}

fn non_empty_trimmed(value: &str) -> Option<&str> {
    let value = value.trim();
    (!value.is_empty()).then_some(value)
}

fn trace_tenant_access_grant_role_for_token(role: TokenRole) -> StorageTraceTenantAccessGrantRole {
    match role {
        TokenRole::Contributor => StorageTraceTenantAccessGrantRole::Contributor,
        TokenRole::Reviewer => StorageTraceTenantAccessGrantRole::Reviewer,
        TokenRole::Admin => StorageTraceTenantAccessGrantRole::Admin,
        TokenRole::ExportWorker => StorageTraceTenantAccessGrantRole::ExportWorker,
        TokenRole::RetentionWorker => StorageTraceTenantAccessGrantRole::RetentionWorker,
        TokenRole::VectorWorker => StorageTraceTenantAccessGrantRole::VectorWorker,
        TokenRole::BenchmarkWorker => StorageTraceTenantAccessGrantRole::BenchmarkWorker,
        TokenRole::UtilityWorker => StorageTraceTenantAccessGrantRole::UtilityWorker,
        TokenRole::ProcessEvalWorker => StorageTraceTenantAccessGrantRole::ProcessEvalWorker,
        TokenRole::RevocationWorker => StorageTraceTenantAccessGrantRole::RevocationWorker,
        TokenRole::CompetitionReadWorker => {
            StorageTraceTenantAccessGrantRole::CompetitionReadWorker
        }
        TokenRole::RegisterStatsWorker => StorageTraceTenantAccessGrantRole::RegisterStatsWorker,
    }
}

fn apply_tenant_access_grant_scope(
    auth: &mut TenantAuth,
    grant: &StorageTraceTenantAccessGrantRecord,
) -> ApiResult<()> {
    let grant_scopes = parse_storage_policy_values::<ConsentScope>(
        &grant.allowed_consent_scopes,
        "tenant_access_grant.allowed_consent_scopes",
    )
    .map_err(internal_error)?;
    restrict_effective_allowlist(
        &mut auth.allowed_consent_scopes,
        grant_scopes,
        "tenant access grant consent scope intersection is empty",
    )?;

    let grant_uses = parse_storage_policy_values::<TraceAllowedUse>(
        &grant.allowed_uses,
        "tenant_access_grant.allowed_uses",
    )
    .map_err(internal_error)?;
    restrict_effective_allowlist(
        &mut auth.allowed_uses,
        grant_uses,
        "tenant access grant allowed-use intersection is empty",
    )
}

fn restrict_effective_allowlist<T>(
    current: &mut BTreeSet<T>,
    grant_values: BTreeSet<T>,
    empty_message: &'static str,
) -> ApiResult<()>
where
    T: Ord + Clone,
{
    if grant_values.is_empty() {
        return Ok(());
    }
    if current.is_empty() {
        *current = grant_values;
        return Ok(());
    }
    *current = current.intersection(&grant_values).cloned().collect();
    if current.is_empty() {
        return Err(api_error(StatusCode::FORBIDDEN, empty_message));
    }
    Ok(())
}

fn enforce_tenant_submission_policy(
    tenant: &TenantAuth,
    envelope: &TraceContributionEnvelope,
    policy: Option<&TenantSubmissionPolicy>,
    require_policy: bool,
) -> ApiResult<()> {
    let Some(policy) = policy else {
        if require_policy {
            tracing::warn!(
                tenant_id = %tenant.tenant_id,
                "Trace Commons tenant policy rejected submission without tenant policy"
            );
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "trace contribution tenant does not have a submission policy",
            ));
        }
        return Ok(());
    };

    if !policy.allowed_consent_scopes.is_empty() {
        let mut requested_scopes = envelope
            .consent
            .scopes
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        requested_scopes.insert(envelope.trace_card.consent_scope);
        if requested_scopes.is_empty() {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "tenant policy requires an allowed trace contribution consent scope",
            ));
        }
        if let Some(scope) = requested_scopes
            .iter()
            .find(|scope| !policy.allowed_consent_scopes.contains(scope))
        {
            tracing::warn!(
                tenant_id = %tenant.tenant_id,
                ?scope,
                "Trace Commons tenant policy rejected disallowed consent scope"
            );
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "trace contribution consent scope is not allowed for this tenant",
            ));
        }
    }

    if !policy.allowed_uses.is_empty() {
        if envelope.trace_card.allowed_uses.is_empty() {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "tenant policy requires trace contribution allowed uses",
            ));
        }
        if let Some(allowed_use) = envelope
            .trace_card
            .allowed_uses
            .iter()
            .find(|allowed_use| !policy.allowed_uses.contains(allowed_use))
        {
            tracing::warn!(
                tenant_id = %tenant.tenant_id,
                ?allowed_use,
                "Trace Commons tenant policy rejected disallowed allowed use"
            );
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "trace contribution allowed use is not allowed for this tenant",
            ));
        }
    }

    Ok(())
}

fn enforce_submission_quota(state: &AppState, tenant: &TenantCtx) -> ApiResult<()> {
    let quota = state.submission_quota;
    if quota.is_disabled() || tenant.role() != TokenRole::Contributor {
        return Ok(());
    }

    let window_start = Utc::now() - Duration::hours(1);
    let records =
        read_all_submission_records(&state.root, tenant.tenant_id()).map_err(internal_error)?;
    if quota.max_per_tenant_per_hour > 0 {
        let tenant_count = records
            .iter()
            .filter(|record| submission_counts_toward_quota(record))
            .filter(|record| record.received_at >= window_start)
            .count();
        if tenant_count >= quota.max_per_tenant_per_hour {
            tracing::warn!(
                tenant_id = %tenant.tenant_id(),
                limit = quota.max_per_tenant_per_hour,
                "Trace Commons tenant submission quota exceeded"
            );
            return Err(api_error(
                StatusCode::TOO_MANY_REQUESTS,
                "trace contribution tenant submission quota exceeded",
            ));
        }
    }

    if quota.max_per_principal_per_hour > 0 {
        let principal_count = records
            .iter()
            .filter(|record| submission_counts_toward_quota(record))
            .filter(|record| {
                tenant
                    .auth()
                    .matches_stored_principal(&record.auth_principal_ref)
                    && record.received_at >= window_start
            })
            .count();
        if principal_count >= quota.max_per_principal_per_hour {
            tracing::warn!(
                tenant_id = %tenant.tenant_id(),
                principal_ref = %tenant.principal_ref(),
                limit = quota.max_per_principal_per_hour,
                "Trace Commons principal submission quota exceeded"
            );
            return Err(api_error(
                StatusCode::TOO_MANY_REQUESTS,
                "trace contribution principal submission quota exceeded",
            ));
        }
    }

    Ok(())
}

fn submission_counts_toward_quota(record: &TraceCommonsSubmissionRecord) -> bool {
    matches!(
        record.status,
        TraceCorpusStatus::Accepted | TraceCorpusStatus::Quarantined
    )
}

async fn tenant_export_policy_for_request(
    state: &AppState,
    tenant: &TenantAuth,
    surface: &str,
    requested_scope: Option<ConsentScope>,
    required_use: TraceAllowedUse,
) -> ApiResult<Option<TenantSubmissionPolicy>> {
    let policy = tenant_submission_policy_for_request(state, tenant).await?;
    enforce_scoped_token_export_policy(tenant, surface, requested_scope, required_use)?;
    enforce_tenant_export_policy(
        tenant,
        surface,
        policy.as_ref(),
        state.require_tenant_submission_policy,
        requested_scope,
        required_use,
    )?;
    Ok(policy)
}

async fn tenant_process_evaluation_policy_for_request(
    state: &AppState,
    tenant: &TenantAuth,
) -> ApiResult<Option<TenantSubmissionPolicy>> {
    let policy = tenant_submission_policy_for_request(state, tenant).await?;
    enforce_scoped_token_required_use(tenant, "process evaluation", TraceAllowedUse::Evaluation)?;
    enforce_tenant_process_evaluation_policy(
        tenant,
        policy.as_ref(),
        state.require_tenant_submission_policy,
    )?;
    Ok(policy)
}

