fn trace_commons_record_from_storage_submission(
    record: StorageTraceSubmissionRecord,
) -> Option<anyhow::Result<TraceCommonsSubmissionRecord>> {
    let status = trace_corpus_status_from_storage(record.status)?;
    Some((|| {
        let object_key = trace_envelope_object_key(&record.tenant_id, status, record.submission_id);
        Ok(TraceCommonsSubmissionRecord {
            tenant_storage_ref: tenant_storage_ref(&record.tenant_id),
            tenant_id: record.tenant_id,
            auth_principal_ref: record.auth_principal_ref,
            submitted_tenant_scope_ref: record.submitted_tenant_scope_ref,
            contributor_pseudonym: record.contributor_pseudonym,
            submission_id: record.submission_id,
            trace_id: record.trace_id,
            status,
            privacy_risk: storage_string_as(&record.privacy_risk, "privacy_risk")?,
            submission_score: record.submission_score.unwrap_or(0.0),
            credit_points_pending: record.credit_points_pending.unwrap_or(0.0),
            credit_points_final: record.credit_points_final,
            consent_scopes: record
                .consent_scopes
                .iter()
                .map(|scope| storage_string_as(scope, "consent_scope"))
                .collect::<anyhow::Result<Vec<_>>>()?,
            allowed_uses: record
                .allowed_uses
                .iter()
                .map(|allowed_use| storage_string_as(allowed_use, "allowed_use"))
                .collect::<anyhow::Result<Vec<_>>>()?,
            redaction_counts: record.redaction_counts,
            received_at: record.received_at,
            review_assigned_to_principal_ref: record.review_assigned_to_principal_ref,
            review_assigned_at: record.review_assigned_at,
            review_lease_expires_at: record.review_lease_expires_at,
            review_due_at: record.review_due_at,
            retention_policy_id: record.retention_policy_id,
            expires_at: record.expires_at,
            purged_at: record.purged_at,
            last_status_reason: record.last_status_reason,
            residual_risk_basis: record.residual_risk_basis,
            object_key,
            artifact_receipt: None,
            artifact_object_store: None,
        })
    })())
}

fn trace_commons_audit_event_from_storage(
    expected_tenant_id: &str,
    event: StorageTraceAuditEventRecord,
) -> anyhow::Result<TraceCommonsAuditEvent> {
    anyhow::ensure!(
        event.tenant_id == expected_tenant_id,
        "DB audit event tenant mismatch"
    );
    ensure_db_audit_canonical_projection_matches(&event)?;
    let mut kind = storage_audit_event_kind(event.action, &event.metadata);
    if event.action == StorageTraceAuditAction::Read
        && event.submission_id.is_some()
        && event
            .reason
            .as_deref()
            .is_some_and(|reason| reason.contains("surface=replay_dataset_export"))
    {
        kind = "trace_content_read".to_string();
    }
    if event.action == StorageTraceAuditAction::Read
        && trace_audit_reason_is_rollout_smoke_evidence(event.reason.as_deref())
    {
        kind = "rollout_smoke_evidence".to_string();
    }
    if event.action == StorageTraceAuditAction::CreditMutate
        && trace_audit_reason_is_credit_settlement_issuer_approval(event.reason.as_deref())
    {
        kind = "credit_settlement_issuer_approval".to_string();
    }
    let (status, reason, export_count) = match &event.metadata {
        StorageTraceAuditSafeMetadata::Submission {
            status,
            privacy_risk: _,
        } => (
            trace_corpus_status_from_storage(*status),
            event.reason.clone(),
            None,
        ),
        StorageTraceAuditSafeMetadata::ReviewDecision {
            decision: _,
            resulting_status,
            reason_code,
        } => (
            trace_corpus_status_from_storage(*resulting_status),
            reason_code.clone().or_else(|| event.reason.clone()),
            None,
        ),
        StorageTraceAuditSafeMetadata::ReviewLease {
            action,
            lease_expires_at,
            review_due_at,
        } => (
            Some(TraceCorpusStatus::Quarantined),
            event.reason.clone().or_else(|| {
                Some(trace_review_lease_reason(
                    *action,
                    lease_expires_at.to_owned(),
                    review_due_at.to_owned(),
                ))
            }),
            None,
        ),
        StorageTraceAuditSafeMetadata::TraceContentRead {
            surface,
            purpose_hash,
        } => (
            None,
            Some(trace_content_read_audit_reason(
                surface,
                purpose_hash.as_deref(),
            )),
            None,
        ),
        StorageTraceAuditSafeMetadata::Read {
            surface,
            item_count,
        } => (
            None,
            Some(trace_read_audit_reason(surface, *item_count as usize)),
            Some(*item_count as usize),
        ),
        StorageTraceAuditSafeMetadata::Revocation { reason_hash: _ } => (
            Some(TraceCorpusStatus::Revoked),
            event.reason.clone(),
            None,
        ),
        StorageTraceAuditSafeMetadata::Export {
            artifact_kind: _,
            purpose_code,
            item_count,
        } => (
            None,
            event.reason.clone().or_else(|| purpose_code.clone()),
            Some(*item_count as usize),
        ),
        StorageTraceAuditSafeMetadata::Maintenance {
            surface: _,
            purpose_hash: _,
            dry_run,
            action_counts,
        } => (
            None,
            storage_maintenance_audit_reason(&event).or_else(|| {
                Some(trace_maintenance_audit_reason(None, *dry_run, action_counts))
            }),
            Some(
                action_counts
                    .values()
                    .copied()
                    .map(|count| count as usize)
                    .sum(),
            ),
        ),
        StorageTraceAuditSafeMetadata::CreditMutation {
            event_type: _,
            credit_points_delta_micros: _,
            reason_hash: _,
            external_ref_hash: _,
        } => (None, event.reason.clone(), None),
        StorageTraceAuditSafeMetadata::CreditSettlementIssuerApproval {
            policy_version,
            source_list_hash,
            evidence_hash,
            reason_hash,
            evidence_ref_hash,
        } => (
            None,
            event.reason.clone().or_else(|| {
                Some(
                    trace_credit_settlement_issuer_approval_audit_reason_from_parts(
                        policy_version,
                        source_list_hash,
                        evidence_hash,
                        reason_hash,
                        evidence_ref_hash.as_deref(),
                    ),
                )
            }),
            None,
        ),
        StorageTraceAuditSafeMetadata::CreditHold {
            action,
            hold_id,
            credit_account_hash,
            hold_reason,
            reason_hash,
        } => (
            None,
            event.reason.clone().or_else(|| {
                Some(trace_credit_hold_audit_reason_from_parts(
                    *action,
                    *hold_id,
                    credit_account_hash,
                    *hold_reason,
                    reason_hash,
                ))
            }),
            None,
        ),
        StorageTraceAuditSafeMetadata::NearCreditOutboxStatus {
            near_outbox_id,
            settlement_batch_id,
            credit_account_hash,
            status,
            near_transaction_hash_hash,
            last_error_hash,
        } => (
            None,
            event.reason.clone().or_else(|| {
                Some(trace_near_credit_outbox_status_audit_reason_from_parts(
                    *near_outbox_id,
                    *settlement_batch_id,
                    credit_account_hash,
                    *status,
                    near_transaction_hash_hash.as_deref(),
                    last_error_hash.as_deref(),
                ))
            }),
            None,
        ),
        StorageTraceAuditSafeMetadata::BenchmarkRegistryOutboxStatus {
            benchmark_outbox_id,
            conversion_id,
            operation,
            registry_ref_hash,
            artifact_payload_hash,
            source_submission_ids_hash,
            evaluator_ref_hash,
            status,
            external_receipt_ref_hash,
            last_error_hash,
        } => (
            None,
            event.reason.clone().or_else(|| {
                Some(trace_benchmark_registry_outbox_status_audit_reason_from_parts(
                    TraceBenchmarkRegistryOutboxStatusAuditReasonParts {
                        benchmark_outbox_id: *benchmark_outbox_id,
                        conversion_id: *conversion_id,
                        operation: *operation,
                        registry_ref_hash,
                        artifact_payload_hash,
                        source_submission_ids_hash,
                        evaluator_ref_hash: evaluator_ref_hash.as_deref(),
                        status: *status,
                        external_receipt_ref_hash: external_receipt_ref_hash.as_deref(),
                        last_error_hash: last_error_hash.as_deref(),
                    },
                ))
            }),
            None,
        ),
        StorageTraceAuditSafeMetadata::ProcessEvaluation {
            evaluator_version_hash: _,
            label_count: _,
            rating_counts: _,
            score_band: _,
            utility_credit_delta_micros: _,
            utility_external_ref_hash: _,
        } => (None, event.reason.clone(), None),
        StorageTraceAuditSafeMetadata::TenantPolicy {
            policy_version: _,
            allowed_consent_scope_count: _,
            allowed_use_count: _,
            policy_projection_hash: _,
        } => (None, event.reason.clone(), None),
        StorageTraceAuditSafeMetadata::TenantAccessGrant {
            action: _,
            role: _,
            status: _,
            allowed_consent_scope_count: _,
            allowed_use_count: _,
            grant_projection_hash: _,
        } => (None, event.reason.clone(), None),
        StorageTraceAuditSafeMetadata::ExportJobRecovery {
            export_job_id,
            recovered_status,
            reason_hash,
        } => (
            None,
            Some(export_job_recovery_audit_reason(
                *export_job_id,
                *recovered_status,
                reason_hash,
            )),
            None,
        ),
        StorageTraceAuditSafeMetadata::RankingWorkerRunRecovery {
            ranking_worker_run_id,
            run_kind,
            recovered_status,
            reason_hash,
        } => (
            None,
            Some(ranking_worker_run_recovery_audit_reason(
                *ranking_worker_run_id,
                *run_kind,
                *recovered_status,
                reason_hash,
            )),
            None,
        ),
        StorageTraceAuditSafeMetadata::RankingCalibrationDatasetQuarantine {
            calibration_dataset_hash: _,
            target_use: _,
            policy_version: _,
            archived_source_manifest_hash,
            conflict_key_hash,
            reason_hash,
        } => (
            None,
            event.reason.clone().or_else(|| {
                Some(format!(
                    "conflict_key_hash={conflict_key_hash};reason_hash={reason_hash};archived_source_manifest_hash={archived_source_manifest_hash}"
                ))
            }),
            None,
        ),
        StorageTraceAuditSafeMetadata::RevocationPropagationFailure { .. } => {
            (None, event.reason.clone(), None)
        }
        StorageTraceAuditSafeMetadata::Empty => (None, event.reason.clone(), None),
    };
    Ok(TraceCommonsAuditEvent {
        event_id: event.audit_event_id,
        tenant_id: event.tenant_id,
        submission_id: event.submission_id.unwrap_or_else(Uuid::nil),
        kind,
        created_at: event.occurred_at,
        status,
        actor_role: TokenRole::parse(&event.actor_role).ok(),
        actor_principal_ref: Some(event.actor_principal_ref),
        reason,
        export_count,
        export_id: event.export_manifest_id,
        decision_inputs_hash: event.decision_inputs_hash,
        previous_event_hash: event.previous_event_hash,
        event_hash: event.event_hash,
    })
}

fn ensure_db_audit_canonical_projection_matches(
    event: &StorageTraceAuditEventRecord,
) -> anyhow::Result<()> {
    let Some(canonical_event_json) = event.canonical_event_json.as_deref() else {
        return Ok(());
    };
    let canonical_event: TraceCommonsAuditEvent = serde_json::from_str(canonical_event_json)
        .with_context(|| {
            format!(
                "failed to parse canonical audit payload for DB audit event {}",
                event.audit_event_id
            )
        })?;
    let mut report = TraceDbAuditChainReport::default();
    verify_db_audit_projection(1, event, &canonical_event, &mut report);
    if let Some(failure) = report.failures.first() {
        anyhow::bail!("DB audit event canonical projection mismatch: {failure}");
    }
    Ok(())
}

fn collect_db_audit_canonical_projection_failures(
    events: &[StorageTraceAuditEventRecord],
) -> Vec<TraceDbAuditProjectionFailure> {
    events
        .iter()
        .enumerate()
        .filter_map(|(index, event)| {
            let canonical_event_json = event.canonical_event_json.as_deref()?;
            let row_number = index + 1;
            let canonical_event: TraceCommonsAuditEvent =
                match serde_json::from_str(canonical_event_json) {
                    Ok(canonical_event) => canonical_event,
                    Err(_) => {
                        return Some(TraceDbAuditProjectionFailure {
                            audit_event_id: event.audit_event_id,
                            failure_count: 1,
                            first_failure: format!(
                                "db row {row_number} event {}: canonical payload parse failed",
                                event.audit_event_id
                            ),
                        });
                    }
                };
            let mut report = TraceDbAuditChainReport::default();
            verify_db_audit_projection(row_number, event, &canonical_event, &mut report);
            report
                .failures
                .first()
                .map(|first_failure| TraceDbAuditProjectionFailure {
                    audit_event_id: event.audit_event_id,
                    failure_count: report.failures.len(),
                    first_failure: first_failure.clone(),
                })
        })
        .collect()
}

fn collect_db_audit_submission_metadata_mismatches(
    events: &[StorageTraceAuditEventRecord],
    db_by_submission: &BTreeMap<Uuid, &StorageTraceSubmissionRecord>,
) -> Vec<TraceDbAuditSubmissionMetadataMismatch> {
    events
        .iter()
        .filter_map(|event| {
            let StorageTraceAuditSafeMetadata::Submission {
                privacy_risk: metadata_privacy_risk,
                ..
            } = &event.metadata
            else {
                return None;
            };
            let submission_id = event.submission_id?;
            let db_record = db_by_submission.get(&submission_id)?;
            (metadata_privacy_risk != &db_record.privacy_risk).then(|| {
                TraceDbAuditSubmissionMetadataMismatch {
                    audit_event_id: event.audit_event_id,
                    submission_id,
                    metadata_privacy_risk: metadata_privacy_risk.clone(),
                    db_privacy_risk: db_record.privacy_risk.clone(),
                }
            })
        })
        .collect()
}

fn collect_db_audit_hash_chain_failures(
    events: &[StorageTraceAuditEventRecord],
) -> Vec<TraceDbAuditHashChainFailure> {
    let mut failures = Vec::new();
    let mut expected_previous_hash = TRACE_AUDIT_EVENT_GENESIS_HASH.to_string();
    for (index, event) in events.iter().enumerate() {
        let row_number = index + 1;
        let Some(event_hash) = event.event_hash.as_deref() else {
            // Legacy unhashed rows break the verifiable chain; restart from genesis
            // so the next hashed row must prove its own chain root.
            expected_previous_hash = TRACE_AUDIT_EVENT_GENESIS_HASH.to_string();
            continue;
        };
        let mut event_failures = Vec::new();
        if !is_canonical_sha256_prefixed_hash(event_hash) {
            event_failures.push(format!(
                "db row {row_number} event {}: event_hash has invalid format",
                event.audit_event_id
            ));
        }
        let previous_event_hash = event
            .previous_event_hash
            .as_deref()
            .unwrap_or(TRACE_AUDIT_EVENT_GENESIS_HASH);
        if !is_audit_chain_previous_hash(previous_event_hash) {
            event_failures.push(format!(
                "db row {row_number} event {}: previous_event_hash has invalid format",
                event.audit_event_id
            ));
        }
        if previous_event_hash != expected_previous_hash {
            event_failures.push(format!(
                "db row {row_number} event {}: previous_event_hash mismatch",
                event.audit_event_id
            ));
        }
        if let Some(canonical_event_json) = event.canonical_event_json.as_deref() {
            let recomputed =
                compute_audit_event_hash_from_canonical(previous_event_hash, canonical_event_json);
            if recomputed != event_hash {
                event_failures.push(format!(
                    "db row {row_number} event {}: canonical payload hash mismatch",
                    event.audit_event_id
                ));
            }
        }
        if let Some(first_failure) = event_failures.first() {
            failures.push(TraceDbAuditHashChainFailure {
                audit_event_id: event.audit_event_id,
                failure_count: event_failures.len(),
                first_failure: first_failure.clone(),
            });
        }
        expected_previous_hash = event_hash.to_string();
    }
    failures
}

fn storage_audit_event_kind(
    action: StorageTraceAuditAction,
    metadata: &StorageTraceAuditSafeMetadata,
) -> String {
    if let StorageTraceAuditAction::Export = action
        && let StorageTraceAuditSafeMetadata::Export {
            purpose_code: Some(purpose_code),
            ..
        } = metadata
        && matches!(
            purpose_code.as_str(),
            "ranker_training_candidates_export" | "ranker_training_pairs_export"
        )
    {
        return purpose_code.clone();
    }
    if let StorageTraceAuditAction::BenchmarkConvert = action
        && let StorageTraceAuditSafeMetadata::Export {
            purpose_code: Some(purpose_code),
            ..
        } = metadata
        && purpose_code == "benchmark_lifecycle_update"
    {
        return purpose_code.clone();
    }
    if let StorageTraceAuditAction::Review = action
        && matches!(metadata, StorageTraceAuditSafeMetadata::ReviewLease { .. })
    {
        return "review_lease".to_string();
    }
    if let StorageTraceAuditAction::CreditMutate = action
        && matches!(
            metadata,
            StorageTraceAuditSafeMetadata::CreditSettlementIssuerApproval { .. }
        )
    {
        return "credit_settlement_issuer_approval".to_string();
    }
    if let StorageTraceAuditAction::CreditMutate = action
        && let StorageTraceAuditSafeMetadata::CreditHold { action, .. } = metadata
    {
        return match action {
            StorageTraceCreditHoldAuditAction::Placed => "credit_hold",
            StorageTraceCreditHoldAuditAction::Released => "credit_hold_release",
        }
        .to_string();
    }
    if let StorageTraceAuditAction::CreditMutate = action
        && matches!(
            metadata,
            StorageTraceAuditSafeMetadata::NearCreditOutboxStatus { .. }
        )
    {
        return "near_credit_outbox_status".to_string();
    }
    if let StorageTraceAuditAction::BenchmarkConvert = action
        && matches!(
            metadata,
            StorageTraceAuditSafeMetadata::BenchmarkRegistryOutboxStatus { .. }
        )
    {
        return "benchmark_registry_outbox_status".to_string();
    }
    if let StorageTraceAuditSafeMetadata::Maintenance {
        surface: Some(surface),
        ..
    } = metadata
    {
        return surface.clone();
    }
    if let StorageTraceAuditAction::Read = action
        && matches!(
            metadata,
            StorageTraceAuditSafeMetadata::TraceContentRead { .. }
        )
    {
        return "trace_content_read".to_string();
    }
    if let StorageTraceAuditAction::PolicyUpdate = action
        && matches!(
            metadata,
            StorageTraceAuditSafeMetadata::TenantAccessGrant { .. }
        )
    {
        return "tenant_access_grant_update".to_string();
    }
    storage_audit_action_kind(action).to_string()
}

fn storage_audit_action_kind(action: StorageTraceAuditAction) -> &'static str {
    match action {
        StorageTraceAuditAction::Submit => "submitted",
        StorageTraceAuditAction::Read => "read",
        StorageTraceAuditAction::Review => "review_decision",
        StorageTraceAuditAction::CreditMutate => "credit_mutate",
        StorageTraceAuditAction::Revoke => "revoked",
        StorageTraceAuditAction::Export => "dataset_export",
        StorageTraceAuditAction::Retain => "retain",
        StorageTraceAuditAction::Purge => "purge",
        StorageTraceAuditAction::VectorIndex => "vector_index",
        StorageTraceAuditAction::BenchmarkConvert => "benchmark_conversion",
        StorageTraceAuditAction::ProcessEvaluate => "process_evaluation",
        StorageTraceAuditAction::PolicyUpdate => "tenant_policy_update",
        StorageTraceAuditAction::ExportJobRecovery => "export_job_recovery",
        StorageTraceAuditAction::RankingWorkerRunRecovery => "ranking_worker_run_recovery",
        StorageTraceAuditAction::RankingCalibrationDatasetQuarantine => {
            "ranking_calibration_dataset_quarantine"
        }
    }
}

fn trace_commons_derived_record_from_storage(
    record: StorageTraceDerivedRecord,
    submission_metadata: &BTreeMap<Uuid, (TraceCorpusStatus, ResidualPiiRisk, String)>,
) -> Option<anyhow::Result<TraceCommonsDerivedRecord>> {
    let (submission_status, submission_privacy_risk, tenant_id) =
        submission_metadata.get(&record.submission_id)?;
    let status = match record.status {
        StorageTraceDerivedStatus::Current => *submission_status,
        StorageTraceDerivedStatus::Revoked => TraceCorpusStatus::Revoked,
        StorageTraceDerivedStatus::Expired => TraceCorpusStatus::Expired,
        StorageTraceDerivedStatus::Invalidated | StorageTraceDerivedStatus::Superseded => {
            return None;
        }
    };
    Some((|| {
        let privacy_risk = match record.privacy_risk.as_deref() {
            Some(raw) => storage_string_as(raw, "derived_privacy_risk")?,
            None => *submission_privacy_risk,
        };
        Ok(TraceCommonsDerivedRecord {
            tenant_storage_ref: tenant_storage_ref(tenant_id),
            tenant_id: tenant_id.clone(),
            derived_id: Some(record.derived_id),
            submission_id: record.submission_id,
            trace_id: record.trace_id,
            status,
            privacy_risk,
            task_success: record.task_success.unwrap_or_else(|| "unknown".to_string()),
            canonical_summary: record.canonical_summary.unwrap_or_default(),
            canonical_summary_hash: record.canonical_summary_hash.unwrap_or_default(),
            summary_model: record.summary_model,
            event_count: record
                .event_count
                .and_then(|value| usize::try_from(value).ok())
                .unwrap_or_default(),
            tool_sequence: record.tool_sequence,
            tool_categories: record.tool_categories,
            coverage_tags: record.coverage_tags,
            duplicate_score: record.duplicate_score.unwrap_or_default(),
            novelty_score: record.novelty_score.unwrap_or_default(),
            created_at: record.created_at,
        })
    })())
}

fn trace_commons_metadata_derived_records_from_storage(
    records: Vec<StorageTraceDerivedRecord>,
    submission_metadata: &BTreeMap<Uuid, (TraceCorpusStatus, ResidualPiiRisk, String)>,
) -> anyhow::Result<Vec<TraceCommonsDerivedRecord>> {
    let mut primary_by_submission = BTreeMap::<Uuid, StorageTraceDerivedRecord>::new();
    let mut fallback_by_submission = BTreeMap::<Uuid, StorageTraceDerivedRecord>::new();
    let mut process_tags_by_submission = BTreeMap::<Uuid, BTreeSet<String>>::new();

    for record in records {
        if record.status == StorageTraceDerivedStatus::Current
            && record.worker_kind == StorageTraceWorkerKind::ProcessEvaluation
        {
            process_tags_by_submission
                .entry(record.submission_id)
                .or_default()
                .extend(
                    record
                        .coverage_tags
                        .iter()
                        .filter(|tag| is_process_evaluation_coverage_tag(tag))
                        .cloned(),
                );
        }

        if record.worker_kind == StorageTraceWorkerKind::DuplicatePrecheck {
            primary_by_submission.insert(record.submission_id, record);
        } else {
            fallback_by_submission.insert(record.submission_id, record);
        }
    }

    for (submission_id, record) in fallback_by_submission {
        primary_by_submission.entry(submission_id).or_insert(record);
    }

    primary_by_submission
        .into_values()
        .filter_map(|record| {
            let submission_id = record.submission_id;
            trace_commons_derived_record_from_storage(record, submission_metadata).map(|result| {
                result.map(|mut derived| {
                    if let Some(process_tags) = process_tags_by_submission.get(&submission_id) {
                        let mut tags = derived.coverage_tags.into_iter().collect::<BTreeSet<_>>();
                        tags.extend(process_tags.iter().cloned());
                        derived.coverage_tags = tags.into_iter().collect();
                    }
                    derived
                })
            })
        })
        .collect()
}

fn is_process_evaluation_coverage_tag(tag: &str) -> bool {
    tag.starts_with("process_label:")
        || tag.starts_with("process_eval:")
        || tag
            .strip_prefix("process_")
            .and_then(|value| value.split_once(':'))
            .is_some()
}

fn trace_commons_credit_event_from_storage(
    event: StorageTraceCreditEventRecord,
    owner_principal_ref: &str,
) -> anyhow::Result<Option<TraceCommonsCreditLedgerRecord>> {
    let Some(event_type) = trace_credit_event_type_from_storage(event.event_type) else {
        return Ok(None);
    };
    let credit_points_delta = event.points_delta.parse::<f32>().with_context(|| {
        format!(
            "failed to parse trace credit points_delta for event {}",
            event.credit_event_id
        )
    })?;
    if !credit_points_delta.is_finite() {
        anyhow::bail!(
            "trace credit points_delta is not finite for event {}",
            event.credit_event_id
        );
    }
    Ok(Some(TraceCommonsCreditLedgerRecord {
        event_id: event.credit_event_id,
        tenant_storage_ref: tenant_storage_ref(&event.tenant_id),
        tenant_id: event.tenant_id,
        submission_id: event.submission_id,
        trace_id: event.trace_id,
        auth_principal_ref: owner_principal_ref.to_string(),
        event_type,
        credit_points_delta,
        reason: Some(event.reason),
        external_ref: event.external_ref,
        actor_role: TokenRole::parse(&event.actor_role)?,
        actor_principal_ref: event.actor_principal_ref,
        created_at: event.occurred_at,
    }))
}

fn trace_corpus_status_from_storage(status: StorageTraceCorpusStatus) -> Option<TraceCorpusStatus> {
    match status {
        StorageTraceCorpusStatus::Accepted => Some(TraceCorpusStatus::Accepted),
        StorageTraceCorpusStatus::Quarantined => Some(TraceCorpusStatus::Quarantined),
        StorageTraceCorpusStatus::AwaitingPiiBackstop => {
            Some(TraceCorpusStatus::AwaitingPiiBackstop)
        }
        StorageTraceCorpusStatus::Rejected => Some(TraceCorpusStatus::Rejected),
        StorageTraceCorpusStatus::Revoked => Some(TraceCorpusStatus::Revoked),
        StorageTraceCorpusStatus::Expired => Some(TraceCorpusStatus::Expired),
        StorageTraceCorpusStatus::Purged => Some(TraceCorpusStatus::Purged),
        StorageTraceCorpusStatus::Received => None,
    }
}

fn trace_credit_event_type_from_storage(
    event_type: StorageTraceCreditEventType,
) -> Option<TraceCreditLedgerEventType> {
    match event_type {
        StorageTraceCreditEventType::Accepted
        | StorageTraceCreditEventType::PrivacyRejection
        | StorageTraceCreditEventType::DuplicateRejection => None,
        StorageTraceCreditEventType::BenchmarkConversion => {
            Some(TraceCreditLedgerEventType::BenchmarkConversion)
        }
        StorageTraceCreditEventType::RegressionCatch => {
            Some(TraceCreditLedgerEventType::RegressionCatch)
        }
        StorageTraceCreditEventType::TrainingUtility => {
            Some(TraceCreditLedgerEventType::TrainingUtility)
        }
        StorageTraceCreditEventType::RankingUtility => {
            Some(TraceCreditLedgerEventType::RankingUtility)
        }
        StorageTraceCreditEventType::ReviewerBonus => {
            Some(TraceCreditLedgerEventType::ReviewerBonus)
        }
        StorageTraceCreditEventType::AbusePenalty => Some(TraceCreditLedgerEventType::AbusePenalty),
        StorageTraceCreditEventType::NoveltyUtility => {
            Some(TraceCreditLedgerEventType::NoveltyUtility)
        }
    }
}

fn storage_string_as<T: DeserializeOwned>(raw: &str, label: &str) -> anyhow::Result<T> {
    serde_json::from_value(serde_json::Value::String(raw.to_string()))
        .with_context(|| format!("failed to parse Trace Commons storage {label}: {raw}"))
}

fn reviewer_credit_for_record(record: &TraceCommonsSubmissionRecord) -> f32 {
    (0.5 + record.submission_score).clamp(0.5, 2.0)
}

fn status_for_risk(
    risk: ResidualPiiRisk,
    accept_medium_risk_submissions: bool,
) -> TraceCorpusStatus {
    match risk {
        ResidualPiiRisk::Low => TraceCorpusStatus::Accepted,
        ResidualPiiRisk::Medium if accept_medium_risk_submissions => TraceCorpusStatus::Accepted,
        ResidualPiiRisk::Medium | ResidualPiiRisk::High => TraceCorpusStatus::Quarantined,
    }
}

/// Decide the stored corpus status for a freshly-submitted trace, applying the
/// PII-backstop hold. When the risk-derived status is `Accepted`, the trace
/// carries raw content, and the backstop driver is enabled, the trace is
/// held on `AwaitingPiiBackstop` until the driver re-redacts it through the
/// NEAR AI PII filter and releases the hold. Every other case (non-Accepted
/// risk, no raw content, or backstop disabled) is returned unchanged so those
/// paths behave exactly as before the backstop existed.
///
/// "Raw content" is either content flag, not message text alone. It keyed on
/// `message_text_included` only, which left a payload-bearing trace that
/// carries no prose entirely outside the hold -- and that combination is not
/// a corner case, it is the structure-preserving mode: tool arguments and
/// results with message text withheld, which is exactly the shape a consumer
/// rebuilding traces as runnable tasks asks for (issue #298). The gap was
/// invisible because nothing has ever set `include_tool_payloads`, so no
/// payload-bearing, prose-free trace has been submitted yet.
///
/// The driver was never the gap: `rescrub_envelope_prose_pii_with` already
/// classifies every string leaf and object key of each `structured_payload`,
/// and fails closed to High via `coverage_incomplete` when it cannot finish.
/// Only enrolment ignored payloads.
///
/// Two things this deliberately does NOT do. It does not make tool payloads
/// safe to turn on: a held trace is released by the driver to whatever
/// `status_for_risk` says about the POST-backstop risk, and `residual_risk`
/// returns `Medium` for any envelope declaring either content flag, so on a
/// deployment that does not accept medium risk the release is to
/// `Quarantined`. Enabling payloads therefore feeds the quarantine queue and
/// depends on that queue being worked. And it does not change behaviour for
/// any trace submitted today: every existing content-bearing envelope also
/// carries message text, so it was already held.
///
/// Takes the whole `ConsentMetadata` rather than a bool per flag. Passing
/// them individually is what let one be forgotten, and a third content flag
/// should not be able to reintroduce the same gap. `correction_included` is
/// that third flag, and it is the one that most needs the hold: a correction
/// is stored AS WRITTEN -- the semantic redaction passes are deliberately
/// skipped, because a placeholder destroys the thing the correction exists to
/// carry -- so the backstop classifier is the only pass that reads it for PII
/// at all. Nothing sets that flag yet, so this changes no behaviour today.
///
/// The `awaiting_pii_backstop` status IS the enrolment: the driver's
/// enumeration LEFT JOINs `trace_pii_backstop` and tolerates an absent row via
/// `COALESCE(attempts, 0)`, and `bump_pii_backstop_attempt` upserts the
/// bookkeeping row on first failure. No explicit enrol write is required here.
///
/// Callers must pass consent that has already been through
/// `reconcile_consent_declarations` (both call sites run
/// `rescrub_trace_envelope` first, which does it), or an under-reported flag
/// skips the hold -- the case that function's own comment exists to prevent.
///
/// # The witness bypass
///
/// `witness` and `bypass_config` are the redaction-witness bypass, and they
/// are consulted at exactly this one call site. When an operator has pinned a
/// witness and a certificate over the submitted bytes verified against that
/// pin, a trace that would have been held is left `Accepted` instead.
///
/// **What that skips is the async backstop's CLASSIFIER stage, and only
/// that.** It is not a wholesale bypass and it needs no exemption from the
/// deterministic sweep, because the sweep has already run: both call sites
/// invoke `rescrub_trace_envelope` -- the deterministic pass over
/// `redacted_content` and `structured_payload`, plus `residual_envelope_scan`
/// -- synchronously before reaching this function. That ordering is the
/// entire safety argument, and
/// `the_synchronous_rescrub_runs_before_the_hold_is_decided` pins it against
/// the handler source. Moving this call above the rescrub turns the feature
/// into a wholesale bypass and must turn that test red.
///
/// **A verified certificate never means the trace is clean.** It means a known
/// program in a pinned enclave reached a `Low` verdict over the originating
/// redaction pass. A credential the prose classifier itself emitted survives
/// that verdict -- which is why the `risk_status == Accepted` precondition
/// below is load-bearing rather than free tidiness: it is what keeps the
/// server's own residual scan authoritative, so a certificate can never lift a
/// quarantine the synchronous pass just imposed.
///
/// Five conditions, all required: the bypass is configured, a certificate
/// verified, its verdict is `Low`, its policy alias is allowlisted, and the
/// risk-derived status is already `Accepted`. The alias check is its own
/// condition because a `deterministic-only` witness never ran a classifier, so
/// admitting its alias would mean no classifier ever reads that trace's prose.
fn corpus_status_with_pii_backstop_hold(
    risk_status: TraceCorpusStatus,
    consent: &ConsentMetadata,
    backstop_enabled: bool,
    witness: Option<&VerifiedWitnessCertificate>,
    bypass_config: Option<&WitnessBypassConfig>,
) -> TraceCorpusStatus {
    let carries_raw_content = consent.message_text_included
        || consent.tool_payloads_included
        || consent.correction_included;
    if risk_status == TraceCorpusStatus::Accepted && carries_raw_content && backstop_enabled {
        if witness_admits_trace(risk_status, witness, bypass_config) {
            return TraceCorpusStatus::Accepted;
        }
        TraceCorpusStatus::AwaitingPiiBackstop
    } else {
        risk_status
    }
}

/// Whether a verified witness certificate lets this trace skip the hold.
///
/// Split out from the decision above so the five conditions read as one list
/// rather than as a nested `if`, and so the ingest tests can name it. It is
/// not a public seam: the only caller is
/// [`corpus_status_with_pii_backstop_hold`].
///
/// `risk_status` is re-checked here even though the caller has already
/// established it. That is deliberate duplication: this predicate is the thing
/// a future reader will lift to a second call site, and it must not be safe to
/// lift only when the caller happens to have checked first.
fn witness_admits_trace(
    risk_status: TraceCorpusStatus,
    witness: Option<&VerifiedWitnessCertificate>,
    bypass_config: Option<&WitnessBypassConfig>,
) -> bool {
    let (Some(witness), Some(config)) = (witness, bypass_config) else {
        return false;
    };
    risk_status == TraceCorpusStatus::Accepted
        && witness.residual_risk_verdict() == ResidualPiiRisk::Low
        && config.policy_version_allowed(witness.redaction_policy_version())
}

/// The contributor-facing sentence describing what will happen to the credit
/// this receipt reports, given the deployment's settlement posture.
///
/// #445: a pilot ran for three months with 307 credit events stuck `pending`,
/// because `NearSettlementMode::Disabled` makes the settlement worker a no-op
/// and nothing said so. The contributor saw an accepted trace, a pending
/// figure, and a blank `FINAL` column, and could not tell "switched off" from
/// "still working on it". Whichever posture is configured, the receipt says
/// it, so the two can never drift apart again.
///
/// The wording itself lives once, in
/// `trace_commons_server::credit_numbers::settlement_status_sentence`, which
/// the credit-numbers API also renders through -- this function only maps the
/// enum to that function's string labels. Do not put the sentences back here.
fn settlement_posture_explanation(mode: NearSettlementMode) -> &'static str {
    // `as_label`, not a second inline match. The credit endpoints reach the
    // same sentence through that method, and two hand-maintained mappings with
    // nothing asserting they agree drift silently: a label this copy got wrong
    // would fall into `settlement_status_sentence`'s `_` arm, so the receipt
    // would say "disabled" while the credit endpoints said "dry_run" about the
    // same deployment.
    trace_commons_server::credit_numbers::settlement_status_sentence(mode.as_label())
}

/// Whether this row was admitted by a verified witness certificate rather
/// than by the ordinary path.
///
/// Reads the allowlisted status-reason label the submit handler wrote. It is
/// deliberately not a re-derivation of the bypass conditions: the receipt has
/// no certificate to inspect, and a second copy of that predicate would drift
/// from the one that decided the status.
fn witness_admitted_record(record: &TraceCommonsSubmissionRecord) -> bool {
    record
        .last_status_reason
        .as_deref()
        .is_some_and(|reason| reason == WITNESS_ADMITTED_STATUS_REASON)
}

fn receipt_from_record(
    record: &TraceCommonsSubmissionRecord,
    settlement_mode: NearSettlementMode,
) -> TraceSubmissionReceipt {
    let explanation = match record.status {
        TraceCorpusStatus::Accepted => {
            let mut lines = vec!["Accepted into the private redacted corpus.".to_string()];
            // #445's argument, applied to a second indistinguishable pair of
            // outcomes: a trace admitted on a witness certificate was admitted
            // on a DIFFERENT BASIS from one admitted on the server's own
            // queued re-check, and a contributor is entitled to know which.
            //
            // The sentence deliberately claims nothing about cleanliness. It
            // says a pinned enclave's redaction was accepted in place of the
            // server's queued re-check, which is exactly what happened, and it
            // carries no measurement and no address -- those are operator
            // configuration and have no business on a contributor surface.
            if witness_admitted_record(record) {
                lines.push(
                    "Admitted on an attested redaction witness certificate, in place of the \
                     server's queued privacy re-check. The deterministic redaction sweep and \
                     residual scan ran on this submission as they do on every submission."
                        .to_string(),
                );
            }
            lines.push(settlement_posture_explanation(settlement_mode).to_string());
            lines.push(format!(
                "Attributed to tenant {}",
                record.tenant_storage_ref
            ));
            lines
        }
        TraceCorpusStatus::Quarantined => vec![
            "Quarantined for privacy review; credit is pending review.".to_string(),
            format!("Attributed to tenant {}", record.tenant_storage_ref),
        ],
        TraceCorpusStatus::AwaitingPiiBackstop => vec![
            "Held pending an automated privacy backstop verdict; not yet in the corpus."
                .to_string(),
            format!("Attributed to tenant {}", record.tenant_storage_ref),
        ],
        TraceCorpusStatus::Revoked => vec!["Revoked and marked with a tombstone.".to_string()],
        TraceCorpusStatus::Rejected => vec!["Rejected by ingestion policy.".to_string()],
        TraceCorpusStatus::Expired => vec!["Expired under the retention policy.".to_string()],
        TraceCorpusStatus::Purged => vec!["Purged under the retention policy.".to_string()],
    };

    TraceSubmissionReceipt {
        status: record.status.as_str().to_string(),
        credit_points_pending: Some(record.credit_points_pending),
        credit_points_final: record.credit_points_final,
        explanation,
    }
}

fn submission_status_from_record(
    record: &TraceCommonsSubmissionRecord,
    credit_events: &[TraceCommonsCreditLedgerRecord],
    settlement_mode: NearSettlementMode,
) -> TraceSubmissionStatusUpdate {
    let receipt = receipt_from_record(record, settlement_mode);
    let delayed_events = credit_events
        .iter()
        .filter(|event| event.submission_id == record.submission_id)
        .collect::<Vec<_>>();
    let ledger_points = if delayed_credit_applies_to_record(record) {
        delayed_events
            .iter()
            .map(|event| event.credit_points_delta)
            .sum::<f32>()
    } else {
        0.0
    };
    let base_final = record.credit_points_final.unwrap_or(0.0);
    let credit_points_total = if delayed_events.is_empty() || record.is_terminal() {
        None
    } else {
        Some(base_final + ledger_points)
    };
    let delayed_credit_explanations = if record.is_terminal() && !delayed_events.is_empty() {
        vec![format!(
            "Delayed credit ledger events are retained for audit but excluded because the trace is {}.",
            record.status.as_str()
        )]
    } else {
        delayed_events
            .iter()
            .rev()
            .take(5)
            .map(|event| {
                let reason = event
                    .reason
                    .as_deref()
                    .filter(|reason| !reason.trim().is_empty())
                    .unwrap_or("delayed utility credit");
                format!(
                    "{:?}: {:+.2} ({})",
                    event.event_type, event.credit_points_delta, reason
                )
            })
            .collect::<Vec<_>>()
    };
    TraceSubmissionStatusUpdate {
        submission_id: record.submission_id,
        trace_id: record.trace_id,
        status: record.status.as_str().to_string(),
        credit_points_pending: record.credit_points_pending,
        credit_points_final: record.credit_points_final,
        credit_points_ledger: ledger_points,
        credit_points_total,
        explanation: receipt.explanation,
        delayed_credit_explanations,
        consent_scopes: record.consent_scopes.clone(),
    }
}

fn delayed_credit_applies_to_record(record: &TraceCommonsSubmissionRecord) -> bool {
    !record.is_terminal()
}

#[derive(Debug, Clone)]
struct StoredTraceEnvelope {
    object_key: String,
    artifact_receipt: Option<EncryptedTraceArtifactReceipt>,
    artifact_object_store: Option<String>,
}

#[derive(Debug, Clone)]
struct TraceExportArtifactObjectRefMaterial {
    object_store: String,
    object_key: String,
    content_sha256: String,
    encryption_key_ref: String,
    size_bytes: i64,
}

const TRACE_VECTOR_PAYLOAD_SCHEMA_VERSION: &str = "ironclaw.trace_commons.vector_payload.v1";
const TRACE_LOCAL_REDACTED_SUMMARY_EMBEDDING_MODEL: &str = "redacted-summary-feature-hash-v1";
const TRACE_LOCAL_REDACTED_SUMMARY_EMBEDDING_ALGORITHM: &str =
    "signed_hashing_vector_l2_normalized";
const TRACE_LOCAL_REDACTED_SUMMARY_EMBEDDING_VERSION: &str =
    "trace_commons_vector_payload_embedding_v1";
const TRACE_LOCAL_REDACTED_SUMMARY_EMBEDDING_DIMENSION: usize = 64;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct TraceVectorPayloadArtifact {
    artifact_schema_version: String,
    tenant_id: String,
    tenant_storage_ref: String,
    submission_id: Uuid,
    trace_id: Uuid,
    derived_id: Uuid,
    vector_entry_id: Uuid,
    source_projection: StorageTraceVectorEntrySourceProjection,
    source_hash: String,
    vector_store: String,
    embedding_model: String,
    embedding_dimension: i32,
    embedding_version: String,
    #[serde(default)]
    embedding_algorithm: Option<String>,
    #[serde(default)]
    embedding_input_hash: Option<String>,
    #[serde(default)]
    embedding_values: Vec<f32>,
    #[serde(default)]
    embedding_sha256: Option<String>,
    canonical_summary: Option<String>,
    canonical_summary_hash: Option<String>,
    summary_model: String,
    worker_kind: StorageTraceWorkerKind,
    worker_version: String,
    tool_sequence: Vec<String>,
    tool_categories: Vec<String>,
    coverage_tags: Vec<String>,
    nearest_trace_ids: Vec<String>,
    cluster_id: Option<String>,
    duplicate_score: Option<f32>,
    novelty_score: Option<f32>,
    indexed_at: DateTime<Utc>,
}

fn ensure_vector_payload_tenant(
    payload: &TraceVectorPayloadArtifact,
    tenant_id: &str,
) -> anyhow::Result<()> {
    anyhow::ensure!(
        payload.tenant_id == tenant_id,
        "trace vector payload tenant mismatch"
    );
    anyhow::ensure!(
        payload.tenant_storage_ref == tenant_storage_ref(tenant_id),
        "trace vector payload tenant storage ref mismatch"
    );
    Ok(())
}

fn store_envelope(
    state: &AppState,
    tenant_id: &str,
    status: TraceCorpusStatus,
    artifact_snapshot_label: &str,
    envelope: &TraceContributionEnvelope,
) -> anyhow::Result<StoredTraceEnvelope> {
    let object_key = trace_envelope_object_key(tenant_id, status, envelope.submission_id);
    let object_primary_submit_review = state.object_primary_submit_review_for_tenant(tenant_id);
    if !object_primary_submit_review
        && state
            .artifact_store
            .as_ref()
            .is_some_and(|store| !store.plaintext_compatibility_allowed())
    {
        anyhow::bail!(
            "TRACE_COMMONS_OBJECT_STORE=remote_service requires object-primary submit/review mode; refusing compatibility plaintext envelope body files"
        );
    }
    if !object_primary_submit_review {
        let path = state.root.join(&object_key);
        write_json_file(&path, envelope, "trace contribution envelope")?;
    }
    let (artifact_receipt, artifact_object_store) = if let Some(store) =
        state.artifact_store.as_ref()
    {
        let receipt = store.put_json(
            &tenant_storage_ref(tenant_id),
            TraceArtifactKind::ContributionEnvelope,
            &trace_envelope_artifact_object_id(
                envelope.submission_id,
                status,
                artifact_snapshot_label,
            ),
            envelope,
        )?;
        (Some(receipt), Some(store.object_store_name().to_string()))
    } else {
        anyhow::ensure!(
            !object_primary_submit_review,
            "{TRACE_COMMONS_OBJECT_PRIMARY_SUBMIT_REVIEW} requires a configured encrypted object store"
        );
        (None, None)
    };
    Ok(StoredTraceEnvelope {
        object_key,
        artifact_receipt,
        artifact_object_store,
    })
}

fn trace_envelope_artifact_object_id(
    submission_id: Uuid,
    status: TraceCorpusStatus,
    artifact_snapshot_label: &str,
) -> String {
    format!(
        "{submission_id}:{}:{}:{}",
        status.as_str(),
        artifact_snapshot_label,
        Uuid::new_v4()
    )
}

fn trace_envelope_object_key(
    tenant_id: &str,
    status: TraceCorpusStatus,
    submission_id: Uuid,
) -> String {
    let tenant_key = tenant_storage_key(tenant_id);
    format!(
        "tenants/{tenant_key}/objects/{}/{}.json",
        status.as_str(),
        submission_id
    )
}

fn trace_object_ref_write_from_record(
    state: &AppState,
    audit_label: &str,
    artifact_kind: StorageTraceObjectArtifactKind,
    record: &TraceCommonsSubmissionRecord,
    envelope: &TraceContributionEnvelope,
) -> anyhow::Result<(StorageTraceObjectRefWrite, String)> {
    let envelope_json = serde_json::to_string_pretty(envelope)
        .context("failed to serialize trace envelope for DB mirror hashing")?;
    let plaintext_sha256 = sha256_prefixed(&envelope_json);
    let (object_store, object_key, content_sha256) =
        if let Some(receipt) = record.artifact_receipt.as_ref() {
            (
                trace_record_artifact_object_store_for_ref(state, record, receipt),
                receipt.object_key.clone(),
                format!("sha256:{}", receipt.ciphertext_sha256),
            )
        } else {
            (
                TRACE_COMMONS_FILE_OBJECT_STORE.to_string(),
                record.object_key.clone(),
                plaintext_sha256,
            )
        };
    Ok((
        StorageTraceObjectRefWrite {
            object_ref_id: deterministic_trace_uuid(audit_label, record),
            tenant_id: record.tenant_id.clone(),
            submission_id: record.submission_id,
            artifact_kind,
            object_store,
            object_key,
            content_sha256: content_sha256.clone(),
            encryption_key_ref: format!("tenant:{}", tenant_storage_ref(&record.tenant_id)),
            size_bytes: i64::try_from(envelope_json.len()).unwrap_or(i64::MAX),
            compression: None,
            created_by_job_id: None,
        },
        content_sha256,
    ))
}

fn trace_record_explicit_artifact_object_store<'a>(
    record: &'a TraceCommonsSubmissionRecord,
    receipt: &EncryptedTraceArtifactReceipt,
) -> Option<&'a str> {
    record.artifact_object_store.as_deref().or_else(|| {
        receipt
            .object_key
            .starts_with("v1/tenants/")
            .then_some(TRACE_COMMONS_SERVICE_REMOTE_OBJECT_STORE)
    })
}

fn trace_record_artifact_object_store_for_ref(
    state: &AppState,
    record: &TraceCommonsSubmissionRecord,
    receipt: &EncryptedTraceArtifactReceipt,
) -> String {
    if let Some(object_store) = trace_record_explicit_artifact_object_store(record, receipt) {
        return object_store.to_string();
    }
    state
        .artifact_store
        .as_ref()
        .map(|store| store.object_store_name())
        .filter(|object_store| {
            matches!(
                *object_store,
                TRACE_COMMONS_LEGACY_ENCRYPTED_OBJECT_STORE
                    | TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE
            )
        })
        .unwrap_or(TRACE_COMMONS_LEGACY_ENCRYPTED_OBJECT_STORE)
        .to_string()
}

/// Exempt from the `canonical_json` treatment the other envelope-hashing
/// paths got, deliberately.
///
/// This serializes a typed struct, so the serializer writes its fields in
/// declaration order with no map involved -- `serde_json/preserve_order`
/// cannot move them. The only ordering-sensitive part is the nested
/// `structured_payload` values, and those arrive here already key-ordered:
/// the envelope is read back from stored bytes, and the redaction pipeline
/// canonicalizes every payload before it is stored
/// (`canonicalize_event_payloads` in `trace-commons-protocol`).
///
/// Making it canonical anyway would mean either cloning the whole envelope
/// to sort payloads in a copy, or routing it through `serde_json::to_value`
/// -- and that second one would sort the *struct* fields too and move this
/// hash today, which is exactly what the canonicalization work was required
/// not to do. Nothing re-verifies a stored value of this hash against a
/// rebuild in any case; the export verifier re-hashes raw file bytes.
fn envelope_plaintext_hash(envelope: &TraceContributionEnvelope) -> anyhow::Result<String> {
    let envelope_json = serde_json::to_string_pretty(envelope)
        .context("failed to serialize trace envelope for hashing")?;
    Ok(sha256_prefixed(&envelope_json))
}

fn trace_export_artifact_object_ref_material<T: Serialize>(
    state: &AppState,
    tenant_id: &str,
    artifact_kind: TraceArtifactKind,
    object_id: Uuid,
    file_path: &Path,
    value: &T,
) -> anyhow::Result<TraceExportArtifactObjectRefMaterial> {
    let json = serde_json::to_string_pretty(value)
        .context("failed to serialize trace export artifact for object ref")?;
    let tenant_ref = tenant_storage_ref(tenant_id);
    let (object_store, object_key, content_sha256) = if let Some(store) =
        state.artifact_store.as_ref()
    {
        let receipt = store.put_json(&tenant_ref, artifact_kind, &object_id.to_string(), value)?;
        (
            store.object_store_name().to_string(),
            receipt.object_key,
            format!("sha256:{}", receipt.ciphertext_sha256),
        )
    } else {
        (
            TRACE_COMMONS_FILE_OBJECT_STORE.to_string(),
            trace_file_object_key(&state.root, file_path)?,
            sha256_prefixed(&json),
        )
    };

    Ok(TraceExportArtifactObjectRefMaterial {
        object_store,
        object_key,
        content_sha256,
        encryption_key_ref: format!("tenant:{tenant_ref}"),
        size_bytes: i64::try_from(json.len()).unwrap_or(i64::MAX),
    })
}

fn trace_file_object_key(root: &Path, path: &Path) -> anyhow::Result<String> {
    let relative = path.strip_prefix(root).with_context(|| {
        format!(
            "trace object file {} is outside root {}",
            path.display(),
            root.display()
        )
    })?;
    anyhow::ensure!(
        relative
            .components()
            .all(|component| matches!(component, std::path::Component::Normal(_))),
        "trace object file key contains unsafe path components"
    );
    let segments = relative
        .components()
        .map(|component| match component {
            std::path::Component::Normal(segment) => segment.to_string_lossy().into_owned(),
            _ => String::new(),
        })
        .collect::<Vec<_>>();
    anyhow::ensure!(!segments.is_empty(), "trace object file key is empty");
    Ok(segments.join("/"))
}

fn trace_export_artifact_object_ref_write(
    tenant_id: &str,
    submission_id: Uuid,
    artifact_kind: StorageTraceObjectArtifactKind,
    export_id: Uuid,
    material: &TraceExportArtifactObjectRefMaterial,
) -> StorageTraceObjectRefWrite {
    StorageTraceObjectRefWrite {
        object_ref_id: deterministic_trace_export_object_ref_uuid(
            tenant_id,
            export_id,
            submission_id,
            artifact_kind,
        ),
        tenant_id: tenant_id.to_string(),
        submission_id,
        artifact_kind,
        object_store: material.object_store.clone(),
        object_key: material.object_key.clone(),
        content_sha256: material.content_sha256.clone(),
        encryption_key_ref: material.encryption_key_ref.clone(),
        size_bytes: material.size_bytes,
        compression: None,
        created_by_job_id: Some(export_id),
    }
}

fn trace_vector_payload_object_ref_write(
    state: &AppState,
    tenant_id: &str,
    submission_id: Uuid,
    vector_entry_id: Uuid,
    payload: &TraceVectorPayloadArtifact,
) -> anyhow::Result<Option<StorageTraceObjectRefWrite>> {
    let Some(store) = state.artifact_store.as_ref() else {
        return Ok(None);
    };
    let json = serde_json::to_string_pretty(payload)
        .context("failed to serialize trace vector payload artifact for object ref")?;
    let tenant_ref = tenant_storage_ref(tenant_id);
    let receipt = store.put_json(
        &tenant_ref,
        TraceArtifactKind::VectorPayload,
        &vector_entry_id.to_string(),
        payload,
    )?;
    Ok(Some(StorageTraceObjectRefWrite {
        object_ref_id: deterministic_trace_vector_payload_object_ref_uuid(
            tenant_id,
            submission_id,
            vector_entry_id,
        ),
        tenant_id: tenant_id.to_string(),
        submission_id,
        artifact_kind: StorageTraceObjectArtifactKind::WorkerIntermediate,
        object_store: store.object_store_name().to_string(),
        object_key: receipt.object_key,
        content_sha256: format!("sha256:{}", receipt.ciphertext_sha256),
        encryption_key_ref: format!("tenant:{tenant_ref}"),
        size_bytes: i64::try_from(json.len()).unwrap_or(i64::MAX),
        compression: None,
        created_by_job_id: Some(vector_entry_id),
    }))
}

fn deterministic_trace_export_object_ref_uuid(
    tenant_id: &str,
    export_id: Uuid,
    submission_id: Uuid,
    artifact_kind: StorageTraceObjectArtifactKind,
) -> Uuid {
    let input = format!(
        "ironclaw.trace_commons.export_artifact_object_ref:{tenant_id}:{export_id}:{submission_id}:{artifact_kind:?}"
    );
    Uuid::new_v5(&Uuid::NAMESPACE_URL, input.as_bytes())
}

fn deterministic_trace_vector_payload_object_ref_uuid(
    tenant_id: &str,
    submission_id: Uuid,
    vector_entry_id: Uuid,
) -> Uuid {
    let input = format!(
        "ironclaw.trace_commons.vector_payload_object_ref:{tenant_id}:{submission_id}:{vector_entry_id}"
    );
    Uuid::new_v5(&Uuid::NAMESPACE_URL, input.as_bytes())
}

async fn mirror_submission_to_db(
    state: &AppState,
    tenant: &TenantAuth,
    record: &TraceCommonsSubmissionRecord,
    derived_record: &TraceCommonsDerivedRecord,
    envelope: &TraceContributionEnvelope,
) -> anyhow::Result<()> {
    mirror_submission_to_db_with_options(state, tenant, record, derived_record, envelope, true)
        .await
}

async fn mirror_submission_to_db_with_options(
    state: &AppState,
    tenant: &TenantAuth,
    record: &TraceCommonsSubmissionRecord,
    derived_record: &TraceCommonsDerivedRecord,
    envelope: &TraceContributionEnvelope,
    append_submit_audit: bool,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    let (object_ref, content_sha256) = trace_object_ref_write_from_record(
        state,
        "submitted-envelope",
        StorageTraceObjectArtifactKind::SubmittedEnvelope,
        record,
        envelope,
    )?;
    let object_ref_id = object_ref.object_ref_id;
    let derived_id = deterministic_trace_uuid("derived-precheck", record);
    let privacy_risk = serde_storage_string(&record.privacy_risk)?;
    let credit_account_ref = envelope
        .contributor
        .credit_account_ref
        .clone()
        .or_else(|| record.contributor_pseudonym.clone())
        .unwrap_or_else(|| record.auth_principal_ref.clone());

    db.upsert_trace_submission(storage_submission_write_from_record(
        record,
        envelope,
        Some(derived_record.canonical_summary_hash.clone()),
    )?)
    .await
    .context("failed to mirror trace submission metadata")?;

    db.append_trace_object_ref(object_ref)
        .await
        .context("failed to mirror trace object ref")?;

    db.append_trace_derived_record(StorageTraceDerivedRecordWrite {
        derived_id,
        tenant_id: record.tenant_id.clone(),
        submission_id: record.submission_id,
        trace_id: record.trace_id,
        status: storage_derived_status(record.status),
        worker_kind: StorageTraceWorkerKind::DuplicatePrecheck,
        worker_version: "trace_commons_ingest_v1".to_string(),
        input_object_ref: Some(
            trace_commons_server::trace_corpus_storage::TenantScopedTraceObjectRef {
                tenant_id: record.tenant_id.clone(),
                submission_id: record.submission_id,
                object_ref_id,
            },
        ),
        input_hash: content_sha256,
        output_object_ref: None,
        canonical_summary: Some(derived_record.canonical_summary.clone()),
        canonical_summary_hash: Some(derived_record.canonical_summary_hash.clone()),
        summary_model: derived_record.summary_model.clone(),
        task_success: Some(derived_record.task_success.clone()),
        privacy_risk: Some(privacy_risk.clone()),
        event_count: Some(derived_record.event_count.min(i32::MAX as usize) as i32),
        tool_sequence: derived_record.tool_sequence.clone(),
        tool_categories: derived_record.tool_categories.clone(),
        coverage_tags: derived_record.coverage_tags.clone(),
        duplicate_score: Some(derived_record.duplicate_score),
        novelty_score: Some(derived_record.novelty_score),
        cluster_id: envelope.embedding_analysis.as_ref().and_then(|analysis| {
            analysis
                .cluster_id
                .clone()
                .or_else(|| analysis.nearest_cluster_id.clone())
        }),
    })
    .await
    .context("failed to mirror trace derived metadata")?;

    if append_submit_audit {
        db.append_trace_audit_event(StorageTraceAuditEventWrite {
            audit_event_id: deterministic_trace_uuid("submit-audit", record),
            tenant_id: record.tenant_id.clone(),
            actor_principal_ref: record.auth_principal_ref.clone(),
            actor_role: format!("{:?}", tenant.role).to_ascii_lowercase(),
            action: StorageTraceAuditAction::Submit,
            reason: Some(format!("auth_method={}", tenant.auth_method.storage_name())),
            request_id: None,
            submission_id: Some(record.submission_id),
            object_ref_id: Some(object_ref_id),
            export_manifest_id: None,
            decision_inputs_hash: Some(derived_record.canonical_summary_hash.clone()),
            previous_event_hash: None,
            event_hash: None,
            canonical_event_json: None,
            metadata: StorageTraceAuditSafeMetadata::Submission {
                status: storage_corpus_status(record.status),
                privacy_risk: privacy_risk.clone(),
            },
        })
        .await
        .context("failed to mirror trace audit event")?;
    }

    if record.status == TraceCorpusStatus::Accepted && record.credit_points_pending > 0.0 {
        db.append_trace_credit_event(StorageTraceCreditEventWrite {
            credit_event_id: deterministic_trace_uuid("accepted-credit", record),
            tenant_id: record.tenant_id.clone(),
            submission_id: record.submission_id,
            trace_id: record.trace_id,
            credit_account_ref,
            event_type: StorageTraceCreditEventType::Accepted,
            points_delta: format!("{:.4}", record.credit_points_pending),
            reason: "Accepted by Trace Commons ingest privacy checks.".to_string(),
            external_ref: None,
            actor_principal_ref: record.auth_principal_ref.clone(),
            actor_role: "system".to_string(),
            settlement_state: StorageTraceCreditSettlementState::Pending,
        })
        .await
        .context("failed to mirror trace credit event")?;
    }

    Ok(())
}

struct TraceRevocationDbMirrorInput<'a> {
    tenant: &'a TenantAuth,
    submission_id: Uuid,
    record: Option<&'a TraceCommonsSubmissionRecord>,
    db_record: Option<&'a StorageTraceSubmissionRecord>,
    revocation_reason: &'a str,
    retention_ledger: Option<&'a mut TraceMaintenanceLedgerAccumulator>,
    prepared_tombstone: Option<&'a TraceCommonsRevocation>,
}

async fn mirror_revocation_to_db(
    state: &AppState,
    input: TraceRevocationDbMirrorInput<'_>,
) -> anyhow::Result<()> {
    let TraceRevocationDbMirrorInput {
        tenant,
        submission_id,
        record,
        db_record,
        revocation_reason,
        retention_ledger,
        prepared_tombstone,
    } = input;
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };

    if let Some(record) = record {
        let file_tombstone = if prepared_tombstone.is_none() {
            read_revocation(&state.root, &tenant.tenant_id, submission_id)?
        } else {
            None
        };
        let redaction_hash = prepared_tombstone
            .as_ref()
            .and_then(|tombstone| tombstone.redaction_hash.clone())
            .or_else(|| {
                file_tombstone
                    .as_ref()
                    .and_then(|tombstone| tombstone.redaction_hash.clone())
            })
            .or_else(|| redaction_hash_for_record(state, record));
        let canonical_summary_hash = prepared_tombstone
            .as_ref()
            .and_then(|tombstone| tombstone.canonical_summary_hash.clone())
            .or_else(|| {
                file_tombstone
                    .as_ref()
                    .and_then(|tombstone| tombstone.canonical_summary_hash.clone())
            })
            .or_else(|| {
                read_derived_record(&state.root, &tenant.tenant_id, submission_id)
                    .ok()
                    .flatten()
                    .map(|derived| derived.canonical_summary_hash)
            });
        db.write_trace_tombstone(StorageTraceTombstoneWrite {
            tombstone_id: deterministic_trace_uuid("revocation-tombstone", record),
            tenant_id: record.tenant_id.clone(),
            submission_id: record.submission_id,
            trace_id: Some(record.trace_id),
            redaction_hash,
            canonical_summary_hash,
            reason: revocation_reason.to_string(),
            effective_at: Utc::now(),
            retain_until: None,
            created_by_principal_ref: tenant.principal_ref.clone(),
        })
        .await
        .context("failed to mirror trace revocation tombstone")?;
    } else if let Some(db_record) = db_record {
        db.write_trace_tombstone(StorageTraceTombstoneWrite {
            tombstone_id: deterministic_trace_uuid_for(
                "revocation-tombstone",
                &db_record.tenant_id,
                db_record.submission_id,
            ),
            tenant_id: db_record.tenant_id.clone(),
            submission_id: db_record.submission_id,
            trace_id: Some(db_record.trace_id),
            redaction_hash: Some(db_record.redaction_hash.clone()),
            canonical_summary_hash: db_record.canonical_summary_hash.clone(),
            reason: revocation_reason.to_string(),
            effective_at: Utc::now(),
            retain_until: None,
            created_by_principal_ref: tenant.principal_ref.clone(),
        })
        .await
        .context("failed to mirror DB-only trace revocation tombstone")?;
    }

    db.update_trace_submission_status(
        &tenant.tenant_id,
        submission_id,
        StorageTraceCorpusStatus::Revoked,
        &tenant.principal_ref,
        Some(revocation_reason),
    )
    .await
    .context("failed to mirror trace revocation status")?;

    let invalidation_counts = db
        .invalidate_trace_submission_artifacts(
            &tenant.tenant_id,
            submission_id,
            StorageTraceDerivedStatus::Revoked,
        )
        .await
        .context("failed to mirror trace artifact invalidation")?;
    let vector_entries_invalidated = db
        .invalidate_trace_vector_entries_for_submission(&tenant.tenant_id, submission_id)
        .await
        .context("failed to mirror trace vector invalidation")?;
    let export_manifests_invalidated = db
        .invalidate_trace_export_manifests_for_submission(&tenant.tenant_id, submission_id)
        .await
        .context("failed to mirror trace export manifest invalidation")?;
    let export_manifest_items_invalidated = db
        .invalidate_trace_export_manifest_items_for_submission(
            &tenant.tenant_id,
            submission_id,
            StorageTraceExportManifestItemInvalidationReason::Revoked,
        )
        .await
        .context("failed to mirror trace export manifest item invalidation")?;
    // Revocation does NOT claw back credit that has already settled. Credit
    // earned and settled stays earned: a contributor who is uneasy about a
    // trace must be able to pull it back without being financially penalised,
    // or the trace stays in the commons out of fear. Revocation removes the
    // trace from the corpus and deletes its content -- it does not reach back
    // onto the chain. The `ReverseCreditSettlement` propagation action and its
    // worker remain, so an operator can still reverse a fraudulent or
    // mistakenly settled credit and so any item enqueued before this change
    // still drains; nothing on the revocation path enqueues one.
    let object_delete_items_enqueued = enqueue_object_payload_delete_items_for_revocation(
        db.as_ref(),
        &tenant.tenant_id,
        submission_id,
    )
    .await
    .context("failed to enqueue object payload delete propagation items")?;
    let worker_queue_items_enqueued = enqueue_worker_queue_invalidation_items_for_revocation(
        db.as_ref(),
        &tenant.tenant_id,
        submission_id,
    )
    .await
    .context("failed to enqueue worker queue invalidation propagation items")?;
    let vector_entry_items_enqueued = enqueue_vector_entry_invalidation_items_for_revocation(
        db.as_ref(),
        &tenant.tenant_id,
        submission_id,
    )
    .await
    .context("failed to enqueue vector entry invalidation propagation items")?;

    let audit_source = record
        .map(|record| {
            (
                deterministic_trace_uuid("revocation-artifact-invalidation", record),
                record.tenant_id.clone(),
                record.submission_id,
            )
        })
        .or_else(|| {
            db_record.map(|record| {
                (
                    deterministic_trace_uuid_for(
                        "revocation-artifact-invalidation",
                        &record.tenant_id,
                        record.submission_id,
                    ),
                    record.tenant_id.clone(),
                    record.submission_id,
                )
            })
        });
    if let Some((audit_event_id, audit_tenant_id, audit_submission_id)) = audit_source
        && (invalidation_counts.object_refs_invalidated > 0
            || invalidation_counts.derived_records_invalidated > 0
            || vector_entries_invalidated > 0
            || export_manifests_invalidated > 0
            || export_manifest_items_invalidated > 0
            || object_delete_items_enqueued > 0
            || worker_queue_items_enqueued > 0
            || vector_entry_items_enqueued > 0)
    {
        let mut action_counts = lifecycle_invalidation_action_counts(
            invalidation_counts,
            0,
            vector_entries_invalidated,
            export_manifests_invalidated,
            export_manifest_items_invalidated,
        );
        if object_delete_items_enqueued > 0 {
            action_counts.insert(
                "object_delete_items_enqueued".to_string(),
                object_delete_items_enqueued.min(u32::MAX as usize) as u32,
            );
        }
        if worker_queue_items_enqueued > 0 {
            action_counts.insert(
                "worker_queue_items_enqueued".to_string(),
                worker_queue_items_enqueued.min(u32::MAX as usize) as u32,
            );
        }
        if vector_entry_items_enqueued > 0 {
            action_counts.insert(
                "vector_entry_items_enqueued".to_string(),
                vector_entry_items_enqueued.min(u32::MAX as usize) as u32,
            );
        }
        if let Some(ledger) = retention_ledger {
            ledger.record_lifecycle_item(
                audit_submission_id,
                StorageTraceRetentionJobItemAction::Revoke,
                TRACE_DEFAULT_REVOCATION_REASON,
                action_counts.clone(),
                "records_marked_revoked",
            );
        }
        db.append_trace_audit_event(StorageTraceAuditEventWrite {
            audit_event_id,
            tenant_id: audit_tenant_id,
            actor_principal_ref: tenant.principal_ref.clone(),
            actor_role: format!("{:?}", tenant.role).to_ascii_lowercase(),
            action: StorageTraceAuditAction::Revoke,
            reason: Some(format!(
                "revocation_artifact_invalidation;reason_hash={}",
                sha256_prefixed(revocation_reason)
            )),
            request_id: None,
            submission_id: Some(audit_submission_id),
            object_ref_id: None,
            export_manifest_id: None,
            decision_inputs_hash: None,
            previous_event_hash: None,
            event_hash: None,
            canonical_event_json: None,
            metadata: StorageTraceAuditSafeMetadata::Maintenance {
                surface: None,
                purpose_hash: None,
                dry_run: false,
                action_counts,
            },
        })
        .await
        .context("failed to mirror trace artifact invalidation audit")?;
    }

    Ok(())
}

fn trace_revocation_worker_queue_invalidation_targets(
    tenant_id: &str,
    submission_id: Uuid,
) -> Vec<(String, String)> {
    ["process_evaluation_queue", "ranking_training_queue"]
        .into_iter()
        .map(|queue_surface| {
            (
                queue_surface.to_string(),
                trace_revocation_worker_queue_key_hash(tenant_id, submission_id, queue_surface),
            )
        })
        .collect()
}

fn is_revocation_worker_queue_surface(queue_surface: &str) -> bool {
    matches!(
        queue_surface,
        "process_evaluation_queue" | "ranking_training_queue"
    )
}

fn trace_revocation_worker_queue_key_hash(
    tenant_id: &str,
    submission_id: Uuid,
    queue_surface: &str,
) -> String {
    sha256_prefixed(&format!(
        "trace_revocation_worker_queue:v1:{tenant_id}:{submission_id}:{queue_surface}"
    ))
}

async fn enqueue_worker_queue_invalidation_items_for_revocation(
    db: &dyn Database,
    tenant_id: &str,
    submission_id: Uuid,
) -> anyhow::Result<usize> {
    let existing_idempotency_keys = db
        .list_trace_revocation_propagation_items(tenant_id, submission_id)
        .await
        .context("failed to read existing revocation propagation items")?
        .into_iter()
        .map(|item| item.idempotency_key)
        .collect::<BTreeSet<_>>();
    let mut enqueued = 0usize;
    for (queue_surface, queue_key_hash) in
        trace_revocation_worker_queue_invalidation_targets(tenant_id, submission_id)
    {
        let idempotency_key = sha256_prefixed(&format!(
            "trace_revocation_worker_queue_invalidation:v1:{tenant_id}:{submission_id}:{queue_surface}"
        ));
        if existing_idempotency_keys.contains(&idempotency_key) {
            continue;
        }
        db.upsert_trace_revocation_propagation_item(StorageTraceRevocationPropagationItemWrite {
            tenant_id: tenant_id.to_string(),
            propagation_item_id: deterministic_trace_uuid_for_external_ref(
                "revocation-worker-queue-invalidation",
                tenant_id,
                submission_id,
                &queue_surface,
            ),
            source_submission_id: submission_id,
            target: StorageTraceRevocationPropagationTarget::WorkerQueue {
                queue_surface: queue_surface.clone(),
                queue_key_hash,
            },
            action: StorageTraceRevocationPropagationAction::InvalidateWorkerQueue,
            status: StorageTraceRevocationPropagationItemStatus::Pending,
            idempotency_key,
            reason: format!("revoked trace worker queue invalidation;surface={queue_surface}"),
            attempt_count: 0,
            last_error: None,
            next_attempt_at: None,
            completed_at: None,
            evidence_hash: None,
            metadata: BTreeMap::from([
                ("source".to_string(), "mirror_revocation_to_db".to_string()),
                ("queue_surface".to_string(), queue_surface),
            ]),
        })
        .await
        .context("failed to upsert worker queue invalidation propagation item")?;
        enqueued += 1;
    }
    Ok(enqueued)
}

/// Enqueue one `InvalidateVector` propagation item per per-chunk vector
/// entry recorded for the submission (V37 `trace_gate_chunk_vector_entries`).
/// The existing propagation worker's `InvalidateVector` branch consumes the
/// items unchanged — one entry id per item. Legacy pre-V37 decisions carry
/// no chunk rows and are unaffected. Idempotent per entry id.
async fn enqueue_vector_entry_invalidation_items_for_revocation(
    db: &dyn Database,
    tenant_id: &str,
    submission_id: Uuid,
) -> anyhow::Result<usize> {
    let existing_idempotency_keys = db
        .list_trace_revocation_propagation_items(tenant_id, submission_id)
        .await
        .context("failed to read existing revocation propagation items")?
        .into_iter()
        .map(|item| item.idempotency_key)
        .collect::<BTreeSet<_>>();
    let mut enqueued = 0usize;
    for entry in db
        .list_trace_gate_chunk_vector_entries(tenant_id, submission_id)
        .await
        .context("failed to read chunk vector entries for revocation")?
    {
        let idempotency_key = sha256_prefixed(&format!(
            "trace_revocation_chunk_vector_entry_invalidation:v1:{tenant_id}:{submission_id}:{}",
            entry.vector_entry_id
        ));
        if existing_idempotency_keys.contains(&idempotency_key) {
            continue;
        }
        db.upsert_trace_revocation_propagation_item(StorageTraceRevocationPropagationItemWrite {
            tenant_id: tenant_id.to_string(),
            propagation_item_id: deterministic_trace_uuid_for_external_ref(
                "revocation-chunk-vector-entry-invalidation",
                tenant_id,
                submission_id,
                &entry.vector_entry_id.to_string(),
            ),
            source_submission_id: submission_id,
            target: StorageTraceRevocationPropagationTarget::VectorEntry {
                vector_entry_id: entry.vector_entry_id,
            },
            action: StorageTraceRevocationPropagationAction::InvalidateVector,
            status: StorageTraceRevocationPropagationItemStatus::Pending,
            idempotency_key,
            reason: "revoked trace per-chunk vector entry invalidation".to_string(),
            attempt_count: 0,
            last_error: None,
            next_attempt_at: None,
            completed_at: None,
            evidence_hash: None,
            metadata: BTreeMap::from([(
                "source".to_string(),
                "mirror_revocation_to_db".to_string(),
            )]),
        })
        .await
        .context("failed to upsert chunk vector entry invalidation propagation item")?;
        enqueued += 1;
    }
    Ok(enqueued)
}

async fn enqueue_object_payload_delete_items_for_revocation(
    db: &dyn Database,
    tenant_id: &str,
    submission_id: Uuid,
) -> anyhow::Result<usize> {
    let existing_idempotency_keys = db
        .list_trace_revocation_propagation_items(tenant_id, submission_id)
        .await
        .context("failed to read existing revocation propagation items")?
        .into_iter()
        .map(|item| item.idempotency_key)
        .collect::<BTreeSet<_>>();
    let mut enqueued = 0usize;
    for object_ref in db
        .list_trace_object_refs(tenant_id, submission_id)
        .await
        .context("failed to read object refs for revocation payload deletion")?
        .into_iter()
        .filter(|object_ref| object_ref.deleted_at.is_none())
        .filter(|object_ref| is_service_owned_trace_object_store(&object_ref.object_store))
        .filter(|object_ref| {
            is_supported_service_owned_physical_delete_artifact_kind(object_ref.artifact_kind)
        })
    {
        let idempotency_key = sha256_prefixed(&format!(
            "trace_revocation_object_payload_delete:v1:{tenant_id}:{submission_id}:{}",
            object_ref.object_ref_id
        ));
        if existing_idempotency_keys.contains(&idempotency_key) {
            continue;
        }
        db.upsert_trace_revocation_propagation_item(StorageTraceRevocationPropagationItemWrite {
            tenant_id: tenant_id.to_string(),
            propagation_item_id: deterministic_trace_uuid_for_external_ref(
                "revocation-object-payload-delete",
                tenant_id,
                submission_id,
                &object_ref.object_ref_id.to_string(),
            ),
            source_submission_id: submission_id,
            target: StorageTraceRevocationPropagationTarget::ObjectRef {
                object_ref_id: object_ref.object_ref_id,
            },
            action: StorageTraceRevocationPropagationAction::DeleteObjectPayload,
            status: StorageTraceRevocationPropagationItemStatus::Pending,
            idempotency_key,
            reason: "revoked trace service-owned object payload deletion".to_string(),
            attempt_count: 0,
            last_error: None,
            next_attempt_at: None,
            completed_at: None,
            evidence_hash: None,
            metadata: BTreeMap::from([(
                "source".to_string(),
                "mirror_revocation_to_db".to_string(),
            )]),
        })
        .await
        .context("failed to upsert object payload delete propagation item")?;
        enqueued += 1;
    }
    Ok(enqueued)
}

async fn db_submission_record_for_revocation(
    state: &AppState,
    tenant_id: &str,
    submission_id: Uuid,
) -> anyhow::Result<Option<StorageTraceSubmissionRecord>> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(None);
    };
    db.get_trace_submission(tenant_id, submission_id)
        .await
        .context("failed to read DB trace submission for revocation")
}

enum TraceRevocationPropagationItemOutcome {
    Done {
        evidence_hash: String,
    },
    Skipped {
        reason: String,
        evidence_hash: String,
    },
}

async fn run_revocation_propagation_worker(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceRevocationPropagationWorkerRequest,
) -> anyhow::Result<TraceRevocationPropagationWorkerResponse> {
    let db = state.db_mirror.as_ref().ok_or_else(|| {
        anyhow::anyhow!("trace revocation propagation worker requires configured DB mirror")
    })?;
    let purpose = request
        .purpose
        .as_deref()
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .unwrap_or("trace_commons_revocation_propagation_worker")
        .to_string();
    let limit = request
        .limit
        .clamp(1, TRACE_REVOCATION_PROPAGATION_MAX_LIMIT);
    let now = Utc::now();
    let due_items = db
        .list_due_trace_revocation_propagation_items(&tenant.tenant_id, now, limit)
        .await
        .context("failed to list due trace revocation propagation items")?;

    let mut response = TraceRevocationPropagationWorkerResponse {
        purpose: purpose.clone(),
        dry_run: request.dry_run,
        checked: due_items.len(),
        completed: 0,
        failed: 0,
        skipped: 0,
        pending: if request.dry_run { due_items.len() } else { 0 },
        next_attempt_scheduled: 0,
    };

    if request.dry_run {
        append_revocation_propagation_audit(state, tenant, &response).await?;
        log_revocation_propagation_worker_summary(tenant, &response);
        return Ok(response);
    }

    for item in due_items {
        let attempt_count = item.attempt_count.saturating_add(1);
        db.update_trace_revocation_propagation_item_status(
            &tenant.tenant_id,
            item.propagation_item_id,
            StorageTraceRevocationPropagationItemStatusUpdate {
                status: StorageTraceRevocationPropagationItemStatus::InProgress,
                attempt_count,
                last_error: None,
                next_attempt_at: None,
                completed_at: None,
                evidence_hash: None,
            },
        )
        .await
        .with_context(|| {
            format!(
                "failed to claim revocation propagation item {}",
                item.propagation_item_id
            )
        })?;

        match apply_revocation_propagation_item(state, db.as_ref(), tenant, &item).await {
            Ok(TraceRevocationPropagationItemOutcome::Done { evidence_hash }) => {
                db.update_trace_revocation_propagation_item_status(
                    &tenant.tenant_id,
                    item.propagation_item_id,
                    StorageTraceRevocationPropagationItemStatusUpdate {
                        status: StorageTraceRevocationPropagationItemStatus::Done,
                        attempt_count,
                        last_error: None,
                        next_attempt_at: None,
                        completed_at: Some(Utc::now()),
                        evidence_hash: Some(evidence_hash),
                    },
                )
                .await
                .with_context(|| {
                    format!(
                        "failed to complete revocation propagation item {}",
                        item.propagation_item_id
                    )
                })?;
                response.completed += 1;
            }
            Ok(TraceRevocationPropagationItemOutcome::Skipped {
                reason,
                evidence_hash,
            }) => {
                db.update_trace_revocation_propagation_item_status(
                    &tenant.tenant_id,
                    item.propagation_item_id,
                    StorageTraceRevocationPropagationItemStatusUpdate {
                        status: StorageTraceRevocationPropagationItemStatus::Skipped,
                        attempt_count,
                        last_error: Some(reason),
                        next_attempt_at: None,
                        completed_at: Some(Utc::now()),
                        evidence_hash: Some(evidence_hash),
                    },
                )
                .await
                .with_context(|| {
                    format!(
                        "failed to skip revocation propagation item {}",
                        item.propagation_item_id
                    )
                })?;
                response.skipped += 1;
            }
            Err(error) => {
                let is_terminal = attempt_count >= state.revocation_propagation_max_attempts;
                let next_attempt_at = if is_terminal {
                    None
                } else {
                    Some(revocation_propagation_retry_at(now, attempt_count))
                };
                db.update_trace_revocation_propagation_item_status(
                    &tenant.tenant_id,
                    item.propagation_item_id,
                    StorageTraceRevocationPropagationItemStatusUpdate {
                        status: StorageTraceRevocationPropagationItemStatus::Failed,
                        attempt_count,
                        last_error: Some(safe_worker_error(&error)),
                        next_attempt_at,
                        completed_at: None,
                        evidence_hash: None,
                    },
                )
                .await
                .with_context(|| {
                    format!(
                        "failed to reschedule revocation propagation item {}",
                        item.propagation_item_id
                    )
                })?;
                // Phase A6 retrofit: hash-only audit row for the failure
                // across all propagation target kinds. The typed
                // `RevocationPropagationFailure` metadata variant carries the
                // `<Action>Failed` error class so operators can filter on
                // stable labels; the raw error text is hashed.
                let error_class = revocation_propagation_error_class_for(item.action);
                if let Err(audit_err) = append_revocation_propagation_failure_audit(
                    state,
                    tenant,
                    &item,
                    error_class,
                    &error,
                    attempt_count,
                    is_terminal,
                )
                .await
                {
                    tracing::warn!(
                        error_hash = %safe_display_error_hash(&audit_err),
                        propagation_item_id = %item.propagation_item_id,
                        target_kind = ?item.target_kind,
                        "failed to append revocation propagation failure audit row"
                    );
                }
                response.failed += 1;
                if !is_terminal {
                    response.next_attempt_scheduled += 1;
                }
            }
        }
    }

    append_revocation_propagation_audit(state, tenant, &response).await?;
    log_revocation_propagation_worker_summary(tenant, &response);
    Ok(response)
}

#[derive(Debug)]
struct TraceRevocationPropagationWorkerLogFields {
    tenant_storage_ref: String,
    purpose_hash: String,
    dry_run: bool,
    checked: usize,
    completed: usize,
    failed: usize,
    skipped: usize,
    pending: usize,
    next_attempt_scheduled: usize,
}

fn revocation_propagation_worker_log_fields(
    tenant: &TenantAuth,
    response: &TraceRevocationPropagationWorkerResponse,
) -> TraceRevocationPropagationWorkerLogFields {
    TraceRevocationPropagationWorkerLogFields {
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        purpose_hash: sha256_prefixed(&response.purpose),
        dry_run: response.dry_run,
        checked: response.checked,
        completed: response.completed,
        failed: response.failed,
        skipped: response.skipped,
        pending: response.pending,
        next_attempt_scheduled: response.next_attempt_scheduled,
    }
}

fn log_revocation_propagation_worker_summary(
    tenant: &TenantAuth,
    response: &TraceRevocationPropagationWorkerResponse,
) {
    let fields = revocation_propagation_worker_log_fields(tenant, response);
    tracing::info!(
        tenant_storage_ref = %fields.tenant_storage_ref,
        purpose_hash = %fields.purpose_hash,
        dry_run = fields.dry_run,
        checked_count = fields.checked,
        completed_count = fields.completed,
        failed_count = fields.failed,
        skipped_count = fields.skipped,
        pending_count = fields.pending,
        next_attempt_scheduled_count = fields.next_attempt_scheduled,
        "Trace Commons revocation propagation worker completed"
    );
}

async fn apply_revocation_propagation_item(
    state: &AppState,
    db: &dyn Database,
    tenant: &TenantAuth,
    item: &StorageTraceRevocationPropagationItemRecord,
) -> anyhow::Result<TraceRevocationPropagationItemOutcome> {
    match item.action {
        StorageTraceRevocationPropagationAction::InvalidateMetadata => {
            db.invalidate_trace_submission_artifacts(
                &tenant.tenant_id,
                item.source_submission_id,
                StorageTraceDerivedStatus::Revoked,
            )
            .await
            .context("failed to invalidate trace metadata for revocation propagation")?;
            Ok(done_revocation_propagation_item(
                item,
                "invalidate_metadata",
            ))
        }
        StorageTraceRevocationPropagationAction::InvalidateExportMembership => {
            db.invalidate_trace_export_manifests_for_submission(
                &tenant.tenant_id,
                item.source_submission_id,
            )
            .await
            .context("failed to invalidate export manifests for revocation propagation")?;
            db.invalidate_trace_export_manifest_items_for_submission(
                &tenant.tenant_id,
                item.source_submission_id,
                StorageTraceExportManifestItemInvalidationReason::Revoked,
            )
            .await
            .context("failed to invalidate export manifest items for revocation propagation")?;
            Ok(done_revocation_propagation_item(
                item,
                "invalidate_export_membership",
            ))
        }
        StorageTraceRevocationPropagationAction::InvalidateVector => {
            let StorageTraceRevocationPropagationTarget::VectorEntry { vector_entry_id } =
                &item.target
            else {
                return Ok(skipped_revocation_propagation_item(
                    item,
                    "vector invalidation requires a vector-entry target",
                ));
            };
            db.invalidate_trace_vector_entry_for_submission(
                &tenant.tenant_id,
                item.source_submission_id,
                *vector_entry_id,
            )
            .await
            .context("failed to invalidate targeted vector entry for revocation propagation")?;
            // Phase A6: also tell the gate service to drop the entry from its
            // in-memory ANN index. The legacy/in-memory services no-op; the
            // dstack stub fails closed; the enclave services route through to
            // the underlying VectorIndex::delete, which treats "not present"
            // as a successful no-op (postcondition is "entry is gone").
            // Canonical tenant_storage_ref: must match the form the gate
            // worker used at insertion time, otherwise UsearchVectorIndex
            // would route the deletion to a different shard than the one
            // holding the entry.
            let tenant_ctx = GateTenantCtx::from_canonical(tenant_storage_ref(&tenant.tenant_id));
            state
                .gate_service
                .invalidate_vector_entry(&tenant_ctx, *vector_entry_id)
                .context("VectorInvalidationFailed")?;
            Ok(done_revocation_propagation_item(item, "invalidate_vector"))
        }
        StorageTraceRevocationPropagationAction::InvalidateBenchmarkArtifact => {
            db.invalidate_trace_submission_artifacts(
                &tenant.tenant_id,
                item.source_submission_id,
                StorageTraceDerivedStatus::Revoked,
            )
            .await
            .context("failed to invalidate benchmark artifacts for revocation propagation")?;
            db.invalidate_trace_export_manifests_for_submission(
                &tenant.tenant_id,
                item.source_submission_id,
            )
            .await
            .context("failed to invalidate benchmark manifests for revocation propagation")?;
            Ok(done_revocation_propagation_item(
                item,
                "invalidate_benchmark_artifact",
            ))
        }
        StorageTraceRevocationPropagationAction::InvalidateRankerArtifact => {
            db.invalidate_trace_submission_artifacts(
                &tenant.tenant_id,
                item.source_submission_id,
                StorageTraceDerivedStatus::Revoked,
            )
            .await
            .context("failed to invalidate ranker artifacts for revocation propagation")?;
            db.invalidate_trace_export_manifests_for_submission(
                &tenant.tenant_id,
                item.source_submission_id,
            )
            .await
            .context("failed to invalidate ranker manifests for revocation propagation")?;
            Ok(done_revocation_propagation_item(
                item,
                "invalidate_ranker_artifact",
            ))
        }
        StorageTraceRevocationPropagationAction::InvalidateWorkerQueue => {
            invalidate_worker_queue_for_revocation_propagation(state, tenant, item).await
        }
        StorageTraceRevocationPropagationAction::ReverseCreditSettlement => {
            reverse_credit_settlement_for_revocation_propagation(state, db, tenant, item).await
        }
        StorageTraceRevocationPropagationAction::DeleteObjectPayload => {
            delete_object_payload_for_revocation_propagation(state, db, tenant, item).await
        }
        StorageTraceRevocationPropagationAction::RecordPhysicalDeleteReceipt => {
            if let StorageTraceRevocationPropagationTarget::PhysicalDeleteReceipt {
                receipt_sha256,
                ..
            } = &item.target
                && !receipt_sha256.trim().is_empty()
            {
                Ok(TraceRevocationPropagationItemOutcome::Done {
                    evidence_hash: receipt_sha256.clone(),
                })
            } else {
                Ok(skipped_revocation_propagation_item(
                    item,
                    "physical delete receipt target is missing evidence",
                ))
            }
        }
    }
}

async fn invalidate_worker_queue_for_revocation_propagation(
    state: &AppState,
    tenant: &TenantAuth,
    item: &StorageTraceRevocationPropagationItemRecord,
) -> anyhow::Result<TraceRevocationPropagationItemOutcome> {
    let StorageTraceRevocationPropagationTarget::WorkerQueue {
        queue_surface,
        queue_key_hash,
    } = &item.target
    else {
        return Ok(skipped_revocation_propagation_item(
            item,
            "worker queue invalidation requires a worker-queue target",
        ));
    };
    if !is_revocation_worker_queue_surface(queue_surface) {
        return Ok(skipped_revocation_propagation_item(
            item,
            "worker queue invalidation target surface is not supported",
        ));
    }
    let expected_key_hash = trace_revocation_worker_queue_key_hash(
        &tenant.tenant_id,
        item.source_submission_id,
        queue_surface,
    );
    if queue_key_hash != &expected_key_hash {
        return Ok(skipped_revocation_propagation_item(
            item,
            "worker queue invalidation target hash does not match tenant submission",
        ));
    }
    if let Some(invalidator) = &state.worker_cache_invalidator {
        let response = invalidator
            .invalidate(TraceWorkerCacheInvalidationRequest {
                tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
                propagation_item_id: item.propagation_item_id,
                source_submission_ref_hash: sha256_prefixed(&format!(
                    "trace_revocation_worker_cache:v1:{}:{}:{queue_surface}",
                    tenant.tenant_id, item.source_submission_id
                )),
                queue_surface: queue_surface.clone(),
                queue_key_hash: queue_key_hash.clone(),
            })
            .await
            .context("failed to invalidate configured trace worker cache")?;
        let evidence_hash =
            validate_trace_sha256_hash(&response.evidence_hash, "worker cache evidence_hash")
                .map_err(|(_, Json(error))| anyhow::anyhow!(error.error))?;
        return Ok(TraceRevocationPropagationItemOutcome::Done { evidence_hash });
    }
    if state.require_external_worker_cache_invalidator {
        anyhow::bail!("worker cache invalidator is required but not configured");
    }

    Ok(done_revocation_propagation_item(
        item,
        &format!("invalidate_worker_queue:{queue_surface}"),
    ))
}

async fn reverse_credit_settlement_for_revocation_propagation(
    state: &AppState,
    db: &dyn Database,
    tenant: &TenantAuth,
    item: &StorageTraceRevocationPropagationItemRecord,
) -> anyhow::Result<TraceRevocationPropagationItemOutcome> {
    let StorageTraceRevocationPropagationTarget::CreditSettlement {
        credit_event_id,
        credit_account_ref,
        settlement_state_at_selection,
    } = &item.target
    else {
        return Ok(skipped_revocation_propagation_item(
            item,
            "credit settlement reversal requires a credit-settlement target",
        ));
    };
    let reversal_event_id = deterministic_trace_uuid_for_external_ref(
        "revocation-credit-reversal",
        &tenant.tenant_id,
        item.source_submission_id,
        &credit_event_id.to_string(),
    );
    let db_credit_events = db
        .list_trace_credit_events(&tenant.tenant_id)
        .await
        .context("failed to read trace credit events for settlement reversal")?;
    let reversal_already_mirrored = db_credit_events
        .iter()
        .any(|event| event.credit_event_id == reversal_event_id);
    let Some(source_event) = db_credit_events.iter().find(|event| {
        event.credit_event_id == *credit_event_id
            && event.submission_id == item.source_submission_id
            && event.credit_account_ref == *credit_account_ref
    }) else {
        if reversal_already_mirrored {
            return Ok(done_revocation_propagation_credit_reversal_item(
                item,
                *credit_event_id,
                reversal_event_id,
            ));
        }
        return Ok(skipped_revocation_propagation_item(
            item,
            "credit settlement target was not found for this tenant submission",
        ));
    };
    if source_event.settlement_state != *settlement_state_at_selection {
        return Ok(skipped_revocation_propagation_item(
            item,
            "credit settlement state changed before reversal",
        ));
    }
    let Some(event_type) = trace_credit_event_type_from_storage(source_event.event_type) else {
        return Ok(skipped_revocation_propagation_item(
            item,
            "credit settlement reversal supports only contributor-visible delayed credit events",
        ));
    };
    let points_delta = source_event.points_delta.parse::<f32>().with_context(|| {
        format!("failed to parse trace credit points_delta for event {credit_event_id}")
    })?;
    anyhow::ensure!(
        points_delta.is_finite(),
        "trace credit points_delta is not finite for event {credit_event_id}"
    );
    if !reversal_already_mirrored {
        let reversal_event = TraceCommonsCreditLedgerRecord {
            event_id: reversal_event_id,
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            submission_id: item.source_submission_id,
            trace_id: source_event.trace_id,
            auth_principal_ref: source_event.credit_account_ref.clone(),
            event_type,
            credit_points_delta: -points_delta,
            reason: Some(format!(
                "Credit settlement reversed for revoked trace event {credit_event_id}."
            )),
            external_ref: Some(format!(
                "{REVOCATION_CREDIT_REVERSAL_EXTERNAL_REF_PREFIX}{credit_event_id}"
            )),
            actor_role: tenant.role,
            actor_principal_ref: tenant.principal_ref.clone(),
            created_at: Utc::now(),
        };
        let file_credit_event_ids = read_all_credit_events(&state.root, &tenant.tenant_id)?
            .into_iter()
            .map(|event| event.event_id)
            .collect::<BTreeSet<_>>();
        if !file_credit_event_ids.contains(&reversal_event_id) {
            append_credit_event(&state.root, &tenant.tenant_id, &reversal_event)?;
        }
        mirror_credit_event_to_db_with_settlement_state(
            state,
            &reversal_event,
            StorageTraceCreditSettlementState::Reversed,
        )
        .await
        .context("failed to mirror reversed trace credit settlement")?;
        append_audit_event_with_db_mirror(
            state,
            tenant,
            TraceCommonsAuditEvent::credit_mutation(
                tenant,
                item.source_submission_id,
                reversal_event.credit_points_delta,
                reversal_event.reason.as_deref(),
            ),
            StorageTraceAuditAction::CreditMutate,
            StorageTraceAuditSafeMetadata::CreditMutation {
                event_type: storage_credit_event_type(reversal_event.event_type),
                credit_points_delta_micros: credit_delta_micros(reversal_event.credit_points_delta),
                reason_hash: sha256_prefixed(reversal_event.reason.as_deref().unwrap_or_default()),
                external_ref_hash: reversal_event.external_ref.as_deref().map(sha256_prefixed),
            },
        )
        .await
        .context("failed to append credit reversal audit event")?;
    }
    ensure_near_credit_reversal_outbox_item_for_revocation(
        state,
        tenant,
        source_event,
        reversal_event_id,
    )
    .await
    .context("failed to enqueue NEAR credit reversal outbox item")?;
    Ok(done_revocation_propagation_credit_reversal_item(
        item,
        *credit_event_id,
        reversal_event_id,
    ))
}

async fn ensure_near_credit_reversal_outbox_item_for_revocation(
    state: &AppState,
    tenant: &TenantAuth,
    source_event: &StorageTraceCreditEventRecord,
    reversal_event_id: Uuid,
) -> anyhow::Result<Option<Uuid>> {
    let settlement_batches = read_credit_settlement_batches_for_admin(state, tenant).await?;
    let Some((batch, line_item, contract_id)) = settlement_batches.iter().find_map(|batch| {
        let contract_id = batch.near_contract_id.as_deref()?;
        if batch.status != StorageTraceCreditSettlementBatchStatus::Finalized {
            return None;
        }
        let line_item = batch.line_items.iter().find(|line_item| {
            line_item.credit_account_ref == source_event.credit_account_ref
                && line_item
                    .source_credit_event_ids
                    .contains(&source_event.credit_event_id)
        })?;
        Some((batch, line_item, contract_id))
    }) else {
        return Ok(None);
    };
    let near_reversal_ref = format!("{}:{reversal_event_id}", source_event.credit_event_id);
    let near_outbox_id = deterministic_trace_uuid_for_external_ref(
        "near-credit-reversal-outbox",
        &tenant.tenant_id,
        source_event.submission_id,
        &near_reversal_ref,
    );
    let mut existing_outbox_ids = read_near_credit_outbox_items_for_admin(state, tenant)
        .await?
        .into_iter()
        .map(|item| item.near_outbox_id)
        .collect::<BTreeSet<_>>();
    if let Some(db) = state.db_mirror.as_ref() {
        existing_outbox_ids.extend(
            db.list_trace_near_credit_outbox_items(&tenant.tenant_id)
                .await
                .context("failed to read DB NEAR credit outbox items")?
                .into_iter()
                .map(|item| item.near_outbox_id),
        );
    }
    if existing_outbox_ids.contains(&near_outbox_id) {
        return Ok(Some(near_outbox_id));
    }
    let outbox_item = near_credit_reversal_outbox_item_from_settled_credit_event(
        &tenant.tenant_id,
        batch,
        line_item,
        source_event,
        contract_id,
        near_outbox_id,
    )?;
    append_near_credit_outbox_item_with_db_mirror(state, tenant, &outbox_item).await?;
    Ok(Some(near_outbox_id))
}

async fn delete_object_payload_for_revocation_propagation(
    state: &AppState,
    db: &dyn Database,
    tenant: &TenantAuth,
    item: &StorageTraceRevocationPropagationItemRecord,
) -> anyhow::Result<TraceRevocationPropagationItemOutcome> {
    let StorageTraceRevocationPropagationTarget::ObjectRef { object_ref_id } = &item.target else {
        return Ok(skipped_revocation_propagation_item(
            item,
            "object payload deletion requires an object-ref target",
        ));
    };
    let object_refs = db
        .list_trace_object_refs(&tenant.tenant_id, item.source_submission_id)
        .await
        .context("failed to read trace object refs for payload deletion")?;
    let Some(object_ref) = object_refs
        .into_iter()
        .find(|object_ref| object_ref.object_ref_id == *object_ref_id)
    else {
        return Ok(skipped_revocation_propagation_item(
            item,
            "object payload target is not active for this tenant submission",
        ));
    };
    anyhow::ensure!(
        object_ref.tenant_id == tenant.tenant_id
            && object_ref.submission_id == item.source_submission_id,
        "trace object ref tenant or submission mismatch"
    );
    if object_ref.deleted_at.is_some() {
        record_physical_delete_receipt_for_revocation_propagation(db, item, &object_ref).await?;
        return Ok(done_revocation_propagation_object_payload_item(
            item,
            &object_ref,
            "delete_object_payload_already_deleted",
        ));
    }
    if object_ref.object_store == TRACE_COMMONS_SERVICE_REMOTE_DISABLED_OBJECT_STORE {
        return delete_disabled_remote_object_payload_for_revocation_propagation(
            state,
            db,
            tenant,
            item,
            &object_ref,
        )
        .await;
    }
    if !is_service_owned_trace_object_store(&object_ref.object_store) {
        return Ok(skipped_revocation_propagation_item(
            item,
            revocation_payload_delete_skip_reason_for_object_store(&object_ref.object_store),
        ));
    }
    ensure_local_trace_object_ref_key_ref(&object_ref, &tenant.tenant_id)?;
    let artifact_kind = match object_ref.artifact_kind {
        StorageTraceObjectArtifactKind::SubmittedEnvelope
        | StorageTraceObjectArtifactKind::RescrubbedEnvelope
        | StorageTraceObjectArtifactKind::ReviewSnapshot => TraceArtifactKind::ContributionEnvelope,
        StorageTraceObjectArtifactKind::WorkerIntermediate => TraceArtifactKind::VectorPayload,
        StorageTraceObjectArtifactKind::BenchmarkArtifact => TraceArtifactKind::BenchmarkConversion,
        StorageTraceObjectArtifactKind::ExportArtifact => TraceArtifactKind::RankerTrainingExport,
    };
    let Some(store) = state.artifact_store.as_ref() else {
        anyhow::bail!("service-owned encrypted object store is not configured");
    };
    anyhow::ensure!(
        store.object_store_name() == object_ref.object_store,
        TRACE_OBJECT_REF_STORE_MISMATCH
    );
    let tenant_ref = tenant_storage_ref(&tenant.tenant_id);
    match artifact_kind.clone() {
        TraceArtifactKind::ContributionEnvelope => {
            store
                .get_json_by_object_key::<serde_json::Value>(
                    &tenant_ref,
                    TraceArtifactKind::ContributionEnvelope,
                    &object_ref.object_key,
                    &object_ref.content_sha256,
                )
                .map_err(|_| {
                    anyhow::anyhow!(
                        "service-owned encrypted object verification failed before deletion"
                    )
                })?;
        }
        TraceArtifactKind::VectorPayload => {
            let payload = store
                .get_json_by_object_key::<TraceVectorPayloadArtifact>(
                    &tenant_ref,
                    TraceArtifactKind::VectorPayload,
                    &object_ref.object_key,
                    &object_ref.content_sha256,
                )
                .map_err(|_| {
                    anyhow::anyhow!(
                        "service-owned encrypted object verification failed before deletion"
                    )
                })?;
            ensure_vector_payload_tenant(&payload, &tenant.tenant_id)
                .context("service-owned vector payload verification failed before deletion")?;
            anyhow::ensure!(
                payload.artifact_schema_version == TRACE_VECTOR_PAYLOAD_SCHEMA_VERSION
                    && payload.submission_id == item.source_submission_id
                    && object_ref.created_by_job_id == Some(payload.vector_entry_id),
                "service-owned vector payload verification failed before deletion"
            );
        }
        TraceArtifactKind::BenchmarkConversion => {
            let artifact = store
                .get_json_by_object_key::<TraceBenchmarkConversionArtifact>(
                    &tenant_ref,
                    TraceArtifactKind::BenchmarkConversion,
                    &object_ref.object_key,
                    &object_ref.content_sha256,
                )
                .map_err(|_| {
                    anyhow::anyhow!(
                        "service-owned encrypted object verification failed before deletion"
                    )
                })?;
            ensure_benchmark_artifact_tenant(&artifact, &tenant.tenant_id)
                .context("service-owned benchmark artifact verification failed before deletion")?;
            anyhow::ensure!(
                artifact.artifact_schema_version == TRACE_BENCHMARK_CONVERSION_SCHEMA_VERSION
                    && object_ref.created_by_job_id == Some(artifact.conversion_id)
                    && artifact
                        .source_submission_ids
                        .contains(&item.source_submission_id),
                "service-owned benchmark artifact verification failed before deletion"
            );
        }
        TraceArtifactKind::RankerTrainingExport => {
            let provenance = store
                .get_json_by_object_key::<TraceExportProvenanceManifest>(
                    &tenant_ref,
                    TraceArtifactKind::RankerTrainingExport,
                    &object_ref.object_key,
                    &object_ref.content_sha256,
                )
                .map_err(|_| {
                    anyhow::anyhow!(
                        "service-owned encrypted object verification failed before deletion"
                    )
                })?;
            ensure_export_provenance_tenant(&provenance, &tenant.tenant_id)
                .context("service-owned ranker export verification failed before deletion")?;
            anyhow::ensure!(
                matches!(
                    provenance.export_kind,
                    TraceExportProvenanceKind::RankerTrainingCandidates
                        | TraceExportProvenanceKind::RankerTrainingPairs
                ) && object_ref.created_by_job_id == Some(provenance.export_id)
                    && provenance
                        .source_submission_ids
                        .contains(&item.source_submission_id),
                "service-owned ranker export verification failed before deletion"
            );
        }
        _ => unreachable!("unsupported physical-delete artifact kind was filtered above"),
    }
    let receipt = EncryptedTraceArtifactReceipt {
        tenant_storage_ref: tenant_ref.clone(),
        artifact_kind: artifact_kind.clone(),
        object_key: object_ref.object_key.clone(),
        ciphertext_sha256: object_ref
            .content_sha256
            .strip_prefix("sha256:")
            .unwrap_or(&object_ref.content_sha256)
            .to_string(),
        encrypted_at: Utc::now(),
    };
    store
        .delete_artifact(&tenant_ref, &receipt)
        .map_err(|_| anyhow::anyhow!("service-owned encrypted object deletion failed"))?;
    db.mark_trace_object_ref_deleted(
        &tenant.tenant_id,
        item.source_submission_id,
        &object_ref.object_store,
        &object_ref.object_key,
    )
    .await
    .context("failed to mark trace object ref deleted")?;
    record_physical_delete_receipt_for_revocation_propagation(db, item, &object_ref).await?;
    Ok(done_revocation_propagation_object_payload_item(
        item,
        &object_ref,
        "delete_object_payload",
    ))
}

async fn delete_disabled_remote_object_payload_for_revocation_propagation(
    state: &AppState,
    db: &dyn Database,
    tenant: &TenantAuth,
    item: &StorageTraceRevocationPropagationItemRecord,
    object_ref: &StorageTraceObjectRefRecord,
) -> anyhow::Result<TraceRevocationPropagationItemOutcome> {
    if !is_supported_service_owned_physical_delete_artifact_kind(object_ref.artifact_kind) {
        return Ok(skipped_revocation_propagation_item(
            item,
            "object payload artifact kind is not supported for physical deletion",
        ));
    }
    let Some(deleter) = &state.remote_object_deleter else {
        return Ok(skipped_revocation_propagation_item(
            item,
            revocation_payload_delete_skip_reason_for_object_store(&object_ref.object_store),
        ));
    };
    validate_trace_sha256_hash(&object_ref.content_sha256, "remote object content_sha256")
        .map_err(|(_, Json(error))| anyhow::anyhow!(error.error))?;
    let response = deleter
        .delete_remote_object(remote_object_delete_request_for_revocation(
            tenant, item, object_ref,
        ))
        .await
        .context("failed to delete configured remote trace object")?;
    let evidence_hash = validate_trace_sha256_hash(
        &response.evidence_hash,
        "remote object delete evidence_hash",
    )
    .map_err(|(_, Json(error))| anyhow::anyhow!(error.error))?;
    if !response.deleted && !response.already_absent {
        return Ok(skipped_revocation_propagation_item(
            item,
            "remote object deleter did not confirm deletion",
        ));
    }
    db.mark_trace_object_ref_deleted(
        &tenant.tenant_id,
        item.source_submission_id,
        &object_ref.object_store,
        &object_ref.object_key,
    )
    .await
    .context("failed to mark remote trace object ref deleted")?;
    record_physical_delete_receipt_for_revocation_propagation(db, item, object_ref).await?;
    Ok(TraceRevocationPropagationItemOutcome::Done { evidence_hash })
}

fn remote_object_delete_request_for_revocation(
    tenant: &TenantAuth,
    item: &StorageTraceRevocationPropagationItemRecord,
    object_ref: &StorageTraceObjectRefRecord,
) -> TraceRemoteObjectDeleteRequest {
    TraceRemoteObjectDeleteRequest {
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        propagation_item_id: item.propagation_item_id,
        object_ref_id: object_ref.object_ref_id,
        source_submission_ref_hash: sha256_prefixed(&format!(
            "trace_remote_object_delete:v1:{}:{}:{}",
            tenant.tenant_id, item.source_submission_id, object_ref.object_ref_id
        )),
        artifact_kind: object_ref.artifact_kind,
        object_store: object_ref.object_store.clone(),
        object_key: object_ref.object_key.clone(),
        object_key_hash: sha256_prefixed(&object_ref.object_key),
        content_sha256: object_ref.content_sha256.clone(),
        encryption_key_ref_hash: sha256_prefixed(&object_ref.encryption_key_ref),
    }
}

async fn record_physical_delete_receipt_for_revocation_propagation(
    db: &dyn Database,
    item: &StorageTraceRevocationPropagationItemRecord,
    object_ref: &StorageTraceObjectRefRecord,
) -> anyhow::Result<()> {
    let receipt_sha256 = physical_delete_receipt_hash(item, object_ref);
    let mut metadata = BTreeMap::new();
    metadata.insert(
        "source_propagation_item_id".to_string(),
        item.propagation_item_id.to_string(),
    );
    metadata.insert(
        "receipt_kind".to_string(),
        "object_payload_delete".to_string(),
    );
    db.upsert_trace_revocation_propagation_item(StorageTraceRevocationPropagationItemWrite {
        tenant_id: item.tenant_id.clone(),
        propagation_item_id: deterministic_trace_uuid_for_external_ref(
            "revocation-physical-delete-receipt",
            &item.tenant_id,
            item.source_submission_id,
            &object_ref.object_ref_id.to_string(),
        ),
        source_submission_id: item.source_submission_id,
        target: StorageTraceRevocationPropagationTarget::PhysicalDeleteReceipt {
            object_ref_id: Some(object_ref.object_ref_id),
            object_store: object_ref.object_store.clone(),
            object_key: physical_delete_receipt_object_key_ref(object_ref),
            receipt_sha256: receipt_sha256.clone(),
        },
        action: StorageTraceRevocationPropagationAction::RecordPhysicalDeleteReceipt,
        status: StorageTraceRevocationPropagationItemStatus::Done,
        idempotency_key: format!(
            "{}:{}:physical-delete-receipt",
            item.source_submission_id, object_ref.object_ref_id
        ),
        reason: "service_owned_object_payload_deleted".to_string(),
        attempt_count: 1,
        last_error: None,
        next_attempt_at: None,
        completed_at: Some(Utc::now()),
        evidence_hash: Some(receipt_sha256),
        metadata,
    })
    .await
    .context("failed to record physical delete receipt")?;
    Ok(())
}

fn physical_delete_receipt_object_key_ref(object_ref: &StorageTraceObjectRefRecord) -> String {
    if object_ref.object_store == TRACE_COMMONS_SERVICE_REMOTE_DISABLED_OBJECT_STORE {
        sha256_prefixed(&object_ref.object_key)
    } else {
        object_ref.object_key.clone()
    }
}

fn physical_delete_receipt_hash(
    item: &StorageTraceRevocationPropagationItemRecord,
    object_ref: &StorageTraceObjectRefRecord,
) -> String {
    sha256_prefixed(&format!(
        "trace_physical_delete_receipt:v1:{}:{}:{}:{}:{}:{}",
        item.tenant_id,
        item.source_submission_id,
        object_ref.object_ref_id,
        object_ref.object_store,
        object_ref.object_key,
        object_ref.content_sha256
    ))
}

fn done_revocation_propagation_object_payload_item(
    item: &StorageTraceRevocationPropagationItemRecord,
    object_ref: &StorageTraceObjectRefRecord,
    label: &str,
) -> TraceRevocationPropagationItemOutcome {
    TraceRevocationPropagationItemOutcome::Done {
        evidence_hash: sha256_prefixed(&format!(
            "trace_revocation_propagation:{}:{}:{}:{}:{}:{}:{}",
            item.tenant_id,
            item.propagation_item_id,
            item.source_submission_id,
            object_ref.object_ref_id,
            object_ref.object_store,
            object_ref.object_key,
            label
        )),
    }
}

fn done_revocation_propagation_credit_reversal_item(
    item: &StorageTraceRevocationPropagationItemRecord,
    credit_event_id: Uuid,
    reversal_event_id: Uuid,
) -> TraceRevocationPropagationItemOutcome {
    TraceRevocationPropagationItemOutcome::Done {
        evidence_hash: sha256_prefixed(&format!(
            "trace_revocation_credit_reversal:v1:{}:{}:{}:{}:{}",
            item.tenant_id,
            item.propagation_item_id,
            item.source_submission_id,
            credit_event_id,
            reversal_event_id
        )),
    }
}

fn done_revocation_propagation_item(
    item: &StorageTraceRevocationPropagationItemRecord,
    label: &str,
) -> TraceRevocationPropagationItemOutcome {
    TraceRevocationPropagationItemOutcome::Done {
        evidence_hash: revocation_propagation_evidence_hash(item, label),
    }
}

fn skipped_revocation_propagation_item(
    item: &StorageTraceRevocationPropagationItemRecord,
    reason: &str,
) -> TraceRevocationPropagationItemOutcome {
    TraceRevocationPropagationItemOutcome::Skipped {
        reason: reason.to_string(),
        evidence_hash: revocation_propagation_evidence_hash(item, reason),
    }
}

fn revocation_propagation_evidence_hash(
    item: &StorageTraceRevocationPropagationItemRecord,
    label: &str,
) -> String {
    sha256_prefixed(&format!(
        "trace_revocation_propagation:{}:{}:{}:{}",
        item.tenant_id, item.propagation_item_id, item.source_submission_id, label
    ))
}

fn revocation_propagation_retry_at(now: DateTime<Utc>, attempt_count: u32) -> DateTime<Utc> {
    let delay_minutes = match attempt_count {
        0 | 1 => 5,
        2 => 15,
        3 => 60,
        _ => 360,
    };
    now + Duration::minutes(delay_minutes)
}

fn safe_worker_error(error: &anyhow::Error) -> String {
    safe_log_error_text(&error.to_string())
}

fn safe_log_error_text(error: &str) -> String {
    error
        .chars()
        .map(|ch| if ch.is_control() { ' ' } else { ch })
        .take(240)
        .collect()
}

fn safe_display_error_hash(error: &(impl std::fmt::Display + ?Sized)) -> String {
    sha256_prefixed(&safe_log_error_text(&error.to_string()))
}

fn safe_runtime_error_hash(error: &anyhow::Error) -> String {
    safe_display_error_hash(error)
}

async fn append_revocation_propagation_audit(
    state: &AppState,
    tenant: &TenantAuth,
    response: &TraceRevocationPropagationWorkerResponse,
) -> anyhow::Result<()> {
    let mut action_counts = BTreeMap::new();
    action_counts.insert(
        "checked".to_string(),
        response.checked.min(u32::MAX as usize) as u32,
    );
    action_counts.insert(
        "completed".to_string(),
        response.completed.min(u32::MAX as usize) as u32,
    );
    action_counts.insert(
        "failed".to_string(),
        response.failed.min(u32::MAX as usize) as u32,
    );
    action_counts.insert(
        "skipped".to_string(),
        response.skipped.min(u32::MAX as usize) as u32,
    );
    action_counts.insert(
        "pending".to_string(),
        response.pending.min(u32::MAX as usize) as u32,
    );
    action_counts.insert(
        "next_attempt_scheduled".to_string(),
        response.next_attempt_scheduled.min(u32::MAX as usize) as u32,
    );
    let purpose_hash = sha256_prefixed(&response.purpose);
    append_audit_event_with_db_mirror(
        state,
        tenant,
        TraceCommonsAuditEvent {
            event_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            submission_id: Uuid::nil(),
            kind: "revocation_propagation".to_string(),
            created_at: Utc::now(),
            status: None,
            actor_role: Some(tenant.role),
            actor_principal_ref: Some(tenant.principal_ref.clone()),
            reason: Some(trace_maintenance_audit_reason(
                Some(&purpose_hash),
                response.dry_run,
                &action_counts,
            )),
            export_count: Some(response.checked),
            export_id: None,
            decision_inputs_hash: None,
            previous_event_hash: None,
            event_hash: None,
        },
        StorageTraceAuditAction::Revoke,
        StorageTraceAuditSafeMetadata::Maintenance {
            surface: Some("revocation_propagation".to_string()),
            purpose_hash: Some(purpose_hash),
            dry_run: response.dry_run,
            action_counts,
        },
    )
    .await
}

/// Phase A6: map a propagation action to its stable error class label, used
/// on the typed `RevocationPropagationFailure` audit-metadata variant.
fn revocation_propagation_error_class_for(
    action: StorageTraceRevocationPropagationAction,
) -> &'static str {
    match action {
        StorageTraceRevocationPropagationAction::InvalidateVector => "VectorInvalidationFailed",
        StorageTraceRevocationPropagationAction::InvalidateMetadata => "MetadataInvalidationFailed",
        StorageTraceRevocationPropagationAction::InvalidateExportMembership => {
            "ExportInvalidationFailed"
        }
        StorageTraceRevocationPropagationAction::DeleteObjectPayload => "ObjectDeletionFailed",
        StorageTraceRevocationPropagationAction::InvalidateBenchmarkArtifact => {
            "BenchmarkArtifactInvalidationFailed"
        }
        StorageTraceRevocationPropagationAction::InvalidateRankerArtifact => {
            "RankerArtifactInvalidationFailed"
        }
        StorageTraceRevocationPropagationAction::InvalidateWorkerQueue => {
            "WorkerQueueInvalidationFailed"
        }
        StorageTraceRevocationPropagationAction::ReverseCreditSettlement => {
            "CreditSettlementReversalFailed"
        }
        StorageTraceRevocationPropagationAction::RecordPhysicalDeleteReceipt => {
            "PhysicalDeleteReceiptRecordFailed"
        }
    }
}

/// Phase A6: emit a hash-only `RevocationPropagationFailure` audit row for a
/// propagation-item attempt that errored out. Bound to the propagation item +
/// source submission so operators can grep; the raw error is hashed.
async fn append_revocation_propagation_failure_audit(
    state: &AppState,
    tenant: &TenantAuth,
    item: &StorageTraceRevocationPropagationItemRecord,
    error_class: &str,
    error: &anyhow::Error,
    attempt_count: u32,
    is_terminal: bool,
) -> anyhow::Result<()> {
    let error_hash = safe_display_error_hash(error);
    tracing::warn!(
        tenant_storage_ref = %tenant_storage_ref(&tenant.tenant_id),
        propagation_item_id = %item.propagation_item_id,
        source_submission_id = %item.source_submission_id,
        target_kind = ?item.target_kind,
        error_class = error_class,
        error_hash = %error_hash,
        attempt_count = attempt_count,
        is_terminal = is_terminal,
        "revocation propagation attempt failed"
    );
    append_audit_event_with_db_mirror(
        state,
        tenant,
        TraceCommonsAuditEvent {
            event_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            submission_id: item.source_submission_id,
            kind: "revocation_propagation_failure".to_string(),
            created_at: Utc::now(),
            status: None,
            actor_role: Some(tenant.role),
            actor_principal_ref: Some(tenant.principal_ref.clone()),
            reason: Some(format!(
                "propagation_item_id={};target_kind={:?};error_class={};attempt_count={};is_terminal={}",
                item.propagation_item_id,
                item.target_kind,
                error_class,
                attempt_count,
                is_terminal,
            )),
            export_count: None,
            export_id: None,
            decision_inputs_hash: None,
            previous_event_hash: None,
            event_hash: None,
        },
        StorageTraceAuditAction::Revoke,
        StorageTraceAuditSafeMetadata::RevocationPropagationFailure {
            propagation_item_id: item.propagation_item_id,
            source_submission_id: item.source_submission_id,
            target_kind: item.target_kind,
            action: item.action,
            error_class: error_class.to_string(),
            error_hash,
            attempt_count,
            is_terminal,
        },
    )
    .await
}

async fn mirror_expiration_to_db(
    state: &AppState,
    tenant: &TenantAuth,
    submission_id: Uuid,
    retention_ledger: Option<&mut TraceMaintenanceLedgerAccumulator>,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    let Some(record) = db
        .get_trace_submission(&tenant.tenant_id, submission_id)
        .await
        .context("failed to check trace submission before expiration mirror")?
    else {
        return Ok(());
    };
    db.update_trace_submission_status(
        &tenant.tenant_id,
        submission_id,
        StorageTraceCorpusStatus::Expired,
        &tenant.principal_ref,
        Some("retention_expired"),
    )
    .await
    .context("failed to mirror trace expiration status")?;
    let invalidation_counts = db
        .invalidate_trace_submission_artifacts(
            &tenant.tenant_id,
            submission_id,
            StorageTraceDerivedStatus::Expired,
        )
        .await
        .context("failed to mirror trace expiration artifact invalidation")?;
    let vector_entries_invalidated = db
        .invalidate_trace_vector_entries_for_submission(&tenant.tenant_id, submission_id)
        .await
        .context("failed to mirror trace expiration vector invalidation")?;
    let export_manifests_invalidated = db
        .invalidate_trace_export_manifests_for_submission(&tenant.tenant_id, submission_id)
        .await
        .context("failed to mirror trace expiration export manifest invalidation")?;
    let export_manifest_items_invalidated = db
        .invalidate_trace_export_manifest_items_for_submission(
            &tenant.tenant_id,
            submission_id,
            StorageTraceExportManifestItemInvalidationReason::Expired,
        )
        .await
        .context("failed to mirror trace expiration export manifest item invalidation")?;
    if let Some(ledger) = retention_ledger {
        ledger.record_lifecycle_item(
            record.submission_id,
            StorageTraceRetentionJobItemAction::Expire,
            "retention_expired",
            lifecycle_invalidation_action_counts(
                invalidation_counts,
                0,
                vector_entries_invalidated,
                export_manifests_invalidated,
                export_manifest_items_invalidated,
            ),
            "records_marked_expired",
        );
    }
    append_lifecycle_invalidation_audit_to_db(
        db.as_ref(),
        tenant,
        &record,
        TraceLifecycleInvalidationAuditInput {
            action: StorageTraceAuditAction::Retain,
            audit_id_label: "retention-expiration-artifact-invalidation",
            reason: "retention_expired_artifact_invalidation",
            status_count_label: "records_marked_expired",
            invalidation_counts,
            object_refs_deleted: 0,
            vector_entries_invalidated,
            export_manifests_invalidated,
            export_manifest_items_invalidated,
        },
    )
    .await?;
    Ok(())
}

async fn mirror_purge_to_db(
    state: &AppState,
    tenant: &TenantAuth,
    submission_id: Uuid,
    deleted_object_targets: &[TraceObjectDeletionTarget],
    retention_ledger: Option<&mut TraceMaintenanceLedgerAccumulator>,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    let Some(record) = db
        .get_trace_submission(&tenant.tenant_id, submission_id)
        .await
        .context("failed to check trace submission before purge mirror")?
    else {
        return Ok(());
    };
    db.update_trace_submission_status(
        &tenant.tenant_id,
        submission_id,
        StorageTraceCorpusStatus::Purged,
        &tenant.principal_ref,
        Some("retention_purged"),
    )
    .await
    .context("failed to mirror trace purge status")?;
    let invalidation_counts = db
        .invalidate_trace_submission_artifacts(
            &tenant.tenant_id,
            submission_id,
            StorageTraceDerivedStatus::Expired,
        )
        .await
        .context("failed to mirror trace purge artifact invalidation")?;
    let mut object_refs_deleted = 0u64;
    for target in deleted_object_targets {
        object_refs_deleted += db
            .mark_trace_object_ref_deleted(
                &tenant.tenant_id,
                submission_id,
                &target.object_store,
                &target.object_key,
            )
            .await
            .with_context(|| {
                format!(
                    "failed to mark purged trace object ref deleted for {}",
                    target.object_key
                )
            })?;
    }
    let vector_entries_invalidated = db
        .invalidate_trace_vector_entries_for_submission(&tenant.tenant_id, submission_id)
        .await
        .context("failed to mirror trace purge vector invalidation")?;
    let export_manifests_invalidated = db
        .invalidate_trace_export_manifests_for_submission(&tenant.tenant_id, submission_id)
        .await
        .context("failed to mirror trace purge export manifest invalidation")?;
    let export_manifest_items_invalidated = db
        .invalidate_trace_export_manifest_items_for_submission(
            &tenant.tenant_id,
            submission_id,
            StorageTraceExportManifestItemInvalidationReason::Purged,
        )
        .await
        .context("failed to mirror trace purge export manifest item invalidation")?;
    if let Some(ledger) = retention_ledger {
        ledger.record_lifecycle_item(
            record.submission_id,
            StorageTraceRetentionJobItemAction::Purge,
            "retention_purged",
            lifecycle_invalidation_action_counts(
                invalidation_counts,
                object_refs_deleted,
                vector_entries_invalidated,
                export_manifests_invalidated,
                export_manifest_items_invalidated,
            ),
            "records_marked_purged",
        );
    }
    append_lifecycle_invalidation_audit_to_db(
        db.as_ref(),
        tenant,
        &record,
        TraceLifecycleInvalidationAuditInput {
            action: StorageTraceAuditAction::Purge,
            audit_id_label: "retention-purge-artifact-invalidation",
            reason: "retention_purged_artifact_invalidation",
            status_count_label: "records_marked_purged",
            invalidation_counts,
            object_refs_deleted,
            vector_entries_invalidated,
            export_manifests_invalidated,
            export_manifest_items_invalidated,
        },
    )
    .await?;
    Ok(())
}

struct TraceLifecycleInvalidationAuditInput {
    action: StorageTraceAuditAction,
    audit_id_label: &'static str,
    reason: &'static str,
    status_count_label: &'static str,
    invalidation_counts: StorageTraceArtifactInvalidationCounts,
    object_refs_deleted: u64,
    vector_entries_invalidated: u64,
    export_manifests_invalidated: u64,
    export_manifest_items_invalidated: u64,
}

#[derive(Debug, Default)]
struct TraceMaintenanceLedgerAccumulator {
    items: Vec<TraceMaintenanceLedgerItem>,
}

impl TraceMaintenanceLedgerAccumulator {
    fn record_lifecycle_item(
        &mut self,
        submission_id: Uuid,
        action: StorageTraceRetentionJobItemAction,
        reason: &'static str,
        mut action_counts: BTreeMap<String, u32>,
        status_count_label: &'static str,
    ) {
        action_counts.insert(status_count_label.to_string(), 1);
        self.items.push(TraceMaintenanceLedgerItem {
            submission_id,
            action,
            reason: reason.to_string(),
            action_counts,
        });
    }
}

#[derive(Debug)]
struct TraceMaintenanceLedgerItem {
    submission_id: Uuid,
    action: StorageTraceRetentionJobItemAction,
    reason: String,
    action_counts: BTreeMap<String, u32>,
}

async fn append_lifecycle_invalidation_audit_to_db(
    db: &dyn Database,
    tenant: &TenantAuth,
    record: &StorageTraceSubmissionRecord,
    input: TraceLifecycleInvalidationAuditInput,
) -> anyhow::Result<()> {
    let mut action_counts = lifecycle_invalidation_action_counts(
        input.invalidation_counts,
        input.object_refs_deleted,
        input.vector_entries_invalidated,
        input.export_manifests_invalidated,
        input.export_manifest_items_invalidated,
    );
    action_counts.insert(input.status_count_label.to_string(), 1);

    db.append_trace_audit_event(StorageTraceAuditEventWrite {
        audit_event_id: deterministic_trace_uuid_for(
            input.audit_id_label,
            &record.tenant_id,
            record.submission_id,
        ),
        tenant_id: record.tenant_id.clone(),
        actor_principal_ref: tenant.principal_ref.clone(),
        actor_role: format!("{:?}", tenant.role).to_ascii_lowercase(),
        action: input.action,
        reason: Some(input.reason.to_string()),
        request_id: None,
        submission_id: Some(record.submission_id),
        object_ref_id: None,
        export_manifest_id: None,
        decision_inputs_hash: None,
        previous_event_hash: None,
        event_hash: None,
        canonical_event_json: None,
        metadata: StorageTraceAuditSafeMetadata::Maintenance {
            surface: None,
            purpose_hash: None,
            dry_run: false,
            action_counts,
        },
    })
    .await
    .context("failed to mirror trace lifecycle artifact invalidation audit")?;
    Ok(())
}

fn lifecycle_invalidation_action_counts(
    invalidation_counts: StorageTraceArtifactInvalidationCounts,
    object_refs_deleted: u64,
    vector_entries_invalidated: u64,
    export_manifests_invalidated: u64,
    export_manifest_items_invalidated: u64,
) -> BTreeMap<String, u32> {
    let mut action_counts = BTreeMap::new();
    action_counts.insert(
        "object_refs_invalidated".to_string(),
        invalidation_counts
            .object_refs_invalidated
            .min(u64::from(u32::MAX)) as u32,
    );
    action_counts.insert(
        "derived_records_invalidated".to_string(),
        invalidation_counts
            .derived_records_invalidated
            .min(u64::from(u32::MAX)) as u32,
    );
    action_counts.insert(
        "object_refs_deleted".to_string(),
        object_refs_deleted.min(u64::from(u32::MAX)) as u32,
    );
    action_counts.insert(
        "vector_entries_invalidated".to_string(),
        vector_entries_invalidated.min(u64::from(u32::MAX)) as u32,
    );
    action_counts.insert(
        "export_manifests_invalidated".to_string(),
        export_manifests_invalidated.min(u64::from(u32::MAX)) as u32,
    );
    action_counts.insert(
        "export_manifest_items_invalidated".to_string(),
        export_manifest_items_invalidated.min(u64::from(u32::MAX)) as u32,
    );
    action_counts
}

struct TraceMaintenanceLedgerWriteInput<'a> {
    retention_job_id: Uuid,
    purpose: &'a str,
    dry_run: bool,
    purge_expired_before: Option<DateTime<Utc>>,
    prune_export_cache: bool,
    max_export_age_hours: Option<i64>,
    audit_event_id: Uuid,
    maintenance_counts: TraceMaintenanceAuditCounts,
    selected_revoked_count: usize,
    selected_expired_count: usize,
    started_at: DateTime<Utc>,
    completed_at: DateTime<Utc>,
}

#[derive(Debug, Clone, Copy)]
struct TraceRetentionLedgerExpectation {
    retention_job_id: Uuid,
    expected_item_count: usize,
}

async fn write_retention_maintenance_ledger_to_db(
    state: &AppState,
    tenant: &TenantAuth,
    input: TraceMaintenanceLedgerWriteInput<'_>,
    ledger: &TraceMaintenanceLedgerAccumulator,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };

    db.upsert_trace_retention_job(StorageTraceRetentionJobWrite {
        tenant_id: tenant.tenant_id.clone(),
        retention_job_id: input.retention_job_id,
        purpose: input.purpose.to_string(),
        dry_run: input.dry_run,
        status: if input.dry_run {
            StorageTraceRetentionJobStatus::DryRun
        } else {
            StorageTraceRetentionJobStatus::Complete
        },
        requested_by_principal_ref: tenant.principal_ref.clone(),
        requested_by_role: format!("{:?}", tenant.role).to_ascii_lowercase(),
        purge_expired_before: input.purge_expired_before,
        prune_export_cache: input.prune_export_cache,
        max_export_age_hours: input.max_export_age_hours,
        audit_event_id: Some(input.audit_event_id),
        action_counts: input.maintenance_counts.action_counts(),
        selected_revoked_count: input.selected_revoked_count.min(u32::MAX as usize) as u32,
        selected_expired_count: input.selected_expired_count.min(u32::MAX as usize) as u32,
        started_at: Some(input.started_at),
        completed_at: Some(input.completed_at),
    })
    .await
    .context("failed to write trace retention job")?;

    for item in &ledger.items {
        db.upsert_trace_retention_job_item(StorageTraceRetentionJobItemWrite {
            tenant_id: tenant.tenant_id.clone(),
            retention_job_id: input.retention_job_id,
            submission_id: item.submission_id,
            action: item.action,
            status: StorageTraceRetentionJobItemStatus::Done,
            reason: item.reason.clone(),
            action_counts: item.action_counts.clone(),
            verified_at: Some(input.completed_at),
        })
        .await
        .with_context(|| {
            format!(
                "failed to write trace retention job item for submission {}",
                item.submission_id
            )
        })?;
    }

    Ok(())
}

async fn mirror_review_decision_to_db(
    state: &AppState,
    tenant: &TenantAuth,
    record: &TraceCommonsSubmissionRecord,
    envelope: &TraceContributionEnvelope,
    canonical_summary_hash: Option<String>,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    db.upsert_trace_submission(storage_submission_write_from_record(
        record,
        envelope,
        canonical_summary_hash,
    )?)
    .await
    .context("failed to mirror reviewed trace submission metadata")?;
    let (object_ref, _) = trace_object_ref_write_from_record(
        state,
        "reviewed-envelope",
        StorageTraceObjectArtifactKind::ReviewSnapshot,
        record,
        envelope,
    )?;
    db.append_trace_object_ref(object_ref)
        .await
        .context("failed to mirror reviewed trace object ref")?;
    db.update_trace_submission_status(
        &record.tenant_id,
        record.submission_id,
        storage_corpus_status(record.status),
        &tenant.principal_ref,
        Some("review_decision"),
    )
    .await
    .context("failed to mirror trace review status")?;
    Ok(())
}

async fn mirror_process_evaluation_to_db(
    state: &AppState,
    _tenant: &TenantAuth,
    record: &TraceCommonsSubmissionRecord,
    envelope: &TraceContributionEnvelope,
    input_object_ref_id: Option<Uuid>,
    input_hash: &str,
) -> anyhow::Result<Option<Uuid>> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(None);
    };
    db.upsert_trace_submission(storage_submission_write_from_record(
        record,
        envelope,
        envelope
            .embedding_analysis
            .as_ref()
            .map(|analysis| analysis.canonical_summary_hash.clone()),
    )?)
    .await
    .context("failed to mirror process-evaluated trace submission metadata")?;
    let (object_ref, output_hash) = trace_object_ref_write_from_record(
        state,
        "process-evaluated-envelope",
        StorageTraceObjectArtifactKind::SubmittedEnvelope,
        record,
        envelope,
    )?;
    let output_object_ref_id = object_ref.object_ref_id;
    db.append_trace_object_ref(object_ref)
        .await
        .context("failed to mirror process-evaluated trace object ref")?;
    let process_evaluation_worker_version = process_evaluation_worker_version(envelope);
    db.append_trace_derived_record(StorageTraceDerivedRecordWrite {
        derived_id: process_evaluation_derived_id(record, &process_evaluation_worker_version),
        tenant_id: record.tenant_id.clone(),
        submission_id: record.submission_id,
        trace_id: record.trace_id,
        status: storage_derived_status(record.status),
        worker_kind: StorageTraceWorkerKind::ProcessEvaluation,
        worker_version: process_evaluation_worker_version,
        input_object_ref: input_object_ref_id.map(|object_ref_id| {
            trace_commons_server::trace_corpus_storage::TenantScopedTraceObjectRef {
                tenant_id: record.tenant_id.clone(),
                submission_id: record.submission_id,
                object_ref_id,
            }
        }),
        input_hash: input_hash.to_string(),
        output_object_ref: Some(
            trace_commons_server::trace_corpus_storage::TenantScopedTraceObjectRef {
                tenant_id: record.tenant_id.clone(),
                submission_id: record.submission_id,
                object_ref_id: output_object_ref_id,
            },
        ),
        canonical_summary: Some(canonical_summary_for_embedding(envelope)),
        canonical_summary_hash: Some(
            envelope
                .embedding_analysis
                .as_ref()
                .map(|analysis| analysis.canonical_summary_hash.clone())
                .unwrap_or_else(|| sha256_prefixed(&canonical_summary_for_embedding(envelope))),
        ),
        summary_model: "process-evaluation-labels-v1".to_string(),
        task_success: Some(format!("{:?}", envelope.outcome.task_success)),
        privacy_risk: Some(serde_storage_string(&record.privacy_risk)?),
        event_count: Some(envelope.events.len().min(i32::MAX as usize) as i32),
        tool_sequence: envelope.replay.required_tools.clone(),
        tool_categories: envelope
            .events
            .iter()
            .filter_map(|event| event.tool_category.clone())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect(),
        coverage_tags: coverage_tags_for_envelope(envelope),
        duplicate_score: envelope
            .embedding_analysis
            .as_ref()
            .and_then(|analysis| analysis.duplicate_score),
        novelty_score: envelope
            .embedding_analysis
            .as_ref()
            .and_then(|analysis| analysis.novelty_score),
        cluster_id: envelope.embedding_analysis.as_ref().and_then(|analysis| {
            analysis
                .cluster_id
                .clone()
                .or_else(|| analysis.nearest_cluster_id.clone())
        }),
    })
    .await
    .with_context(|| {
        format!(
            "failed to mirror process evaluation derived metadata for output hash {output_hash}"
        )
    })?;
    Ok(Some(output_object_ref_id))
}

fn process_evaluation_worker_version(envelope: &TraceContributionEnvelope) -> String {
    envelope
        .process_evaluation
        .as_ref()
        .map(|labels| labels.evaluator_version.trim())
        .filter(|version| !version.is_empty())
        .unwrap_or("process-evaluation-worker-v1")
        .to_string()
}

fn process_evaluation_derived_id(
    record: &TraceCommonsSubmissionRecord,
    evaluator_version: &str,
) -> Uuid {
    deterministic_trace_uuid_for_external_ref(
        "process-evaluation",
        &record.tenant_id,
        record.submission_id,
        evaluator_version,
    )
}

