#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum TraceCorpusStatus {
    Accepted,
    Quarantined,
    // Held state: the trace is out of consumer/export/credit reach pending the
    // NEAR AI PII backstop verdict. It is NOT reviewer-eligible (distinct from
    // Quarantined) and NEVER satisfies a `== Accepted` consumer predicate. Set
    // explicitly by ingest (Task 7) and cleared by the driver (Task 6).
    AwaitingPiiBackstop,
    Rejected,
    Revoked,
    Expired,
    Purged,
}

impl TraceCorpusStatus {
    fn as_str(self) -> &'static str {
        match self {
            Self::Accepted => "accepted",
            Self::Quarantined => "quarantined",
            Self::AwaitingPiiBackstop => "awaiting_pii_backstop",
            Self::Rejected => "rejected",
            Self::Revoked => "revoked",
            Self::Expired => "expired",
            Self::Purged => "purged",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct TraceCommonsSubmissionRecord {
    tenant_id: String,
    tenant_storage_ref: String,
    #[serde(default = "legacy_principal_ref")]
    auth_principal_ref: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    submitted_tenant_scope_ref: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    contributor_pseudonym: Option<String>,
    submission_id: Uuid,
    trace_id: Uuid,
    status: TraceCorpusStatus,
    privacy_risk: ResidualPiiRisk,
    submission_score: f32,
    credit_points_pending: f32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    credit_points_final: Option<f32>,
    consent_scopes: Vec<ConsentScope>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    allowed_uses: Vec<TraceAllowedUse>,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    redaction_counts: BTreeMap<String, u32>,
    received_at: DateTime<Utc>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    review_assigned_to_principal_ref: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    review_assigned_at: Option<DateTime<Utc>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    review_lease_expires_at: Option<DateTime<Utc>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    review_due_at: Option<DateTime<Utc>>,
    #[serde(default = "default_retention_policy_id")]
    retention_policy_id: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    expires_at: Option<DateTime<Utc>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    purged_at: Option<DateTime<Utc>>,
    /// Allowlisted label for why the submission is in its current status.
    /// `None` for records written before V49; see `safe_status_reason_label`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    last_status_reason: Option<String>,
    /// Which conditions held when `privacy_risk` was decided, as allowlisted
    /// labels (#474). Written by the server's own scrub pass -- never read
    /// from the envelope, which is deserialised from contributor input.
    /// `None` means not recorded (every record written before V51), never
    /// "no condition held".
    #[serde(default, skip_serializing_if = "Option::is_none")]
    residual_risk_basis: Option<Vec<String>>,
    object_key: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    artifact_receipt: Option<EncryptedTraceArtifactReceipt>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    artifact_object_store: Option<String>,
}

impl TraceCommonsSubmissionRecord {
    fn is_revoked(&self) -> bool {
        self.status == TraceCorpusStatus::Revoked
    }

    fn is_terminal(&self) -> bool {
        matches!(
            self.status,
            TraceCorpusStatus::Revoked | TraceCorpusStatus::Expired | TraceCorpusStatus::Purged
        )
    }

    fn is_expired_at(&self, now: DateTime<Utc>) -> bool {
        self.expires_at.is_some_and(|expires_at| expires_at <= now)
            && !matches!(
                self.status,
                TraceCorpusStatus::Revoked | TraceCorpusStatus::Expired | TraceCorpusStatus::Purged
            )
    }

    fn is_export_eligible(&self) -> bool {
        self.status == TraceCorpusStatus::Accepted && !self.is_revoked()
    }

    fn is_benchmark_eligible(&self) -> bool {
        self.is_export_eligible()
    }
}

fn default_retention_policy_id() -> String {
    "private_corpus_revocable".to_string()
}

