#[derive(Debug, Serialize)]
struct TraceReviewQueueItem {
    submission_id: Uuid,
    trace_id: Uuid,
    status: TraceCorpusStatus,
    privacy_risk: ResidualPiiRisk,
    submission_score: f32,
    redaction_counts: BTreeMap<String, u32>,
    received_at: DateTime<Utc>,
    review_age_hours: i64,
    review_escalation_state: TraceReviewEscalationState,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    review_escalation_reasons: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    review_assigned_to_principal_ref: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    review_assigned_at: Option<DateTime<Utc>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    review_lease_expires_at: Option<DateTime<Utc>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    review_due_at: Option<DateTime<Utc>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    canonical_summary: Option<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    coverage_tags: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    tool_sequence: Vec<String>,
    /// Why this submission is in the queue, as an allowlisted label.
    ///
    /// `pii_backstop_attempts_exhausted` means the trace was never examined --
    /// the classifier was unreachable and its retry budget ran out -- as
    /// opposed to a filter having actually found something. Those need
    /// opposite handling, and before this field a reviewer could not tell them
    /// apart without hand-joining the audit trail. `None` on rows predating
    /// V49.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    last_status_reason: Option<String>,
    /// Which conditions held when this trace's residual risk was decided
    /// (#474). `coverage_incomplete` forcing High is correct fail-closed
    /// behaviour; being unable to TELL at review time is the defect. A
    /// reviewer should read the condition rather than infer it, because when
    /// the overwhelming majority of a queue is benign, bulk approval becomes
    /// the rational response, which is how a real finding gets waved through.
    ///
    /// Serialised even when absent, deliberately: `null` means not recorded
    /// (any trace last written before V51) and is not the same claim as `[]`,
    /// which means the pass recorded a basis and no condition held.
    #[serde(default)]
    residual_risk_basis: Option<Vec<String>>,
}

impl TraceReviewQueueItem {
    fn from_record(
        record: TraceCommonsSubmissionRecord,
        derived_by_submission: &BTreeMap<Uuid, TraceCommonsDerivedRecord>,
        now: DateTime<Utc>,
    ) -> Self {
        let escalation = trace_review_escalation(&record, now);
        let derived = derived_by_submission.get(&record.submission_id);
        Self {
            submission_id: record.submission_id,
            trace_id: record.trace_id,
            status: record.status,
            privacy_risk: record.privacy_risk,
            submission_score: record.submission_score,
            redaction_counts: record.redaction_counts,
            received_at: record.received_at,
            review_age_hours: escalation.age_hours,
            review_escalation_state: escalation.state,
            review_escalation_reasons: escalation.reasons,
            review_assigned_to_principal_ref: record.review_assigned_to_principal_ref,
            review_assigned_at: record.review_assigned_at,
            review_lease_expires_at: record.review_lease_expires_at,
            review_due_at: record.review_due_at,
            canonical_summary: derived.map(|record| record.canonical_summary.clone()),
            coverage_tags: derived
                .map(|record| record.coverage_tags.clone())
                .unwrap_or_default(),
            tool_sequence: derived
                .map(|record| record.tool_sequence.clone())
                .unwrap_or_default(),
            last_status_reason: record.last_status_reason,
            residual_risk_basis: record.residual_risk_basis,
        }
    }
}

#[derive(Debug, Serialize)]
struct TraceReviewRoutingSummary {
    tenant_storage_ref: String,
    queue_count: usize,
    available_count: usize,
    active_lease_count: usize,
    expired_lease_count: usize,
    mine_count: usize,
    unassigned_count: usize,
    by_privacy_risk: BTreeMap<String, usize>,
    by_escalation_state: BTreeMap<String, usize>,
    assignee_loads: Vec<TraceReviewRoutingAssigneeLoad>,
}

impl TraceReviewRoutingSummary {
    fn from_records(
        tenant: &TenantAuth,
        records: &[TraceCommonsSubmissionRecord],
        now: DateTime<Utc>,
    ) -> Self {
        let mut summary = Self {
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            queue_count: 0,
            available_count: 0,
            active_lease_count: 0,
            expired_lease_count: 0,
            mine_count: 0,
            unassigned_count: 0,
            by_privacy_risk: BTreeMap::new(),
            by_escalation_state: BTreeMap::new(),
            assignee_loads: Vec::new(),
        };
        let mut assignee_loads = BTreeMap::<String, TraceReviewRoutingAssigneeAccumulator>::new();
        for record in records
            .iter()
            .filter(|record| record.status == TraceCorpusStatus::Quarantined)
        {
            summary.queue_count += 1;
            *summary
                .by_privacy_risk
                .entry(residual_pii_risk_name(record.privacy_risk).to_string())
                .or_insert(0) += 1;
            let escalation = trace_review_escalation(record, now);
            *summary
                .by_escalation_state
                .entry(trace_operational_review_state_name(escalation.state).to_string())
                .or_insert(0) += 1;
            if trace_review_lease_filter_matches(
                record,
                &tenant.principal_ref,
                now,
                TraceReviewLeaseFilter::Available,
            ) {
                summary.available_count += 1;
            }
            if trace_review_lease_filter_matches(
                record,
                &tenant.principal_ref,
                now,
                TraceReviewLeaseFilter::Mine,
            ) {
                summary.mine_count += 1;
            }
            let assigned_to = record.review_assigned_to_principal_ref.as_deref();
            let is_expired = record
                .review_lease_expires_at
                .is_some_and(|expires_at| expires_at <= now);
            match assigned_to {
                Some(principal_ref) => {
                    if is_expired {
                        summary.expired_lease_count += 1;
                    } else {
                        summary.active_lease_count += 1;
                    }
                    let principal_hash = sha256_prefixed(principal_ref);
                    assignee_loads
                        .entry(principal_hash)
                        .or_default()
                        .record(escalation, is_expired);
                }
                None => summary.unassigned_count += 1,
            }
        }
        summary.assignee_loads = assignee_loads
            .into_iter()
            .map(|(principal_ref_hash, load)| load.into_summary(principal_ref_hash))
            .collect();
        summary
    }
}

#[derive(Debug, Default)]
struct TraceReviewRoutingAssigneeAccumulator {
    active_lease_count: usize,
    expired_lease_count: usize,
    urgent_count: usize,
    oldest_review_age_hours: i64,
}

impl TraceReviewRoutingAssigneeAccumulator {
    fn record(&mut self, escalation: TraceReviewEscalation, is_expired: bool) {
        if is_expired {
            self.expired_lease_count += 1;
        } else {
            self.active_lease_count += 1;
        }
        if escalation.state == TraceReviewEscalationState::Urgent {
            self.urgent_count += 1;
        }
        self.oldest_review_age_hours = self.oldest_review_age_hours.max(escalation.age_hours);
    }

    fn into_summary(self, reviewer_principal_ref_hash: String) -> TraceReviewRoutingAssigneeLoad {
        TraceReviewRoutingAssigneeLoad {
            reviewer_principal_ref_hash,
            active_lease_count: self.active_lease_count,
            expired_lease_count: self.expired_lease_count,
            urgent_count: self.urgent_count,
            oldest_review_age_hours: self.oldest_review_age_hours,
        }
    }
}

#[derive(Debug, Serialize)]
struct TraceReviewRoutingAssigneeLoad {
    reviewer_principal_ref_hash: String,
    active_lease_count: usize,
    expired_lease_count: usize,
    urgent_count: usize,
    oldest_review_age_hours: i64,
}

#[derive(Debug, Clone, Copy, Serialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum TraceReviewEscalationState {
    Fresh,
    Due,
    Overdue,
    Urgent,
}

impl TraceReviewEscalationState {
    fn rank(self) -> u8 {
        match self {
            Self::Fresh => 0,
            Self::Due => 1,
            Self::Overdue => 2,
            Self::Urgent => 3,
        }
    }
}

#[derive(Debug, Clone)]
struct TraceReviewEscalation {
    state: TraceReviewEscalationState,
    age_hours: i64,
    reasons: Vec<String>,
}

fn trace_review_escalation(
    record: &TraceCommonsSubmissionRecord,
    now: DateTime<Utc>,
) -> TraceReviewEscalation {
    let age_hours = now
        .signed_duration_since(record.received_at)
        .num_hours()
        .max(0);
    let mut reasons = Vec::new();
    let mut state = TraceReviewEscalationState::Fresh;

    match record.privacy_risk {
        ResidualPiiRisk::High => reasons.push("high_residual_pii_risk".to_string()),
        ResidualPiiRisk::Medium => reasons.push("medium_residual_pii_risk".to_string()),
        ResidualPiiRisk::Low => {}
    }

    if age_hours >= TRACE_REVIEW_DUE_AFTER_HOURS {
        state = TraceReviewEscalationState::Due;
        reasons.push("review_due_24h".to_string());
    }
    if age_hours >= TRACE_REVIEW_OVERDUE_AFTER_HOURS {
        state = TraceReviewEscalationState::Overdue;
        reasons.push("review_overdue_72h".to_string());
    }
    if record.privacy_risk == ResidualPiiRisk::High
        && age_hours >= TRACE_REVIEW_HIGH_RISK_URGENT_AFTER_HOURS
    {
        state = TraceReviewEscalationState::Urgent;
        reasons.push("high_risk_sla_4h".to_string());
    }

    TraceReviewEscalation {
        state,
        age_hours,
        reasons,
    }
}

