fn dedupe_benchmark_candidates_by_summary_hash(
    candidates: Vec<TraceBenchmarkCandidate>,
) -> Vec<TraceBenchmarkCandidate> {
    let mut representatives = Vec::new();
    let mut keyed_indexes = BTreeMap::<String, usize>::new();
    for candidate in candidates {
        let Some(key) = trace_candidate_summary_dedupe_key(&candidate.canonical_summary_hash)
        else {
            representatives.push(candidate);
            continue;
        };
        if let Some(representative_index) = keyed_indexes.get(&key).copied() {
            if benchmark_candidate_replaces_summary_representative(
                &candidate,
                &representatives[representative_index],
            ) {
                representatives[representative_index] = candidate;
            }
        } else {
            keyed_indexes.insert(key, representatives.len());
            representatives.push(candidate);
        }
    }
    representatives
}

fn benchmark_candidate_replaces_summary_representative(
    candidate: &TraceBenchmarkCandidate,
    current: &TraceBenchmarkCandidate,
) -> bool {
    let duplicate_cmp = candidate
        .duplicate_score
        .total_cmp(&current.duplicate_score);
    if duplicate_cmp != std::cmp::Ordering::Equal {
        return duplicate_cmp.is_lt();
    }
    let novelty_cmp = candidate.novelty_score.total_cmp(&current.novelty_score);
    if novelty_cmp != std::cmp::Ordering::Equal {
        return novelty_cmp.is_gt();
    }
    let submission_cmp = candidate
        .submission_score
        .total_cmp(&current.submission_score);
    if submission_cmp != std::cmp::Ordering::Equal {
        return submission_cmp.is_gt();
    }
    candidate.submission_id < current.submission_id
}

struct BenchmarkEvaluationWorkerDecision {
    status: TraceBenchmarkEvaluationStatus,
    score: f32,
    pass_count: u32,
    fail_count: u32,
}

fn benchmark_artifact_is_pending_evaluation(artifact: &TraceBenchmarkConversionArtifact) -> bool {
    artifact.registry.status == TraceBenchmarkRegistryStatus::Candidate
        && artifact.evaluation.status == TraceBenchmarkEvaluationStatus::NotRun
        && !artifact.candidates.is_empty()
}

fn benchmark_artifact_is_publishable_by_worker(
    artifact: &TraceBenchmarkConversionArtifact,
) -> bool {
    artifact.registry.status == TraceBenchmarkRegistryStatus::Candidate
        && artifact.evaluation.status == TraceBenchmarkEvaluationStatus::Passed
        && benchmark_artifact_has_publishable_evaluation_metadata(artifact)
}

fn benchmark_artifact_has_publishable_evaluation_metadata(
    artifact: &TraceBenchmarkConversionArtifact,
) -> bool {
    artifact.evaluation.evaluator_ref.is_some()
        && artifact.evaluation.evaluated_at.is_some()
        && artifact.evaluation.score.is_some()
}

fn evaluate_benchmark_artifact_for_worker(
    artifact: &TraceBenchmarkConversionArtifact,
    min_score: f32,
) -> Option<BenchmarkEvaluationWorkerDecision> {
    if artifact.candidates.is_empty() {
        return None;
    }
    let pass_count = artifact
        .candidates
        .iter()
        .filter(|candidate| benchmark_candidate_passes_structural_evaluation(candidate))
        .count();
    let fail_count = artifact.candidates.len().saturating_sub(pass_count);
    let score = pass_count as f32 / artifact.candidates.len() as f32;
    let status = if score >= min_score {
        TraceBenchmarkEvaluationStatus::Passed
    } else {
        TraceBenchmarkEvaluationStatus::Failed
    };
    Some(BenchmarkEvaluationWorkerDecision {
        status,
        score,
        pass_count: pass_count.min(u32::MAX as usize) as u32,
        fail_count: fail_count.min(u32::MAX as usize) as u32,
    })
}

fn benchmark_evaluator_request_from_artifact(
    artifact: &TraceBenchmarkConversionArtifact,
    evaluator_ref: &str,
    min_score: f32,
) -> anyhow::Result<TraceBenchmarkEvaluatorRequest> {
    let artifact_payload_hash = benchmark_artifact_payload_hash(artifact)?;
    let candidates = artifact
        .candidates
        .iter()
        .enumerate()
        .map(
            |(candidate_index, candidate)| TraceBenchmarkEvaluatorCandidate {
                candidate_index,
                canonical_summary_hash: candidate.canonical_summary_hash.clone(),
                canonical_summary: candidate.canonical_summary.clone(),
                summary_model: candidate.summary_model.clone(),
                task_success: candidate.task_success.clone(),
                event_count: candidate.event_count,
                tool_sequence: candidate.tool_sequence.clone(),
                tool_categories: candidate.tool_categories.clone(),
                coverage_tags: candidate.coverage_tags.clone(),
                novelty_score: candidate.novelty_score,
                duplicate_score: candidate.duplicate_score,
                submission_score: candidate.submission_score,
                consent_scopes: candidate.consent_scopes.clone(),
            },
        )
        .collect::<Vec<_>>();
    Ok(TraceBenchmarkEvaluatorRequest {
        tenant_storage_ref: artifact.tenant_storage_ref.clone(),
        conversion_id: artifact.conversion_id,
        artifact_schema_version: artifact.artifact_schema_version.clone(),
        artifact_payload_hash,
        source_submission_ids_hash: artifact.source_submission_ids_hash.clone(),
        purpose_hash: sha256_prefixed(&artifact.purpose),
        evaluator_ref: evaluator_ref.to_string(),
        min_score,
        candidate_count: candidates.len(),
        candidates,
    })
}

fn benchmark_evaluation_worker_decision_from_external_response(
    response: &TraceBenchmarkEvaluatorResponse,
) -> anyhow::Result<BenchmarkEvaluationWorkerDecision> {
    anyhow::ensure!(
        response.score.is_finite() && (0.0..=1.0).contains(&response.score),
        "benchmark evaluator score must be between 0 and 1"
    );
    anyhow::ensure!(
        matches!(
            response.status,
            TraceBenchmarkEvaluationStatus::Passed
                | TraceBenchmarkEvaluationStatus::Failed
                | TraceBenchmarkEvaluationStatus::Inconclusive
        ),
        "benchmark evaluator status must be passed, failed, or inconclusive"
    );
    Ok(BenchmarkEvaluationWorkerDecision {
        status: response.status,
        score: response.score,
        pass_count: response.pass_count,
        fail_count: response.fail_count,
    })
}

fn benchmark_candidate_passes_structural_evaluation(candidate: &TraceBenchmarkCandidate) -> bool {
    is_canonical_sha256_prefixed_hash(&candidate.canonical_summary_hash)
        && !candidate.canonical_summary.trim().is_empty()
        && candidate.event_count > 0
        && !candidate.task_success.trim().is_empty()
        && candidate
            .consent_scopes
            .contains(&ConsentScope::BenchmarkOnly)
}

