#[derive(Debug, Serialize)]
struct TraceCommonsTenantCreditResponse {
    tenant_id: String,
    tenant_storage_ref: String,
    accepted: usize,
    quarantined: usize,
    revoked: usize,
    rejected: usize,
    expired: usize,
    credit_points_pending: f32,
    credit_points_final: f32,
    credit_points_ledger: f32,
    credit_points_total: f32,
    credit_points_estimated: f32,
    credit_points_pending_ledger: f32,
    credit_points_settled: f32,
    credit_points_reversed: f32,
    credit_points_held: f32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    last_settlement_batch_id: Option<Uuid>,
}

#[derive(Debug, Default)]
struct TraceCreditRiskAccountAccumulator {
    pending_credit_micros: i64,
    held_credit_micros: i64,
    pending_source_event_count: usize,
    held_source_event_count: usize,
}

#[derive(Debug, Serialize)]
struct TraceCreditRiskSummaryResponse {
    tenant_id: String,
    tenant_storage_ref: String,
    settlement_max_credit_micros_per_account: Option<i64>,
    limit: usize,
    account_count: usize,
    returned_account_count: usize,
    truncated: bool,
    pending_account_count: usize,
    held_account_count: usize,
    over_cap_account_count: usize,
    pending_credit_micros: i64,
    held_credit_micros: i64,
    over_cap_credit_micros: i64,
    accounts: Vec<TraceCreditRiskAccountSummary>,
}

#[derive(Debug, Serialize)]
struct TraceCreditRiskAccountSummary {
    credit_account_hash: String,
    pending_credit_micros: i64,
    held_credit_micros: i64,
    pending_source_event_count: usize,
    held_source_event_count: usize,
    held: bool,
    over_cap: bool,
}

impl TraceCreditRiskSummaryResponse {
    fn from_account_summaries(
        tenant: &TenantAuth,
        settlement_max_credit_micros_per_account: Option<i64>,
        limit: usize,
        account_summaries: BTreeMap<String, TraceCreditRiskAccountAccumulator>,
    ) -> Self {
        let mut accounts = account_summaries
            .into_iter()
            .filter_map(|(credit_account_ref, summary)| {
                if summary.pending_credit_micros <= 0 && summary.held_credit_micros <= 0 {
                    return None;
                }
                let over_cap = settlement_max_credit_micros_per_account
                    .is_some_and(|max_micros| summary.pending_credit_micros > max_micros);
                Some(TraceCreditRiskAccountSummary {
                    credit_account_hash: sha256_prefixed(&credit_account_ref),
                    pending_credit_micros: summary.pending_credit_micros,
                    held_credit_micros: summary.held_credit_micros,
                    pending_source_event_count: summary.pending_source_event_count,
                    held_source_event_count: summary.held_source_event_count,
                    held: summary.held_credit_micros > 0,
                    over_cap,
                })
            })
            .collect::<Vec<_>>();
        accounts.sort_by(|left, right| {
            right
                .over_cap
                .cmp(&left.over_cap)
                .then_with(|| right.pending_credit_micros.cmp(&left.pending_credit_micros))
                .then_with(|| right.held_credit_micros.cmp(&left.held_credit_micros))
                .then_with(|| left.credit_account_hash.cmp(&right.credit_account_hash))
        });
        let account_count = accounts.len();
        let pending_account_count = accounts
            .iter()
            .filter(|account| account.pending_credit_micros > 0)
            .count();
        let held_account_count = accounts.iter().filter(|account| account.held).count();
        let over_cap_account_count = accounts.iter().filter(|account| account.over_cap).count();
        let pending_credit_micros = accounts
            .iter()
            .map(|account| account.pending_credit_micros)
            .sum();
        let held_credit_micros = accounts
            .iter()
            .map(|account| account.held_credit_micros)
            .sum();
        let over_cap_credit_micros = accounts
            .iter()
            .filter(|account| account.over_cap)
            .map(|account| account.pending_credit_micros)
            .sum();
        let truncated = account_count > limit;
        accounts.truncate(limit);
        let returned_account_count = accounts.len();
        Self {
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            settlement_max_credit_micros_per_account,
            limit,
            account_count,
            returned_account_count,
            truncated,
            pending_account_count,
            held_account_count,
            over_cap_account_count,
            pending_credit_micros,
            held_credit_micros,
            over_cap_credit_micros,
            accounts,
        }
    }
}

impl TraceCommonsTenantCreditResponse {
    // `account_scope` (principal-keyed events/records) and `account_id`
    // (account-keyed settlements/holds) are the two visibility keys this builder
    // needs; passing them alongside the existing record/event/settlement/hold
    // inputs crosses clippy's arg threshold. Matches the repo's existing
    // `#[allow(clippy::too_many_arguments)]` convention rather than widening the
    // CI allow-list.
    #[allow(clippy::too_many_arguments)]
    fn from_records_events_and_settlements(
        tenant_id: String,
        auth: &TenantAuth,
        account_scope: Option<&AccountPrincipalSet>,
        account_id: Option<Uuid>,
        records: Vec<TraceCommonsSubmissionRecord>,
        credit_events: &[TraceCommonsCreditLedgerRecord],
        settlement_batches: &[TraceCreditSettlementBatchRecord],
        credit_holds: &[TraceCreditHoldRecord],
    ) -> Self {
        let mut response = Self {
            tenant_storage_ref: tenant_storage_ref(&tenant_id),
            tenant_id,
            accepted: 0,
            quarantined: 0,
            revoked: 0,
            rejected: 0,
            expired: 0,
            credit_points_pending: 0.0,
            credit_points_final: 0.0,
            credit_points_ledger: 0.0,
            credit_points_total: 0.0,
            credit_points_estimated: 0.0,
            credit_points_pending_ledger: 0.0,
            credit_points_settled: 0.0,
            credit_points_reversed: 0.0,
            credit_points_held: 0.0,
            last_settlement_batch_id: None,
        };

        let delayed_credit_eligible_submission_ids = records
            .iter()
            .filter(|record| delayed_credit_applies_to_record(record))
            .map(|record| record.submission_id)
            .collect::<BTreeSet<_>>();

        for record in &records {
            match record.status {
                TraceCorpusStatus::Accepted => {
                    response.accepted += 1;
                    response.credit_points_pending += record.credit_points_pending;
                    response.credit_points_estimated += record.credit_points_pending;
                    response.credit_points_final += record.credit_points_final.unwrap_or(0.0);
                }
                // Held pending the PII backstop: no credit is accrued (it is not
                // Accepted). Reported alongside quarantined as a not-yet-accepted,
                // non-terminal pending count on this contributor credit summary.
                TraceCorpusStatus::Quarantined | TraceCorpusStatus::AwaitingPiiBackstop => {
                    response.quarantined += 1
                }
                TraceCorpusStatus::Revoked => response.revoked += 1,
                TraceCorpusStatus::Rejected => response.rejected += 1,
                TraceCorpusStatus::Expired | TraceCorpusStatus::Purged => response.expired += 1,
            }
        }

        let tenant_wide_credit_view = auth.role.can_review();
        let legacy_wildcard_principal_ref = legacy_principal_ref();
        let legacy_wildcard_principal_ref = legacy_wildcard_principal_ref.as_str();
        // Slice 3b: a credit `account_ref` is visible to this caller iff it is the
        // caller's own principal, the legacy wildcard, a principal on the caller's
        // account (active links only), OR the caller's own account-settlement key.
        // Two keying schemes flow through this closure:
        // - credit EVENTS carry a raw `auth_principal_ref` matched by the
        //   principal-set arm;
        // - SETTLEMENT line items / credit HOLDS for a linked account are re-keyed
        //   by Task 5 to `{ACCOUNT_SETTLEMENT_KEY_PREFIX}{account_id}`
        //   (`account:{uuid}`), which a principal-ref set NEVER contains — so
        //   without the account-keyed arm a linked contributor's settled/held
        //   roll-ups would zero out. The account-keyed arm is inert for the event
        //   path (an `auth_principal_ref` never has the `account:` shape).
        // `account_scope`/`account_id == None` (unlinked caller / file-only path)
        // reproduces the pre-3b own-principal predicate exactly. The SAME scope
        // drives the per-event credit filter, so the visible record list and these
        // scalar sums stay consistent.
        let account_settlement_key =
            account_id.map(|id| format!("{ACCOUNT_SETTLEMENT_KEY_PREFIX}{id}"));
        let account_ref_visible = |account_ref: &str| -> bool {
            tenant_wide_credit_view
                || auth.matches_stored_principal(account_ref)
                || account_ref == legacy_wildcard_principal_ref
                || account_scope.is_some_and(|scope| scope.contains(account_ref))
                || account_settlement_key
                    .as_deref()
                    .is_some_and(|key| account_ref == key)
        };
        let visible_settlements = settlement_batches
            .iter()
            .filter(|batch| batch.status == StorageTraceCreditSettlementBatchStatus::Finalized)
            .flat_map(|batch| {
                batch.line_items.iter().filter_map(|item| {
                    account_ref_visible(item.credit_account_ref.as_str())
                        .then_some((batch.settlement_batch_id, item))
                })
            })
            .collect::<Vec<_>>();
        let settled_credit_event_ids = visible_settlements
            .iter()
            .flat_map(|(_, item)| item.source_credit_event_ids.iter().copied())
            .collect::<BTreeSet<_>>();
        let gross_credit_points_settled: f32 = visible_settlements
            .iter()
            .map(|(_, item)| item.settled_credit_delta_micros as f32 / 1_000_000.0)
            .sum();
        response.credit_points_reversed = credit_events
            .iter()
            .filter(|event| account_ref_visible(event.auth_principal_ref.as_str()))
            .filter_map(|event| {
                let source_credit_event_id =
                    parse_revocation_credit_reversal_external_ref(event.external_ref.as_deref())?;
                (settled_credit_event_ids.contains(&source_credit_event_id)
                    && event.credit_points_delta < 0.0)
                    .then_some(-event.credit_points_delta)
            })
            .sum::<f32>();
        response.credit_points_settled =
            (gross_credit_points_settled - response.credit_points_reversed).max(0.0);
        response.last_settlement_batch_id = visible_settlements
            .iter()
            .map(|(batch_id, _)| *batch_id)
            .next_back();
        let held_account_refs = credit_holds
            .iter()
            .filter(|hold| hold.released_at.is_none())
            .filter(|hold| account_ref_visible(hold.credit_account_ref.as_str()))
            .map(|hold| hold.credit_account_ref.as_str())
            .collect::<BTreeSet<_>>();
        response.credit_points_held = credit_events
            .iter()
            .filter(|event| delayed_credit_eligible_submission_ids.contains(&event.submission_id))
            .filter(|event| !settled_credit_event_ids.contains(&event.event_id))
            .filter(|event| {
                parse_revocation_credit_reversal_external_ref(event.external_ref.as_deref())
                    .is_none()
            })
            .filter(|event| held_account_refs.contains(event.auth_principal_ref.as_str()))
            .map(|event| event.credit_points_delta)
            .sum();
        response.credit_points_pending_ledger = credit_events
            .iter()
            .filter(|event| delayed_credit_eligible_submission_ids.contains(&event.submission_id))
            .filter(|event| !settled_credit_event_ids.contains(&event.event_id))
            .filter(|event| {
                parse_revocation_credit_reversal_external_ref(event.external_ref.as_deref())
                    .is_none()
            })
            .filter(|event| !held_account_refs.contains(event.auth_principal_ref.as_str()))
            .map(|event| event.credit_points_delta)
            .sum();
        response.credit_points_ledger =
            response.credit_points_pending_ledger + response.credit_points_settled;
        response.credit_points_total = response.credit_points_final + response.credit_points_ledger;
        response
    }
}

#[derive(Debug, Serialize)]
struct TraceCommonsAnalyticsResponse {
    tenant_id: String,
    tenant_storage_ref: String,
    submissions_total: usize,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    min_cell_count: Option<usize>,
    #[serde(default, skip_serializing_if = "is_zero")]
    suppressed_cell_count: usize,
    by_status: BTreeMap<String, usize>,
    by_privacy_risk: BTreeMap<String, usize>,
    by_task_success: BTreeMap<String, usize>,
    by_tool: BTreeMap<String, usize>,
    by_tool_category: BTreeMap<String, usize>,
    coverage_tags: BTreeMap<String, usize>,
    process_evaluation: TraceProcessEvaluationAnalytics,
    privacy_budget: TraceAnalyticsPrivacyBudget,
    duplicate_groups: usize,
    average_novelty_score: f32,
}

#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
struct TraceAnalyticsPrivacyBudget {
    strategy: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    min_cell_count: Option<usize>,
    privacy_accounting_enabled: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    epsilon_micros_per_release: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    max_epsilon_micros: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    epsilon_spent_micros: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    epsilon_remaining_micros: Option<u64>,
    noise_applied: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    noise_max_delta: Option<usize>,
    noisy_cell_count: usize,
    suppressed_cell_count: usize,
    released_cell_count: usize,
    suppression_applied: bool,
    broad_release_ready: bool,
    broad_release_blocking_reasons: Vec<String>,
}

impl TraceAnalyticsPrivacyBudget {
    fn disabled(released_cell_count: usize) -> Self {
        Self {
            strategy: "k_anonymity_min_cell".to_string(),
            min_cell_count: None,
            privacy_accounting_enabled: false,
            epsilon_micros_per_release: None,
            max_epsilon_micros: None,
            epsilon_spent_micros: None,
            epsilon_remaining_micros: None,
            noise_applied: false,
            noise_max_delta: None,
            noisy_cell_count: 0,
            suppressed_cell_count: 0,
            released_cell_count,
            suppression_applied: false,
            broad_release_ready: false,
            broad_release_blocking_reasons: vec!["min_cell_count_disabled".to_string()],
        }
    }

    fn applied(
        min_cell_count: usize,
        suppressed_cell_count: usize,
        released_cell_count: usize,
    ) -> Self {
        let suppression_applied = suppressed_cell_count > 0;
        let broad_release_blocking_reasons = if suppression_applied {
            vec!["small_cells_suppressed".to_string()]
        } else {
            Vec::new()
        };
        Self {
            strategy: "k_anonymity_min_cell".to_string(),
            min_cell_count: Some(min_cell_count),
            privacy_accounting_enabled: false,
            epsilon_micros_per_release: None,
            max_epsilon_micros: None,
            epsilon_spent_micros: None,
            epsilon_remaining_micros: None,
            noise_applied: false,
            noise_max_delta: None,
            noisy_cell_count: 0,
            suppressed_cell_count,
            released_cell_count,
            suppression_applied,
            broad_release_ready: broad_release_blocking_reasons.is_empty(),
            broad_release_blocking_reasons,
        }
    }

    fn block_broad_release(&mut self, reason: &str) {
        self.broad_release_ready = false;
        if !self
            .broad_release_blocking_reasons
            .iter()
            .any(|existing| existing == reason)
        {
            self.broad_release_blocking_reasons.push(reason.to_string());
        }
    }

    fn apply_noise(&mut self, max_delta: usize, noisy_cell_count: usize) {
        self.strategy = "k_anonymity_min_cell+keyed_count_noise".to_string();
        self.noise_applied = true;
        self.noise_max_delta = Some(max_delta);
        self.noisy_cell_count = noisy_cell_count;
    }

    fn apply_privacy_accounting(
        &mut self,
        config: TraceAnalyticsPrivacyAccountingConfig,
        spent_micros: u64,
    ) {
        self.privacy_accounting_enabled = true;
        self.epsilon_micros_per_release = Some(config.epsilon_micros_per_release);
        self.max_epsilon_micros = Some(config.max_epsilon_micros);
        self.epsilon_spent_micros = Some(spent_micros);
        self.epsilon_remaining_micros =
            Some(config.max_epsilon_micros.saturating_sub(spent_micros));
    }
}

#[derive(Debug, Default, Clone, Serialize, PartialEq, Eq)]
struct TraceProcessEvaluationAnalytics {
    evaluated_traces: usize,
    by_label: BTreeMap<String, usize>,
    by_rating: BTreeMap<String, BTreeMap<String, usize>>,
    by_score_band: BTreeMap<String, usize>,
}

impl TraceProcessEvaluationAnalytics {
    fn record_coverage_tags(&mut self, coverage_tags: &[String]) {
        let mut has_process_evaluation = false;
        for tag in coverage_tags {
            if let Some(label) = tag.strip_prefix("process_label:") {
                has_process_evaluation = true;
                *self.by_label.entry(label.to_string()).or_insert(0) += 1;
                continue;
            }
            if let Some(score_band) = tag.strip_prefix("process_eval:") {
                has_process_evaluation = true;
                *self
                    .by_score_band
                    .entry(score_band.to_string())
                    .or_insert(0) += 1;
                continue;
            }
            if let Some((axis, rating)) = tag
                .strip_prefix("process_")
                .and_then(|value| value.split_once(':'))
            {
                has_process_evaluation = true;
                *self
                    .by_rating
                    .entry(axis.to_string())
                    .or_default()
                    .entry(rating.to_string())
                    .or_insert(0) += 1;
            }
        }
        if has_process_evaluation {
            self.evaluated_traces += 1;
        }
    }

    fn apply_min_cell_count(&mut self, min_cell_count: usize) -> usize {
        let mut suppressed = 0usize;
        suppressed += suppress_small_analytics_cells(&mut self.by_label, min_cell_count);
        suppressed += suppress_small_analytics_cells(&mut self.by_score_band, min_cell_count);
        let axes = self.by_rating.keys().cloned().collect::<Vec<_>>();
        for axis in axes {
            if let Some(cells) = self.by_rating.get_mut(&axis) {
                suppressed += suppress_small_analytics_cells(cells, min_cell_count);
            }
            if self.by_rating.get(&axis).is_some_and(BTreeMap::is_empty) {
                self.by_rating.remove(&axis);
            }
        }
        suppressed
    }

    fn apply_broad_release_noise(
        &mut self,
        config: &TraceAnalyticsNoiseConfig,
        tenant_storage_ref: &str,
        noisy_cell_count: &mut usize,
    ) {
        self.evaluated_traces = noisy_analytics_count(
            config,
            tenant_storage_ref,
            "process_evaluation.evaluated_traces",
            "total",
            self.evaluated_traces,
            noisy_cell_count,
        );
        apply_noisy_analytics_cells(
            &mut self.by_label,
            config,
            tenant_storage_ref,
            "process_evaluation.by_label",
            noisy_cell_count,
        );
        apply_noisy_analytics_cells(
            &mut self.by_score_band,
            config,
            tenant_storage_ref,
            "process_evaluation.by_score_band",
            noisy_cell_count,
        );
        for (axis, cells) in &mut self.by_rating {
            apply_noisy_analytics_cells(
                cells,
                config,
                tenant_storage_ref,
                &format!("process_evaluation.by_rating.{axis}"),
                noisy_cell_count,
            );
        }
    }

    fn released_cell_count(&self) -> usize {
        self.by_label.len()
            + self.by_score_band.len()
            + self.by_rating.values().map(BTreeMap::len).sum::<usize>()
    }
}

impl TraceCommonsAnalyticsResponse {
    fn from_records(
        tenant_id: String,
        records: Vec<TraceCommonsSubmissionRecord>,
        derived: Vec<TraceCommonsDerivedRecord>,
    ) -> Self {
        let mut response = Self {
            tenant_storage_ref: tenant_storage_ref(&tenant_id),
            tenant_id,
            submissions_total: records.len(),
            min_cell_count: None,
            suppressed_cell_count: 0,
            by_status: BTreeMap::new(),
            by_privacy_risk: BTreeMap::new(),
            by_task_success: BTreeMap::new(),
            by_tool: BTreeMap::new(),
            by_tool_category: BTreeMap::new(),
            coverage_tags: BTreeMap::new(),
            process_evaluation: TraceProcessEvaluationAnalytics::default(),
            privacy_budget: TraceAnalyticsPrivacyBudget::disabled(0),
            duplicate_groups: 0,
            average_novelty_score: 0.0,
        };

        for record in &records {
            *response
                .by_status
                .entry(record.status.as_str().to_string())
                .or_insert(0) += 1;
            *response
                .by_privacy_risk
                .entry(format!("{:?}", record.privacy_risk).to_ascii_lowercase())
                .or_insert(0) += 1;
        }

        let mut summary_hash_counts = BTreeMap::<String, usize>::new();
        let mut novelty_total = 0.0f32;
        for record in &derived {
            *response
                .by_task_success
                .entry(record.task_success.to_ascii_lowercase())
                .or_insert(0) += 1;
            for tool in &record.tool_sequence {
                *response.by_tool.entry(tool.clone()).or_insert(0) += 1;
            }
            for category in &record.tool_categories {
                *response
                    .by_tool_category
                    .entry(category.clone())
                    .or_insert(0) += 1;
            }
            for tag in &record.coverage_tags {
                *response.coverage_tags.entry(tag.clone()).or_insert(0) += 1;
            }
            response
                .process_evaluation
                .record_coverage_tags(&record.coverage_tags);
            *summary_hash_counts
                .entry(record.canonical_summary_hash.clone())
                .or_insert(0) += 1;
            novelty_total += record.novelty_score;
        }

        response.duplicate_groups = summary_hash_counts
            .values()
            .filter(|count| **count > 1)
            .count();
        if !derived.is_empty() {
            response.average_novelty_score = novelty_total / derived.len() as f32;
        }
        response.privacy_budget =
            TraceAnalyticsPrivacyBudget::disabled(response.released_cell_count());
        response
    }

    fn apply_min_cell_count(&mut self, min_cell_count: usize) {
        if min_cell_count <= 1 {
            self.privacy_budget = TraceAnalyticsPrivacyBudget::disabled(self.released_cell_count());
            return;
        }
        self.min_cell_count = Some(min_cell_count);
        self.suppressed_cell_count +=
            suppress_small_analytics_cells(&mut self.by_status, min_cell_count);
        self.suppressed_cell_count +=
            suppress_small_analytics_cells(&mut self.by_privacy_risk, min_cell_count);
        self.suppressed_cell_count +=
            suppress_small_analytics_cells(&mut self.by_task_success, min_cell_count);
        self.suppressed_cell_count +=
            suppress_small_analytics_cells(&mut self.by_tool, min_cell_count);
        self.suppressed_cell_count +=
            suppress_small_analytics_cells(&mut self.by_tool_category, min_cell_count);
        self.suppressed_cell_count +=
            suppress_small_analytics_cells(&mut self.coverage_tags, min_cell_count);
        self.suppressed_cell_count += self.process_evaluation.apply_min_cell_count(min_cell_count);
        self.privacy_budget = TraceAnalyticsPrivacyBudget::applied(
            min_cell_count,
            self.suppressed_cell_count,
            self.released_cell_count(),
        );
    }

    fn apply_broad_release_noise(&mut self, config: &TraceAnalyticsNoiseConfig) {
        let mut noisy_cell_count = 0usize;
        let tenant_storage_ref = self.tenant_storage_ref.clone();
        self.submissions_total = noisy_analytics_count(
            config,
            &tenant_storage_ref,
            "submissions_total",
            "total",
            self.submissions_total,
            &mut noisy_cell_count,
        );
        apply_noisy_analytics_cells(
            &mut self.by_status,
            config,
            &tenant_storage_ref,
            "by_status",
            &mut noisy_cell_count,
        );
        apply_noisy_analytics_cells(
            &mut self.by_privacy_risk,
            config,
            &tenant_storage_ref,
            "by_privacy_risk",
            &mut noisy_cell_count,
        );
        apply_noisy_analytics_cells(
            &mut self.by_task_success,
            config,
            &tenant_storage_ref,
            "by_task_success",
            &mut noisy_cell_count,
        );
        apply_noisy_analytics_cells(
            &mut self.by_tool,
            config,
            &tenant_storage_ref,
            "by_tool",
            &mut noisy_cell_count,
        );
        apply_noisy_analytics_cells(
            &mut self.by_tool_category,
            config,
            &tenant_storage_ref,
            "by_tool_category",
            &mut noisy_cell_count,
        );
        apply_noisy_analytics_cells(
            &mut self.coverage_tags,
            config,
            &tenant_storage_ref,
            "coverage_tags",
            &mut noisy_cell_count,
        );
        self.process_evaluation.apply_broad_release_noise(
            config,
            &tenant_storage_ref,
            &mut noisy_cell_count,
        );
        self.duplicate_groups = noisy_analytics_count(
            config,
            &tenant_storage_ref,
            "duplicate_groups",
            "total",
            self.duplicate_groups,
            &mut noisy_cell_count,
        );
        self.privacy_budget
            .apply_noise(config.max_delta, noisy_cell_count);
    }

    fn released_cell_count(&self) -> usize {
        self.by_status.len()
            + self.by_privacy_risk.len()
            + self.by_task_success.len()
            + self.by_tool.len()
            + self.by_tool_category.len()
            + self.coverage_tags.len()
            + self.process_evaluation.released_cell_count()
    }
}

#[derive(Debug, Serialize)]
struct TraceOperationalSummaryResponse {
    tenant_id: String,
    tenant_storage_ref: String,
    generated_at: DateTime<Utc>,
    promotion_gates: TraceOperationalPromotionGateSummary,
    object_store: TraceOperationalObjectStoreSummary,
    rollout_smoke: TraceOperationalRolloutSmokeSummary,
    revocation_propagation: TraceOperationalRevocationPropagationSummary,
    submissions: TraceOperationalSubmissionSummary,
    review_sla: TraceOperationalReviewSlaSummary,
    exports: TraceOperationalExportSummary,
    retention: TraceOperationalRetentionSummary,
    analytics: TraceOperationalAnalyticsSummary,
    vectors: TraceOperationalVectorSummary,
    benchmarks: TraceOperationalBenchmarkSummary,
    ranking: TraceOperationalRankingSummary,
    near_credit: TraceOperationalNearCreditSummary,
    delayed_credit: TraceOperationalDelayedCreditSummary,
    credit_risk: TraceOperationalCreditRiskSummary,
}

#[derive(Debug, Serialize)]
struct TraceRolloutSmokePreflightResponse {
    tenant_id: String,
    tenant_storage_ref: String,
    generated_at: DateTime<Utc>,
    rollout_smoke: TraceOperationalRolloutSmokeSummary,
    latest_evidence: Vec<TraceRolloutSmokeEvidenceResponse>,
}

struct TraceOperationalSummaryInputs<'a> {
    state: &'a AppState,
    tenant_id: String,
    records: Vec<TraceCommonsSubmissionRecord>,
    derived: Vec<TraceCommonsDerivedRecord>,
    credit_events: Vec<TraceCommonsCreditLedgerRecord>,
    credit_risk: TraceOperationalCreditRiskSummary,
    db_summary: TraceOperationalDbSummary,
    benchmark_artifacts: Vec<TraceBenchmarkConversionArtifact>,
    benchmark_registry_outbox: Vec<TraceBenchmarkRegistryOutboxItem>,
    near_credit_outbox: Vec<TraceNearCreditOutboxItem>,
    ranking: TraceOperationalRankingSummary,
    rollout_smoke_evidence: Vec<TraceRolloutSmokeEvidenceResponse>,
    revocation_propagation: TraceOperationalRevocationPropagationSummary,
    generated_at: DateTime<Utc>,
}

impl TraceOperationalSummaryResponse {
    fn from_parts(inputs: TraceOperationalSummaryInputs<'_>) -> Self {
        let submissions = TraceOperationalSubmissionSummary::from_records(&inputs.records);
        let review_sla =
            TraceOperationalReviewSlaSummary::from_records(&inputs.records, inputs.generated_at);
        let delayed_credit =
            TraceOperationalDelayedCreditSummary::from_events(&inputs.credit_events);
        let credit_risk = inputs.credit_risk;
        let exports = TraceOperationalExportSummary::from_db_summary(
            &inputs.db_summary,
            inputs.generated_at,
            inputs.state,
        );
        let retention =
            TraceOperationalRetentionSummary::from_db_summary(&inputs.db_summary, inputs.state);
        let analytics = TraceOperationalAnalyticsSummary::from_state(inputs.state);
        let object_store = TraceOperationalObjectStoreSummary::from_state(inputs.state);
        let vectors = TraceOperationalVectorSummary::from_records_and_db_summary(
            &inputs.derived,
            &inputs.db_summary,
            inputs.state,
        );
        let benchmarks = TraceOperationalBenchmarkSummary::from_artifacts_and_registry_outbox(
            &inputs.benchmark_artifacts,
            &inputs.benchmark_registry_outbox,
            TraceOperationalBenchmarkAdapterReadiness::from_state(inputs.state),
        );
        let near_credit = TraceOperationalNearCreditSummary::from_outbox(
            &inputs.near_credit_outbox,
            inputs.state.near_credit_submitter.is_some(),
            inputs.state.near_credit_submitter_auth_configured,
            inputs.state.near_credit_confirmer.is_some(),
            inputs.state.near_credit_confirmer_auth_configured,
            inputs.state.near_credit_require_adapter_auth,
        );
        let promotion_gates = TraceOperationalPromotionGateSummary::from_inputs(
            TraceOperationalPromotionGateInputs {
                state: inputs.state,
                db_summary: &inputs.db_summary,
                review_sla: &review_sla,
                exports: &exports,
                retention: &retention,
                vectors: &vectors,
                benchmarks: &benchmarks,
                ranking: &inputs.ranking,
                near_credit: &near_credit,
                delayed_credit: &delayed_credit,
                credit_risk: &credit_risk,
                revocation_propagation: &inputs.revocation_propagation,
            },
        );
        let rollout_smoke = TraceOperationalRolloutSmokeSummary::from_promotion_gates_and_evidence(
            &promotion_gates,
            &inputs.rollout_smoke_evidence,
            inputs.generated_at,
            inputs.state.near_attestation_client.is_some(),
        );
        Self {
            tenant_storage_ref: tenant_storage_ref(&inputs.tenant_id),
            tenant_id: inputs.tenant_id,
            generated_at: inputs.generated_at,
            promotion_gates,
            object_store,
            rollout_smoke,
            revocation_propagation: inputs.revocation_propagation,
            submissions,
            review_sla,
            exports,
            retention,
            analytics,
            vectors,
            benchmarks,
            ranking: inputs.ranking,
            near_credit,
            delayed_credit,
            credit_risk,
        }
    }
}

#[derive(Debug, Serialize)]
struct TraceOperationalObjectStoreSummary {
    configured: bool,
    object_store_name: Option<String>,
    io_enabled: bool,
    object_primary_eligible: bool,
    plaintext_compatibility_allowed: bool,
    versioning_required: bool,
    object_versioning_supported: bool,
    restore_after_delete_supported: bool,
    remote_object_deleter_required: bool,
    remote_object_deleter_configured: bool,
    remote_object_deleter_ready: bool,
}

impl Default for TraceOperationalObjectStoreSummary {
    fn default() -> Self {
        Self {
            configured: false,
            object_store_name: None,
            io_enabled: false,
            object_primary_eligible: false,
            plaintext_compatibility_allowed: false,
            versioning_required: false,
            object_versioning_supported: false,
            restore_after_delete_supported: false,
            remote_object_deleter_required: false,
            remote_object_deleter_configured: false,
            remote_object_deleter_ready: true,
        }
    }
}

impl TraceOperationalObjectStoreSummary {
    fn from_state(state: &AppState) -> Self {
        let remote_object_deleter_configured = state.remote_object_deleter.is_some();
        let Some(store) = state.artifact_store.as_ref() else {
            let remote_object_deleter_required = state.require_external_remote_object_deleter;
            return Self {
                versioning_required: state.require_object_store_versioning,
                remote_object_deleter_required,
                remote_object_deleter_configured,
                remote_object_deleter_ready: !remote_object_deleter_required
                    || remote_object_deleter_configured,
                ..Self::default()
            };
        };
        let remote_object_deleter_required = state.require_external_remote_object_deleter
            || store.object_store_name() == TRACE_COMMONS_SERVICE_REMOTE_DISABLED_OBJECT_STORE;
        Self {
            configured: true,
            object_store_name: Some(store.object_store_name().to_string()),
            io_enabled: store.object_io_enabled(),
            object_primary_eligible: store.object_primary_eligible(),
            plaintext_compatibility_allowed: store.plaintext_compatibility_allowed(),
            versioning_required: state.require_object_store_versioning,
            object_versioning_supported: store.object_versioning_supported(),
            restore_after_delete_supported: store.restore_after_delete_supported(),
            remote_object_deleter_required,
            remote_object_deleter_configured,
            remote_object_deleter_ready: !remote_object_deleter_required
                || remote_object_deleter_configured,
        }
    }
}

#[derive(Debug, Clone, Serialize)]
struct TraceOperationalRevocationPropagationSummary {
    latest_run_recorded: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    latest_run_at: Option<DateTime<Utc>>,
    latest_run_dry_run: bool,
    latest_checked_count: usize,
    latest_completed_count: usize,
    latest_failed_count: usize,
    latest_skipped_count: usize,
    latest_pending_count: usize,
    worker_cache_invalidator_required: bool,
    worker_cache_invalidator_configured: bool,
    worker_cache_invalidator_ready: bool,
    /// Phase A6: number of `VectorEntry` propagation items that have reached
    /// the configured retry cap (`TRACE_COMMONS_REVOCATION_PROPAGATION_MAX_ATTEMPTS`)
    /// without succeeding. Counted across all recent
    /// `revocation_propagation_failure` audit events for this tenant where the
    /// `RevocationPropagationFailure` metadata variant has
    /// `target_kind = "vector_entry"` and `is_terminal = true`. Duplicates per
    /// `propagation_item_id` are collapsed so retry exhaustion is counted once.
    revocation_propagation_terminal_failed_vector_entries: u64,
    /// Phase A6 retrofit: terminal-failed counters for the remaining
    /// propagation target kinds. Semantics match
    /// `revocation_propagation_terminal_failed_vector_entries`; each counter
    /// collapses duplicate `propagation_item_id` values so retry exhaustion
    /// is counted once per item.
    revocation_propagation_terminal_failed_object_refs: u64,
    revocation_propagation_terminal_failed_export_manifests: u64,
    revocation_propagation_terminal_failed_export_manifest_items: u64,
    revocation_propagation_terminal_failed_derived_records: u64,
    revocation_propagation_terminal_failed_benchmark_artifacts: u64,
    revocation_propagation_terminal_failed_ranker_artifacts: u64,
    revocation_propagation_terminal_failed_credit_settlements: u64,
    revocation_propagation_terminal_failed_worker_queues: u64,
    revocation_propagation_terminal_failed_physical_delete_receipts: u64,
}

impl Default for TraceOperationalRevocationPropagationSummary {
    fn default() -> Self {
        Self {
            latest_run_recorded: false,
            latest_run_at: None,
            latest_run_dry_run: false,
            latest_checked_count: 0,
            latest_completed_count: 0,
            latest_failed_count: 0,
            latest_skipped_count: 0,
            latest_pending_count: 0,
            worker_cache_invalidator_required: false,
            worker_cache_invalidator_configured: false,
            worker_cache_invalidator_ready: true,
            revocation_propagation_terminal_failed_vector_entries: 0,
            revocation_propagation_terminal_failed_object_refs: 0,
            revocation_propagation_terminal_failed_export_manifests: 0,
            revocation_propagation_terminal_failed_export_manifest_items: 0,
            revocation_propagation_terminal_failed_derived_records: 0,
            revocation_propagation_terminal_failed_benchmark_artifacts: 0,
            revocation_propagation_terminal_failed_ranker_artifacts: 0,
            revocation_propagation_terminal_failed_credit_settlements: 0,
            revocation_propagation_terminal_failed_worker_queues: 0,
            revocation_propagation_terminal_failed_physical_delete_receipts: 0,
        }
    }
}

impl TraceOperationalRevocationPropagationSummary {
    fn from_audit_events(events: &[TraceCommonsAuditEvent]) -> anyhow::Result<Self> {
        let mut latest: Option<Self> = None;
        for record in events
            .iter()
            .filter_map(trace_revocation_propagation_summary_from_audit_event)
        {
            let record = record?;
            let is_newer = latest
                .as_ref()
                .and_then(|current| current.latest_run_at)
                .is_none_or(|current| {
                    record
                        .latest_run_at
                        .is_some_and(|candidate| candidate > current)
                });
            if is_newer {
                latest = Some(record);
            }
        }
        let mut summary = latest.unwrap_or_default();
        // Phase A6 retrofit: count distinct propagation items that reached
        // the retry cap, bucketed by target kind. Reuses the hash-only
        // reason fields stamped onto each RevocationPropagationFailure audit
        // row. Duplicates per propagation_item_id are collapsed so retry
        // exhaustion is counted once.
        let mut per_kind: BTreeMap<&'static str, BTreeSet<String>> = BTreeMap::new();
        for event in events
            .iter()
            .filter(|event| event.kind == "revocation_propagation_failure")
        {
            let reason = event.reason.as_deref();
            let target_kind = trace_audit_reason_value(reason, "target_kind").unwrap_or("");
            let is_terminal = trace_audit_reason_bool(reason, "is_terminal").unwrap_or(false);
            if !is_terminal {
                continue;
            }
            let bucket = match target_kind {
                "VectorEntry" => "vector_entry",
                "ObjectRef" => "object_ref",
                "ExportManifest" => "export_manifest",
                "ExportManifestItem" => "export_manifest_item",
                "DerivedRecord" => "derived_record",
                "BenchmarkArtifact" => "benchmark_artifact",
                "RankerArtifact" => "ranker_artifact",
                "CreditSettlement" => "credit_settlement",
                "WorkerQueue" => "worker_queue",
                "PhysicalDeleteReceipt" => "physical_delete_receipt",
                _ => continue,
            };
            if let Some(item_id) = trace_audit_reason_value(reason, "propagation_item_id") {
                per_kind
                    .entry(bucket)
                    .or_default()
                    .insert(item_id.to_string());
            }
        }
        let count =
            |bucket: &str| -> u64 { per_kind.get(bucket).map(|s| s.len() as u64).unwrap_or(0) };
        summary.revocation_propagation_terminal_failed_vector_entries = count("vector_entry");
        summary.revocation_propagation_terminal_failed_object_refs = count("object_ref");
        summary.revocation_propagation_terminal_failed_export_manifests = count("export_manifest");
        summary.revocation_propagation_terminal_failed_export_manifest_items =
            count("export_manifest_item");
        summary.revocation_propagation_terminal_failed_derived_records = count("derived_record");
        summary.revocation_propagation_terminal_failed_benchmark_artifacts =
            count("benchmark_artifact");
        summary.revocation_propagation_terminal_failed_ranker_artifacts = count("ranker_artifact");
        summary.revocation_propagation_terminal_failed_credit_settlements =
            count("credit_settlement");
        summary.revocation_propagation_terminal_failed_worker_queues = count("worker_queue");
        summary.revocation_propagation_terminal_failed_physical_delete_receipts =
            count("physical_delete_receipt");
        Ok(summary)
    }
}

async fn read_revocation_propagation_summary_for_admin(
    state: &AppState,
    tenant: &TenantAuth,
) -> anyhow::Result<TraceOperationalRevocationPropagationSummary> {
    let events = if state.db_audit_reads_for_tenant(&tenant.tenant_id) {
        read_audit_events_from_db(state, tenant).await?
    } else {
        read_all_audit_events(&state.root, &tenant.tenant_id)?
    };
    let mut summary = TraceOperationalRevocationPropagationSummary::from_audit_events(&events)?;
    summary.worker_cache_invalidator_required = state.require_external_worker_cache_invalidator;
    summary.worker_cache_invalidator_configured = state.worker_cache_invalidator.is_some();
    summary.worker_cache_invalidator_ready =
        !summary.worker_cache_invalidator_required || summary.worker_cache_invalidator_configured;
    Ok(summary)
}

fn trace_revocation_propagation_summary_from_audit_event(
    event: &TraceCommonsAuditEvent,
) -> Option<anyhow::Result<TraceOperationalRevocationPropagationSummary>> {
    if event.kind != "revocation_propagation" {
        return None;
    }
    Some((|| {
        let reason = event.reason.as_deref();
        let latest_checked_count = trace_audit_reason_u32(reason, "checked")
            .context("revocation propagation audit event missing checked count")?
            as usize;
        let latest_completed_count = trace_audit_reason_u32(reason, "completed")
            .context("revocation propagation audit event missing completed count")?
            as usize;
        let latest_failed_count = trace_audit_reason_u32(reason, "failed")
            .context("revocation propagation audit event missing failed count")?
            as usize;
        let latest_skipped_count = trace_audit_reason_u32(reason, "skipped")
            .context("revocation propagation audit event missing skipped count")?
            as usize;
        let latest_pending_count = trace_audit_reason_u32(reason, "pending")
            .context("revocation propagation audit event missing pending count")?
            as usize;
        let latest_run_dry_run = trace_audit_reason_bool(reason, "dry_run").unwrap_or(false);
        Ok(TraceOperationalRevocationPropagationSummary {
            latest_run_recorded: true,
            latest_run_at: Some(event.created_at),
            latest_run_dry_run,
            latest_checked_count,
            latest_completed_count,
            latest_failed_count,
            latest_skipped_count,
            latest_pending_count,
            ..TraceOperationalRevocationPropagationSummary::default()
        })
    })())
}

/// Build the NEAR AI attestation client from env, or `None` when the
/// endpoint is not fully configured.
///
/// A partial configuration returns `None` rather than failing startup: the
/// drill's job is to name missing controls, and a boot failure would name it
/// to nobody. [`near_attestation_missing_controls`] is what turns the `None`
/// back into a list an operator can act on.
fn build_near_attestation_client_from_env() -> anyhow::Result<Option<Arc<HttpAttestationClient>>> {
    let base_url = trimmed_env(TRACE_COMMONS_NEAR_AI_BASE_URL);
    let model = trimmed_env(TRACE_COMMONS_NEAR_AI_MODEL);
    let api_key = trimmed_env(TRACE_COMMONS_NEAR_AI_API_KEY);
    let (Some(base_url), Some(model), Some(api_key)) = (base_url, model, api_key) else {
        return Ok(None);
    };
    let pccs_url =
        trimmed_env(TRACE_COMMONS_NEAR_AI_PCCS_URL).unwrap_or_else(|| INTEL_PCS_URL.to_string());
    let timeout_seconds = match trimmed_env(TRACE_COMMONS_NEAR_AI_TIMEOUT_SECONDS) {
        Some(raw) => raw.parse::<u64>().with_context(|| {
            format!("{TRACE_COMMONS_NEAR_AI_TIMEOUT_SECONDS} must be a positive integer")
        })?,
        None => TRACE_COMMONS_NEAR_AI_DEFAULT_TIMEOUT_SECONDS,
    };
    anyhow::ensure!(
        timeout_seconds > 0,
        "{TRACE_COMMONS_NEAR_AI_TIMEOUT_SECONDS} must be greater than zero"
    );
    let client = HttpAttestationClient::new(
        base_url,
        model,
        SecretString::from(api_key),
        pccs_url,
        StdDuration::from_secs(timeout_seconds),
        trimmed_env(TRACE_COMMONS_NEAR_AI_ATTESTATION_BASE_URL),
    )
    .map_err(|error| anyhow::anyhow!("{error}"))?;
    Ok(Some(Arc::new(client)))
}

fn trimmed_env(name: &str) -> Option<String> {
    std::env::var(name)
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

/// Which of the endpoint controls the drill needs are not configured.
///
/// Read from env at call time rather than cached at boot, because the only
/// thing this is used for is telling an operator what to set; process env
/// does not change underneath it.
fn near_attestation_missing_controls() -> Vec<&'static str> {
    let mut missing = Vec::new();
    if trimmed_env(TRACE_COMMONS_NEAR_AI_BASE_URL).is_none() {
        missing.push(NEAR_ATTESTATION_BASE_URL_CONTROL);
    }
    if trimmed_env(TRACE_COMMONS_NEAR_AI_MODEL).is_none() {
        missing.push(NEAR_ATTESTATION_MODEL_CONTROL);
    }
    if trimmed_env(TRACE_COMMONS_NEAR_AI_API_KEY).is_none() {
        missing.push(NEAR_ATTESTATION_API_KEY_CONTROL);
    }
    missing
}

#[derive(Debug, Default, Deserialize)]
struct TraceNearAttestationDrillRequest {
    #[serde(default)]
    purpose: Option<String>,
    #[serde(default)]
    record_evidence: bool,
}

#[derive(Debug, Serialize)]
struct TraceNearAttestationDrillResponse {
    tenant_id: String,
    tenant_storage_ref: String,
    generated_at: DateTime<Utc>,
    purpose: String,
    ready: bool,
    evidence_hash: String,
    /// Named so an operator reading a refusal knows what to set.
    expected_measurements_env: &'static str,
    /// Absent when the drill did not run at all -- a missing endpoint control
    /// or an unparseable pin set. Absent is not a pass; `ready` is false and
    /// `blocking_gaps` says why.
    #[serde(skip_serializing_if = "Option::is_none")]
    outcome: Option<NearAttestationDrillOutcome>,
    blocking_gaps: Vec<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    recorded_evidence: Option<TraceRolloutSmokeEvidenceResponse>,
}

fn near_attestation_drill_evidence_hash(
    tenant: &TenantAuth,
    purpose: &str,
    outcome: Option<&NearAttestationDrillOutcome>,
    blocking_gaps: &[String],
) -> String {
    let evidence = serde_json::json!({
        "schema": "trace_commons_near_attestation_drill.v1",
        "tenant_storage_ref": tenant_storage_ref(&tenant.tenant_id),
        "actor_principal_ref": tenant.principal_ref,
        "purpose_hash": sha256_prefixed(purpose),
        "outcome": outcome,
        "blocking_gaps": blocking_gaps,
    });
    sha256_prefixed(&evidence.to_string())
}

/// Prove the inference endpoint is the enclave we think it is.
///
/// The drill is deliberately cheap to fail and expensive only to pass: every
/// check that costs nothing runs first, and the paid completion is reached
/// only once the endpoint has been established as a TDX enclave running a
/// pinned image and answering our nonce. See
/// `docs/operator/near-attestation-drill.md`.
async fn run_near_attestation_drill(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceNearAttestationDrillRequest,
) -> ApiResult<TraceNearAttestationDrillResponse> {
    let generated_at = Utc::now();
    let purpose = request
        .purpose
        .as_deref()
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .unwrap_or("trace_commons_near_attestation_drill")
        .to_string();

    let mut blocking_gaps: Vec<String> = Vec::new();
    let mut outcome = None;

    // Fail closed on configuration before anything reaches the network, so a
    // misconfigured deployment gets a named control rather than a timeout.
    let expected = match expected_measurements_from_env() {
        Ok(expected) => expected,
        Err(error) => {
            // The error names a key, never a value.
            blocking_gaps.push(format!("expected_measurements_config_invalid:{error}"));
            None
        }
    };
    let expected_measurements_valid = blocking_gaps.is_empty();

    match state.near_attestation_client.as_ref() {
        Some(client) if expected_measurements_valid => {
            let nonce = generate_drill_nonce();
            let now_unix = state
                .near_attestation_verification_clock
                .unwrap_or(generated_at)
                .timestamp()
                .max(0) as u64;
            outcome = Some(
                run_near_attestation_drill_steps(
                    client.as_ref(),
                    expected.as_ref(),
                    &nonce,
                    now_unix,
                )
                .await,
            );
        }
        Some(_) => {}
        None => {
            let missing = near_attestation_missing_controls();
            if missing.is_empty() {
                // The endpoint controls are all set yet no client exists.
                // That should be unreachable -- both come from the same env
                // read at boot -- but an empty gap list beside `ready:false`
                // would be a refusal with no stated reason, which is worse
                // than a slightly awkward label.
                blocking_gaps.push("near_attestation_client_unavailable".to_string());
            }
            for control in missing {
                blocking_gaps.push(format!("missing_control:{control}"));
            }
        }
    }

    if let Some(outcome) = outcome.as_ref() {
        blocking_gaps.extend(outcome.blocking_steps());
    }
    let ready = blocking_gaps.is_empty() && outcome.as_ref().is_some_and(|outcome| outcome.passed);
    let evidence_hash =
        near_attestation_drill_evidence_hash(tenant, &purpose, outcome.as_ref(), &blocking_gaps);

    let mut response = TraceNearAttestationDrillResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        generated_at,
        purpose: purpose.clone(),
        ready,
        evidence_hash,
        expected_measurements_env: EXPECTED_MEASUREMENTS_ENV,
        outcome,
        blocking_gaps,
        recorded_evidence: None,
    };

    if request.record_evidence {
        let evidence = TraceRolloutSmokeEvidenceResponse {
            event_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            check_name: "near_attestation".to_string(),
            status: if response.ready {
                TraceRolloutSmokeEvidenceStatus::Passed
            } else {
                TraceRolloutSmokeEvidenceStatus::Failed
            },
            evidence_hash: response.evidence_hash.clone(),
            evidence_ref_hash: Some(sha256_prefixed(&purpose)),
            actor_principal_ref: tenant.principal_ref.clone(),
            recorded_at: Utc::now(),
        };
        append_audit_event_with_db_mirror(
            state,
            tenant,
            TraceCommonsAuditEvent::rollout_smoke_evidence(&evidence),
            StorageTraceAuditAction::Read,
            StorageTraceAuditSafeMetadata::Empty,
        )
        .await
        .map_err(internal_error)?;
        response.recorded_evidence = Some(evidence);
    }

    Ok(response)
}

async fn near_attestation_drill_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<TraceNearAttestationDrillRequest>,
) -> ApiResult<Json<TraceNearAttestationDrillResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    let response = run_near_attestation_drill(state.as_ref(), &tenant, request).await?;
    Ok(Json(response))
}

/// The rollout-smoke check name the drift probe records under.
///
/// Deliberately distinct from `near_attestation`: the two drills probe
/// different reports (`signing_algo=ecdsa` versus `ed25519`) and answer
/// different questions, and sharing a check name would let one drill's
/// evidence satisfy the other's gate.
///
/// **Advisory, and deliberately not in
/// [`TRACE_OPERATIONAL_ROLLOUT_SMOKE_REQUIRED_CHECKS`] yet.** This probe has
/// never run against the live endpoint, so we do not yet know it can pass:
/// whether our credential is even authorized for the report endpoint is one
/// of the questions it exists to answer, and per-quote collateral has never
/// been fetched for a live model enclave. A required check that turns out to
/// be structurally unpassable is permanently missing on every configured
/// deployment, and a control nobody can ever turn green teaches operators to
/// ignore red controls -- the exact failure this surface exists to prevent.
///
/// Promote it to a conditional required check -- beside `near_attestation`,
/// keyed on the NEAR AI surface being configured -- once a live run has
/// produced a baseline. Until then the evidence row is still written and
/// still hash-only; it is simply not gating anything, and
/// [`TraceOperationalRolloutSmokeSummary`] filters it out of the summary
/// entirely, so read the drill's own response.
const NEAR_ATTESTATION_KEY_DRIFT_CHECK: &str = "near_attestation_key_drift";

#[derive(Debug, Default, Deserialize)]
struct TraceNearAttestationKeyDriftDrillRequest {
    #[serde(default)]
    purpose: Option<String>,
    #[serde(default)]
    record_evidence: bool,
    /// The previous run's `outcome`, posted back verbatim.
    ///
    /// The probe keeps no state of its own: an operator stores the `outcome`
    /// object from the last run and hands it back here. Absent is the
    /// ordinary first-run case and is **not** drift -- see
    /// `baseline_compared`.
    #[serde(default)]
    baseline: Option<AttestedKeyDriftOutcome>,
}

#[derive(Debug, Serialize)]
struct TraceNearAttestationKeyDriftDrillResponse {
    tenant_id: String,
    tenant_storage_ref: String,
    generated_at: DateTime<Utc>,
    purpose: String,
    /// Whether **this run** passed every step. Says nothing about drift.
    ready: bool,
    evidence_hash: String,
    expected_measurements_env: &'static str,
    /// Absent when the probe did not run at all -- a missing endpoint control
    /// or an unparseable pin set. Absent is not a pass.
    #[serde(skip_serializing_if = "Option::is_none")]
    outcome: Option<AttestedKeyDriftOutcome>,
    /// Whether the credential this deployment holds reached the report
    /// endpoint, mirrored out of the outcome so it is answerable without
    /// reading the step list. `unauthorized` here is one of the questions the
    /// probe exists to answer and is never folded into a generic failure.
    #[serde(skip_serializing_if = "Option::is_none")]
    credential: Option<ReportCredentialVerdict>,
    /// False when no baseline was supplied. A first run has nothing to
    /// compare against; that is a baseline, not a finding.
    baseline_compared: bool,
    /// Every difference from the baseline, each named separately. Empty when
    /// `baseline_compared` is false.
    drift: Vec<AttestedKeyDrift>,
    /// The same findings as stable flat labels, for evidence and for logs. A
    /// measurement move names its register; a count change and a TCB change
    /// stay distinct from a key rotation.
    drift_labels: Vec<String>,
    drift_detected: bool,
    blocking_gaps: Vec<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    recorded_evidence: Option<TraceRolloutSmokeEvidenceResponse>,
}

/// A stable flat label for one finding.
///
/// A pure rendering of the variant the comparison already chose -- it makes no
/// judgement of its own. Registers, counts and TCB statuses are public
/// identifiers and appear in full; nothing here can reach a key, because the
/// comparison never sees one.
fn attested_key_drift_label(drift: &AttestedKeyDrift) -> String {
    match drift {
        AttestedKeyDrift::ReportUnavailable => "report_unavailable".to_string(),
        AttestedKeyDrift::CredentialRejected => "credential_rejected".to_string(),
        AttestedKeyDrift::GatewayKeyRotated => "gateway_key_rotated".to_string(),
        AttestedKeyDrift::ModelKeysRotated => "model_keys_rotated".to_string(),
        AttestedKeyDrift::ModelEntryCountChanged { before, after } => {
            format!("model_entry_count_changed:{before}->{after}")
        }
        AttestedKeyDrift::MeasurementMoved { field } => format!("measurement_moved:{field}"),
        AttestedKeyDrift::TcbStatusChanged { before, after } => {
            format!("tcb_status_changed:{before}->{after}")
        }
        AttestedKeyDrift::QuoteVerificationRegressed => "quote_verification_regressed".to_string(),
        AttestedKeyDrift::QuoteVerificationRecovered => "quote_verification_recovered".to_string(),
    }
}

/// The evidence status a probe run earns.
///
/// A named function rather than an inline conditional because the cell that
/// matters -- a run that passed every step while the keys it watches moved --
/// is not reachable from any offline fixture: a passing run needs a report
/// bound to the nonce this process generated, and no capture can be. Left
/// inline, that cell would be untested, and it is the whole point: green
/// evidence beside a moved key is worse than no evidence.
fn near_attestation_key_drift_evidence_status(
    ready: bool,
    drift_detected: bool,
) -> TraceRolloutSmokeEvidenceStatus {
    if ready && !drift_detected {
        TraceRolloutSmokeEvidenceStatus::Passed
    } else {
        TraceRolloutSmokeEvidenceStatus::Failed
    }
}

fn near_attestation_key_drift_evidence_hash(
    tenant: &TenantAuth,
    purpose: &str,
    outcome: Option<&AttestedKeyDriftOutcome>,
    drift_labels: &[String],
    blocking_gaps: &[String],
) -> String {
    let evidence = serde_json::json!({
        "schema": "trace_commons_near_attestation_key_drift_drill.v1",
        "tenant_storage_ref": tenant_storage_ref(&tenant.tenant_id),
        "actor_principal_ref": tenant.principal_ref,
        "purpose_hash": sha256_prefixed(purpose),
        "outcome": outcome,
        "drift": drift_labels,
        "blocking_gaps": blocking_gaps,
    });
    sha256_prefixed(&evidence.to_string())
}

/// Probe the per-model attested keys, and name what moved since last time.
///
/// Read-only in the strongest sense available: it fetches a report and
/// collateral, verifies quotes, and writes nothing but hash-only smoke
/// evidence. It pins no key, admits nothing, and changes no admission
/// behaviour. See `docs/operator/near-attestation-drill.md`.
async fn run_near_attestation_key_drift_drill(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceNearAttestationKeyDriftDrillRequest,
) -> ApiResult<TraceNearAttestationKeyDriftDrillResponse> {
    let generated_at = Utc::now();
    let purpose = request
        .purpose
        .as_deref()
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .unwrap_or("trace_commons_near_attestation_key_drift_drill")
        .to_string();

    let mut blocking_gaps: Vec<String> = Vec::new();
    let mut outcome = None;

    let expected = match expected_measurements_from_env() {
        Ok(expected) => expected,
        Err(error) => {
            // The error names a key, never a value.
            blocking_gaps.push(format!("expected_measurements_config_invalid:{error}"));
            None
        }
    };
    let expected_measurements_valid = blocking_gaps.is_empty();

    match state.near_attestation_key_report_client.as_ref() {
        Some(client) if expected_measurements_valid => {
            let now_unix = state
                .near_attestation_verification_clock
                .unwrap_or(generated_at)
                .timestamp()
                .max(0) as u64;
            outcome = Some(
                run_attested_key_drift_drill(
                    client.as_ref(),
                    expected.as_ref(),
                    &RandomNonce,
                    now_unix,
                )
                .await,
            );
        }
        Some(_) => {}
        None => {
            let missing = near_attestation_missing_controls();
            if missing.is_empty() {
                blocking_gaps.push("near_attestation_client_unavailable".to_string());
            }
            for control in missing {
                blocking_gaps.push(format!("missing_control:{control}"));
            }
        }
    }

    let credential = outcome.as_ref().map(|outcome| outcome.credential);
    // "The credential was refused" is one of the questions this probe exists
    // to answer. Left to `blocking_steps` alone it arrives as an HTTP-status
    // label on `report_fetched`, which is exactly the generic failure the
    // operator cannot act on.
    if credential == Some(ReportCredentialVerdict::Unauthorized) {
        blocking_gaps.push("report_credential_unauthorized".to_string());
    }
    if let Some(outcome) = outcome.as_ref() {
        blocking_gaps.extend(outcome.blocking_steps());
    }

    // Drift is compared only where there is something to compare. A first run
    // is a baseline, not a finding.
    let baseline_compared = matches!((&request.baseline, &outcome), (Some(_), Some(_)));
    let drift = match (&request.baseline, &outcome) {
        (Some(before), Some(after)) => compare_attested_key_drift(before, after),
        _ => Vec::new(),
    };
    let drift_labels: Vec<String> = drift.iter().map(attested_key_drift_label).collect();
    let drift_detected = !drift.is_empty();

    let ready = blocking_gaps.is_empty() && outcome.as_ref().is_some_and(|outcome| outcome.passed);
    let evidence_hash = near_attestation_key_drift_evidence_hash(
        tenant,
        &purpose,
        outcome.as_ref(),
        &drift_labels,
        &blocking_gaps,
    );

    let mut response = TraceNearAttestationKeyDriftDrillResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        generated_at,
        purpose: purpose.clone(),
        ready,
        evidence_hash,
        expected_measurements_env: EXPECTED_MEASUREMENTS_ENV,
        outcome,
        credential,
        baseline_compared,
        drift,
        drift_labels,
        drift_detected,
        blocking_gaps,
        recorded_evidence: None,
    };

    if request.record_evidence {
        let evidence = TraceRolloutSmokeEvidenceResponse {
            event_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            check_name: NEAR_ATTESTATION_KEY_DRIFT_CHECK.to_string(),
            // Drift against a supplied baseline is a failure of the check even
            // where every step of this run passed: the keys the client pins
            // moved, and that is the event the probe exists to catch.
            status: near_attestation_key_drift_evidence_status(
                response.ready,
                response.drift_detected,
            ),
            evidence_hash: response.evidence_hash.clone(),
            evidence_ref_hash: Some(sha256_prefixed(&purpose)),
            actor_principal_ref: tenant.principal_ref.clone(),
            recorded_at: Utc::now(),
        };
        append_audit_event_with_db_mirror(
            state,
            tenant,
            TraceCommonsAuditEvent::rollout_smoke_evidence(&evidence),
            StorageTraceAuditAction::Read,
            StorageTraceAuditSafeMetadata::Empty,
        )
        .await
        .map_err(internal_error)?;
        response.recorded_evidence = Some(evidence);
    }

    Ok(response)
}

async fn near_attestation_key_drift_drill_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<TraceNearAttestationKeyDriftDrillRequest>,
) -> ApiResult<Json<TraceNearAttestationKeyDriftDrillResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    let response = run_near_attestation_key_drift_drill(state.as_ref(), &tenant, request).await?;
    Ok(Json(response))
}

const TRACE_OPERATIONAL_ROLLOUT_SMOKE_REQUIRED_CHECKS: &[&str] = &[
    "submit_status",
    "tenant_canary_isolation",
    "contributor_credit",
    "reviewer_metadata",
    "replay_export_selection",
    "audit_reads",
    "db_reconciliation_clean",
    "rollback_flag_drill",
    "key_rotation_drill",
    "audit_chain_verification",
    "revocation_propagation",
    "retention_dry_run",
    "vector_index",
    "analytics_release",
    "benchmark_pipeline",
    "ranking_model_readiness",
    "credit_settlement",
    "near_attestation",
    "object_primary_reads",
    "object_store_migration",
    "postgres_rls_readiness",
    "delayed_credit_reversal",
    "object_deletion_refs",
    "worker_queue_invalidation",
];
/// Checks that are required only when the surface they cover is in use.
///
/// `near_attestation` proves the NEAR AI inference endpoint is the enclave we
/// pinned. A deployment that routes no inference through NEAR AI has nothing
/// for it to prove, and holding a permanently red required check over such a
/// deployment teaches operators to ignore red checks -- which is the failure
/// this whole surface exists to prevent.
///
/// This keys on **whether the surface is configured at all**, never on the
/// drill's result. A deployment that does use NEAR AI cannot opt out of a red
/// drill; there is no allow-list, no severity dial and no acknowledgement
/// flag. That distinction is the whole of it.
const TRACE_OPERATIONAL_ROLLOUT_SMOKE_CONDITIONAL_CHECKS: &[&str] = &["near_attestation"];

/// The required checks for a deployment, given which conditional surfaces it
/// has configured.
fn rollout_smoke_required_checks(near_attestation_configured: bool) -> Vec<&'static str> {
    TRACE_OPERATIONAL_ROLLOUT_SMOKE_REQUIRED_CHECKS
        .iter()
        .copied()
        .filter(|check| {
            !TRACE_OPERATIONAL_ROLLOUT_SMOKE_CONDITIONAL_CHECKS.contains(check)
                || (*check == "near_attestation" && near_attestation_configured)
        })
        .collect()
}

const TRACE_OPERATIONAL_ROLLOUT_SMOKE_EVIDENCE_MAX_AGE: Duration = Duration::hours(24);

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum TraceRolloutSmokeEvidenceStatus {
    Passed,
    Failed,
}

impl TraceRolloutSmokeEvidenceStatus {
    fn storage_name(self) -> &'static str {
        match self {
            Self::Passed => "passed",
            Self::Failed => "failed",
        }
    }

    fn from_storage_name(value: &str) -> Option<Self> {
        match value {
            "passed" => Some(Self::Passed),
            "failed" => Some(Self::Failed),
            _ => None,
        }
    }
}

#[derive(Debug, Deserialize)]
struct TraceRolloutSmokeEvidenceRequest {
    check_name: String,
    status: TraceRolloutSmokeEvidenceStatus,
    evidence_hash: String,
    #[serde(default)]
    evidence_ref: Option<String>,
}

#[derive(Debug, Default, Deserialize)]
struct TraceRolloutSmokeEvidenceQuery {
    latest_only: Option<bool>,
}

#[derive(Debug, Clone, Serialize)]
struct TraceRolloutSmokeEvidenceResponse {
    event_id: Uuid,
    tenant_id: String,
    tenant_storage_ref: String,
    check_name: String,
    status: TraceRolloutSmokeEvidenceStatus,
    evidence_hash: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    evidence_ref_hash: Option<String>,
    actor_principal_ref: String,
    recorded_at: DateTime<Utc>,
}

impl TraceRolloutSmokeEvidenceResponse {
    fn from_request(
        tenant: &TenantAuth,
        request: TraceRolloutSmokeEvidenceRequest,
    ) -> ApiResult<Self> {
        let check_name = validate_rollout_smoke_check_name(&request.check_name)?;
        let evidence_hash = validate_rollout_smoke_evidence_hash(&request.evidence_hash)?;
        let evidence_ref_hash = request
            .evidence_ref
            .as_deref()
            .map(str::trim)
            .filter(|evidence_ref| !evidence_ref.is_empty())
            .map(sha256_prefixed);
        Ok(Self {
            event_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            check_name,
            status: request.status,
            evidence_hash,
            evidence_ref_hash,
            actor_principal_ref: tenant.principal_ref.clone(),
            recorded_at: Utc::now(),
        })
    }
}

fn validate_rollout_smoke_check_name(value: &str) -> ApiResult<String> {
    let value = value.trim();
    if TRACE_OPERATIONAL_ROLLOUT_SMOKE_REQUIRED_CHECKS.contains(&value) {
        Ok(value.to_string())
    } else {
        Err(api_error(
            StatusCode::BAD_REQUEST,
            "rollout smoke evidence check_name is not a required smoke check",
        ))
    }
}

fn validate_rollout_smoke_evidence_hash(value: &str) -> ApiResult<String> {
    let value = value.trim();
    if is_canonical_sha256_prefixed_hash(value) {
        Ok(value.to_string())
    } else {
        Err(api_error(
            StatusCode::BAD_REQUEST,
            "rollout smoke evidence_hash must be a canonical sha256-prefixed hex digest",
        ))
    }
}

async fn read_rollout_smoke_evidence_for_admin(
    state: &AppState,
    tenant: &TenantAuth,
) -> anyhow::Result<Vec<TraceRolloutSmokeEvidenceResponse>> {
    let events = if state.db_audit_reads_for_tenant(&tenant.tenant_id) {
        read_audit_events_from_db(state, tenant).await?
    } else {
        read_all_audit_events(&state.root, &tenant.tenant_id)?
    };
    events
        .iter()
        .filter_map(trace_rollout_smoke_evidence_from_audit_event)
        .collect()
}

fn latest_rollout_smoke_evidence_by_check(
    evidence: Vec<TraceRolloutSmokeEvidenceResponse>,
) -> Vec<TraceRolloutSmokeEvidenceResponse> {
    latest_rollout_smoke_evidence_map(evidence.iter())
        .into_values()
        .cloned()
        .collect()
}

fn latest_rollout_smoke_evidence_map<'a>(
    evidence: impl IntoIterator<Item = &'a TraceRolloutSmokeEvidenceResponse>,
) -> BTreeMap<String, &'a TraceRolloutSmokeEvidenceResponse> {
    let mut latest_by_check = BTreeMap::new();
    for record in evidence {
        latest_by_check
            .entry(record.check_name.clone())
            .and_modify(|current: &mut &'a TraceRolloutSmokeEvidenceResponse| {
                if rollout_smoke_evidence_is_newer(record, current) {
                    *current = record;
                }
            })
            .or_insert(record);
    }
    latest_by_check
}

fn rollout_smoke_evidence_is_newer(
    candidate: &TraceRolloutSmokeEvidenceResponse,
    current: &TraceRolloutSmokeEvidenceResponse,
) -> bool {
    // Break timestamp ties with the event id so replayed evidence resolves deterministically.
    (candidate.recorded_at, candidate.event_id) > (current.recorded_at, current.event_id)
}

fn trace_rollout_smoke_evidence_from_audit_event(
    event: &TraceCommonsAuditEvent,
) -> Option<anyhow::Result<TraceRolloutSmokeEvidenceResponse>> {
    let reason = event.reason.as_deref();
    if event.kind != "rollout_smoke_evidence"
        && trace_audit_reason_value(reason, "surface") != Some("rollout_smoke_evidence")
    {
        return None;
    }
    Some((|| {
        let check_name = trace_audit_reason_value(reason, "check_name")
            .context("rollout smoke evidence audit event missing check_name")?
            .to_string();
        anyhow::ensure!(
            TRACE_OPERATIONAL_ROLLOUT_SMOKE_REQUIRED_CHECKS.contains(&check_name.as_str()),
            "rollout smoke evidence audit event has unsupported check_name"
        );
        let status = TraceRolloutSmokeEvidenceStatus::from_storage_name(
            trace_audit_reason_value(reason, "status")
                .context("rollout smoke evidence audit event missing status")?,
        )
        .context("rollout smoke evidence audit event has unsupported status")?;
        let evidence_hash = trace_audit_reason_value(reason, "evidence_hash")
            .context("rollout smoke evidence audit event missing evidence_hash")?
            .to_string();
        anyhow::ensure!(
            is_canonical_sha256_prefixed_hash(&evidence_hash),
            "rollout smoke evidence audit event has unsupported evidence_hash"
        );
        let evidence_ref_hash =
            trace_audit_reason_value(reason, "evidence_ref_hash").map(ToOwned::to_owned);
        if let Some(evidence_ref_hash) = evidence_ref_hash.as_deref() {
            anyhow::ensure!(
                is_canonical_sha256_prefixed_hash(evidence_ref_hash),
                "rollout smoke evidence audit event has unsupported evidence_ref_hash"
            );
        }
        Ok(TraceRolloutSmokeEvidenceResponse {
            event_id: event.event_id,
            tenant_id: event.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&event.tenant_id),
            check_name,
            status,
            evidence_hash,
            evidence_ref_hash,
            actor_principal_ref: event.actor_principal_ref.clone().unwrap_or_default(),
            recorded_at: event.created_at,
        })
    })())
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalRolloutSmokeSummary {
    ready: bool,
    evidence_status: String,
    promotion_gate_ready: bool,
    promotion_gate_blocking_count: usize,
    promotion_gate_warning_count: usize,
    required_check_count: usize,
    missing_evidence_count: usize,
    recorded_evidence_count: usize,
    passed_evidence_count: usize,
    failed_evidence_count: usize,
    stale_evidence_count: usize,
    required_checks: Vec<String>,
    /// Conditional checks this deployment does not require, and why they are
    /// absent from `required_checks`. Reported rather than silently omitted:
    /// a check that vanished from the list without a word would be
    /// indistinguishable from one that was quietly dropped.
    not_applicable_checks: Vec<String>,
    passed_evidence_checks: Vec<String>,
    missing_evidence_checks: Vec<String>,
    failed_evidence_checks: Vec<String>,
    stale_evidence_checks: Vec<String>,
    blocker_reasons: Vec<String>,
}

impl TraceOperationalRolloutSmokeSummary {
    fn from_promotion_gates_and_evidence(
        promotion_gates: &TraceOperationalPromotionGateSummary,
        evidence: &[TraceRolloutSmokeEvidenceResponse],
        generated_at: DateTime<Utc>,
        near_attestation_configured: bool,
    ) -> Self {
        let applicable = rollout_smoke_required_checks(near_attestation_configured);
        let required_checks = applicable
            .iter()
            .map(|check| (*check).to_string())
            .collect::<Vec<_>>();
        let not_applicable_checks = TRACE_OPERATIONAL_ROLLOUT_SMOKE_REQUIRED_CHECKS
            .iter()
            .filter(|check| !applicable.contains(check))
            .map(|check| (*check).to_string())
            .collect::<Vec<_>>();
        // Evidence for a check this deployment does not require must not
        // count towards stale or failed either -- it is not a gap, and
        // counting it would reintroduce the red check by another route.
        let latest_evidence_by_check = latest_rollout_smoke_evidence_map(
            evidence
                .iter()
                .filter(|record| applicable.contains(&record.check_name.as_str())),
        );
        let stale_evidence_checks = latest_evidence_by_check
            .iter()
            .filter_map(|(check, record)| {
                rollout_smoke_evidence_is_stale(record, generated_at).then_some(check.clone())
            })
            .collect::<Vec<_>>();
        let stale_evidence_check_set = stale_evidence_checks
            .iter()
            .map(String::as_str)
            .collect::<BTreeSet<_>>();
        let passed_evidence_checks = latest_evidence_by_check
            .iter()
            .filter_map(|(check, record)| {
                (record.status == TraceRolloutSmokeEvidenceStatus::Passed
                    && !stale_evidence_check_set.contains(check.as_str()))
                .then_some(check.clone())
            })
            .collect::<Vec<_>>();
        let failed_evidence_checks = latest_evidence_by_check
            .iter()
            .filter_map(|(check, record)| {
                (record.status == TraceRolloutSmokeEvidenceStatus::Failed
                    && !stale_evidence_check_set.contains(check.as_str()))
                .then_some(check.clone())
            })
            .collect::<Vec<_>>();
        let missing_evidence_checks = required_checks
            .iter()
            .filter(|check| !latest_evidence_by_check.contains_key(check.as_str()))
            .cloned()
            .collect::<Vec<_>>();
        let mut blocker_reasons = promotion_gates
            .blocking_gates
            .iter()
            .map(|gate| format!("promotion_gate_blocked:{gate}"))
            .collect::<Vec<_>>();
        push_gap_count(
            &mut blocker_reasons,
            "smoke_rehearsal_evidence_missing",
            missing_evidence_checks.len(),
        );
        push_gap_count(
            &mut blocker_reasons,
            "smoke_rehearsal_evidence_failed",
            failed_evidence_checks.len(),
        );
        push_gap_count(
            &mut blocker_reasons,
            "smoke_rehearsal_evidence_stale",
            stale_evidence_checks.len(),
        );
        let evidence_status = if !promotion_gates.ready {
            "promotion_gates_blocked"
        } else if !failed_evidence_checks.is_empty() {
            "failed_rehearsal_evidence"
        } else if !stale_evidence_checks.is_empty() {
            "stale_rehearsal_evidence"
        } else if missing_evidence_checks.is_empty() {
            "ready"
        } else {
            "missing_rehearsal_evidence"
        };

        Self {
            ready: promotion_gates.ready
                && missing_evidence_checks.is_empty()
                && failed_evidence_checks.is_empty()
                && stale_evidence_checks.is_empty(),
            evidence_status: evidence_status.to_string(),
            promotion_gate_ready: promotion_gates.ready,
            promotion_gate_blocking_count: promotion_gates.blocking_count,
            promotion_gate_warning_count: promotion_gates.warning_count,
            required_check_count: required_checks.len(),
            missing_evidence_count: missing_evidence_checks.len(),
            recorded_evidence_count: latest_evidence_by_check.len(),
            passed_evidence_count: passed_evidence_checks.len(),
            failed_evidence_count: failed_evidence_checks.len(),
            stale_evidence_count: stale_evidence_checks.len(),
            required_checks,
            not_applicable_checks,
            passed_evidence_checks,
            missing_evidence_checks,
            failed_evidence_checks,
            stale_evidence_checks,
            blocker_reasons,
        }
    }
}

fn rollout_smoke_evidence_is_stale(
    evidence: &TraceRolloutSmokeEvidenceResponse,
    generated_at: DateTime<Utc>,
) -> bool {
    generated_at - evidence.recorded_at > TRACE_OPERATIONAL_ROLLOUT_SMOKE_EVIDENCE_MAX_AGE
}

