struct TraceOperationalPromotionGateInputs<'a> {
    state: &'a AppState,
    db_summary: &'a TraceOperationalDbSummary,
    review_sla: &'a TraceOperationalReviewSlaSummary,
    exports: &'a TraceOperationalExportSummary,
    retention: &'a TraceOperationalRetentionSummary,
    vectors: &'a TraceOperationalVectorSummary,
    benchmarks: &'a TraceOperationalBenchmarkSummary,
    ranking: &'a TraceOperationalRankingSummary,
    near_credit: &'a TraceOperationalNearCreditSummary,
    delayed_credit: &'a TraceOperationalDelayedCreditSummary,
    credit_risk: &'a TraceOperationalCreditRiskSummary,
    revocation_propagation: &'a TraceOperationalRevocationPropagationSummary,
}

impl TraceOperationalPromotionGateSummary {
    fn from_inputs(inputs: TraceOperationalPromotionGateInputs<'_>) -> Self {
        let state = inputs.state;
        let db_summary = inputs.db_summary;
        let review_sla = inputs.review_sla;
        let exports = inputs.exports;
        let retention = inputs.retention;
        let vectors = inputs.vectors;
        let benchmarks = inputs.benchmarks;
        let ranking = inputs.ranking;
        let near_credit = inputs.near_credit;
        let delayed_credit = inputs.delayed_credit;
        let credit_risk = inputs.credit_risk;
        let db_mirror_configured = state.db_mirror.is_some();
        let tenant_rollout_gate_counts = state.tenant_rollout_gates.status_counts();
        let tenant_rollout_gate_count = tenant_rollout_gate_counts.values().sum();
        let open_review_count = review_sla.quarantined_total;
        let urgent_review_count = review_sla.urgent;
        let failed_export_job_count = exports.jobs_by_status.get("failed").copied().unwrap_or(0);
        let stale_export_job_count = exports.stale_running_job_count;
        let failed_retention_job_count =
            retention.jobs_by_status.get("failed").copied().unwrap_or(0);
        let vector_missing_count = vectors
            .accepted_current_derived
            .saturating_sub(vectors.accepted_current_derived_with_active_vector);
        let vector_nearest_neighbor_policy_gap_count = vectors.nearest_neighbor_policy_gap_count;
        let published_benchmark_external_registry_gap_count =
            benchmarks.external_registry_adapter_gap_count;
        let revoked_benchmark_external_registry_invalidation_gap_count =
            benchmarks.external_registry_invalidation_gap_count;
        let benchmark_registry_outbox_pending_without_submitter_count =
            benchmarks.registry_outbox_pending_without_submitter_count;
        let benchmark_registry_outbox_pending_without_submitter_auth_count =
            benchmarks.registry_outbox_pending_without_submitter_auth_count;
        let benchmark_registry_outbox_submitted_without_confirmer_count =
            benchmarks.registry_outbox_submitted_without_confirmer_count;
        let benchmark_registry_outbox_submitted_without_confirmer_auth_count =
            benchmarks.registry_outbox_submitted_without_confirmer_auth_count;
        let benchmark_registry_outbox_failed_count = benchmarks.registry_outbox_failed_count;
        let publishable_benchmark_without_external_evaluator_count =
            benchmarks.publishable_without_external_evaluator_count;
        let at_risk_ranking_model_count = ranking.at_risk_model_count;
        let failing_ranking_model_backtest_count = ranking.failing_backtest_model_target_count;
        let ranking_adjudication_issue_count = ranking.adjudication_issue_group_count;
        let blocked_ranking_credit_event_count = ranking.blocked_credit_event_count;
        let ranking_calibration_dataset_manifest_conflict_count =
            ranking.calibration_dataset_manifest_conflict_count;
        let near_credit_outbox_pending_without_submitter_count =
            near_credit.pending_without_submitter_count;
        let near_credit_outbox_submitted_without_confirmer_count =
            near_credit.submitted_without_confirmer_count;
        let near_credit_outbox_failed_count = near_credit.failed_count;
        let stale_ranking_worker_run_count = ranking.stale_running_worker_run_count;
        let failed_ranking_worker_run_count = ranking.failed_worker_run_count;
        let artifact_object_store_configured = state.artifact_store.is_some();
        let artifact_object_store_io_enabled = state
            .artifact_store
            .as_ref()
            .is_some_and(|store| store.object_io_enabled());
        let object_primary_object_store_eligible = state
            .artifact_store
            .as_ref()
            .is_some_and(|store| store.object_primary_eligible());
        let object_store_versioning_required = state.require_object_store_versioning;
        let object_store_versioning_supported = state
            .artifact_store
            .as_ref()
            .is_some_and(|store| store.object_versioning_supported());
        let object_store_restore_after_delete_supported = state
            .artifact_store
            .as_ref()
            .is_some_and(|store| store.restore_after_delete_supported());
        let disabled_remote_object_deleter_required =
            state.artifact_store.as_ref().is_some_and(|store| {
                store.object_store_name() == TRACE_COMMONS_SERVICE_REMOTE_DISABLED_OBJECT_STORE
            });
        let remote_object_deleter_required =
            state.require_external_remote_object_deleter || disabled_remote_object_deleter_required;
        let remote_object_deleter_configured = state.remote_object_deleter.is_some();
        let remote_object_deleter_missing =
            remote_object_deleter_required && !remote_object_deleter_configured;
        let object_primary_enabled = state.object_primary_submit_review
            || state.object_primary_replay_export
            || state.object_primary_derived_exports;
        let ranking_worker_run_actionable_skip_count = ranking
            .worker_run_skipped_model_risk_total
            .saturating_add(ranking.worker_run_skipped_ineligible_total);
        let ranking_worker_run_skip_reason_counts = ranking.worker_run_reason_counts.clone();
        let revocation_propagation_latest_failed_count =
            inputs.revocation_propagation.latest_failed_count;
        let revocation_propagation_latest_skipped_count =
            inputs.revocation_propagation.latest_skipped_count;
        let worker_cache_invalidator_required = state.require_external_worker_cache_invalidator;
        let worker_cache_invalidator_configured = state.worker_cache_invalidator.is_some();
        let worker_cache_invalidator_missing =
            worker_cache_invalidator_required && !worker_cache_invalidator_configured;
        let credit_settlement_central_issuer_profile_required =
            state.credit_settlement_require_central_issuer_profile;
        let central_issuer_profile_config =
            credit_settlement_central_issuer_profile_config_from_state(state);
        let central_issuer_profile_missing_controls =
            credit_settlement_central_issuer_profile_missing_config(&central_issuer_profile_config);
        let credit_settlement_central_issuer_profile_missing_control_count =
            central_issuer_profile_missing_controls.len();
        let credit_settlement_central_issuer_profile_ready =
            credit_settlement_central_issuer_profile_missing_control_count == 0;
        let credit_settlement_managed_eddsa_signed_tokens_required =
            central_issuer_profile_config.require_managed_eddsa_signed_tokens;
        let credit_settlement_tenant_access_grants_required =
            central_issuer_profile_config.require_tenant_access_grants;
        let credit_settlement_account_cap_configured =
            state.credit_settlement_max_micros_per_account.is_some();
        let credit_settlement_account_cap_missing =
            delayed_credit.points_positive > 0.0 && !credit_settlement_account_cap_configured;
        let credit_settlement_policy_allowlist_configured =
            !state.credit_settlement_allowed_policy_versions.is_empty();
        let credit_settlement_policy_allowlist_missing =
            delayed_credit.points_positive > 0.0 && !credit_settlement_policy_allowlist_configured;
        let credit_settlement_held_account_count = credit_risk.held_account_count;
        let credit_settlement_over_cap_account_count = credit_risk.over_cap_account_count;
        let credit_settlement_risk_summary_truncated = credit_risk.truncated;
        let credit_settlement_near_contract_required =
            state.credit_settlement_require_near_contract;
        let credit_settlement_near_contract_configured =
            state.credit_settlement_near_contract_id.is_some();
        let credit_settlement_near_contract_missing = delayed_credit.points_positive > 0.0
            && credit_settlement_near_contract_required
            && !credit_settlement_near_contract_configured;
        let credit_settlement_near_submitter_configured = near_credit.submitter_configured;
        let credit_settlement_near_submitter_missing =
            delayed_credit.points_positive > 0.0 && !credit_settlement_near_submitter_configured;
        let credit_settlement_near_confirmer_configured = near_credit.confirmer_configured;
        let credit_settlement_near_confirmer_missing =
            delayed_credit.points_positive > 0.0 && !credit_settlement_near_confirmer_configured;
        let credit_settlement_near_adapter_auth_required = near_credit.require_adapter_auth;
        let credit_settlement_near_submitter_auth_configured =
            near_credit.submitter_auth_configured;
        let credit_settlement_near_submitter_auth_missing = delayed_credit.points_positive > 0.0
            && credit_settlement_near_adapter_auth_required
            && credit_settlement_near_submitter_configured
            && !credit_settlement_near_submitter_auth_configured;
        let credit_settlement_near_confirmer_auth_configured =
            near_credit.confirmer_auth_configured;
        let credit_settlement_near_confirmer_auth_missing = delayed_credit.points_positive > 0.0
            && credit_settlement_near_adapter_auth_required
            && credit_settlement_near_confirmer_configured
            && !credit_settlement_near_confirmer_auth_configured;
        let credit_settlement_issuer_approval_required =
            state.credit_settlement_require_issuer_approval;
        let credit_settlement_issuer_approval_missing =
            delayed_credit.points_positive > 0.0 && !credit_settlement_issuer_approval_required;
        let credit_settlement_scheduler_enabled = state.credit_settlement_scheduler.is_some();
        let postgres_runtime_role_hash = state.postgres_runtime_role_sha256.as_deref();
        let trace_corpus_rls_ready = db_summary.trace_corpus_rls.as_ref().map(|diagnostics| {
            diagnostics.production_ready_with_expected_runtime_role(postgres_runtime_role_hash)
        });
        let trace_corpus_rls_expected_table_count = db_summary
            .trace_corpus_rls
            .as_ref()
            .map_or(0, |diagnostics| diagnostics.expected_table_count);
        let trace_corpus_rls_missing_policy_table_count = db_summary
            .trace_corpus_rls
            .as_ref()
            .map_or(0, |diagnostics| diagnostics.missing_policy_tables.len());
        let trace_corpus_rls_disabled_table_count = db_summary
            .trace_corpus_rls
            .as_ref()
            .map_or(0, |diagnostics| diagnostics.rls_disabled_tables.len());
        let force_rls_disabled_table_count = db_summary
            .trace_corpus_rls
            .as_ref()
            .map_or(0, |diagnostics| diagnostics.force_rls_disabled_tables.len());
        let trace_corpus_rls_expression_mismatch_table_count = db_summary
            .trace_corpus_rls
            .as_ref()
            .map_or(0, |diagnostics| {
                diagnostics.policy_expression_mismatch_tables.len()
            });
        let current_role_bypasses_rls = db_summary
            .trace_corpus_rls
            .as_ref()
            .is_some_and(|diagnostics| diagnostics.current_role_bypasses_rls);
        let current_role_owns_trace_tables = db_summary
            .trace_corpus_rls
            .as_ref()
            .is_some_and(|diagnostics| diagnostics.current_role_owns_trace_tables);
        let postgres_runtime_role_hash_configured = postgres_runtime_role_hash.is_some();
        let postgres_runtime_role_hash_matched =
            db_summary
                .trace_corpus_rls
                .as_ref()
                .and_then(|diagnostics| {
                    postgres_runtime_role_hash.map(|expected_hash| {
                        diagnostics.runtime_role_matches_expected_hash(Some(expected_hash))
                    })
                });
        let tenant_context_transaction_local = db_summary
            .trace_corpus_rls
            .as_ref()
            .is_some_and(|diagnostics| diagnostics.tenant_context_transaction_local);
        let mut blocking_gates = Vec::new();
        let mut warning_gates = Vec::new();

        push_gap_count(&mut blocking_gates, "urgent_reviews", urgent_review_count);
        push_gap_count(
            &mut blocking_gates,
            "failed_export_jobs",
            failed_export_job_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "stale_export_jobs",
            stale_export_job_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "failed_retention_jobs",
            failed_retention_job_count,
        );
        if state.require_db_mirror_writes && !db_mirror_configured {
            blocking_gates.push("db_mirror_writes_required_without_db_mirror".to_string());
        }
        if state.require_db_reconciliation_clean && !db_mirror_configured {
            blocking_gates.push("db_reconciliation_clean_required_without_db_mirror".to_string());
        }
        if state.require_derived_export_object_refs && !db_mirror_configured {
            blocking_gates
                .push("derived_export_object_refs_required_without_db_mirror".to_string());
        }
        if (state.object_primary_submit_review
            || state.object_primary_replay_export
            || state.object_primary_derived_exports)
            && !db_mirror_configured
        {
            blocking_gates.push("object_primary_storage_required_without_db_mirror".to_string());
        }
        if object_primary_enabled && !artifact_object_store_configured {
            blocking_gates.push("object_primary_object_store_missing".to_string());
        } else if object_primary_enabled && !artifact_object_store_io_enabled {
            blocking_gates.push("object_primary_object_store_io_disabled".to_string());
        } else if object_primary_enabled && !object_primary_object_store_eligible {
            blocking_gates.push("object_primary_object_store_not_eligible".to_string());
        }
        if object_store_versioning_required && !object_store_versioning_supported {
            blocking_gates.push("object_store_versioning_required_unsupported".to_string());
        }
        if object_store_versioning_required && !object_store_restore_after_delete_supported {
            blocking_gates.push("object_store_restore_required_unsupported".to_string());
        }
        if disabled_remote_object_deleter_required && !remote_object_deleter_configured {
            blocking_gates.push("disabled_remote_object_deleter_missing".to_string());
        } else if remote_object_deleter_missing {
            blocking_gates.push("remote_object_deleter_required_missing".to_string());
        }
        if db_summary.db_available {
            match trace_corpus_rls_ready {
                Some(true) => {}
                Some(false) => {
                    blocking_gates.push("postgres_trace_rls_not_ready".to_string());
                }
                None => {
                    blocking_gates.push("postgres_trace_rls_diagnostics_unavailable".to_string());
                }
            }
        }
        if matches!(postgres_runtime_role_hash_matched, Some(false)) {
            blocking_gates.push("postgres_trace_runtime_role_hash_mismatch".to_string());
        }
        if state.require_derived_export_object_refs {
            push_gap_count(
                &mut blocking_gates,
                "missing_active_vectors",
                vector_missing_count,
            );
        }
        push_gap_count(
            &mut blocking_gates,
            "vector_nearest_neighbor_policy_gaps",
            vector_nearest_neighbor_policy_gap_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "at_risk_ranking_models",
            at_risk_ranking_model_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "failing_ranking_model_backtests",
            failing_ranking_model_backtest_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "ranking_adjudication_issues",
            ranking_adjudication_issue_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "blocked_ranking_credit_events",
            blocked_ranking_credit_event_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "ranking_calibration_dataset_manifest_conflicts",
            ranking_calibration_dataset_manifest_conflict_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "near_credit_outbox_pending_without_submitter",
            near_credit_outbox_pending_without_submitter_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "near_credit_outbox_submitted_without_confirmer",
            near_credit_outbox_submitted_without_confirmer_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "near_credit_outbox_failed",
            near_credit_outbox_failed_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "stale_ranking_worker_runs",
            stale_ranking_worker_run_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "failed_ranking_worker_runs",
            failed_ranking_worker_run_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "revocation_propagation_failures",
            revocation_propagation_latest_failed_count,
        );
        if worker_cache_invalidator_missing {
            blocking_gates.push("worker_cache_invalidator_required_missing".to_string());
        }
        if credit_settlement_account_cap_missing {
            blocking_gates.push("credit_settlement_account_cap_missing".to_string());
        }
        if credit_settlement_policy_allowlist_missing {
            blocking_gates.push("credit_settlement_policy_allowlist_missing".to_string());
        }
        push_gap_count(
            &mut blocking_gates,
            "held_credit_accounts_present",
            credit_settlement_held_account_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "over_cap_credit_accounts_present",
            credit_settlement_over_cap_account_count,
        );
        if credit_settlement_risk_summary_truncated {
            blocking_gates.push("credit_risk_summary_truncated".to_string());
        }
        if credit_settlement_near_contract_missing {
            blocking_gates.push("credit_settlement_near_contract_missing".to_string());
        }
        if credit_settlement_near_submitter_missing {
            blocking_gates.push("credit_settlement_near_submitter_missing".to_string());
        }
        if credit_settlement_near_confirmer_missing {
            blocking_gates.push("credit_settlement_near_confirmer_missing".to_string());
        }
        if credit_settlement_near_submitter_auth_missing {
            blocking_gates.push("credit_settlement_near_submitter_auth_missing".to_string());
        }
        if credit_settlement_near_confirmer_auth_missing {
            blocking_gates.push("credit_settlement_near_confirmer_auth_missing".to_string());
        }
        if credit_settlement_issuer_approval_missing {
            blocking_gates.push("credit_settlement_issuer_approval_missing".to_string());
        }
        if credit_settlement_central_issuer_profile_required
            && !credit_settlement_central_issuer_profile_ready
        {
            blocking_gates.push("credit_settlement_central_issuer_profile_incomplete".to_string());
        }

        push_gap_count(
            &mut warning_gates,
            "non_urgent_open_reviews",
            open_review_count.saturating_sub(urgent_review_count),
        );
        push_gap_count(
            &mut warning_gates,
            "tenant_rollout_gates",
            tenant_rollout_gate_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "published_benchmarks_waiting_for_external_registry_adapter",
            published_benchmark_external_registry_gap_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "benchmark_registry_outbox_pending_without_submitter",
            benchmark_registry_outbox_pending_without_submitter_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "benchmark_registry_outbox_pending_without_submitter_auth",
            benchmark_registry_outbox_pending_without_submitter_auth_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "benchmark_registry_outbox_submitted_without_confirmer",
            benchmark_registry_outbox_submitted_without_confirmer_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "benchmark_registry_outbox_submitted_without_confirmer_auth",
            benchmark_registry_outbox_submitted_without_confirmer_auth_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "benchmark_registry_outbox_failed",
            benchmark_registry_outbox_failed_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "publishable_benchmarks_without_external_evaluator",
            publishable_benchmark_without_external_evaluator_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "revoked_benchmarks_waiting_for_external_registry_invalidation",
            revoked_benchmark_external_registry_invalidation_gap_count,
        );
        push_gap_count(
            &mut warning_gates,
            "ranking_worker_run_actionable_skips",
            ranking_worker_run_actionable_skip_count,
        );
        push_gap_count(
            &mut warning_gates,
            "revocation_propagation_skips",
            revocation_propagation_latest_skipped_count,
        );

        Self {
            ready: blocking_gates.is_empty(),
            blocking_count: blocking_gates.len(),
            warning_count: warning_gates.len(),
            blocking_gates,
            warning_gates,
            db_mirror_configured,
            require_db_mirror_writes: state.require_db_mirror_writes,
            require_db_reconciliation_clean: state.require_db_reconciliation_clean,
            require_derived_export_object_refs: state.require_derived_export_object_refs,
            require_export_guardrails: state.require_export_guardrails,
            object_primary_submit_review: state.object_primary_submit_review,
            object_primary_replay_export: state.object_primary_replay_export,
            object_primary_derived_exports: state.object_primary_derived_exports,
            trace_corpus_rls_ready,
            trace_corpus_rls_expected_table_count,
            trace_corpus_rls_missing_policy_table_count,
            trace_corpus_rls_disabled_table_count,
            force_rls_disabled_table_count,
            trace_corpus_rls_expression_mismatch_table_count,
            current_role_bypasses_rls,
            current_role_owns_trace_tables,
            postgres_runtime_role_hash_configured,
            postgres_runtime_role_hash_matched,
            tenant_context_transaction_local,
            tenant_rollout_gate_count,
            tenant_rollout_gate_counts,
            open_review_count,
            urgent_review_count,
            failed_export_job_count,
            stale_export_job_count,
            failed_retention_job_count,
            vector_missing_count,
            vector_nearest_neighbor_policy_gap_count,
            benchmark_registry_outbox_pending_without_submitter_count,
            benchmark_registry_outbox_pending_without_submitter_auth_count,
            benchmark_registry_outbox_submitted_without_confirmer_count,
            benchmark_registry_outbox_submitted_without_confirmer_auth_count,
            benchmark_registry_outbox_failed_count,
            publishable_benchmark_without_external_evaluator_count,
            published_benchmark_external_registry_gap_count,
            revoked_benchmark_external_registry_invalidation_gap_count,
            at_risk_ranking_model_count,
            failing_ranking_model_backtest_count,
            ranking_adjudication_issue_count,
            blocked_ranking_credit_event_count,
            ranking_calibration_dataset_manifest_conflict_count,
            near_credit_outbox_pending_without_submitter_count,
            near_credit_outbox_submitted_without_confirmer_count,
            near_credit_outbox_failed_count,
            stale_ranking_worker_run_count,
            failed_ranking_worker_run_count,
            ranking_worker_run_actionable_skip_count,
            ranking_worker_run_skip_reason_counts,
            revocation_propagation_latest_failed_count,
            revocation_propagation_latest_skipped_count,
            worker_cache_invalidator_required,
            worker_cache_invalidator_configured,
            worker_cache_invalidator_missing,
            credit_settlement_central_issuer_profile_required,
            credit_settlement_central_issuer_profile_ready,
            credit_settlement_central_issuer_profile_missing_control_count,
            credit_settlement_managed_eddsa_signed_tokens_required,
            credit_settlement_tenant_access_grants_required,
            credit_settlement_account_cap_configured,
            credit_settlement_account_cap_missing,
            credit_settlement_policy_allowlist_configured,
            credit_settlement_policy_allowlist_missing,
            credit_settlement_held_account_count,
            credit_settlement_over_cap_account_count,
            credit_settlement_risk_summary_truncated,
            credit_settlement_near_contract_required,
            credit_settlement_near_contract_configured,
            credit_settlement_near_contract_missing,
            credit_settlement_near_submitter_configured,
            credit_settlement_near_submitter_missing,
            credit_settlement_near_confirmer_configured,
            credit_settlement_near_confirmer_missing,
            credit_settlement_near_adapter_auth_required,
            credit_settlement_near_submitter_auth_configured,
            credit_settlement_near_submitter_auth_missing,
            credit_settlement_near_confirmer_auth_configured,
            credit_settlement_near_confirmer_auth_missing,
            credit_settlement_issuer_approval_required,
            credit_settlement_issuer_approval_missing,
            credit_settlement_scheduler_enabled,
            object_store_versioning_required,
            object_store_versioning_supported,
            object_store_restore_after_delete_supported,
            remote_object_deleter_required,
            remote_object_deleter_configured,
            remote_object_deleter_missing,
        }
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalSubmissionSummary {
    total: usize,
    by_status: BTreeMap<String, usize>,
    by_privacy_risk: BTreeMap<String, usize>,
    accepted: usize,
    quarantined: usize,
    rejected: usize,
    revoked: usize,
    expired: usize,
    purged: usize,
}

impl TraceOperationalSubmissionSummary {
    fn from_records(records: &[TraceCommonsSubmissionRecord]) -> Self {
        let mut summary = Self {
            total: records.len(),
            ..Self::default()
        };
        for record in records {
            *summary
                .by_status
                .entry(record.status.as_str().to_string())
                .or_insert(0) += 1;
            *summary
                .by_privacy_risk
                .entry(format!("{:?}", record.privacy_risk).to_ascii_lowercase())
                .or_insert(0) += 1;
            match record.status {
                TraceCorpusStatus::Accepted => summary.accepted += 1,
                // Held pending the PII backstop: not Accepted. The precise count
                // is preserved in `by_status["awaiting_pii_backstop"]`; folded
                // into quarantined for the coarse not-yet-accepted tally.
                TraceCorpusStatus::Quarantined | TraceCorpusStatus::AwaitingPiiBackstop => {
                    summary.quarantined += 1
                }
                TraceCorpusStatus::Rejected => summary.rejected += 1,
                TraceCorpusStatus::Revoked => summary.revoked += 1,
                TraceCorpusStatus::Expired => summary.expired += 1,
                TraceCorpusStatus::Purged => summary.purged += 1,
            }
        }
        summary
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalReviewSlaSummary {
    quarantined_total: usize,
    fresh: usize,
    due: usize,
    overdue: usize,
    urgent: usize,
    assigned: usize,
    expired_leases: usize,
    oldest_age_hours: i64,
    by_state: BTreeMap<String, usize>,
}

impl TraceOperationalReviewSlaSummary {
    fn from_records(records: &[TraceCommonsSubmissionRecord], now: DateTime<Utc>) -> Self {
        let mut summary = Self::default();
        for record in records
            .iter()
            .filter(|record| record.status == TraceCorpusStatus::Quarantined)
        {
            summary.quarantined_total += 1;
            if record.review_assigned_to_principal_ref.is_some() {
                summary.assigned += 1;
            }
            if record
                .review_lease_expires_at
                .is_some_and(|expires_at| expires_at <= now)
            {
                summary.expired_leases += 1;
            }
            let escalation = trace_review_escalation(record, now);
            summary.oldest_age_hours = summary.oldest_age_hours.max(escalation.age_hours);
            let state_name = trace_operational_review_state_name(escalation.state);
            *summary.by_state.entry(state_name.to_string()).or_insert(0) += 1;
            match escalation.state {
                TraceReviewEscalationState::Fresh => summary.fresh += 1,
                TraceReviewEscalationState::Due => summary.due += 1,
                TraceReviewEscalationState::Overdue => summary.overdue += 1,
                TraceReviewEscalationState::Urgent => summary.urgent += 1,
            }
        }
        summary
    }
}

fn trace_operational_review_state_name(state: TraceReviewEscalationState) -> &'static str {
    match state {
        TraceReviewEscalationState::Fresh => "fresh",
        TraceReviewEscalationState::Due => "due",
        TraceReviewEscalationState::Overdue => "overdue",
        TraceReviewEscalationState::Urgent => "urgent",
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalExportSummary {
    db_available: bool,
    manifest_count: usize,
    active_manifest_count: usize,
    invalidated_manifest_count: usize,
    deleted_manifest_count: usize,
    total_manifest_items: usize,
    by_artifact_kind: BTreeMap<String, usize>,
    job_count: usize,
    jobs_by_status: BTreeMap<String, usize>,
    stale_running_job_count: usize,
    scheduler_enabled: bool,
}

impl TraceOperationalExportSummary {
    fn from_db_summary(
        db_summary: &TraceOperationalDbSummary,
        generated_at: DateTime<Utc>,
        state: &AppState,
    ) -> Self {
        let mut summary = Self {
            db_available: db_summary.db_available,
            manifest_count: db_summary.export_manifests.len(),
            job_count: db_summary.export_jobs.len(),
            scheduler_enabled: state.export_job_scheduler.is_some(),
            ..Self::default()
        };
        for manifest in &db_summary.export_manifests {
            if manifest.deleted_at.is_some() {
                summary.deleted_manifest_count += 1;
            } else if manifest.invalidated_at.is_some() {
                summary.invalidated_manifest_count += 1;
            } else {
                summary.active_manifest_count += 1;
            }
            summary.total_manifest_items += manifest.item_count as usize;
            *summary
                .by_artifact_kind
                .entry(trace_operational_artifact_kind_name(manifest.artifact_kind).to_string())
                .or_insert(0) += 1;
        }
        for job in &db_summary.export_jobs {
            *summary
                .jobs_by_status
                .entry(trace_operational_export_job_status_name(job.status).to_string())
                .or_insert(0) += 1;
            if job.status == StorageTraceExportJobStatus::Running && job.expires_at <= generated_at
            {
                summary.stale_running_job_count += 1;
            }
        }
        summary
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalRetentionSummary {
    db_available: bool,
    job_count: usize,
    dry_run_count: usize,
    scheduler_enabled: bool,
    jobs_by_status: BTreeMap<String, usize>,
    selected_revoked_total: u64,
    selected_expired_total: u64,
}

impl TraceOperationalRetentionSummary {
    fn from_db_summary(db_summary: &TraceOperationalDbSummary, state: &AppState) -> Self {
        let mut summary = Self {
            db_available: db_summary.db_available,
            job_count: db_summary.retention_jobs.len(),
            scheduler_enabled: state.retention_maintenance_scheduler.is_some(),
            ..Self::default()
        };
        for job in &db_summary.retention_jobs {
            if job.dry_run {
                summary.dry_run_count += 1;
            }
            summary.selected_revoked_total += u64::from(job.selected_revoked_count);
            summary.selected_expired_total += u64::from(job.selected_expired_count);
            *summary
                .jobs_by_status
                .entry(trace_operational_retention_job_status_name(job.status).to_string())
                .or_insert(0) += 1;
        }
        summary
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalAnalyticsSummary {
    min_cell_count: usize,
    min_cell_count_configured: bool,
    broad_release_noise_configured: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    broad_release_noise_max_delta: Option<usize>,
    broad_release_ready: bool,
    blocker_reasons: Vec<String>,
}

impl TraceOperationalAnalyticsSummary {
    fn from_state(state: &AppState) -> Self {
        let min_cell_count_configured = state.analytics_min_cell_count > 1;
        let broad_release_noise_max_delta = state
            .analytics_broad_release_noise
            .as_ref()
            .map(|config| config.max_delta);
        let broad_release_noise_configured = broad_release_noise_max_delta.is_some();
        let mut blocker_reasons = Vec::new();
        if !min_cell_count_configured {
            blocker_reasons.push("min_cell_count_disabled".to_string());
        }
        if !broad_release_noise_configured {
            blocker_reasons.push("noise_not_configured".to_string());
        }
        Self {
            min_cell_count: state.analytics_min_cell_count,
            min_cell_count_configured,
            broad_release_noise_configured,
            broad_release_noise_max_delta,
            broad_release_ready: blocker_reasons.is_empty(),
            blocker_reasons,
        }
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalVectorSummary {
    db_available: bool,
    private_embedder_configured: bool,
    private_embedder_required: bool,
    private_searcher_configured: bool,
    private_searcher_required: bool,
    scheduler_enabled: bool,
    entry_count: usize,
    active_entries: usize,
    invalidated_entries: usize,
    deleted_entries: usize,
    accepted_current_derived: usize,
    accepted_current_derived_with_active_vector: usize,
    nearest_neighbor_policy_gap_count: usize,
    active_coverage_percent: f32,
}

impl TraceOperationalVectorSummary {
    fn from_records_and_db_summary(
        derived: &[TraceCommonsDerivedRecord],
        db_summary: &TraceOperationalDbSummary,
        state: &AppState,
    ) -> Self {
        let active_vector_submission_ids = db_summary
            .vector_entries
            .iter()
            .filter(|entry| entry.status == StorageTraceVectorEntryStatus::Active)
            .map(|entry| entry.submission_id)
            .collect::<BTreeSet<_>>();
        let accepted_current_derived = derived
            .iter()
            .filter(|record| record.status == TraceCorpusStatus::Accepted)
            .count();
        let accepted_current_derived_with_active_vector = derived
            .iter()
            .filter(|record| record.status == TraceCorpusStatus::Accepted)
            .filter(|record| active_vector_submission_ids.contains(&record.submission_id))
            .count();
        let mut summary = Self {
            db_available: db_summary.db_available,
            private_embedder_configured: state.vector_embedder.is_some(),
            private_embedder_required: state.require_external_vector_embedder,
            private_searcher_configured: state.vector_searcher.is_some(),
            private_searcher_required: state.require_external_vector_searcher,
            scheduler_enabled: state.vector_index_scheduler.is_some(),
            entry_count: db_summary.vector_entries.len(),
            accepted_current_derived,
            accepted_current_derived_with_active_vector,
            nearest_neighbor_policy_gap_count: trace_vector_nearest_neighbor_policy_gap_count(
                derived,
                &db_summary.vector_entries,
            ),
            active_coverage_percent: if accepted_current_derived == 0 {
                0.0
            } else {
                (accepted_current_derived_with_active_vector as f32
                    / accepted_current_derived as f32)
                    * 100.0
            },
            ..Self::default()
        };
        for entry in &db_summary.vector_entries {
            match entry.status {
                StorageTraceVectorEntryStatus::Active => summary.active_entries += 1,
                StorageTraceVectorEntryStatus::Invalidated => summary.invalidated_entries += 1,
                StorageTraceVectorEntryStatus::Deleted => summary.deleted_entries += 1,
            }
        }
        summary
    }
}

fn trace_vector_nearest_neighbor_policy_gap_count(
    derived: &[TraceCommonsDerivedRecord],
    vector_entries: &[StorageTraceVectorEntryRecord],
) -> usize {
    let trace_id_by_submission = derived
        .iter()
        .filter(|record| record.status == TraceCorpusStatus::Accepted)
        .map(|record| (record.submission_id, record.trace_id.to_string()))
        .collect::<BTreeMap<_, _>>();
    let mut active_entries_by_trace_id: BTreeMap<String, Vec<&StorageTraceVectorEntryRecord>> =
        BTreeMap::new();
    for entry in vector_entries
        .iter()
        .filter(|entry| trace_vector_entry_is_active(entry))
    {
        if let Some(trace_id) = trace_id_by_submission.get(&entry.submission_id) {
            active_entries_by_trace_id
                .entry(trace_id.clone())
                .or_default()
                .push(entry);
        }
    }

    vector_entries
        .iter()
        .filter(|entry| trace_vector_entry_is_active(entry))
        .filter(|entry| {
            let own_trace_id = trace_id_by_submission.get(&entry.submission_id);
            entry.nearest_trace_ids.iter().any(|nearest_trace_id| {
                own_trace_id.is_some_and(|own_trace_id| own_trace_id == nearest_trace_id)
                    || !active_entries_by_trace_id
                        .get(nearest_trace_id)
                        .is_some_and(|neighbors| {
                            neighbors.iter().any(|neighbor| {
                                trace_vector_entries_are_policy_compatible(entry, neighbor)
                            })
                        })
            })
        })
        .count()
}

fn trace_vector_entry_is_active(entry: &StorageTraceVectorEntryRecord) -> bool {
    entry.status == StorageTraceVectorEntryStatus::Active
        && entry.invalidated_at.is_none()
        && entry.deleted_at.is_none()
}

fn trace_vector_entries_are_policy_compatible(
    target: &StorageTraceVectorEntryRecord,
    neighbor: &StorageTraceVectorEntryRecord,
) -> bool {
    target.vector_store == neighbor.vector_store
        && target.embedding_model == neighbor.embedding_model
        && target.embedding_dimension == neighbor.embedding_dimension
        && target.embedding_version == neighbor.embedding_version
        && target.source_projection == neighbor.source_projection
}

